    $profileHorizontal = $aksesoris->filter(function($item) {
        return $item->area && $item->area->slug == 'profile-horizontal';
    })->first();
    
    $satuanTerkecilHorizontal = $profileHorizontal ? (float)$profileHorizontal->satuan_terkecil : 0;
    $variableB = $jumlah * $satuanTerkecilHorizontal;
    $frameHorizontal = $variableB * $lebar;
    $batangHorizontal = $frameHorizontal / 580;
    $batangHorizontal = ceil($batangHorizontal * 10) / 10;
    $totalLebar = $lebar * $variableB;

    // === PERHITUNGAN REINFORCEMENT ===
    $totalBatang = ($frameVertikal + $frameHorizontal) / 600;
    $reinforcementQty = ceil($totalBatang * 10) / 10;

    // === PERHITUNGAN SETTING BLOCK ===
    $settingBlockItem = $aksesoris->filter(function($item) {
        return $item->area && $item->area->slug == 'setting-block';
    })->first();
    
    $satuanTerkecilSettingBlock = $settingBlockItem ? (float)$settingBlockItem->satuan_terkecil : 0;
    
    $variableC = 3 * $satuanTerkecilSettingBlock;
    $variableD = $variableC * $jumlah;
    $variableE = $variableD * 25;
    $variableF = $variableE / 1000;
    $settingBlockQty = ceil($variableF);

    // === PERHITUNGAN PROFILE COUPLING VERTIKAL ===
    $profileCouplingVertikal = $aksesoris->filter(function($item) {
        return $item->area && $item->area->slug == 'profile-coupling-vertikal';
    })->first();
    
    $satuanTerkecilCoupling = $profileCouplingVertikal ? (float)$profileCouplingVertikal->satuan_terkecil : 0;
    $variableCouplingA = $satuanTerkecilCoupling * $jumlah * 2;
    $variableCouplingB = $variableCouplingA * $panjang;
    $batangCoupling = $variableCouplingB / 580;
    $batangCouplingQty = ceil($batangCoupling * 10) / 10;

    // === PERHITUNGAN PROFILE MULLION VERTIKAL ===
    $profileMullionVertikal = $aksesoris->filter(function($item) {
        return $item->area && $item->area->slug == 'profile-mullion-vertikal';
    })->first();
    
    $variableMullionVertikalA = 6 * $jumlah;
    $variableMullionVertikalB = $variableMullionVertikalA * $panjang;
    $batangMullionVertikal = $variableMullionVertikalB / 580;
    $batangMullionVertikalQty = ceil($batangMullionVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE MULLION HORIZONTAL ===
    $profileMullionHorizontal = $aksesoris->filter(function($item) {
        return $item->area && $item->area->slug == 'profile-mullion-horizontal';
    })->first();
    
    $satuanTerkecilMullionHorizontal = $profileMullionHorizontal ? (float)$profileMullionHorizontal->satuan_terkecil : 0;
    $variableMullionHorizontalA = $satuanTerkecilMullionHorizontal * $jumlah;
    $variableMullionHorizontalB = $variableMullionHorizontalA * $lebar;
    $batangMullionHorizontal = $variableMullionHorizontalB / 580;
    $batangMullionHorizontalQty = ceil($batangMullionHorizontal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT MULLION ===
    $totalMullionBatang = ($variableMullionVertikalB + $variableMullionHorizontalB) / 600;
    $reinforcementMullionQty = ceil($totalMullionBatang * 10) / 10;

    // === PERHITUNGAN SCREW ===
    $screwItem = $aksesoris->filter(function($item) {
        return $item->area && $item->area->slug == 'screw-reinforcement';
    })->first();
    $satuanTerkecilScrew = $screwItem ? (float)$screwItem->satuan_terkecil : 1;
    $screwQty = ((($totalLebar + $totalPanjang)) + ($variableMullionVertikalB + $variableMullionHorizontalB)) / $satuanTerkecilScrew;
    $screwQty = ceil($screwQty * 10);

    // === HITUNG QTY PER AKSESORIS ===
    foreach ($aksesoris as $item) {
        $areaSlug = $item->area ? $item->area->slug : '';
        $qty = 0;
        
        if ($areaSlug == 'profile-vertikal') {
            $qty = $batangVertikal;
        } elseif ($areaSlug == 'profile-horizontal') {
            $qty = $batangHorizontal;
        } elseif ($areaSlug == 'glaze-bead-vertical') {
            $qty = ($panjang / 100) * $jumlah;
        } elseif ($areaSlug == 'glaze-bead-horizontal') {
            $qty = ($lebar / 100) * $jumlah;
        } elseif ($areaSlug == 'reinforcement') {
            $qty = $reinforcementQty;
        } elseif ($areaSlug == 'reinforcement-mullion') {
            $qty = $reinforcementMullionQty;
        } elseif ($areaSlug == 'kaca') {
            $qty = $luasKacaTotal;
        } elseif ($areaSlug == 'screw-reinforcement') {
            $qty = $screwQty;
        } elseif ($areaSlug == 'setting-block') {
            $qty = $settingBlockQty;
        } elseif ($areaSlug == 'profile-coupling-vertikal') {
            $qty = $batangCouplingQty;
        } elseif ($areaSlug == 'profile-mullion-vertikal') {
            $qty = $batangMullionVertikalQty;
        } elseif ($areaSlug == 'profile-mullion-horizontal') {
            $qty = $batangMullionHorizontalQty;
        } else {
            $qty = $jumlah * ($item->satuan_terkecil ?? 1);
        }
        
        $item->qty = $qty;
    }

    // Kelompokkan berdasarkan area
    $grouped = [];
    foreach ($aksesoris as $item) {
        $areaSlug = $item->area ? $item->area->slug : 'lainnya';
        
        if (str_starts_with($areaSlug, 'profile')) {
            $groupKey = 'profile';
        } elseif ($areaSlug == 'setting-block') {
            $groupKey = 'kaca';
        } elseif ($areaSlug == 'reinforcement' || $areaSlug == 'reinforcement-mullion') {
            $groupKey = 'reinforcement';
        } else {
            $groupKey = $areaSlug;
        }
        
        if (!isset($grouped[$groupKey])) {
            $grouped[$groupKey] = [];
        }
        $grouped[$groupKey][] = $item;
    }

    $areaLabels = [
        'profile' => 'PROFILE',
        'reinforcement' => 'REINFORCEMENT',
        'kaca' => 'KACA',
        'screw-reinforcement' => 'SCREW',
    ];

    // ============ GENERATE NOMOR BOQ ============
    $nomorBoq = Boq::generateNomorBoq();

    // ============ STORE BOQ ============
    try {
        $allResults = [];
        
        foreach ($aksesoris as $item) {
            if ($item->qty > 0) {
                $allResults[] = [
                    'produk_id' => $item->id,
                    'qty' => $item->qty,
                    'nama_produk' => $item->nama_produk,
                ];
            }
        }
        
        $uniqueResults = [];
        $seenIds = [];
        
        foreach ($allResults as $item) {
            $produkId = $item['produk_id'] ?? null;
            
            if (!$produkId) {
                continue;
            }
            
            if (in_array($produkId, $seenIds)) {
                continue;
            }
            
            $seenIds[] = $produkId;
            $uniqueResults[] = $item;
        }
        
        if (count($uniqueResults) > 0) {
            $boq = new Boq();
            $boq->nomor_boq = $nomorBoq;
            $boq->tanggal_boq = now();
            $boq->save();
            
            foreach ($uniqueResults as $item) {
                $produkId = $item['produk_id'] ?? null;
                $qty = (int)($item['qty'] ?? 0);
                
                if ($produkId && $qty > 0) {
                    $produk = Product::find($produkId);
                    
                    \DB::table('detail_boq')->insert([
                        'boq_id' => $boq->id,
                        'produk_id' => $produkId,
                        'kode_produk' => $produk ? $produk->kode_produk : null,
                        'qty' => $qty,
                        'created_at' => now(),
                        'updated_at' => now()
                    ]);
                }
            }
            
            \Log::info('BOQ SAVED JENDELA MATI 2 MULLION:', [
                'boq_id' => $boq->id,
                'nomor_boq' => $nomorBoq,
                'total' => count($uniqueResults)
            ]);
        }
        
    } catch (\Exception $e) {
        \Log::error('Error saving BOQ Jendela Mati 2 Mullion: ' . $e->getMessage());
        \Log::error($e->getTraceAsString());
    }

    $data = [
        'judul' => $judul,
        'panjang' => $panjang,
        'lebar' => $lebar,
        'tebal_kaca' => $tebal_kaca,
        'jumlah' => $jumlah,
        'warna' => $warna,
        'type_kaca' => $type_kaca,
        'luas_kaca_total' => $luasKacaTotal,
        'keliling_total' => $kelilingTotal,
        'batang_vertikal' => $batangVertikal,
        'batang_horizontal' => $batangHorizontal,
        'reinforcement_qty' => $reinforcementQty,
        'reinforcement_mullion_qty' => $reinforcementMullionQty,
        'screw_qty' => $screwQty,
        'setting_block_qty' => $settingBlockQty,
        'batang_coupling_qty' => $batangCouplingQty,
        'batang_mullion_vertikal_qty' => $batangMullionVertikalQty,
        'batang_mullion_horizontal_qty' => $batangMullionHorizontalQty,
        'grouped' => $grouped,
        'areaLabels' => $areaLabels,
        'nomor_boq' => $nomorBoq,
    ];

    return view('boq.jendela.pdf-jendela-mati-3-kaca-mullion', compact('data'));
}

public function hitungSwing1(Request $request)
{
    $request->validate([
        'panjang' => 'required|numeric|min:1',
        'lebar' => 'required|numeric|min:1',
        'tebal_kaca' => 'required|numeric|min:1',
        'jumlah' => 'required|numeric|min:1',
        'warna' => 'required|string',
        'type_kaca' => 'required|string',
    ]);

    // Ambil data dari form
    $panjang = $request->panjang; // cm
    $lebar = $request->lebar; // cm
    $tebalKaca = $request->tebal_kaca; // mm
    $jumlah = $request->jumlah;
    $warna = $request->warna;
    $typeKaca = $request->type_kaca;

    // Ambil produk utama (Jendela Swing 1) dari database
    $produkUtama = Product::find(155);
    
    if (!$produkUtama) {
        return back()->with('error', 'Produk Jendela Swing 1 tidak ditemukan!');
    }

    // Ambil aksesoris dari tabel product_accessories dengan relasi area
    $aksesorisIds = ProductAccessories::where('parent_product_id', 155)->pluck('accessory_id');
    $aksesoris = Product::with('area', 'unit')
        ->whereIn('id', $aksesorisIds)
        ->get();

    // === PERHITUNGAN DASAR ===
    
    // Konversi ke meter
    $panjangM = $panjang / 100;
    $lebarM = $lebar / 100;
    $tebalKacaM = $tebalKaca / 1000;

    // 1. Luas Kaca (m²)
    $luasKacaPerUnit = $panjangM * $lebarM;
    $luasKacaTotal = $luasKacaPerUnit * $jumlah;
    $luasKacaTotal = ceil($luasKacaTotal * 10) / 10;

    // 2. Keliling Profile (meter)
    $kelilingPerUnit = 2 * ($panjangM + $lebarM);
    $kelilingTotal = $kelilingPerUnit * $jumlah;

    // === PERHITUNGAN PROFILE VERTIKAL ===
    $profileVertikal = null;
    $aksesorisCount = count($aksesoris);
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-vertikal') {
            $profileVertikal = $item;
            break;
        }
    }
    $satuanTerkecilVertikal = $profileVertikal ? (float)$profileVertikal->satuan_terkecil : 0;

    $variableA = $jumlah * $satuanTerkecilVertikal;
    $frameVertikal = $variableA * $panjang;
    $batangVertikal = $frameVertikal / 580;
    $batangVertikal = ceil($batangVertikal * 10) / 10;
    $totalPanjang = $panjang * $variableA;

    // === PERHITUNGAN PROFILE HORIZONTAL ===
    $profileHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-horizontal') {
            $profileHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilHorizontal = $profileHorizontal ? (float)$profileHorizontal->satuan_terkecil : 0;
    
    $variableB = $jumlah * $satuanTerkecilHorizontal;
    $frameHorizontal = $variableB * $lebar;
    $batangHorizontal = $frameHorizontal / 580;
    $batangHorizontal = ceil($batangHorizontal * 10) / 10;
    $totalLebar = $lebar * $variableB;

    // === PERHITUNGAN REINFORCEMENT ===
    $totalBatang = ($frameVertikal + $frameHorizontal) / 600;
    $reinforcementQty = ceil($totalBatang * 10) / 10;

    // === PERHITUNGAN PROFILE SASH VERTIKAL ===
    $profileSashVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-vertikal') {
            $profileSashVertikal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashVertikal = $profileSashVertikal ? (float)$profileSashVertikal->satuan_terkecil : 0;
    
    $variableSashVertikalA = $satuanTerkecilSashVertikal * $jumlah;
    $variableSashVertikalB = $variableSashVertikalA * $panjang;
    $batangSashVertikal = $variableSashVertikalB / 580;
    $batangSashVertikalQty = ceil($batangSashVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE SASH HORIZONTAL ===
    $profileSashHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-horizontal') {
            $profileSashHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashHorizontal = $profileSashHorizontal ? (float)$profileSashHorizontal->satuan_terkecil : 0;
    
    $variableSashHorizontalA = $satuanTerkecilSashHorizontal * $jumlah;
    $variableSashHorizontalB = $variableSashHorizontalA * $lebar;
    $batangSashHorizontal = $variableSashHorizontalB / 580;
    $batangSashHorizontalQty = ceil($batangSashHorizontal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT SASH ===
    $totalBatangSash = ($variableSashVertikalB + $variableSashHorizontalB) / 600;
    $reinforcementSashQty = ceil($totalBatangSash * 10) / 10;

    // === PERHITUNGAN DECORATION BAR ===
    $decorationBarVertikalInput = (int)($request->decoration_bar_vertikal ?? 0);
    $decorationBarVertikalItem = null;
    $batangDecorationVertikal = 0;
    $batangDecorationVertikalQty = 0;

    if ($decorationBarVertikalInput > 0) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'profile-decoration-vertikal') {
                $decorationBarVertikalItem = $item;
                break;
            }
        }
        if ($decorationBarVertikalItem) {
            $satuanTerkecil = (float)($decorationBarVertikalItem->satuan_terkecil ?? 0);
            $variableDecorationVertikalA = $decorationBarVertikalInput * $jumlah * 2;
            $variableDecorationVertikalB = $variableDecorationVertikalA * $panjang;
            $batangDecorationVertikal = $variableDecorationVertikalB / 580;
            $batangDecorationVertikalQty = ceil($batangDecorationVertikal * 10) / 10;
            $decorationBarVertikalItem->qty = $batangDecorationVertikalQty;
        }
    }

    $decorationBarHorizontalInput = (int)($request->decoration_bar_horizontal ?? 0);
    $decorationBarHorizontalItem = null;
    $batangDecorationHorizontal = 0;
    $batangDecorationHorizontalQty = 0;

    if ($decorationBarHorizontalInput > 0) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'profile-decoration-horizontal') {
                $decorationBarHorizontalItem = $item;
                break;
            }
        }
        if ($decorationBarHorizontalItem) {
            $satuanTerkecil = (float)($decorationBarHorizontalItem->satuan_terkecil ?? 0);
            $variableDecorationHorizontalA = $decorationBarHorizontalInput * $jumlah * 2;
            $variableDecorationHorizontalB = $variableDecorationHorizontalA * $lebar;
            $batangDecorationHorizontal = $variableDecorationHorizontalB / 580;
            $batangDecorationHorizontalQty = ceil($batangDecorationHorizontal * 10) / 10;
            $decorationBarHorizontalItem->qty = $batangDecorationHorizontalQty;
        }
    }

    $totalDecorationBarQty = ceil(($batangDecorationVertikal + $batangDecorationHorizontal) * 10) / 10;

    // === PERHITUNGAN WINDOW HARDWARE TRANSMITTER ===
    $ukuranTransmitter = $panjang - 20;

    $transmitterMapping = [
        40 => 172,
        60 => 171,
        80 => 170,
        100 => 173,
        120 => 162,
        140 => 166,
        160 => 167,
        180 => 168,
        200 => 169,
    ];

    $ukuranTransmitterFinal = $ukuranTransmitter;
    if (!isset($transmitterMapping[$ukuranTransmitter])) {
        $availableSizes = array_keys($transmitterMapping);
        sort($availableSizes);
        
        $found = false;
        for ($i = 0; $i < count($availableSizes); $i++) {
            if ($availableSizes[$i] >= $ukuranTransmitter) {
                $ukuranTransmitterFinal = $availableSizes[$i];
                $found = true;
                break;
            }
        }
        
        if (!$found) {
            $ukuranTransmitterFinal = max($availableSizes);
        }
    }

    $transmitterItem = null;
    $transmitterId = $transmitterMapping[$ukuranTransmitterFinal] ?? null;

    if ($transmitterId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $transmitterId) {
                $transmitterItem = $item;
                break;
            }
        }
    }

    $totalWindowHardwareTransmitterQty = 0;
    if ($transmitterItem) {
        $satuanTerkecil = (float)($transmitterItem->satuan_terkecil ?? 0);
        $qty = $jumlah * $satuanTerkecil;
        $transmitterItem->qty = $qty;
        $totalWindowHardwareTransmitterQty += $qty;
    }

    // === PERHITUNGAN WINDOW HARDWARE FRICTION STAY ===
    $ukuranFrictionStay = $panjang / 3;

    $frictionStayMapping = [
        25 => 175,
        30 => 174,
        35 => 179,
        40 => 173,
        45 => 176,
        50 => 177,
        60 => 178,
    ];

    $ukuranFrictionStayFinal = $ukuranFrictionStay;
    if (!isset($frictionStayMapping[$ukuranFrictionStay])) {
        $availableSizes = array_keys($frictionStayMapping);
        sort($availableSizes);
        
        $found = false;
        for ($i = 0; $i < count($availableSizes); $i++) {
            if ($availableSizes[$i] >= $ukuranFrictionStay) {
                $ukuranFrictionStayFinal = $availableSizes[$i];
                $found = true;
                break;
            }
        }
        
        if (!$found) {
            $ukuranFrictionStayFinal = max($availableSizes);
        }
    }

    $frictionStayItem = null;
    $frictionStayId = $frictionStayMapping[$ukuranFrictionStayFinal] ?? null;

    if ($frictionStayId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $frictionStayId) {
                $frictionStayItem = $item;
                break;
            }
        }
    }

    $totalWindowHardwareFrictionStayQty = 0;
    if ($frictionStayItem) {
        $satuanTerkecil = (float)($frictionStayItem->satuan_terkecil ?? 0);
        $qty = $jumlah * $satuanTerkecil;
        $frictionStayItem->qty = $qty;
        $totalWindowHardwareFrictionStayQty += $qty;
    }

    // === PERHITUNGAN WINDOW HARDWARE HANDLE ===
    $handleItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'window-hardware-handle') {
            $handleItem = $item;
            break;
        }
    }

    $totalWindowHardwareHandleQty = 0;
    if ($handleItem) {
        $satuanTerkecil = (float)($handleItem->satuan_terkecil ?? 0);
        $qty = $jumlah * $satuanTerkecil;
        $handleItem->qty = $qty;
        $totalWindowHardwareHandleQty += $qty;
    }

    // === PERHITUNGAN SCREW TRANSMITTER ===
    $screwTransmitterItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-transmitter') {
            $screwTransmitterItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewTransmitter = $screwTransmitterItem ? (float)$screwTransmitterItem->satuan_terkecil : 0;
    $screwTransmitterQty = ($totalWindowHardwareTransmitterQty * $satuanTerkecilScrewTransmitter) / 2;
    if ($screwTransmitterItem) {
        $screwTransmitterItem->qty = $screwTransmitterQty;
    }

    // === PERHITUNGAN SCREW FRICTION STAY ===
    $screwFrictionStayItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-friction-stay') {
            $screwFrictionStayItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewFrictionStay = $screwFrictionStayItem ? (float)$screwFrictionStayItem->satuan_terkecil : 0;
    $screwFrictionStayQty = $totalWindowHardwareFrictionStayQty * $satuanTerkecilScrewFrictionStay;
    if ($screwFrictionStayItem) {
        $screwFrictionStayItem->qty = $screwFrictionStayQty;
    }

    // === PERHITUNGAN SCREW HANDLE ===
    $screwHandleItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-handle') {
            $screwHandleItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewHandle = $screwHandleItem ? (float)$screwHandleItem->satuan_terkecil : 0;
    $screwHandleQty = $totalWindowHardwareHandleQty * $satuanTerkecilScrewHandle;
    if ($screwHandleItem) {
        $screwHandleItem->qty = $screwHandleQty;
    }

    // === PERHITUNGAN SETTING BLOCK ===
    $settingBlockItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'setting-block') {
            $settingBlockItem = $item;
            break;
        }
    }
    
    $satuanTerkecilSettingBlock = $settingBlockItem ? (float)$settingBlockItem->satuan_terkecil : 0;
    
    $variableC = 1 * $satuanTerkecilSettingBlock;
    $variableD = $variableC * $jumlah;
    $variableE = $variableD * 25;
    $variableF = $variableE / 1000;
    $settingBlockQty = ceil($variableF);

    // === PERHITUNGAN SCREW REINFORCEMENT ===
    $screwItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-reinforcement') {
            $screwItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrew = $screwItem ? (float)$screwItem->satuan_terkecil : 0;
    $screwQty = ((($totalLebar + $totalPanjang)) + ($variableSashVertikalB + $variableSashHorizontalB)) / $satuanTerkecilScrew;
    $screwQty = ceil($screwQty * 10);

    // === PERHITUNGAN QTY PER AKSESORIS ===
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        $areaSlug = $item->area ? $item->area->slug : '';
        $qty = 0;
        
        if ($areaSlug == 'profile-vertikal') {
            $qty = $batangVertikal;
        } elseif ($areaSlug == 'profile-horizontal') {
            $qty = $batangHorizontal;
        } elseif ($areaSlug == 'glaze-bead-vertical') {
            $qty = ($panjang / 100) * $jumlah;
        } elseif ($areaSlug == 'glaze-bead-horizontal') {
            $qty = ($lebar / 100) * $jumlah;
        } elseif ($areaSlug == 'reinforcement') {
            $qty = $reinforcementQty;
        } elseif ($areaSlug == 'reinforcement-sash') {
            $qty = $reinforcementSashQty;
        } elseif ($areaSlug == 'kaca') {
            $qty = $luasKacaTotal;
        } elseif ($areaSlug == 'screw-reinforcement') {
            $qty = $screwQty;
        } elseif ($areaSlug == 'setting-block') {
            $qty = $settingBlockQty;
        } elseif ($areaSlug == 'profile-sash-vertikal') {
            $qty = $batangSashVertikalQty;
        } elseif ($areaSlug == 'profile-sash-horizontal') {
            $qty = $batangSashHorizontalQty;
        } elseif ($areaSlug == 'window-hardware-transmitter') {
            $qty = ($transmitterItem && $transmitterItem->id == $item->id) ? $transmitterItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-friction-stay') {
            $qty = ($frictionStayItem && $frictionStayItem->id == $item->id) ? $frictionStayItem->qty : 0;
       } elseif ($areaSlug == 'window-hardware-handle-rambuncis' || $areaSlug == 'window-hardware-handle-multilock') {
    $qty = ($handleItem && $handleItem->id == $item->id) ? $handleItem->qty : 0;
} elseif ($areaSlug == 'screw-transmitter') {
            $qty = $screwTransmitterQty;
        } elseif ($areaSlug == 'screw-friction-stay') {
            $qty = $screwFrictionStayQty;
        } elseif ($areaSlug == 'screw-handle') {
            $qty = $screwHandleQty;
        } elseif ($areaSlug == 'profile-decoration-vertikal') {
            $qty = $batangDecorationVertikalQty;
        } elseif ($areaSlug == 'profile-decoration-horizontal') {
            $qty = $batangDecorationHorizontalQty;
        } else {
            $qty = $jumlah * ($item->satuan_terkecil ?? 1);
        }
        
        $item->qty = $qty;
    }

    // Data untuk view
    $data = [
        'produk' => $produkUtama,
        'panjang' => $panjang,
        'lebar' => $lebar,
        'tebal_kaca' => $tebalKaca,
        'jumlah' => $jumlah,
        'warna' => $warna,
        'type_kaca' => $typeKaca,
        
        'luas_kaca_per_unit' => $luasKacaPerUnit,
        'luas_kaca_total' => $luasKacaTotal,
        'keliling_per_unit' => $kelilingPerUnit,
        'keliling_total' => $kelilingTotal,
        
        'profile_vertikal' => $profileVertikal,
        'variable_a' => $variableA,
        'frame_vertikal' => $frameVertikal,
        'batang_vertikal' => $batangVertikal,
        
        'profile_horizontal' => $profileHorizontal,
        'satuan_terkecil_horizontal' => $satuanTerkecilHorizontal,
        'variable_b' => $variableB,
        'frame_horizontal' => $frameHorizontal,
        'batang_horizontal' => $batangHorizontal,
        
        'total_batang' => $totalBatang,
        'reinforcement_qty' => $reinforcementQty,
        
        'profile_sash_vertikal' => $profileSashVertikal,
        'satuan_terkecil_sash_vertikal' => $satuanTerkecilSashVertikal,
        'variable_sash_vertikal_a' => $variableSashVertikalA,
        'variable_sash_vertikal_b' => $variableSashVertikalB,
        'batang_sash_vertikal' => $batangSashVertikal,
        'batang_sash_vertikal_qty' => $batangSashVertikalQty,
        
        'profile_sash_horizontal' => $profileSashHorizontal,
        'satuan_terkecil_sash_horizontal' => $satuanTerkecilSashHorizontal,
        'variable_sash_horizontal_a' => $variableSashHorizontalA,
        'variable_sash_horizontal_b' => $variableSashHorizontalB,
        'batang_sash_horizontal' => $batangSashHorizontal,
        'batang_sash_horizontal_qty' => $batangSashHorizontalQty,
        
        'reinforcement_sash_qty' => $reinforcementSashQty,
        
        'decoration_bar_vertikal_input' => $decorationBarVertikalInput,
        'decoration_bar_vertikal_item' => $decorationBarVertikalItem,
        'batang_decoration_vertikal' => $batangDecorationVertikal,
        'batang_decoration_vertikal_qty' => $batangDecorationVertikalQty,
        
        'decoration_bar_horizontal_input' => $decorationBarHorizontalInput,
        'decoration_bar_horizontal_item' => $decorationBarHorizontalItem,
        'batang_decoration_horizontal' => $batangDecorationHorizontal,
        'batang_decoration_horizontal_qty' => $batangDecorationHorizontalQty,
        
        'total_decoration_bar_qty' => $totalDecorationBarQty,
        
        'transmitter_item' => $transmitterItem,
        'ukuran_transmitter' => $ukuranTransmitter,
        'ukuran_transmitter_final' => $ukuranTransmitterFinal,
        'total_window_hardware_transmitter_qty' => $totalWindowHardwareTransmitterQty,
        
        'friction_stay_item' => $frictionStayItem,
        'ukuran_friction_stay' => $ukuranFrictionStay,
        'ukuran_friction_stay_final' => $ukuranFrictionStayFinal,
        'total_window_hardware_friction_stay_qty' => $totalWindowHardwareFrictionStayQty,
        
        'handle_item' => $handleItem,
        'total_window_hardware_handle_qty' => $totalWindowHardwareHandleQty,
        
        'screw_transmitter_item' => $screwTransmitterItem,
        'screw_transmitter_qty' => $screwTransmitterQty,
        
        'screw_friction_stay_item' => $screwFrictionStayItem,
        'screw_friction_stay_qty' => $screwFrictionStayQty,
        
        'screw_handle_item' => $screwHandleItem,
        'screw_handle_qty' => $screwHandleQty,
        
        'satuan_terkecil_screw' => $satuanTerkecilScrew,
        'screw_qty' => $screwQty,
        
        'setting_block_item' => $settingBlockItem,
        'satuan_terkecil_setting_block' => $satuanTerkecilSettingBlock,
        'variable_c' => $variableC,
        'variable_d' => $variableD,
        'variable_e' => $variableE,
        'variable_f' => $variableF,
        'setting_block_qty' => $settingBlockQty,
        
        'aksesoris' => $aksesoris,
    ];

    return view('boq.jendela.jendela-swing-1', $data);
}
public function exportPdfSwing1(Request $request)
{
    $panjang = $request->panjang;
    $lebar = $request->lebar;
    $tebal_kaca = $request->tebal_kaca;
    $jumlah = $request->jumlah;
    $warna = $request->warna;
    $type_kaca = $request->type_kaca;
    $judul = $request->judul ?? 'BOQ - Jendela Swing 1 Daun';

    // Ambil data aksesoris
    $aksesorisIds = ProductAccessories::where('parent_product_id', 155)->pluck('accessory_id');
    $aksesoris = Product::with('area', 'unit')
        ->whereIn('id', $aksesorisIds)
        ->get();

    // === PERHITUNGAN DASAR ===
    $panjangM = $panjang / 100;
    $lebarM = $lebar / 100;
    
    $luasKacaPerUnit = $panjangM * $lebarM;
    $luasKacaTotal = $luasKacaPerUnit * $jumlah;
    $luasKacaTotal = ceil($luasKacaTotal * 10) / 10;

    $kelilingPerUnit = 2 * ($panjangM + $lebarM);
    $kelilingTotal = $kelilingPerUnit * $jumlah;

    // === PERHITUNGAN PROFILE VERTIKAL ===
    $profileVertikal = null;
    $aksesorisCount = count($aksesoris);
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-vertikal') {
            $profileVertikal = $item;
            break;
        }
    }
    $satuanTerkecilVertikal = $profileVertikal ? (float)$profileVertikal->satuan_terkecil : 0;

    $variableA = $jumlah * $satuanTerkecilVertikal;
    $frameVertikal = $variableA * $panjang;
    $batangVertikal = $frameVertikal / 580;
    $batangVertikal = ceil($batangVertikal * 10) / 10;
    $totalPanjang = $panjang * $variableA;

    // === PERHITUNGAN PROFILE HORIZONTAL ===
    $profileHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-horizontal') {
            $profileHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilHorizontal = $profileHorizontal ? (float)$profileHorizontal->satuan_terkecil : 0;
    
    $variableB = $jumlah * $satuanTerkecilHorizontal;
    $frameHorizontal = $variableB * $lebar;
    $batangHorizontal = $frameHorizontal / 580;
    $batangHorizontal = ceil($batangHorizontal * 10) / 10;
    $totalLebar = $lebar * $variableB;

    // === PERHITUNGAN REINFORCEMENT ===
    $totalBatang = ($frameVertikal + $frameHorizontal) / 600;
    $reinforcementQty = ceil($totalBatang * 10) / 10;

    // === PERHITUNGAN PROFILE SASH VERTIKAL ===
    $profileSashVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-vertikal') {
            $profileSashVertikal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashVertikal = $profileSashVertikal ? (float)$profileSashVertikal->satuan_terkecil : 0;
    
    $variableSashVertikalA = $satuanTerkecilSashVertikal * $jumlah;
    $variableSashVertikalB = $variableSashVertikalA * $panjang;
    $batangSashVertikal = $variableSashVertikalB / 580;
    $batangSashVertikalQty = ceil($batangSashVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE SASH HORIZONTAL ===
    $profileSashHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-horizontal') {
            $profileSashHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashHorizontal = $profileSashHorizontal ? (float)$profileSashHorizontal->satuan_terkecil : 0;
    
    $variableSashHorizontalA = $satuanTerkecilSashHorizontal * $jumlah;
    $variableSashHorizontalB = $variableSashHorizontalA * $lebar;
    $batangSashHorizontal = $variableSashHorizontalB / 580;
    $batangSashHorizontalQty = ceil($batangSashHorizontal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT SASH ===
    $totalBatangSash = ($variableSashVertikalB + $variableSashHorizontalB) / 600;
    $reinforcementSashQty = ceil($totalBatangSash * 10) / 10;

    // === PERHITUNGAN DECORATION BAR ===
    $decorationBarVertikalInput = (int)($request->decoration_bar_vertikal ?? 0);
    $decorationBarVertikalItem = null;
    $batangDecorationVertikal = 0;
    $batangDecorationVertikalQty = 0;

    if ($decorationBarVertikalInput > 0) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'profile-decoration-vertikal') {
                $decorationBarVertikalItem = $item;
                break;
            }
        }
        if ($decorationBarVertikalItem) {
            $satuanTerkecil = (float)($decorationBarVertikalItem->satuan_terkecil ?? 0);
            $variableDecorationVertikalA = $decorationBarVertikalInput * $jumlah * 2;
            $variableDecorationVertikalB = $variableDecorationVertikalA * $panjang;
            $batangDecorationVertikal = $variableDecorationVertikalB / 580;
            $batangDecorationVertikalQty = ceil($batangDecorationVertikal * 10) / 10;
            $decorationBarVertikalItem->qty = $batangDecorationVertikalQty;
        }
    }

    $decorationBarHorizontalInput = (int)($request->decoration_bar_horizontal ?? 0);
    $decorationBarHorizontalItem = null;
    $batangDecorationHorizontal = 0;
    $batangDecorationHorizontalQty = 0;

    if ($decorationBarHorizontalInput > 0) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'profile-decoration-horizontal') {
                $decorationBarHorizontalItem = $item;
                break;
            }
        }
        if ($decorationBarHorizontalItem) {
            $satuanTerkecil = (float)($decorationBarHorizontalItem->satuan_terkecil ?? 0);
            $variableDecorationHorizontalA = $decorationBarHorizontalInput * $jumlah * 2;
            $variableDecorationHorizontalB = $variableDecorationHorizontalA * $lebar;
            $batangDecorationHorizontal = $variableDecorationHorizontalB / 580;
            $batangDecorationHorizontalQty = ceil($batangDecorationHorizontal * 10) / 10;
            $decorationBarHorizontalItem->qty = $batangDecorationHorizontalQty;
        }
    }

    $totalDecorationBarQty = ceil(($batangDecorationVertikal + $batangDecorationHorizontal) * 10) / 10;

    // === PERHITUNGAN WINDOW HARDWARE TRANSMITTER ===
    $ukuranTransmitter = $panjang - 20;

    $transmitterMapping = [
        40 => 172,
        60 => 171,
        80 => 170,
        100 => 173,
        120 => 162,
        140 => 166,
        160 => 167,
        180 => 168,
        200 => 169,
    ];

    $ukuranTransmitterFinal = $ukuranTransmitter;
    if (!isset($transmitterMapping[$ukuranTransmitter])) {
        $availableSizes = array_keys($transmitterMapping);
        sort($availableSizes);
        
        $found = false;
        for ($i = 0; $i < count($availableSizes); $i++) {
            if ($availableSizes[$i] >= $ukuranTransmitter) {
                $ukuranTransmitterFinal = $availableSizes[$i];
                $found = true;
                break;
            }
        }
        
        if (!$found) {
            $ukuranTransmitterFinal = max($availableSizes);
        }
    }

    $transmitterItem = null;
    $transmitterId = $transmitterMapping[$ukuranTransmitterFinal] ?? null;

    if ($transmitterId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $transmitterId) {
                $transmitterItem = $item;
                break;
            }
        }
    }

    $totalWindowHardwareTransmitterQty = 0;
    if ($transmitterItem) {
        $satuanTerkecil = (float)($transmitterItem->satuan_terkecil ?? 0);
        $qty = $jumlah * $satuanTerkecil;
        $transmitterItem->qty = $qty;
        $totalWindowHardwareTransmitterQty += $qty;
    }

    // === PERHITUNGAN WINDOW HARDWARE FRICTION STAY ===
    $ukuranFrictionStay = $panjang / 3;

    $frictionStayMapping = [
        25 => 175,
        30 => 174,
        35 => 179,
        40 => 173,
        45 => 176,
        50 => 177,
        60 => 178,
    ];

    $ukuranFrictionStayFinal = $ukuranFrictionStay;
    if (!isset($frictionStayMapping[$ukuranFrictionStay])) {
        $availableSizes = array_keys($frictionStayMapping);
        sort($availableSizes);
        
        $found = false;
        for ($i = 0; $i < count($availableSizes); $i++) {
            if ($availableSizes[$i] >= $ukuranFrictionStay) {
                $ukuranFrictionStayFinal = $availableSizes[$i];
                $found = true;
                break;
            }
        }
        
        if (!$found) {
            $ukuranFrictionStayFinal = max($availableSizes);
        }
    }

    $frictionStayItem = null;
    $frictionStayId = $frictionStayMapping[$ukuranFrictionStayFinal] ?? null;

    if ($frictionStayId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $frictionStayId) {
                $frictionStayItem = $item;
                break;
            }
        }
    }

    $totalWindowHardwareFrictionStayQty = 0;
    if ($frictionStayItem) {
        $satuanTerkecil = (float)($frictionStayItem->satuan_terkecil ?? 0);
        $qty = $jumlah * $satuanTerkecil;
        $frictionStayItem->qty = $qty;
        $totalWindowHardwareFrictionStayQty += $qty;
    }

    // === PERHITUNGAN WINDOW HARDWARE HANDLE ===
    $handleItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'window-hardware-handle') {
            $handleItem = $item;
            break;
        }
    }

    $totalWindowHardwareHandleQty = 0;
    if ($handleItem) {
        $satuanTerkecil = (float)($handleItem->satuan_terkecil ?? 0);
        $qty = $jumlah * $satuanTerkecil;
        $handleItem->qty = $qty;
        $totalWindowHardwareHandleQty += $qty;
    }

    // === PERHITUNGAN SCREW TRANSMITTER ===
    $screwTransmitterItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-transmitter') {
            $screwTransmitterItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewTransmitter = $screwTransmitterItem ? (float)$screwTransmitterItem->satuan_terkecil : 0;
    $screwTransmitterQty = ($totalWindowHardwareTransmitterQty * $satuanTerkecilScrewTransmitter) / 2;
    if ($screwTransmitterItem) {
        $screwTransmitterItem->qty = $screwTransmitterQty;
    }

    // === PERHITUNGAN SCREW FRICTION STAY ===
    $screwFrictionStayItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-friction-stay') {
            $screwFrictionStayItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewFrictionStay = $screwFrictionStayItem ? (float)$screwFrictionStayItem->satuan_terkecil : 0;
    $screwFrictionStayQty = $totalWindowHardwareFrictionStayQty * $satuanTerkecilScrewFrictionStay;
    if ($screwFrictionStayItem) {
        $screwFrictionStayItem->qty = $screwFrictionStayQty;
    }

    // === PERHITUNGAN SCREW HANDLE ===
    $screwHandleItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-handle') {
            $screwHandleItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewHandle = $screwHandleItem ? (float)$screwHandleItem->satuan_terkecil : 0;
    $screwHandleQty = $totalWindowHardwareHandleQty * $satuanTerkecilScrewHandle;
    if ($screwHandleItem) {
        $screwHandleItem->qty = $screwHandleQty;
    }

    // === PERHITUNGAN SETTING BLOCK ===
    $settingBlockItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'setting-block') {
            $settingBlockItem = $item;
            break;
        }
    }
    
    $satuanTerkecilSettingBlock = $settingBlockItem ? (float)$settingBlockItem->satuan_terkecil : 0;
    
    $variableC = 1 * $satuanTerkecilSettingBlock;
    $variableD = $variableC * $jumlah;
    $variableE = $variableD * 25;
    $variableF = $variableE / 1000;
    $settingBlockQty = ceil($variableF);

    // === PERHITUNGAN SCREW REINFORCEMENT ===
    $screwItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-reinforcement') {
            $screwItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrew = $screwItem ? (float)$screwItem->satuan_terkecil : 0;
    $screwQty = ((($totalLebar + $totalPanjang)) + ($variableSashVertikalB + $variableSashHorizontalB)) / $satuanTerkecilScrew;
    $screwQty = ceil($screwQty * 10);

    // === HITUNG QTY PER AKSESORIS ===
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        $areaSlug = $item->area ? $item->area->slug : '';
        $qty = 0;
        
        if ($areaSlug == 'profile-vertikal') {
            $qty = $batangVertikal;
        } elseif ($areaSlug == 'profile-horizontal') {
            $qty = $batangHorizontal;
        } elseif ($areaSlug == 'glaze-bead-vertical') {
            $qty = ($panjang / 100) * $jumlah;
        } elseif ($areaSlug == 'glaze-bead-horizontal') {
            $qty = ($lebar / 100) * $jumlah;
        } elseif ($areaSlug == 'reinforcement') {
            $qty = $reinforcementQty;
        } elseif ($areaSlug == 'reinforcement-sash') {
            $qty = $reinforcementSashQty;
        } elseif ($areaSlug == 'kaca') {
            $qty = $luasKacaTotal;
        } elseif ($areaSlug == 'screw-reinforcement') {
            $qty = $screwQty;
        } elseif ($areaSlug == 'setting-block') {
            $qty = $settingBlockQty;
        } elseif ($areaSlug == 'profile-sash-vertikal') {
            $qty = $batangSashVertikalQty;
        } elseif ($areaSlug == 'profile-sash-horizontal') {
            $qty = $batangSashHorizontalQty;
        } elseif ($areaSlug == 'window-hardware-transmitter') {
            $qty = ($transmitterItem && $transmitterItem->id == $item->id) ? $transmitterItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-friction-stay') {
            $qty = ($frictionStayItem && $frictionStayItem->id == $item->id) ? $frictionStayItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-handle') {
            $qty = $handleItem ? $handleItem->qty : 0;
        } elseif ($areaSlug == 'screw-transmitter') {
            $qty = $screwTransmitterQty;
        } elseif ($areaSlug == 'screw-friction-stay') {
            $qty = $screwFrictionStayQty;
        } elseif ($areaSlug == 'screw-handle') {
            $qty = $screwHandleQty;
        } elseif ($areaSlug == 'profile-decoration-vertikal') {
            $qty = $batangDecorationVertikalQty;
        } elseif ($areaSlug == 'profile-decoration-horizontal') {
            $qty = $batangDecorationHorizontalQty;
        } else {
            $qty = $jumlah * ($item->satuan_terkecil ?? 1);
        }
        
        $item->qty = $qty;
    }

    // Kelompokkan berdasarkan area
    $grouped = [];
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->qty <= 0) {
            continue;
        }
        
        // Skip window hardware yang tidak terpilih (qty 0)
        if ($item->area && ($item->area->slug == 'window-hardware-transmitter' || $item->area->slug == 'window-hardware-friction-stay' || $item->area->slug == 'window-hardware-handle') && $item->qty <= 0) {
            continue;
        }
        
        $areaSlug = $item->area ? $item->area->slug : 'lainnya';
        
        if (str_starts_with($areaSlug, 'profile')) {
            $groupKey = 'profile';
        } elseif ($areaSlug == 'setting-block') {
            $groupKey = 'kaca';
        } elseif ($areaSlug == 'reinforcement' || $areaSlug == 'reinforcement-sash') {
            $groupKey = 'reinforcement';
        } elseif (str_starts_with($areaSlug, 'window-hardware')) {
            $groupKey = 'window-hardware';
        } elseif ($areaSlug == 'screw-reinforcement' || $areaSlug == 'screw-transmitter' || $areaSlug == 'screw-friction-stay' || $areaSlug == 'screw-handle') {
            $groupKey = 'screw';
        } else {
            $groupKey = $areaSlug;
        }
        
        if (!isset($grouped[$groupKey])) {
            $grouped[$groupKey] = [];
        }
        $grouped[$groupKey][] = $item;
    }

    $areaLabels = [
        'profile' => 'PROFILE',
        'reinforcement' => 'REINFORCEMENT',
        'kaca' => 'KACA',
        'screw' => 'SCREW',
        'window-hardware' => 'WINDOW HARDWARE',
    ];

    // ============ GENERATE NOMOR BOQ ============
    $nomorBoq = Boq::generateNomorBoq();

    // ============ STORE BOQ ============
    try {
        $allResults = [];
        
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->qty > 0) {
                $allResults[] = [
                    'produk_id' => $item->id,
                    'qty' => $item->qty,
                    'nama_produk' => $item->nama_produk,
                ];
            }
        }
        
        $uniqueResults = [];
        $seenIds = [];
        $allResultsCount = count($allResults);
        
        for ($i = 0; $i < $allResultsCount; $i++) {
            $item = $allResults[$i];
            $produkId = $item['produk_id'] ?? null;
            
            if (!$produkId) {
                continue;
            }
            
            $isDuplicate = false;
            $seenCount = count($seenIds);
            for ($j = 0; $j < $seenCount; $j++) {
                if ($seenIds[$j] == $produkId) {
                    $isDuplicate = true;
                    break;
                }
            }
            
            if ($isDuplicate) {
                continue;
            }
            
            $seenIds[] = $produkId;
            $uniqueResults[] = $item;
        }
        
        if (count($uniqueResults) > 0) {
            $boq = new Boq();
            $boq->nomor_boq = $nomorBoq;
            $boq->tanggal_boq = now();
            $boq->save();
            
            $uniqueCount = count($uniqueResults);
            for ($i = 0; $i < $uniqueCount; $i++) {
                $item = $uniqueResults[$i];
                $produkId = $item['produk_id'] ?? null;
                $qty = (int)($item['qty'] ?? 0);
                
                if ($produkId && $qty > 0) {
                    $produk = Product::find($produkId);
                    
                    \DB::table('detail_boq')->insert([
                        'boq_id' => $boq->id,
                        'produk_id' => $produkId,
                        'kode_produk' => $produk ? $produk->kode_produk : null,
                        'qty' => $qty,
                        'created_at' => now(),
                        'updated_at' => now()
                    ]);
                }
            }
            
            \Log::info('BOQ SAVED JENDELA SWING 1:', [
                'boq_id' => $boq->id,
                'nomor_boq' => $nomorBoq,
                'total' => count($uniqueResults)
            ]);
        }
        
    } catch (\Exception $e) {
        \Log::error('Error saving BOQ Jendela Swing 1: ' . $e->getMessage());
        \Log::error($e->getTraceAsString());
    }

    $data = [
        'judul' => $judul,
        'panjang' => $panjang,
        'lebar' => $lebar,
        'tebal_kaca' => $tebal_kaca,
        'jumlah' => $jumlah,
        'warna' => $warna,
        'type_kaca' => $type_kaca,
        'luas_kaca_total' => $luasKacaTotal,
        'keliling_total' => $kelilingTotal,
        'batang_vertikal' => $batangVertikal,
        'batang_horizontal' => $batangHorizontal,
        'reinforcement_qty' => $reinforcementQty,
        'reinforcement_sash_qty' => $reinforcementSashQty,
        'batang_sash_vertikal_qty' => $batangSashVertikalQty,
        'batang_sash_horizontal_qty' => $batangSashHorizontalQty,
        'total_decoration_bar_qty' => $totalDecorationBarQty,
        'transmitter_item' => $transmitterItem,
        'ukuran_transmitter' => $ukuranTransmitter,
        'ukuran_transmitter_final' => $ukuranTransmitterFinal,
        'total_window_hardware_transmitter_qty' => $totalWindowHardwareTransmitterQty,
        'friction_stay_item' => $frictionStayItem,
        'ukuran_friction_stay' => $ukuranFrictionStay,
        'ukuran_friction_stay_final' => $ukuranFrictionStayFinal,
        'total_window_hardware_friction_stay_qty' => $totalWindowHardwareFrictionStayQty,
        'handle_item' => $handleItem,
        'total_window_hardware_handle_qty' => $totalWindowHardwareHandleQty,
        'screw_transmitter_qty' => $screwTransmitterQty,
        'screw_friction_stay_qty' => $screwFrictionStayQty,
        'screw_handle_qty' => $screwHandleQty,
        'screw_qty' => $screwQty,
        'setting_block_qty' => $settingBlockQty,
        'grouped' => $grouped,
        'areaLabels' => $areaLabels,
        'nomor_boq' => $nomorBoq,
    ];

    return view('boq.jendela.pdf-jendela-swing-1', compact('data'));
}

public function hitungSwing2(Request $request)
{
    $request->validate([
        'panjang' => 'required|numeric|min:1',
        'lebar' => 'required|numeric|min:1',
        'tebal_kaca' => 'required|numeric|min:1',
        'jumlah' => 'required|numeric|min:1',
        'warna' => 'required|string',
        'type_kaca' => 'required|string',
    ]);

    // Ambil data dari form
    $panjang = $request->panjang; // cm
    $lebar = $request->lebar; // cm
    $tebalKaca = $request->tebal_kaca; // mm
    $jumlah = $request->jumlah;
    $warna = $request->warna;
    $typeKaca = $request->type_kaca;

    // Ambil produk utama (Jendela Swing 2) dari database
    $produkUtama = Product::find(180);
    
    if (!$produkUtama) {
        return back()->with('error', 'Produk Jendela Swing 2 tidak ditemukan!');
    }

    // Ambil aksesoris dari tabel product_accessories dengan relasi area
    $aksesorisIds = ProductAccessories::where('parent_product_id', 180)->pluck('accessory_id');
    $aksesoris = Product::with('area', 'unit')
        ->whereIn('id', $aksesorisIds)
        ->get();

    // === PERHITUNGAN DASAR ===
    
    // Konversi ke meter
    $panjangM = $panjang / 100;
    $lebarM = $lebar / 100;
    $tebalKacaM = $tebalKaca / 1000;

    // 1. Luas Kaca (m²)
    $luasKacaPerUnit = $panjangM * $lebarM;
    $luasKacaTotal = $luasKacaPerUnit * $jumlah;
    $luasKacaTotal = ceil($luasKacaTotal * 10) / 10;

    // 2. Keliling Profile (meter)
    $kelilingPerUnit = 2 * ($panjangM + $lebarM);
    $kelilingTotal = $kelilingPerUnit * $jumlah;

    // === PERHITUNGAN PROFILE VERTIKAL ===
    $profileVertikal = null;
    $aksesorisCount = count($aksesoris);
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-vertikal') {
            $profileVertikal = $item;
            break;
        }
    }
    $satuanTerkecilVertikal = $profileVertikal ? (float)$profileVertikal->satuan_terkecil : 0;

    $variableA = $jumlah * 4;
    $frameVertikal = $variableA * $panjang;
    $batangVertikal = $frameVertikal / 580;
    $batangVertikal = ceil($batangVertikal * 10) / 10;
    $totalPanjang = $panjang * $variableA;

    // === PERHITUNGAN PROFILE HORIZONTAL ===
    $profileHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-horizontal') {
            $profileHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilHorizontal = $profileHorizontal ? (float)$profileHorizontal->satuan_terkecil : 0;
    
    $variableB = $jumlah * $satuanTerkecilHorizontal;
    $frameHorizontal = $variableB * $lebar;
    $batangHorizontal = $frameHorizontal / 580;
    $batangHorizontal = ceil($batangHorizontal * 10) / 10;
    $totalLebar = $lebar * $variableB;

    // === PERHITUNGAN REINFORCEMENT ===
    $totalBatang = ($frameVertikal + $frameHorizontal) / 600;
    $reinforcementQty = ceil($totalBatang * 10) / 10;

    // === PERHITUNGAN PROFILE SASH VERTIKAL ===
    $profileSashVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-vertikal') {
            $profileSashVertikal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashVertikal = $profileSashVertikal ? (float)$profileSashVertikal->satuan_terkecil : 0;
    
    $variableSashVertikalA = 4 * $jumlah;
    $variableSashVertikalB = $variableSashVertikalA * $panjang;
    $batangSashVertikal = $variableSashVertikalB / 580;
    $batangSashVertikalQty = ceil($batangSashVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE SASH HORIZONTAL ===
    $profileSashHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-horizontal') {
            $profileSashHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashHorizontal = $profileSashHorizontal ? (float)$profileSashHorizontal->satuan_terkecil : 0;
    
    $variableSashHorizontalA = $satuanTerkecilSashHorizontal * $jumlah;
    $variableSashHorizontalB = $variableSashHorizontalA * $lebar;
    $batangSashHorizontal = $variableSashHorizontalB / 580;
    $batangSashHorizontalQty = ceil($batangSashHorizontal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT SASH ===
    $totalBatangSash = ($variableSashVertikalB + $variableSashHorizontalB) / 600;
    $reinforcementSashQty = ceil($totalBatangSash * 10) / 10;

    // === PERHITUNGAN PROFILE COUPLING VERTIKAL ===
    $profileCouplingVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-coupling-vertikal') {
            $profileCouplingVertikal = $item;
            break;
        }
    }
    
    $satuanTerkecilCoupling = $profileCouplingVertikal ? (float)$profileCouplingVertikal->satuan_terkecil : 0;
    
    // variable coupling a = satuan terkecil x jumlah x 2
    $variableCouplingA = $satuanTerkecilCoupling * $jumlah * 2;
    
    // variable coupling b = variable coupling a x panjang
    $variableCouplingB = $variableCouplingA * $panjang;
    
    // variable batang coupling = variable coupling b / 580
    $batangCoupling = $variableCouplingB / 580;
    
    // qty = round up, 1 desimal
    $batangCouplingQty = ceil($batangCoupling * 10) / 10;

    // === PERHITUNGAN DECORATION BAR ===
    $decorationBarVertikalInput = (int)($request->decoration_bar_vertikal ?? 0);
    $decorationBarVertikalItem = null;
    $batangDecorationVertikal = 0;
    $batangDecorationVertikalQty = 0;

    if ($decorationBarVertikalInput > 0) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'profile-decoration-vertikal') {
                $decorationBarVertikalItem = $item;
                break;
            }
        }
        if ($decorationBarVertikalItem) {
            $satuanTerkecil = (float)($decorationBarVertikalItem->satuan_terkecil ?? 0);
            $variableDecorationVertikalA = $decorationBarVertikalInput * $jumlah * 2;
            $variableDecorationVertikalB = $variableDecorationVertikalA * $panjang;
            $batangDecorationVertikal = $variableDecorationVertikalB / 580;
            $batangDecorationVertikalQty = ceil($batangDecorationVertikal * 10) / 10;
            $decorationBarVertikalItem->qty = $batangDecorationVertikalQty;
        }
    }

    $decorationBarHorizontalInput = (int)($request->decoration_bar_horizontal ?? 0);
    $decorationBarHorizontalItem = null;
    $batangDecorationHorizontal = 0;
    $batangDecorationHorizontalQty = 0;

    if ($decorationBarHorizontalInput > 0) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'profile-decoration-horizontal') {
                $decorationBarHorizontalItem = $item;
                break;
            }
        }
        if ($decorationBarHorizontalItem) {
            $satuanTerkecil = (float)($decorationBarHorizontalItem->satuan_terkecil ?? 0);
            $variableDecorationHorizontalA = $decorationBarHorizontalInput * $jumlah * 2;
            $variableDecorationHorizontalB = $variableDecorationHorizontalA * $lebar;
            $batangDecorationHorizontal = $variableDecorationHorizontalB / 580;
            $batangDecorationHorizontalQty = ceil($batangDecorationHorizontal * 10) / 10;
            $decorationBarHorizontalItem->qty = $batangDecorationHorizontalQty;
        }
    }

    $totalDecorationBarQty = ceil(($batangDecorationVertikal + $batangDecorationHorizontal) * 10) / 10;

    // === PERHITUNGAN WINDOW HARDWARE TRANSMITTER ===
    $ukuranTransmitter = $panjang - 20;

    $transmitterMapping = [
        40 => 172,
        60 => 171,
        80 => 170,
        100 => 173,
        120 => 162,
        140 => 166,
        160 => 167,
        180 => 168,
        200 => 169,
    ];

    $ukuranTransmitterFinal = $ukuranTransmitter;
    if (!isset($transmitterMapping[$ukuranTransmitter])) {
        $availableSizes = array_keys($transmitterMapping);
        sort($availableSizes);
        
        $found = false;
        for ($i = 0; $i < count($availableSizes); $i++) {
            if ($availableSizes[$i] >= $ukuranTransmitter) {
                $ukuranTransmitterFinal = $availableSizes[$i];
                $found = true;
                break;
            }
        }
        
        if (!$found) {
            $ukuranTransmitterFinal = max($availableSizes);
        }
    }

    $transmitterItem = null;
    $transmitterId = $transmitterMapping[$ukuranTransmitterFinal] ?? null;

    if ($transmitterId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $transmitterId) {
                $transmitterItem = $item;
                break;
            }
        }
    }

    $totalWindowHardwareTransmitterQty = 0;
    if ($transmitterItem) {
        $satuanTerkecil = (float)($transmitterItem->satuan_terkecil ?? 0);
        $qty = $jumlah * 2;
        $transmitterItem->qty = $qty;
        $totalWindowHardwareTransmitterQty += $qty;
    }

    // === PERHITUNGAN WINDOW HARDWARE FRICTION STAY ===
    $ukuranFrictionStay = $panjang / 3;

    $frictionStayMapping = [
        25 => 175,
        30 => 174,
        35 => 179,
        40 => 173,
        45 => 176,
        50 => 177,
        60 => 178,
    ];

    $ukuranFrictionStayFinal = $ukuranFrictionStay;
    if (!isset($frictionStayMapping[$ukuranFrictionStay])) {
        $availableSizes = array_keys($frictionStayMapping);
        sort($availableSizes);
        
        $found = false;
        for ($i = 0; $i < count($availableSizes); $i++) {
            if ($availableSizes[$i] >= $ukuranFrictionStay) {
                $ukuranFrictionStayFinal = $availableSizes[$i];
                $found = true;
                break;
            }
        }
        
        if (!$found) {
            $ukuranFrictionStayFinal = max($availableSizes);
        }
    }

    $frictionStayItem = null;
    $frictionStayId = $frictionStayMapping[$ukuranFrictionStayFinal] ?? null;

    if ($frictionStayId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $frictionStayId) {
                $frictionStayItem = $item;
                break;
            }
        }
    }

    $totalWindowHardwareFrictionStayQty = 0;
    if ($frictionStayItem) {
        $satuanTerkecil = (float)($frictionStayItem->satuan_terkecil ?? 0);
        $qty = $jumlah * 4;
        $frictionStayItem->qty = $qty;
        $totalWindowHardwareFrictionStayQty += $qty;
    }

    // === PERHITUNGAN WINDOW HARDWARE HANDLE ===
    $handleItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'window-hardware-handle') {
            $handleItem = $item;
            break;
        }
    }

    $totalWindowHardwareHandleQty = 0;
    if ($handleItem) {
        $satuanTerkecil = (float)($handleItem->satuan_terkecil ?? 0);
        $qty = $jumlah * 2;
        $handleItem->qty = $qty;
        $totalWindowHardwareHandleQty += $qty;
    }

    // === PERHITUNGAN SCREW TRANSMITTER ===
    $screwTransmitterItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-transmitter') {
            $screwTransmitterItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewTransmitter = $screwTransmitterItem ? (float)$screwTransmitterItem->satuan_terkecil : 0;
    $screwTransmitterQty = ($totalWindowHardwareTransmitterQty * $satuanTerkecilScrewTransmitter);
    if ($screwTransmitterItem) {
        $screwTransmitterItem->qty = $screwTransmitterQty;
    }

    // === PERHITUNGAN SCREW FRICTION STAY ===
    $screwFrictionStayItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-friction-stay') {
            $screwFrictionStayItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewFrictionStay = $screwFrictionStayItem ? (float)$screwFrictionStayItem->satuan_terkecil : 0;
    $screwFrictionStayQty = $totalWindowHardwareFrictionStayQty * $satuanTerkecilScrewFrictionStay;
    if ($screwFrictionStayItem) {
        $screwFrictionStayItem->qty = $screwFrictionStayQty;
    }

    // === PERHITUNGAN SCREW HANDLE ===
    $screwHandleItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-handle') {
            $screwHandleItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewHandle = $screwHandleItem ? (float)$screwHandleItem->satuan_terkecil : 0;
    $screwHandleQty = $totalWindowHardwareHandleQty * $satuanTerkecilScrewHandle;
    if ($screwHandleItem) {
        $screwHandleItem->qty = $screwHandleQty;
    }

    // === PERHITUNGAN SETTING BLOCK ===
    $settingBlockItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'setting-block') {
            $settingBlockItem = $item;
            break;
        }
    }
    
    $satuanTerkecilSettingBlock = $settingBlockItem ? (float)$settingBlockItem->satuan_terkecil : 0;
    
    $variableC = 2 * $satuanTerkecilSettingBlock;
    $variableD = $variableC * $jumlah;
    $variableE = $variableD * 25;
    $variableF = $variableE / 1000;
    $settingBlockQty = ceil($variableF);

    // === PERHITUNGAN SCREW REINFORCEMENT ===
    $screwItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-reinforcement') {
            $screwItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrew = $screwItem ? (float)$screwItem->satuan_terkecil : 0;
    $screwQty = ((($totalLebar + $totalPanjang)) + ($variableSashVertikalB + $variableSashHorizontalB)) / $satuanTerkecilScrew;
    $screwQty = ceil($screwQty * 10);

    // === PERHITUNGAN QTY PER AKSESORIS ===
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        $areaSlug = $item->area ? $item->area->slug : '';
        $qty = 0;
        
        if ($areaSlug == 'profile-vertikal') {
            $qty = $batangVertikal;
        } elseif ($areaSlug == 'profile-horizontal') {
            $qty = $batangHorizontal;
        } elseif ($areaSlug == 'glaze-bead-vertical') {
            $qty = ($panjang / 100) * $jumlah;
        } elseif ($areaSlug == 'glaze-bead-horizontal') {
            $qty = ($lebar / 100) * $jumlah;
        } elseif ($areaSlug == 'reinforcement') {
            $qty = $reinforcementQty;
        } elseif ($areaSlug == 'reinforcement-sash') {
            $qty = $reinforcementSashQty;
        } elseif ($areaSlug == 'kaca') {
            $qty = $luasKacaTotal;
        } elseif ($areaSlug == 'screw-reinforcement') {
            $qty = $screwQty;
        } elseif ($areaSlug == 'setting-block') {
            $qty = $settingBlockQty;
        } elseif ($areaSlug == 'profile-sash-vertikal') {
            $qty = $batangSashVertikalQty;
        } elseif ($areaSlug == 'profile-sash-horizontal') {
            $qty = $batangSashHorizontalQty;
        } elseif ($areaSlug == 'window-hardware-transmitter') {
            $qty = ($transmitterItem && $transmitterItem->id == $item->id) ? $transmitterItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-friction-stay') {
            $qty = ($frictionStayItem && $frictionStayItem->id == $item->id) ? $frictionStayItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-handle') {
            $qty = $handleItem ? $handleItem->qty : 0;
        } elseif ($areaSlug == 'profile-coupling-vertikal') {
            $qty = $batangCouplingQty;
        } elseif ($areaSlug == 'screw-transmitter') {
            $qty = $screwTransmitterQty;
        } elseif ($areaSlug == 'screw-friction-stay') {
            $qty = $screwFrictionStayQty;
        } elseif ($areaSlug == 'screw-handle') {
            $qty = $screwHandleQty;
        } elseif ($areaSlug == 'profile-decoration-vertikal') {
            $qty = $batangDecorationVertikalQty;
        } elseif ($areaSlug == 'profile-decoration-horizontal') {
            $qty = $batangDecorationHorizontalQty;
        } else {
            $qty = $jumlah * ($item->satuan_terkecil ?? 1);
        }
        
        $item->qty = $qty;
    }

    // Data untuk view
    $data = [
        'produk' => $produkUtama,
        'panjang' => $panjang,
        'lebar' => $lebar,
        'tebal_kaca' => $tebalKaca,
        'jumlah' => $jumlah,
        'warna' => $warna,
        'type_kaca' => $typeKaca,
        
        'luas_kaca_per_unit' => $luasKacaPerUnit,
        'luas_kaca_total' => $luasKacaTotal,
        'keliling_per_unit' => $kelilingPerUnit,
        'keliling_total' => $kelilingTotal,
        
        'profile_vertikal' => $profileVertikal,
        'variable_a' => $variableA,
        'frame_vertikal' => $frameVertikal,
        'batang_vertikal' => $batangVertikal,
        
        'profile_horizontal' => $profileHorizontal,
        'satuan_terkecil_horizontal' => $satuanTerkecilHorizontal,
        'variable_b' => $variableB,
        'frame_horizontal' => $frameHorizontal,
        'batang_horizontal' => $batangHorizontal,
        
        'total_batang' => $totalBatang,
        'reinforcement_qty' => $reinforcementQty,
        
        'profile_sash_vertikal' => $profileSashVertikal,
        'satuan_terkecil_sash_vertikal' => $satuanTerkecilSashVertikal,
        'variable_sash_vertikal_a' => $variableSashVertikalA,
        'variable_sash_vertikal_b' => $variableSashVertikalB,
        'batang_sash_vertikal' => $batangSashVertikal,
        'batang_sash_vertikal_qty' => $batangSashVertikalQty,
        
        'profile_sash_horizontal' => $profileSashHorizontal,
        'satuan_terkecil_sash_horizontal' => $satuanTerkecilSashHorizontal,
        'variable_sash_horizontal_a' => $variableSashHorizontalA,
        'variable_sash_horizontal_b' => $variableSashHorizontalB,
        'batang_sash_horizontal' => $batangSashHorizontal,
        'batang_sash_horizontal_qty' => $batangSashHorizontalQty,
        
        'reinforcement_sash_qty' => $reinforcementSashQty,
        
        'profile_coupling_vertikal' => $profileCouplingVertikal,
        'satuan_terkecil_coupling' => $satuanTerkecilCoupling,
        'variable_coupling_a' => $variableCouplingA,
        'variable_coupling_b' => $variableCouplingB,
        'batang_coupling' => $batangCoupling,
        'batang_coupling_qty' => $batangCouplingQty,
        
        'decoration_bar_vertikal_input' => $decorationBarVertikalInput,
        'decoration_bar_vertikal_item' => $decorationBarVertikalItem,
        'batang_decoration_vertikal' => $batangDecorationVertikal,
        'batang_decoration_vertikal_qty' => $batangDecorationVertikalQty,
        
        'decoration_bar_horizontal_input' => $decorationBarHorizontalInput,
        'decoration_bar_horizontal_item' => $decorationBarHorizontalItem,
        'batang_decoration_horizontal' => $batangDecorationHorizontal,
        'batang_decoration_horizontal_qty' => $batangDecorationHorizontalQty,
        
        'total_decoration_bar_qty' => $totalDecorationBarQty,
        
        'transmitter_item' => $transmitterItem,
        'ukuran_transmitter' => $ukuranTransmitter,
        'ukuran_transmitter_final' => $ukuranTransmitterFinal,
        'total_window_hardware_transmitter_qty' => $totalWindowHardwareTransmitterQty,
        
        'friction_stay_item' => $frictionStayItem,
        'ukuran_friction_stay' => $ukuranFrictionStay,
        'ukuran_friction_stay_final' => $ukuranFrictionStayFinal,
        'total_window_hardware_friction_stay_qty' => $totalWindowHardwareFrictionStayQty,
        
        'handle_item' => $handleItem,
        'total_window_hardware_handle_qty' => $totalWindowHardwareHandleQty,
        
        'screw_transmitter_item' => $screwTransmitterItem,
        'screw_transmitter_qty' => $screwTransmitterQty,
        
        'screw_friction_stay_item' => $screwFrictionStayItem,
        'screw_friction_stay_qty' => $screwFrictionStayQty,
        
        'screw_handle_item' => $screwHandleItem,
        'screw_handle_qty' => $screwHandleQty,
        
        'satuan_terkecil_screw' => $satuanTerkecilScrew,
        'screw_qty' => $screwQty,
        
        'setting_block_item' => $settingBlockItem,
        'satuan_terkecil_setting_block' => $satuanTerkecilSettingBlock,
        'variable_c' => $variableC,
        'variable_d' => $variableD,
        'variable_e' => $variableE,
        'variable_f' => $variableF,
        'setting_block_qty' => $settingBlockQty,
        
        'aksesoris' => $aksesoris,
    ];

    return view('boq.jendela.jendela-swing-2', $data);
}

public function exportPdfSwing2(Request $request)
{
    $panjang = $request->panjang;
    $lebar = $request->lebar;
    $tebal_kaca = $request->tebal_kaca;
    $jumlah = $request->jumlah;
    $warna = $request->warna;
    $type_kaca = $request->type_kaca;
    $judul = $request->judul ?? 'BOQ - Jendela Swing 2 Daun';

    // Ambil data aksesoris
    $aksesorisIds = ProductAccessories::where('parent_product_id', 180)->pluck('accessory_id');
    $aksesoris = Product::with('area', 'unit')
        ->whereIn('id', $aksesorisIds)
        ->get();

    // === PERHITUNGAN DASAR ===
    $panjangM = $panjang / 100;
    $lebarM = $lebar / 100;
    
    $luasKacaPerUnit = $panjangM * $lebarM;
    $luasKacaTotal = $luasKacaPerUnit * $jumlah;
    $luasKacaTotal = ceil($luasKacaTotal * 10) / 10;

    $kelilingPerUnit = 2 * ($panjangM + $lebarM);
    $kelilingTotal = $kelilingPerUnit * $jumlah;

    // === PERHITUNGAN PROFILE VERTIKAL ===
    $profileVertikal = null;
    $aksesorisCount = count($aksesoris);
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-vertikal') {
            $profileVertikal = $item;
            break;
        }
    }
    $satuanTerkecilVertikal = $profileVertikal ? (float)$profileVertikal->satuan_terkecil : 0;

    $variableA = $jumlah * 4;
    $frameVertikal = $variableA * $panjang;
    $batangVertikal = $frameVertikal / 580;
    $batangVertikal = ceil($batangVertikal * 10) / 10;
    $totalPanjang = $panjang * $variableA;

    // === PERHITUNGAN PROFILE HORIZONTAL ===
    $profileHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-horizontal') {
            $profileHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilHorizontal = $profileHorizontal ? (float)$profileHorizontal->satuan_terkecil : 0;
    
    $variableB = $jumlah * $satuanTerkecilHorizontal;
    $frameHorizontal = $variableB * $lebar;
    $batangHorizontal = $frameHorizontal / 580;
    $batangHorizontal = ceil($batangHorizontal * 10) / 10;
    $totalLebar = $lebar * $variableB;

    // === PERHITUNGAN REINFORCEMENT ===
    $totalBatang = ($frameVertikal + $frameHorizontal) / 600;
    $reinforcementQty = ceil($totalBatang * 10) / 10;

    // === PERHITUNGAN PROFILE SASH VERTIKAL ===
    $profileSashVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-vertikal') {
            $profileSashVertikal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashVertikal = $profileSashVertikal ? (float)$profileSashVertikal->satuan_terkecil : 0;
    
    $variableSashVertikalA = 4 * $jumlah;
    $variableSashVertikalB = $variableSashVertikalA * $panjang;
    $batangSashVertikal = $variableSashVertikalB / 580;
    $batangSashVertikalQty = ceil($batangSashVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE SASH HORIZONTAL ===
    $profileSashHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-horizontal') {
            $profileSashHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashHorizontal = $profileSashHorizontal ? (float)$profileSashHorizontal->satuan_terkecil : 0;
    
    $variableSashHorizontalA = $satuanTerkecilSashHorizontal * $jumlah;
    $variableSashHorizontalB = $variableSashHorizontalA * $lebar;
    $batangSashHorizontal = $variableSashHorizontalB / 580;
    $batangSashHorizontalQty = ceil($batangSashHorizontal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT SASH ===
    $totalBatangSash = ($variableSashVertikalB + $variableSashHorizontalB) / 600;
    $reinforcementSashQty = ceil($totalBatangSash * 10) / 10;

    // === PERHITUNGAN PROFILE COUPLING VERTIKAL ===
    $profileCouplingVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-coupling-vertikal') {
            $profileCouplingVertikal = $item;
            break;
        }
    }
    
    $satuanTerkecilCoupling = $profileCouplingVertikal ? (float)$profileCouplingVertikal->satuan_terkecil : 0;
    $variableCouplingA = $satuanTerkecilCoupling * $jumlah * 2;
    $variableCouplingB = $variableCouplingA * $panjang;
    $batangCoupling = $variableCouplingB / 580;
    $batangCouplingQty = ceil($batangCoupling * 10) / 10;

    // === PERHITUNGAN DECORATION BAR ===
    $decorationBarVertikalInput = (int)($request->decoration_bar_vertikal ?? 0);
    $decorationBarVertikalItem = null;
    $batangDecorationVertikal = 0;
    $batangDecorationVertikalQty = 0;

    if ($decorationBarVertikalInput > 0) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'profile-decoration-vertikal') {
                $decorationBarVertikalItem = $item;
                break;
            }
        }
        if ($decorationBarVertikalItem) {
            $satuanTerkecil = (float)($decorationBarVertikalItem->satuan_terkecil ?? 0);
            $variableDecorationVertikalA = $decorationBarVertikalInput * $jumlah * 2;
            $variableDecorationVertikalB = $variableDecorationVertikalA * $panjang;
            $batangDecorationVertikal = $variableDecorationVertikalB / 580;
            $batangDecorationVertikalQty = ceil($batangDecorationVertikal * 10) / 10;
            $decorationBarVertikalItem->qty = $batangDecorationVertikalQty;
        }
    }

    $decorationBarHorizontalInput = (int)($request->decoration_bar_horizontal ?? 0);
    $decorationBarHorizontalItem = null;
    $batangDecorationHorizontal = 0;
    $batangDecorationHorizontalQty = 0;

    if ($decorationBarHorizontalInput > 0) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'profile-decoration-horizontal') {
                $decorationBarHorizontalItem = $item;
                break;
            }
        }
        if ($decorationBarHorizontalItem) {
            $satuanTerkecil = (float)($decorationBarHorizontalItem->satuan_terkecil ?? 0);
            $variableDecorationHorizontalA = $decorationBarHorizontalInput * $jumlah * 2;
            $variableDecorationHorizontalB = $variableDecorationHorizontalA * $lebar;
            $batangDecorationHorizontal = $variableDecorationHorizontalB / 580;
            $batangDecorationHorizontalQty = ceil($batangDecorationHorizontal * 10) / 10;
            $decorationBarHorizontalItem->qty = $batangDecorationHorizontalQty;
        }
    }

    $totalDecorationBarQty = ceil(($batangDecorationVertikal + $batangDecorationHorizontal) * 10) / 10;

    // === PERHITUNGAN WINDOW HARDWARE TRANSMITTER ===
    $ukuranTransmitter = $panjang - 20;

    $transmitterMapping = [
        40 => 172,
        60 => 171,
        80 => 170,
        100 => 173,
        120 => 162,
        140 => 166,
        160 => 167,
        180 => 168,
        200 => 169,
    ];

    $ukuranTransmitterFinal = $ukuranTransmitter;
    if (!isset($transmitterMapping[$ukuranTransmitter])) {
        $availableSizes = array_keys($transmitterMapping);
        sort($availableSizes);
        
        $found = false;
        for ($i = 0; $i < count($availableSizes); $i++) {
            if ($availableSizes[$i] >= $ukuranTransmitter) {
                $ukuranTransmitterFinal = $availableSizes[$i];
                $found = true;
                break;
            }
        }
        
        if (!$found) {
            $ukuranTransmitterFinal = max($availableSizes);
        }
    }

    $transmitterItem = null;
    $transmitterId = $transmitterMapping[$ukuranTransmitterFinal] ?? null;

    if ($transmitterId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $transmitterId) {
                $transmitterItem = $item;
                break;
            }
        }
    }

    $totalWindowHardwareTransmitterQty = 0;
    if ($transmitterItem) {
        $satuanTerkecil = (float)($transmitterItem->satuan_terkecil ?? 0);
        $qty = $jumlah * 2;
        $transmitterItem->qty = $qty;
        $totalWindowHardwareTransmitterQty += $qty;
    }

    // === PERHITUNGAN WINDOW HARDWARE FRICTION STAY ===
    $ukuranFrictionStay = $panjang / 3;

    $frictionStayMapping = [
        25 => 175,
        30 => 174,
        35 => 179,
        40 => 173,
        45 => 176,
        50 => 177,
        60 => 178,
    ];

    $ukuranFrictionStayFinal = $ukuranFrictionStay;
    if (!isset($frictionStayMapping[$ukuranFrictionStay])) {
        $availableSizes = array_keys($frictionStayMapping);
        sort($availableSizes);
        
        $found = false;
        for ($i = 0; $i < count($availableSizes); $i++) {
            if ($availableSizes[$i] >= $ukuranFrictionStay) {
                $ukuranFrictionStayFinal = $availableSizes[$i];
                $found = true;
                break;
            }
        }
        
        if (!$found) {
            $ukuranFrictionStayFinal = max($availableSizes);
        }
    }

    $frictionStayItem = null;
    $frictionStayId = $frictionStayMapping[$ukuranFrictionStayFinal] ?? null;

    if ($frictionStayId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $frictionStayId) {
                $frictionStayItem = $item;
                break;
            }
        }
    }

    $totalWindowHardwareFrictionStayQty = 0;
    if ($frictionStayItem) {
        $satuanTerkecil = (float)($frictionStayItem->satuan_terkecil ?? 0);
        $qty = $jumlah * 4;
        $frictionStayItem->qty = $qty;
        $totalWindowHardwareFrictionStayQty += $qty;
    }

    // === PERHITUNGAN WINDOW HARDWARE HANDLE ===
    $handleItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'window-hardware-handle') {
            $handleItem = $item;
            break;
        }
    }

    $totalWindowHardwareHandleQty = 0;
    if ($handleItem) {
        $satuanTerkecil = (float)($handleItem->satuan_terkecil ?? 0);
        $qty = $jumlah * 2;
        $handleItem->qty = $qty;
        $totalWindowHardwareHandleQty += $qty;
    }

    // === PERHITUNGAN SCREW TRANSMITTER ===
    $screwTransmitterItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-transmitter') {
            $screwTransmitterItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewTransmitter = $screwTransmitterItem ? (float)$screwTransmitterItem->satuan_terkecil : 0;
    $screwTransmitterQty = ($totalWindowHardwareTransmitterQty * $satuanTerkecilScrewTransmitter);
    if ($screwTransmitterItem) {
        $screwTransmitterItem->qty = $screwTransmitterQty;
    }

    // === PERHITUNGAN SCREW FRICTION STAY ===
    $screwFrictionStayItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-friction-stay') {
            $screwFrictionStayItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewFrictionStay = $screwFrictionStayItem ? (float)$screwFrictionStayItem->satuan_terkecil : 0;
    $screwFrictionStayQty = $totalWindowHardwareFrictionStayQty * $satuanTerkecilScrewFrictionStay;
    if ($screwFrictionStayItem) {
        $screwFrictionStayItem->qty = $screwFrictionStayQty;
    }

    // === PERHITUNGAN SCREW HANDLE ===
    $screwHandleItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-handle') {
            $screwHandleItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewHandle = $screwHandleItem ? (float)$screwHandleItem->satuan_terkecil : 0;
    $screwHandleQty = $totalWindowHardwareHandleQty * $satuanTerkecilScrewHandle;
    if ($screwHandleItem) {
        $screwHandleItem->qty = $screwHandleQty;
    }

    // === PERHITUNGAN SETTING BLOCK ===
    $settingBlockItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'setting-block') {
            $settingBlockItem = $item;
            break;
        }
    }
    
    $satuanTerkecilSettingBlock = $settingBlockItem ? (float)$settingBlockItem->satuan_terkecil : 0;
    
    $variableC = 2 * $satuanTerkecilSettingBlock;
    $variableD = $variableC * $jumlah;
    $variableE = $variableD * 25;
    $variableF = $variableE / 1000;
    $settingBlockQty = ceil($variableF);

    // === PERHITUNGAN SCREW REINFORCEMENT ===
    $screwItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-reinforcement') {
            $screwItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrew = $screwItem ? (float)$screwItem->satuan_terkecil : 0;
    $screwQty = ((($totalLebar + $totalPanjang)) + ($variableSashVertikalB + $variableSashHorizontalB)) / $satuanTerkecilScrew;
    $screwQty = ceil($screwQty * 10);

    // === HITUNG QTY PER AKSESORIS ===
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        $areaSlug = $item->area ? $item->area->slug : '';
        $qty = 0;
        
        if ($areaSlug == 'profile-vertikal') {
            $qty = $batangVertikal;
        } elseif ($areaSlug == 'profile-horizontal') {
            $qty = $batangHorizontal;
        } elseif ($areaSlug == 'glaze-bead-vertical') {
            $qty = ($panjang / 100) * $jumlah;
        } elseif ($areaSlug == 'glaze-bead-horizontal') {
            $qty = ($lebar / 100) * $jumlah;
        } elseif ($areaSlug == 'reinforcement') {
            $qty = $reinforcementQty;
        } elseif ($areaSlug == 'reinforcement-sash') {
            $qty = $reinforcementSashQty;
        } elseif ($areaSlug == 'kaca') {
            $qty = $luasKacaTotal;
        } elseif ($areaSlug == 'screw-reinforcement') {
            $qty = $screwQty;
        } elseif ($areaSlug == 'setting-block') {
            $qty = $settingBlockQty;
        } elseif ($areaSlug == 'profile-sash-vertikal') {
            $qty = $batangSashVertikalQty;
        } elseif ($areaSlug == 'profile-sash-horizontal') {
            $qty = $batangSashHorizontalQty;
        } elseif ($areaSlug == 'window-hardware-transmitter') {
            $qty = ($transmitterItem && $transmitterItem->id == $item->id) ? $transmitterItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-friction-stay') {
            $qty = ($frictionStayItem && $frictionStayItem->id == $item->id) ? $frictionStayItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-handle') {
            $qty = $handleItem ? $handleItem->qty : 0;
        } elseif ($areaSlug == 'profile-coupling-vertikal') {
            $qty = $batangCouplingQty;
        } elseif ($areaSlug == 'screw-transmitter') {
            $qty = $screwTransmitterQty;
        } elseif ($areaSlug == 'screw-friction-stay') {
            $qty = $screwFrictionStayQty;
        } elseif ($areaSlug == 'screw-handle') {
            $qty = $screwHandleQty;
        } elseif ($areaSlug == 'profile-decoration-vertikal') {
            $qty = $batangDecorationVertikalQty;
        } elseif ($areaSlug == 'profile-decoration-horizontal') {
            $qty = $batangDecorationHorizontalQty;
        } else {
            $qty = $jumlah * ($item->satuan_terkecil ?? 1);
        }
        
        $item->qty = $qty;
    }

    // Kelompokkan berdasarkan area
    $grouped = [];
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->qty <= 0) {
            continue;
        }
        
        // Skip window hardware yang tidak terpilih (qty 0)
        if ($item->area && ($item->area->slug == 'window-hardware-transmitter' || $item->area->slug == 'window-hardware-friction-stay' || $item->area->slug == 'window-hardware-handle') && $item->qty <= 0) {
            continue;
        }
        
        $areaSlug = $item->area ? $item->area->slug : 'lainnya';
        
        if (str_starts_with($areaSlug, 'profile')) {
            $groupKey = 'profile';
        } elseif ($areaSlug == 'setting-block') {
            $groupKey = 'kaca';
        } elseif ($areaSlug == 'reinforcement' || $areaSlug == 'reinforcement-sash') {
            $groupKey = 'reinforcement';
        } elseif (str_starts_with($areaSlug, 'window-hardware')) {
            $groupKey = 'window-hardware';
        } elseif ($areaSlug == 'screw-reinforcement' || $areaSlug == 'screw-transmitter' || $areaSlug == 'screw-friction-stay' || $areaSlug == 'screw-handle') {
            $groupKey = 'screw';
        } else {
            $groupKey = $areaSlug;
        }
        
        if (!isset($grouped[$groupKey])) {
            $grouped[$groupKey] = [];
        }
        $grouped[$groupKey][] = $item;
    }

    $areaLabels = [
        'profile' => 'PROFILE',
        'reinforcement' => 'REINFORCEMENT',
        'kaca' => 'KACA',
        'screw' => 'SCREW',
        'window-hardware' => 'WINDOW HARDWARE',
    ];

    // ============ GENERATE NOMOR BOQ ============
    $nomorBoq = Boq::generateNomorBoq();

    // ============ STORE BOQ ============
    try {
        $allResults = [];
        
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->qty > 0) {
                $allResults[] = [
                    'produk_id' => $item->id,
                    'qty' => $item->qty,
                    'nama_produk' => $item->nama_produk,
                ];
            }
        }
        
        $uniqueResults = [];
        $seenIds = [];
        $allResultsCount = count($allResults);
        
        for ($i = 0; $i < $allResultsCount; $i++) {
            $item = $allResults[$i];
            $produkId = $item['produk_id'] ?? null;
            
            if (!$produkId) {
                continue;
            }
            
            $isDuplicate = false;
            $seenCount = count($seenIds);
            for ($j = 0; $j < $seenCount; $j++) {
                if ($seenIds[$j] == $produkId) {
                    $isDuplicate = true;
                    break;
                }
            }
            
            if ($isDuplicate) {
                continue;
            }
            
            $seenIds[] = $produkId;
            $uniqueResults[] = $item;
        }
        
        if (count($uniqueResults) > 0) {
            $boq = new Boq();
            $boq->nomor_boq = $nomorBoq;
            $boq->tanggal_boq = now();
            $boq->save();
            
            $uniqueCount = count($uniqueResults);
            for ($i = 0; $i < $uniqueCount; $i++) {
                $item = $uniqueResults[$i];
                $produkId = $item['produk_id'] ?? null;
                $qty = (int)($item['qty'] ?? 0);
                
                if ($produkId && $qty > 0) {
                    $produk = Product::find($produkId);
                    
                    \DB::table('detail_boq')->insert([
                        'boq_id' => $boq->id,
                        'produk_id' => $produkId,
                        'kode_produk' => $produk ? $produk->kode_produk : null,
                        'qty' => $qty,
                        'created_at' => now(),
                        'updated_at' => now()
                    ]);
                }
            }
            
            \Log::info('BOQ SAVED JENDELA SWING 2:', [
                'boq_id' => $boq->id,
                'nomor_boq' => $nomorBoq,
                'total' => count($uniqueResults)
            ]);
        }
        
    } catch (\Exception $e) {
        \Log::error('Error saving BOQ Jendela Swing 2: ' . $e->getMessage());
        \Log::error($e->getTraceAsString());
    }

    $data = [
        'judul' => $judul,
        'panjang' => $panjang,
        'lebar' => $lebar,
        'tebal_kaca' => $tebal_kaca,
        'jumlah' => $jumlah,
        'warna' => $warna,
        'type_kaca' => $type_kaca,
        'luas_kaca_total' => $luasKacaTotal,
        'keliling_total' => $kelilingTotal,
        'batang_vertikal' => $batangVertikal,
        'batang_horizontal' => $batangHorizontal,
        'reinforcement_qty' => $reinforcementQty,
        'reinforcement_sash_qty' => $reinforcementSashQty,
        'batang_sash_vertikal_qty' => $batangSashVertikalQty,
        'batang_sash_horizontal_qty' => $batangSashHorizontalQty,
        'batang_coupling_qty' => $batangCouplingQty,
        'total_decoration_bar_qty' => $totalDecorationBarQty,
        'transmitter_item' => $transmitterItem,
        'ukuran_transmitter' => $ukuranTransmitter,
        'ukuran_transmitter_final' => $ukuranTransmitterFinal,
        'total_window_hardware_transmitter_qty' => $totalWindowHardwareTransmitterQty,
        'friction_stay_item' => $frictionStayItem,
        'ukuran_friction_stay' => $ukuranFrictionStay,
        'ukuran_friction_stay_final' => $ukuranFrictionStayFinal,
        'total_window_hardware_friction_stay_qty' => $totalWindowHardwareFrictionStayQty,
        'handle_item' => $handleItem,
        'total_window_hardware_handle_qty' => $totalWindowHardwareHandleQty,
        'screw_transmitter_qty' => $screwTransmitterQty,
        'screw_friction_stay_qty' => $screwFrictionStayQty,
        'screw_handle_qty' => $screwHandleQty,
        'screw_qty' => $screwQty,
        'setting_block_qty' => $settingBlockQty,
        'grouped' => $grouped,
        'areaLabels' => $areaLabels,
        'nomor_boq' => $nomorBoq,
    ];

    return view('boq.jendela.pdf-jendela-swing-2', compact('data'));
}

public function hitungJungkit1(Request $request)
{
    $request->validate([
        'panjang' => 'required|numeric|min:1',
        'lebar' => 'required|numeric|min:1',
        'tebal_kaca' => 'required|numeric|min:1',
        'jumlah' => 'required|numeric|min:1',
        'warna' => 'required|string',
        'type_kaca' => 'required|string',
    ]);

    // Ambil data dari form
    $panjang = $request->panjang; // cm
    $lebar = $request->lebar; // cm
    $tebalKaca = $request->tebal_kaca; // mm
    $jumlah = $request->jumlah;
    $warna = $request->warna;
    $typeKaca = $request->type_kaca;
    $handleId = $request->handle_id;

    // Ambil produk utama (Jendela Jungkit 1) dari database
    $produkUtama = Product::find(181);
    
    if (!$produkUtama) {
        return back()->with('error', 'Produk Jendela Jungkit 1 tidak ditemukan!');
    }

    // Ambil aksesoris dari tabel product_accessories dengan relasi area
    $aksesorisIds = ProductAccessories::where('parent_product_id', 181)->pluck('accessory_id');
    $aksesoris = Product::with('area', 'unit')
        ->whereIn('id', $aksesorisIds)
        ->get();

    // === PERHITUNGAN DASAR ===
    
    // Konversi ke meter
    $panjangM = $panjang / 100;
    $lebarM = $lebar / 100;
    $tebalKacaM = $tebalKaca / 1000;

    // 1. Luas Kaca (m²)
    $luasKacaPerUnit = $panjangM * $lebarM;
    $luasKacaTotal = $luasKacaPerUnit * $jumlah;
    $luasKacaTotal = ceil($luasKacaTotal * 10) / 10;

    // 2. Keliling Profile (meter)
    $kelilingPerUnit = 2 * ($panjangM + $lebarM);
    $kelilingTotal = $kelilingPerUnit * $jumlah;

    // === PERHITUNGAN PROFILE VERTIKAL ===
    $profileVertikal = null;
    $aksesorisCount = count($aksesoris);
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-vertikal') {
            $profileVertikal = $item;
            break;
        }
    }
    $satuanTerkecilVertikal = $profileVertikal ? (float)$profileVertikal->satuan_terkecil : 0;

    $variableA = $jumlah * $satuanTerkecilVertikal;
    $frameVertikal = $variableA * $panjang;
    $batangVertikal = $frameVertikal / 580;
    $batangVertikal = ceil($batangVertikal * 10) / 10;
    $totalPanjang = $panjang * $variableA;

    // === PERHITUNGAN PROFILE HORIZONTAL ===
    $profileHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-horizontal') {
            $profileHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilHorizontal = $profileHorizontal ? (float)$profileHorizontal->satuan_terkecil : 0;
    
    $variableB = $jumlah * $satuanTerkecilHorizontal;
    $frameHorizontal = $variableB * $lebar;
    $batangHorizontal = $frameHorizontal / 580;
    $batangHorizontal = ceil($batangHorizontal * 10) / 10;
    $totalLebar = $lebar * $variableB;

    // === PERHITUNGAN REINFORCEMENT ===
    $totalBatang = ($frameVertikal + $frameHorizontal) / 600;
    $reinforcementQty = ceil($totalBatang * 10) / 10;

    // === PERHITUNGAN PROFILE SASH VERTIKAL ===
    $profileSashVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-vertikal') {
            $profileSashVertikal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashVertikal = $profileSashVertikal ? (float)$profileSashVertikal->satuan_terkecil : 0;
    
    $variableSashVertikalA = $satuanTerkecilSashVertikal * $jumlah;
    $variableSashVertikalB = $variableSashVertikalA * $panjang;
    $batangSashVertikal = $variableSashVertikalB / 580;
    $batangSashVertikalQty = ceil($batangSashVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE SASH HORIZONTAL ===
    $profileSashHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-horizontal') {
            $profileSashHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashHorizontal = $profileSashHorizontal ? (float)$profileSashHorizontal->satuan_terkecil : 0;
    
    $variableSashHorizontalA = $satuanTerkecilSashHorizontal * $jumlah;
    $variableSashHorizontalB = $variableSashHorizontalA * $lebar;
    $batangSashHorizontal = $variableSashHorizontalB / 580;
    $batangSashHorizontalQty = ceil($batangSashHorizontal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT SASH ===
    $totalBatangSash = ($variableSashVertikalB + $variableSashHorizontalB) / 600;
    $reinforcementSashQty = ceil($totalBatangSash * 10) / 10;

    // === PERHITUNGAN DECORATION BAR ===
    $decorationBarVertikalInput = (int)($request->decoration_bar_vertikal ?? 0);
    $decorationBarVertikalItem = null;
    $batangDecorationVertikal = 0;
    $batangDecorationVertikalQty = 0;

    if ($decorationBarVertikalInput > 0) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'profile-decoration-vertikal') {
                $decorationBarVertikalItem = $item;
                break;
            }
        }
        if ($decorationBarVertikalItem) {
            $satuanTerkecil = (float)($decorationBarVertikalItem->satuan_terkecil ?? 0);
            $variableDecorationVertikalA = $decorationBarVertikalInput * $jumlah * 2;
            $variableDecorationVertikalB = $variableDecorationVertikalA * $panjang;
            $batangDecorationVertikal = $variableDecorationVertikalB / 580;
            $batangDecorationVertikalQty = ceil($batangDecorationVertikal * 10) / 10;
            $decorationBarVertikalItem->qty = $batangDecorationVertikalQty;
        }
    }

    $decorationBarHorizontalInput = (int)($request->decoration_bar_horizontal ?? 0);
    $decorationBarHorizontalItem = null;
    $batangDecorationHorizontal = 0;
    $batangDecorationHorizontalQty = 0;

    if ($decorationBarHorizontalInput > 0) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'profile-decoration-horizontal') {
                $decorationBarHorizontalItem = $item;
                break;
            }
        }
        if ($decorationBarHorizontalItem) {
            $satuanTerkecil = (float)($decorationBarHorizontalItem->satuan_terkecil ?? 0);
            $variableDecorationHorizontalA = $decorationBarHorizontalInput * $jumlah * 2;
            $variableDecorationHorizontalB = $variableDecorationHorizontalA * $lebar;
            $batangDecorationHorizontal = $variableDecorationHorizontalB / 580;
            $batangDecorationHorizontalQty = ceil($batangDecorationHorizontal * 10) / 10;
            $decorationBarHorizontalItem->qty = $batangDecorationHorizontalQty;
        }
    }

    $totalDecorationBarQty = ceil(($batangDecorationVertikal + $batangDecorationHorizontal) * 10) / 10;

    // === PERHITUNGAN WINDOW HARDWARE HANDLE (dari dropdown) ===
    $handleItem = null;
    $totalWindowHardwareHandleQty = 0;

    // RESET QTY UNTUK SEMUA HANDLE = 0
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && ($item->area->slug == 'window-hardware-handle-rambuncis' || $item->area->slug == 'window-hardware-handle-multilock')) {
            $item->qty = 0;
        }
    }

    // SET QTY UNTUK HANDLE YANG DIPILIH
    if ($handleId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $handleId) {
                $handleItem = $item;
                break;
            }
        }
    }

    if ($handleItem) {
        $satuanTerkecil = (float)($handleItem->satuan_terkecil ?? 0);
        $qty = $jumlah * $satuanTerkecil;
        $handleItem->qty = $qty;
        $totalWindowHardwareHandleQty += $qty;
    }

    // CEK APAKAH HANDLE YANG DIPILIH ADALAH MULTILOCK
    $isMultilock = false;
    if ($handleItem) {
        $namaLower = strtolower($handleItem->nama_produk);
        if (str_contains($namaLower, 'multilock')) {
            $isMultilock = true;
        }
    }

   // === PERHITUNGAN WINDOW HARDWARE TRANSMITTER ===
$transmitterItem = null;
$totalWindowHardwareTransmitterQty = 0;
$ukuranTransmitter = 0;
$ukuranTransmitterFinal = 0;

// HANYA HITUNG TRANSMITTER JIKA HANDLE MULTILOCK
if ($isMultilock) {
    $ukuranTransmitter = $panjang - 20;

    $transmitterMapping = [
        40 => 172,
        60 => 171,
        80 => 170,
        100 => 173,
        120 => 162,
        140 => 166,
        160 => 167,
        180 => 168,
        200 => 169,
    ];

    $ukuranTransmitterFinal = $ukuranTransmitter;
    if (!isset($transmitterMapping[$ukuranTransmitter])) {
        $availableSizes = array_keys($transmitterMapping);
        sort($availableSizes);
        
        $found = false;
        for ($i = 0; $i < count($availableSizes); $i++) {
            if ($availableSizes[$i] >= $ukuranTransmitter) {
                $ukuranTransmitterFinal = $availableSizes[$i];
                $found = true;
                break;
            }
        }
        
        if (!$found) {
            $ukuranTransmitterFinal = max($availableSizes);
        }
    }

    $transmitterId = $transmitterMapping[$ukuranTransmitterFinal] ?? null;

    if ($transmitterId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $transmitterId) {
                $transmitterItem = $item;
                break;
            }
        }
    }

    if ($transmitterItem) {
        $satuanTerkecil = (float)($transmitterItem->satuan_terkecil ?? 0);
        $qty = $jumlah * $satuanTerkecil;
        $transmitterItem->qty = $qty;
        $totalWindowHardwareTransmitterQty += $qty;
    }
}

    // === PERHITUNGAN WINDOW HARDWARE FRICTION STAY ===
    $ukuranFrictionStay = $panjang / 3;

    $frictionStayMapping = [
        25 => 175,
        30 => 174,
        35 => 179,
        40 => 173,
        45 => 176,
        50 => 177,
        60 => 178,
    ];

    $ukuranFrictionStayFinal = $ukuranFrictionStay;
    if (!isset($frictionStayMapping[$ukuranFrictionStay])) {
        $availableSizes = array_keys($frictionStayMapping);
        sort($availableSizes);
        
        $found = false;
        for ($i = 0; $i < count($availableSizes); $i++) {
            if ($availableSizes[$i] >= $ukuranFrictionStay) {
                $ukuranFrictionStayFinal = $availableSizes[$i];
                $found = true;
                break;
            }
        }
        
        if (!$found) {
            $ukuranFrictionStayFinal = max($availableSizes);
        }
    }

    $frictionStayItem = null;
    $frictionStayId = $frictionStayMapping[$ukuranFrictionStayFinal] ?? null;

    if ($frictionStayId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $frictionStayId) {
                $frictionStayItem = $item;
                break;
            }
        }
    }

    $totalWindowHardwareFrictionStayQty = 0;
    if ($frictionStayItem) {
        $satuanTerkecil = (float)($frictionStayItem->satuan_terkecil ?? 0);
        $qty = $jumlah * $satuanTerkecil;
        $frictionStayItem->qty = $qty;
        $totalWindowHardwareFrictionStayQty += $qty;
    }

    // === PERHITUNGAN SCREW TRANSMITTER ===
    $screwTransmitterItem = null;
    $screwTransmitterQty = 0;

    // HANYA JIKA MULTILOCK DAN ADA TRANSMITTER
    if ($isMultilock && $transmitterItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-transmitter') {
                $screwTransmitterItem = $item;
                break;
            }
        }

        $satuanTerkecilScrewTransmitter = $screwTransmitterItem ? (float)$screwTransmitterItem->satuan_terkecil : 0;
        $screwTransmitterQty = ($totalWindowHardwareTransmitterQty * $satuanTerkecilScrewTransmitter);
        if ($screwTransmitterItem) {
            $screwTransmitterItem->qty = $screwTransmitterQty;
        }
    }

    // === PERHITUNGAN SCREW FRICTION STAY ===
    $screwFrictionStayItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-friction-stay') {
            $screwFrictionStayItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewFrictionStay = $screwFrictionStayItem ? (float)$screwFrictionStayItem->satuan_terkecil : 0;
    $screwFrictionStayQty = $totalWindowHardwareFrictionStayQty * $satuanTerkecilScrewFrictionStay;
    if ($screwFrictionStayItem) {
        $screwFrictionStayItem->qty = $screwFrictionStayQty;
    }

    // === PERHITUNGAN SCREW HANDLE ===
    $screwHandleItem = null;
    if ($handleItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-handle') {
                $screwHandleItem = $item;
                break;
            }
        }
    }

    $satuanTerkecilScrewHandle = $screwHandleItem ? (float)$screwHandleItem->satuan_terkecil : 0;
    $screwHandleQty = $totalWindowHardwareHandleQty * $satuanTerkecilScrewHandle;
    if ($screwHandleItem) {
        $screwHandleItem->qty = $screwHandleQty;
    }

    // === PERHITUNGAN SETTING BLOCK ===
    $settingBlockItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'setting-block') {
            $settingBlockItem = $item;
            break;
        }
    }
    
    $satuanTerkecilSettingBlock = $settingBlockItem ? (float)$settingBlockItem->satuan_terkecil : 0;
    
    $variableC = 1 * $satuanTerkecilSettingBlock;
    $variableD = $variableC * $jumlah;
    $variableE = $variableD * 25;
    $variableF = $variableE / 1000;
    $settingBlockQty = ceil($variableF);

    // === PERHITUNGAN SCREW REINFORCEMENT ===
    $screwItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-reinforcement') {
            $screwItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrew = $screwItem ? (float)$screwItem->satuan_terkecil : 0;
    $screwQty = ((($totalLebar + $totalPanjang)) + ($variableSashVertikalB + $variableSashHorizontalB)) / $satuanTerkecilScrew;
    $screwQty = ceil($screwQty * 10);

    // === PERHITUNGAN QTY PER AKSESORIS ===
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        $areaSlug = $item->area ? $item->area->slug : '';
        $qty = 0;
        
        if ($areaSlug == 'profile-vertikal') {
            $qty = $batangVertikal;
        } elseif ($areaSlug == 'profile-horizontal') {
            $qty = $batangHorizontal;
        } elseif ($areaSlug == 'glaze-bead-vertical') {
            $qty = ($panjang / 100) * $jumlah;
        } elseif ($areaSlug == 'glaze-bead-horizontal') {
            $qty = ($lebar / 100) * $jumlah;
        } elseif ($areaSlug == 'reinforcement') {
            $qty = $reinforcementQty;
        } elseif ($areaSlug == 'reinforcement-sash') {
            $qty = $reinforcementSashQty;
        } elseif ($areaSlug == 'kaca') {
            $qty = $luasKacaTotal;
        } elseif ($areaSlug == 'screw-reinforcement') {
            $qty = $screwQty;
        } elseif ($areaSlug == 'setting-block') {
            $qty = $settingBlockQty;
        } elseif ($areaSlug == 'profile-sash-vertikal') {
            $qty = $batangSashVertikalQty;
        } elseif ($areaSlug == 'profile-sash-horizontal') {
            $qty = $batangSashHorizontalQty;
        } elseif ($areaSlug == 'window-hardware-transmitter') {
            $qty = ($transmitterItem && $transmitterItem->id == $item->id) ? $transmitterItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-friction-stay') {
            $qty = ($frictionStayItem && $frictionStayItem->id == $item->id) ? $frictionStayItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-handle-rambuncis' || $areaSlug == 'window-hardware-handle-multilock') {
            $qty = $item->qty;
        } elseif ($areaSlug == 'screw-transmitter') {
            $qty = $screwTransmitterQty;
        } elseif ($areaSlug == 'screw-friction-stay') {
            $qty = $screwFrictionStayQty;
        } elseif ($areaSlug == 'screw-handle') {
            $qty = $screwHandleQty;
        } elseif ($areaSlug == 'profile-decoration-vertikal') {
            $qty = $batangDecorationVertikalQty;
        } elseif ($areaSlug == 'profile-decoration-horizontal') {
            $qty = $batangDecorationHorizontalQty;
        } else {
            $qty = $jumlah * ($item->satuan_terkecil ?? 1);
        }
        
        $item->qty = $qty;
    }

    // Data untuk view
    $data = [
        'produk' => $produkUtama,
        'panjang' => $panjang,
        'lebar' => $lebar,
        'tebal_kaca' => $tebalKaca,
        'jumlah' => $jumlah,
        'warna' => $warna,
        'type_kaca' => $typeKaca,
        'handle_id' => $handleId,
        'is_multilock' => $isMultilock,
        
        'luas_kaca_per_unit' => $luasKacaPerUnit,
        'luas_kaca_total' => $luasKacaTotal,
        'keliling_per_unit' => $kelilingPerUnit,
        'keliling_total' => $kelilingTotal,
        
        'profile_vertikal' => $profileVertikal,
        'variable_a' => $variableA,
        'frame_vertikal' => $frameVertikal,
        'batang_vertikal' => $batangVertikal,
        
        'profile_horizontal' => $profileHorizontal,
        'satuan_terkecil_horizontal' => $satuanTerkecilHorizontal,
        'variable_b' => $variableB,
        'frame_horizontal' => $frameHorizontal,
        'batang_horizontal' => $batangHorizontal,
        
        'total_batang' => $totalBatang,
        'reinforcement_qty' => $reinforcementQty,
        
        'profile_sash_vertikal' => $profileSashVertikal,
        'satuan_terkecil_sash_vertikal' => $satuanTerkecilSashVertikal,
        'variable_sash_vertikal_a' => $variableSashVertikalA,
        'variable_sash_vertikal_b' => $variableSashVertikalB,
        'batang_sash_vertikal' => $batangSashVertikal,
        'batang_sash_vertikal_qty' => $batangSashVertikalQty,
        
        'profile_sash_horizontal' => $profileSashHorizontal,
        'satuan_terkecil_sash_horizontal' => $satuanTerkecilSashHorizontal,
        'variable_sash_horizontal_a' => $variableSashHorizontalA,
        'variable_sash_horizontal_b' => $variableSashHorizontalB,
        'batang_sash_horizontal' => $batangSashHorizontal,
        'batang_sash_horizontal_qty' => $batangSashHorizontalQty,
        
        'reinforcement_sash_qty' => $reinforcementSashQty,
        
        'decoration_bar_vertikal_input' => $decorationBarVertikalInput,
        'decoration_bar_vertikal_item' => $decorationBarVertikalItem,
        'batang_decoration_vertikal' => $batangDecorationVertikal,
        'batang_decoration_vertikal_qty' => $batangDecorationVertikalQty,
        
        'decoration_bar_horizontal_input' => $decorationBarHorizontalInput,
        'decoration_bar_horizontal_item' => $decorationBarHorizontalItem,
        'batang_decoration_horizontal' => $batangDecorationHorizontal,
        'batang_decoration_horizontal_qty' => $batangDecorationHorizontalQty,
        
        'total_decoration_bar_qty' => $totalDecorationBarQty,
        
        'transmitter_item' => $transmitterItem,
        'ukuran_transmitter' => $ukuranTransmitter,
        'ukuran_transmitter_final' => $ukuranTransmitterFinal,
        'total_window_hardware_transmitter_qty' => $totalWindowHardwareTransmitterQty,
        
        'friction_stay_item' => $frictionStayItem,
        'ukuran_friction_stay' => $ukuranFrictionStay,
        'ukuran_friction_stay_final' => $ukuranFrictionStayFinal,
        'total_window_hardware_friction_stay_qty' => $totalWindowHardwareFrictionStayQty,
        
        'handle_item' => $handleItem,
        'total_window_hardware_handle_qty' => $totalWindowHardwareHandleQty,
        
        'screw_transmitter_item' => $screwTransmitterItem,
        'screw_transmitter_qty' => $screwTransmitterQty,
        
        'screw_friction_stay_item' => $screwFrictionStayItem,
        'screw_friction_stay_qty' => $screwFrictionStayQty,
        
        'screw_handle_item' => $screwHandleItem,
        'screw_handle_qty' => $screwHandleQty,
        
        'satuan_terkecil_screw' => $satuanTerkecilScrew,
        'screw_qty' => $screwQty,
        
        'setting_block_item' => $settingBlockItem,
        'satuan_terkecil_setting_block' => $satuanTerkecilSettingBlock,
        'variable_c' => $variableC,
        'variable_d' => $variableD,
        'variable_e' => $variableE,
        'variable_f' => $variableF,
        'setting_block_qty' => $settingBlockQty,
        
        'aksesoris' => $aksesoris,
    ];

    return view('boq.jendela.jendela-jungkit-1', $data);
}

public function exportPdfJungkit1(Request $request)
{
    $panjang = $request->panjang;
    $lebar = $request->lebar;
    $tebal_kaca = $request->tebal_kaca;
    $jumlah = $request->jumlah;
    $warna = $request->warna;
    $type_kaca = $request->type_kaca;
    $handle_id = $request->handle_id;
    $judul = $request->judul ?? 'BOQ - Jendela Jungkit 1 Daun';

    // Ambil data aksesoris
    $aksesorisIds = ProductAccessories::where('parent_product_id', 181)->pluck('accessory_id');
    $aksesoris = Product::with('area', 'unit')
        ->whereIn('id', $aksesorisIds)
        ->get();

    // === PERHITUNGAN DASAR ===
    $panjangM = $panjang / 100;
    $lebarM = $lebar / 100;
    
    $luasKacaPerUnit = $panjangM * $lebarM;
    $luasKacaTotal = $luasKacaPerUnit * $jumlah;
    $luasKacaTotal = ceil($luasKacaTotal * 10) / 10;

    $kelilingPerUnit = 2 * ($panjangM + $lebarM);
    $kelilingTotal = $kelilingPerUnit * $jumlah;

    // === PERHITUNGAN PROFILE VERTIKAL ===
    $profileVertikal = null;
    $aksesorisCount = count($aksesoris);
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-vertikal') {
            $profileVertikal = $item;
            break;
        }
    }
    $satuanTerkecilVertikal = $profileVertikal ? (float)$profileVertikal->satuan_terkecil : 0;

    $variableA = $jumlah * $satuanTerkecilVertikal;
    $frameVertikal = $variableA * $panjang;
    $batangVertikal = $frameVertikal / 580;
    $batangVertikal = ceil($batangVertikal * 10) / 10;
    $totalPanjang = $panjang * $variableA;

    // === PERHITUNGAN PROFILE HORIZONTAL ===
    $profileHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-horizontal') {
            $profileHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilHorizontal = $profileHorizontal ? (float)$profileHorizontal->satuan_terkecil : 0;
    
    $variableB = $jumlah * $satuanTerkecilHorizontal;
    $frameHorizontal = $variableB * $lebar;
    $batangHorizontal = $frameHorizontal / 580;
    $batangHorizontal = ceil($batangHorizontal * 10) / 10;
    $totalLebar = $lebar * $variableB;

    // === PERHITUNGAN REINFORCEMENT ===
    $totalBatang = ($frameVertikal + $frameHorizontal) / 600;
    $reinforcementQty = ceil($totalBatang * 10) / 10;

    // === PERHITUNGAN PROFILE SASH VERTIKAL ===
    $profileSashVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-vertikal') {
            $profileSashVertikal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashVertikal = $profileSashVertikal ? (float)$profileSashVertikal->satuan_terkecil : 0;
    
    $variableSashVertikalA = $satuanTerkecilSashVertikal * $jumlah;
    $variableSashVertikalB = $variableSashVertikalA * $panjang;
    $batangSashVertikal = $variableSashVertikalB / 580;
    $batangSashVertikalQty = ceil($batangSashVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE SASH HORIZONTAL ===
    $profileSashHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-horizontal') {
            $profileSashHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashHorizontal = $profileSashHorizontal ? (float)$profileSashHorizontal->satuan_terkecil : 0;
    
    $variableSashHorizontalA = $satuanTerkecilSashHorizontal * $jumlah;
    $variableSashHorizontalB = $variableSashHorizontalA * $lebar;
    $batangSashHorizontal = $variableSashHorizontalB / 580;
    $batangSashHorizontalQty = ceil($batangSashHorizontal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT SASH ===
    $totalBatangSash = ($variableSashVertikalB + $variableSashHorizontalB) / 600;
    $reinforcementSashQty = ceil($totalBatangSash * 10) / 10;

    // === PERHITUNGAN DECORATION BAR ===
    $decorationBarVertikalInput = (int)($request->decoration_bar_vertikal ?? 0);
    $decorationBarVertikalItem = null;
    $batangDecorationVertikal = 0;
    $batangDecorationVertikalQty = 0;

    if ($decorationBarVertikalInput > 0) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'profile-decoration-vertikal') {
                $decorationBarVertikalItem = $item;
                break;
            }
        }
        if ($decorationBarVertikalItem) {
            $satuanTerkecil = (float)($decorationBarVertikalItem->satuan_terkecil ?? 0);
            $variableDecorationVertikalA = $decorationBarVertikalInput * $jumlah * 2;
            $variableDecorationVertikalB = $variableDecorationVertikalA * $panjang;
            $batangDecorationVertikal = $variableDecorationVertikalB / 580;
            $batangDecorationVertikalQty = ceil($batangDecorationVertikal * 10) / 10;
            $decorationBarVertikalItem->qty = $batangDecorationVertikalQty;
        }
    }

    $decorationBarHorizontalInput = (int)($request->decoration_bar_horizontal ?? 0);
    $decorationBarHorizontalItem = null;
    $batangDecorationHorizontal = 0;
    $batangDecorationHorizontalQty = 0;

    if ($decorationBarHorizontalInput > 0) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'profile-decoration-horizontal') {
                $decorationBarHorizontalItem = $item;
                break;
            }
        }
        if ($decorationBarHorizontalItem) {
            $satuanTerkecil = (float)($decorationBarHorizontalItem->satuan_terkecil ?? 0);
            $variableDecorationHorizontalA = $decorationBarHorizontalInput * $jumlah * 2;
            $variableDecorationHorizontalB = $variableDecorationHorizontalA * $lebar;
            $batangDecorationHorizontal = $variableDecorationHorizontalB / 580;
            $batangDecorationHorizontalQty = ceil($batangDecorationHorizontal * 10) / 10;
            $decorationBarHorizontalItem->qty = $batangDecorationHorizontalQty;
        }
    }

    $totalDecorationBarQty = ceil(($batangDecorationVertikal + $batangDecorationHorizontal) * 10) / 10;

    // === PERHITUNGAN WINDOW HARDWARE HANDLE ===
    $handleItem = null;
    $totalWindowHardwareHandleQty = 0;

    // RESET QTY UNTUK SEMUA HANDLE = 0
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && ($item->area->slug == 'window-hardware-handle-rambuncis' || $item->area->slug == 'window-hardware-handle-multilock')) {
            $item->qty = 0;
        }
    }

    // SET QTY UNTUK HANDLE YANG DIPILIH
    if ($handle_id) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $handle_id) {
                $handleItem = $item;
                break;
            }
        }
    }

    if ($handleItem) {
        $satuanTerkecil = (float)($handleItem->satuan_terkecil ?? 0);
        $qty = $jumlah * $satuanTerkecil;
        $handleItem->qty = $qty;
        $totalWindowHardwareHandleQty += $qty;
    }

    // CEK APAKAH HANDLE YANG DIPILIH ADALAH MULTILOCK
    $isMultilock = false;
    if ($handleItem) {
        $namaLower = strtolower($handleItem->nama_produk);
        if (str_contains($namaLower, 'multilock')) {
            $isMultilock = true;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE TRANSMITTER ===
    $transmitterItem = null;
    $totalWindowHardwareTransmitterQty = 0;
    $ukuranTransmitter = 0;
    $ukuranTransmitterFinal = 0;

    if ($isMultilock) {
        $ukuranTransmitter = $panjang - 20;

        $transmitterMapping = [
            40 => 172,
            60 => 171,
            80 => 170,
            100 => 173,
            120 => 162,
            140 => 166,
            160 => 167,
            180 => 168,
            200 => 169,
        ];

        $ukuranTransmitterFinal = $ukuranTransmitter;
        if (!isset($transmitterMapping[$ukuranTransmitter])) {
            $availableSizes = array_keys($transmitterMapping);
            sort($availableSizes);
            
            $found = false;
            for ($i = 0; $i < count($availableSizes); $i++) {
                if ($availableSizes[$i] >= $ukuranTransmitter) {
                    $ukuranTransmitterFinal = $availableSizes[$i];
                    $found = true;
                    break;
                }
            }
            
            if (!$found) {
                $ukuranTransmitterFinal = max($availableSizes);
            }
        }

        $transmitterId = $transmitterMapping[$ukuranTransmitterFinal] ?? null;

        if ($transmitterId) {
            for ($i = 0; $i < $aksesorisCount; $i++) {
                $item = $aksesoris[$i];
                if ($item->id == $transmitterId) {
                    $transmitterItem = $item;
                    break;
                }
            }
        }

        if ($transmitterItem) {
            $satuanTerkecil = (float)($transmitterItem->satuan_terkecil ?? 0);
            $qty = $jumlah * $satuanTerkecil;
            $transmitterItem->qty = $qty;
            $totalWindowHardwareTransmitterQty += $qty;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE FRICTION STAY ===
    $ukuranFrictionStay = $panjang / 3;

    $frictionStayMapping = [
        25 => 175,
        30 => 174,
        35 => 179,
        40 => 173,
        45 => 176,
        50 => 177,
        60 => 178,
    ];

    $ukuranFrictionStayFinal = $ukuranFrictionStay;
    if (!isset($frictionStayMapping[$ukuranFrictionStay])) {
        $availableSizes = array_keys($frictionStayMapping);
        sort($availableSizes);
        
        $found = false;
        for ($i = 0; $i < count($availableSizes); $i++) {
            if ($availableSizes[$i] >= $ukuranFrictionStay) {
                $ukuranFrictionStayFinal = $availableSizes[$i];
                $found = true;
                break;
            }
        }
        
        if (!$found) {
            $ukuranFrictionStayFinal = max($availableSizes);
        }
    }

    $frictionStayItem = null;
    $frictionStayId = $frictionStayMapping[$ukuranFrictionStayFinal] ?? null;

    if ($frictionStayId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $frictionStayId) {
                $frictionStayItem = $item;
                break;
            }
        }
    }

    $totalWindowHardwareFrictionStayQty = 0;
    if ($frictionStayItem) {
        $satuanTerkecil = (float)($frictionStayItem->satuan_terkecil ?? 0);
        $qty = $jumlah * $satuanTerkecil;
        $frictionStayItem->qty = $qty;
        $totalWindowHardwareFrictionStayQty += $qty;
    }

    // === PERHITUNGAN SCREW TRANSMITTER ===
    $screwTransmitterItem = null;
    $screwTransmitterQty = 0;

    if ($isMultilock && $transmitterItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-transmitter') {
                $screwTransmitterItem = $item;
                break;
            }
        }

        $satuanTerkecilScrewTransmitter = $screwTransmitterItem ? (float)$screwTransmitterItem->satuan_terkecil : 0;
        $screwTransmitterQty = ($totalWindowHardwareTransmitterQty * $satuanTerkecilScrewTransmitter) / 2;
        if ($screwTransmitterItem) {
            $screwTransmitterItem->qty = $screwTransmitterQty;
        }
    }

    // === PERHITUNGAN SCREW FRICTION STAY ===
    $screwFrictionStayItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-friction-stay') {
            $screwFrictionStayItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewFrictionStay = $screwFrictionStayItem ? (float)$screwFrictionStayItem->satuan_terkecil : 0;
    $screwFrictionStayQty = $totalWindowHardwareFrictionStayQty * $satuanTerkecilScrewFrictionStay;
    if ($screwFrictionStayItem) {
        $screwFrictionStayItem->qty = $screwFrictionStayQty;
    }

    // === PERHITUNGAN SCREW HANDLE ===
    $screwHandleItem = null;
    if ($handleItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-handle') {
                $screwHandleItem = $item;
                break;
            }
        }
    }

    $satuanTerkecilScrewHandle = $screwHandleItem ? (float)$screwHandleItem->satuan_terkecil : 0;
    $screwHandleQty = $totalWindowHardwareHandleQty * $satuanTerkecilScrewHandle;
    if ($screwHandleItem) {
        $screwHandleItem->qty = $screwHandleQty;
    }

    // === PERHITUNGAN SETTING BLOCK ===
    $settingBlockItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'setting-block') {
            $settingBlockItem = $item;
            break;
        }
    }
    
    $satuanTerkecilSettingBlock = $settingBlockItem ? (float)$settingBlockItem->satuan_terkecil : 0;
    
    $variableC = 1 * $satuanTerkecilSettingBlock;
    $variableD = $variableC * $jumlah;
    $variableE = $variableD * 25;
    $variableF = $variableE / 1000;
    $settingBlockQty = ceil($variableF);

    // === PERHITUNGAN SCREW REINFORCEMENT ===
    $screwItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-reinforcement') {
            $screwItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrew = $screwItem ? (float)$screwItem->satuan_terkecil : 0;
    $screwQty = ((($totalLebar + $totalPanjang)) + ($variableSashVertikalB + $variableSashHorizontalB)) / $satuanTerkecilScrew;
    $screwQty = ceil($screwQty * 10);

    // === HITUNG QTY PER AKSESORIS ===
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        $areaSlug = $item->area ? $item->area->slug : '';
        $qty = 0;
        
        if ($areaSlug == 'profile-vertikal') {
            $qty = $batangVertikal;
        } elseif ($areaSlug == 'profile-horizontal') {
            $qty = $batangHorizontal;
        } elseif ($areaSlug == 'glaze-bead-vertical') {
            $qty = ($panjang / 100) * $jumlah;
        } elseif ($areaSlug == 'glaze-bead-horizontal') {
            $qty = ($lebar / 100) * $jumlah;
        } elseif ($areaSlug == 'reinforcement') {
            $qty = $reinforcementQty;
        } elseif ($areaSlug == 'reinforcement-sash') {
            $qty = $reinforcementSashQty;
        } elseif ($areaSlug == 'kaca') {
            $qty = $luasKacaTotal;
        } elseif ($areaSlug == 'screw-reinforcement') {
            $qty = $screwQty;
        } elseif ($areaSlug == 'setting-block') {
            $qty = $settingBlockQty;
        } elseif ($areaSlug == 'profile-sash-vertikal') {
            $qty = $batangSashVertikalQty;
        } elseif ($areaSlug == 'profile-sash-horizontal') {
            $qty = $batangSashHorizontalQty;
        } elseif ($areaSlug == 'window-hardware-transmitter') {
            $qty = ($transmitterItem && $transmitterItem->id == $item->id) ? $transmitterItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-friction-stay') {
            $qty = ($frictionStayItem && $frictionStayItem->id == $item->id) ? $frictionStayItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-handle-rambuncis' || $areaSlug == 'window-hardware-handle-multilock') {
            $qty = $item->qty;
        } elseif ($areaSlug == 'screw-transmitter') {
            $qty = $screwTransmitterQty;
        } elseif ($areaSlug == 'screw-friction-stay') {
            $qty = $screwFrictionStayQty;
        } elseif ($areaSlug == 'screw-handle') {
            $qty = $screwHandleQty;
        } elseif ($areaSlug == 'profile-decoration-vertikal') {
            $qty = $batangDecorationVertikalQty;
        } elseif ($areaSlug == 'profile-decoration-horizontal') {
            $qty = $batangDecorationHorizontalQty;
        } else {
            $qty = $jumlah * ($item->satuan_terkecil ?? 1);
        }
        
        $item->qty = $qty;
    }

    // Kelompokkan berdasarkan area
    $grouped = [];
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->qty <= 0) {
            continue;
        }
        
        // Skip transmitter, friction stay, dan handle yang tidak terpilih (qty 0)
        if ($item->area && ($item->area->slug == 'window-hardware-transmitter' || $item->area->slug == 'window-hardware-friction-stay' || $item->area->slug == 'window-hardware-handle-rambuncis' || $item->area->slug == 'window-hardware-handle-multilock') && $item->qty <= 0) {
            continue;
        }
        
        $areaSlug = $item->area ? $item->area->slug : 'lainnya';
        
        if (str_starts_with($areaSlug, 'profile')) {
            $groupKey = 'profile';
        } elseif ($areaSlug == 'setting-block') {
            $groupKey = 'kaca';
        } elseif ($areaSlug == 'reinforcement' || $areaSlug == 'reinforcement-sash') {
            $groupKey = 'reinforcement';
        } elseif (str_starts_with($areaSlug, 'window-hardware')) {
            $groupKey = 'window-hardware';
        } elseif ($areaSlug == 'screw-reinforcement' || $areaSlug == 'screw-transmitter' || $areaSlug == 'screw-friction-stay' || $areaSlug == 'screw-handle') {
            $groupKey = 'screw';
        } else {
            $groupKey = $areaSlug;
        }
        
        if (!isset($grouped[$groupKey])) {
            $grouped[$groupKey] = [];
        }
        $grouped[$groupKey][] = $item;
    }

    $areaLabels = [
        'profile' => 'PROFILE',
        'reinforcement' => 'REINFORCEMENT',
        'kaca' => 'KACA',
        'screw' => 'SCREW',
        'window-hardware' => 'WINDOW HARDWARE',
    ];

    // ============ GENERATE NOMOR BOQ ============
    $nomorBoq = Boq::generateNomorBoq();

    // ============ STORE BOQ ============
    try {
        $allResults = [];
        
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->qty > 0) {
                $allResults[] = [
                    'produk_id' => $item->id,
                    'qty' => $item->qty,
                    'nama_produk' => $item->nama_produk,
                ];
            }
        }
        
        $uniqueResults = [];
        $seenIds = [];
        $allResultsCount = count($allResults);
        
        for ($i = 0; $i < $allResultsCount; $i++) {
            $item = $allResults[$i];
            $produkId = $item['produk_id'] ?? null;
            
            if (!$produkId) {
                continue;
            }
            
            $isDuplicate = false;
            $seenCount = count($seenIds);
            for ($j = 0; $j < $seenCount; $j++) {
                if ($seenIds[$j] == $produkId) {
                    $isDuplicate = true;
                    break;
                }
            }
            
            if ($isDuplicate) {
                continue;
            }
            
            $seenIds[] = $produkId;
            $uniqueResults[] = $item;
        }
        
        if (count($uniqueResults) > 0) {
            $boq = new Boq();
            $boq->nomor_boq = $nomorBoq;
            $boq->tanggal_boq = now();
            $boq->save();
            
            $uniqueCount = count($uniqueResults);
            for ($i = 0; $i < $uniqueCount; $i++) {
                $item = $uniqueResults[$i];
                $produkId = $item['produk_id'] ?? null;
                $qty = (int)($item['qty'] ?? 0);
                
                if ($produkId && $qty > 0) {
                    $produk = Product::find($produkId);
                    
                    \DB::table('detail_boq')->insert([
                        'boq_id' => $boq->id,
                        'produk_id' => $produkId,
                        'kode_produk' => $produk ? $produk->kode_produk : null,
                        'qty' => $qty,
                        'created_at' => now(),
                        'updated_at' => now()
                    ]);
                }
            }
            
            \Log::info('BOQ SAVED JENDELA JUNGKIT 1:', [
                'boq_id' => $boq->id,
                'nomor_boq' => $nomorBoq,
                'total' => count($uniqueResults)
            ]);
        }
        
    } catch (\Exception $e) {
        \Log::error('Error saving BOQ Jendela Jungkit 1: ' . $e->getMessage());
        \Log::error($e->getTraceAsString());
    }

    $data = [
        'judul' => $judul,
        'panjang' => $panjang,
        'lebar' => $lebar,
        'tebal_kaca' => $tebal_kaca,
        'jumlah' => $jumlah,
        'warna' => $warna,
        'type_kaca' => $type_kaca,
        'handle_id' => $handle_id,
        'is_multilock' => $isMultilock,
        'luas_kaca_total' => $luasKacaTotal,
        'keliling_total' => $kelilingTotal,
        'batang_vertikal' => $batangVertikal,
        'batang_horizontal' => $batangHorizontal,
        'reinforcement_qty' => $reinforcementQty,
        'reinforcement_sash_qty' => $reinforcementSashQty,
        'batang_sash_vertikal_qty' => $batangSashVertikalQty,
        'batang_sash_horizontal_qty' => $batangSashHorizontalQty,
        'total_decoration_bar_qty' => $totalDecorationBarQty,
        'handle_item' => $handleItem,
        'total_window_hardware_handle_qty' => $totalWindowHardwareHandleQty,
        'transmitter_item' => $transmitterItem,
        'ukuran_transmitter' => $ukuranTransmitter,
        'ukuran_transmitter_final' => $ukuranTransmitterFinal,
        'total_window_hardware_transmitter_qty' => $totalWindowHardwareTransmitterQty,
        'friction_stay_item' => $frictionStayItem,
        'ukuran_friction_stay' => $ukuranFrictionStay,
        'ukuran_friction_stay_final' => $ukuranFrictionStayFinal,
        'total_window_hardware_friction_stay_qty' => $totalWindowHardwareFrictionStayQty,
        'screw_transmitter_qty' => $screwTransmitterQty,
        'screw_friction_stay_qty' => $screwFrictionStayQty,
        'screw_handle_qty' => $screwHandleQty,
        'screw_qty' => $screwQty,
        'setting_block_qty' => $settingBlockQty,
        'grouped' => $grouped,
        'areaLabels' => $areaLabels,
        'nomor_boq' => $nomorBoq,
    ];

    return view('boq.jendela.pdf-jendela-jungkit-1', compact('data'));
}

public function hitungJungkit2(Request $request)
{
    $request->validate([
        'panjang' => 'required|numeric|min:1',
        'lebar' => 'required|numeric|min:1',
        'tebal_kaca' => 'required|numeric|min:1',
        'jumlah' => 'required|numeric|min:1',
        'warna' => 'required|string',
        'type_kaca' => 'required|string',
    ]);

    // Ambil data dari form
    $panjang = $request->panjang; // cm
    $lebar = $request->lebar; // cm
    $tebalKaca = $request->tebal_kaca; // mm
    $jumlah = $request->jumlah;
    $warna = $request->warna;
    $typeKaca = $request->type_kaca;
    $handleId = $request->handle_id;

    // Ambil produk utama (Jendela Jungkit 1) dari database
    $produkUtama = Product::find(184);
    
    if (!$produkUtama) {
        return back()->with('error', 'Produk Jendela Jungkit 1 tidak ditemukan!');
    }

    // Ambil aksesoris dari tabel product_accessories dengan relasi area
    $aksesorisIds = ProductAccessories::where('parent_product_id', 184)->pluck('accessory_id');
    $aksesoris = Product::with('area', 'unit')
        ->whereIn('id', $aksesorisIds)
        ->get();

    // === PERHITUNGAN DASAR ===
    
    // Konversi ke meter
    $panjangM = $panjang / 100;
    $lebarM = $lebar / 100;
    $tebalKacaM = $tebalKaca / 1000;

    // 1. Luas Kaca (m²)
    $luasKacaPerUnit = $panjangM * $lebarM;
    $luasKacaTotal = $luasKacaPerUnit * $jumlah;
    $luasKacaTotal = ceil($luasKacaTotal * 10) / 10;

    // 2. Keliling Profile (meter)
    $kelilingPerUnit = 2 * ($panjangM + $lebarM);
    $kelilingTotal = $kelilingPerUnit * $jumlah;

    // === PERHITUNGAN PROFILE VERTIKAL ===
    $profileVertikal = null;
    $aksesorisCount = count($aksesoris);
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-vertikal') {
            $profileVertikal = $item;
            break;
        }
    }
    $satuanTerkecilVertikal = $profileVertikal ? (float)$profileVertikal->satuan_terkecil : 0;

    $variableA = $jumlah * 4;
    $frameVertikal = $variableA * $panjang;
    $batangVertikal = $frameVertikal / 580;
    $batangVertikal = ceil($batangVertikal * 10) / 10;
    $totalPanjang = $panjang * $variableA;

    // === PERHITUNGAN PROFILE HORIZONTAL ===
    $profileHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-horizontal') {
            $profileHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilHorizontal = $profileHorizontal ? (float)$profileHorizontal->satuan_terkecil : 0;
    
    $variableB = $jumlah * $satuanTerkecilHorizontal;
    $frameHorizontal = $variableB * $lebar;
    $batangHorizontal = $frameHorizontal / 580;
    $batangHorizontal = ceil($batangHorizontal * 10) / 10;
    $totalLebar = $lebar * $variableB;

    // === PERHITUNGAN REINFORCEMENT ===
    $totalBatang = ($frameVertikal + $frameHorizontal) / 600;
    $reinforcementQty = ceil($totalBatang * 10) / 10;

    // === PERHITUNGAN PROFILE SASH VERTIKAL ===
    $profileSashVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-vertikal') {
            $profileSashVertikal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashVertikal = $profileSashVertikal ? (float)$profileSashVertikal->satuan_terkecil : 0;
    
    $variableSashVertikalA = 4 * $jumlah;
    $variableSashVertikalB = $variableSashVertikalA * $panjang;
    $batangSashVertikal = $variableSashVertikalB / 580;
    $batangSashVertikalQty = ceil($batangSashVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE SASH HORIZONTAL ===
    $profileSashHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-horizontal') {
            $profileSashHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashHorizontal = $profileSashHorizontal ? (float)$profileSashHorizontal->satuan_terkecil : 0;
    
    $variableSashHorizontalA = $satuanTerkecilSashHorizontal * $jumlah;
    $variableSashHorizontalB = $variableSashHorizontalA * $lebar;
    $batangSashHorizontal = $variableSashHorizontalB / 580;
    $batangSashHorizontalQty = ceil($batangSashHorizontal * 10) / 10;

    // === PERHITUNGAN PROFILE COUPLING VERTIKAL ===
    $profileCouplingVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-coupling-vertikal') {
            $profileCouplingVertikal = $item;
            break;
        }
    }

    $satuanTerkecilCouplingVertikal = $profileCouplingVertikal ? (float)$profileCouplingVertikal->satuan_terkecil : 0;

    $variableCouplingVertikalA = $satuanTerkecilCouplingVertikal * $jumlah * 2;
    $variableCouplingVertikalB = $variableCouplingVertikalA * $panjang;
    $batangCouplingVertikal = $variableCouplingVertikalB / 580;
    $batangCouplingVertikalQty = ceil($batangCouplingVertikal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT SASH ===
    $totalBatangSash = ($variableSashVertikalB + $variableSashHorizontalB) / 600;
    $reinforcementSashQty = ceil($totalBatangSash * 10) / 10;

    // === PERHITUNGAN DECORATION BAR ===
    $decorationBarVertikalInput = (int)($request->decoration_bar_vertikal ?? 0);
    $decorationBarVertikalItem = null;
    $batangDecorationVertikal = 0;
    $batangDecorationVertikalQty = 0;

    if ($decorationBarVertikalInput > 0) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'profile-decoration-vertikal') {
                $decorationBarVertikalItem = $item;
                break;
            }
        }
        if ($decorationBarVertikalItem) {
            $satuanTerkecil = (float)($decorationBarVertikalItem->satuan_terkecil ?? 0);
            $variableDecorationVertikalA = $decorationBarVertikalInput * $jumlah * 2;
            $variableDecorationVertikalB = $variableDecorationVertikalA * $panjang;
            $batangDecorationVertikal = $variableDecorationVertikalB / 580;
            $batangDecorationVertikalQty = ceil($batangDecorationVertikal * 10) / 10;
            $decorationBarVertikalItem->qty = $batangDecorationVertikalQty;
        }
    }

    $decorationBarHorizontalInput = (int)($request->decoration_bar_horizontal ?? 0);
    $decorationBarHorizontalItem = null;
    $batangDecorationHorizontal = 0;
    $batangDecorationHorizontalQty = 0;

    if ($decorationBarHorizontalInput > 0) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'profile-decoration-horizontal') {
                $decorationBarHorizontalItem = $item;
                break;
            }
        }
        if ($decorationBarHorizontalItem) {
            $satuanTerkecil = (float)($decorationBarHorizontalItem->satuan_terkecil ?? 0);
            $variableDecorationHorizontalA = $decorationBarHorizontalInput * $jumlah * 2;
            $variableDecorationHorizontalB = $variableDecorationHorizontalA * $lebar;
            $batangDecorationHorizontal = $variableDecorationHorizontalB / 580;
            $batangDecorationHorizontalQty = ceil($batangDecorationHorizontal * 10) / 10;
            $decorationBarHorizontalItem->qty = $batangDecorationHorizontalQty;
        }
    }

    $totalDecorationBarQty = ceil(($batangDecorationVertikal + $batangDecorationHorizontal) * 10) / 10;

    // === PERHITUNGAN WINDOW HARDWARE HANDLE (dari dropdown) ===
    $handleItem = null;
    $totalWindowHardwareHandleQty = 0;

    // RESET QTY UNTUK SEMUA HANDLE = 0
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && ($item->area->slug == 'window-hardware-handle-rambuncis' || $item->area->slug == 'window-hardware-handle-multilock')) {
            $item->qty = 0;
        }
    }

    // SET QTY UNTUK HANDLE YANG DIPILIH
    if ($handleId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $handleId) {
                $handleItem = $item;
                break;
            }
        }
    }

    if ($handleItem) {
        $satuanTerkecil = (float)($handleItem->satuan_terkecil ?? 0);
        $qty = $jumlah * 2;
        $handleItem->qty = $qty;
        $totalWindowHardwareHandleQty += $qty;
    }

    // CEK APAKAH HANDLE YANG DIPILIH ADALAH MULTILOCK
    $isMultilock = false;
    if ($handleItem) {
        $namaLower = strtolower($handleItem->nama_produk);
        if (str_contains($namaLower, 'multilock')) {
            $isMultilock = true;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE TRANSMITTER ===
    $transmitterItem = null;
    $totalWindowHardwareTransmitterQty = 0;
    $ukuranTransmitter = 0;
    $ukuranTransmitterFinal = 0;

    // HANYA HITUNG TRANSMITTER JIKA HANDLE MULTILOCK
    if ($isMultilock) {
        $ukuranTransmitter = $panjang - 20;

        $transmitterMapping = [
            40 => 172,
            60 => 171,
            80 => 170,
            100 => 173,
            120 => 162,
            140 => 166,
            160 => 167,
            180 => 168,
            200 => 169,
        ];

        $ukuranTransmitterFinal = $ukuranTransmitter;
        if (!isset($transmitterMapping[$ukuranTransmitter])) {
            $availableSizes = array_keys($transmitterMapping);
            sort($availableSizes);
            
            $found = false;
            for ($i = 0; $i < count($availableSizes); $i++) {
                if ($availableSizes[$i] >= $ukuranTransmitter) {
                    $ukuranTransmitterFinal = $availableSizes[$i];
                    $found = true;
                    break;
                }
            }
            
            if (!$found) {
                $ukuranTransmitterFinal = max($availableSizes);
            }
        }

        $transmitterId = $transmitterMapping[$ukuranTransmitterFinal] ?? null;

        if ($transmitterId) {
            for ($i = 0; $i < $aksesorisCount; $i++) {
                $item = $aksesoris[$i];
                if ($item->id == $transmitterId) {
                    $transmitterItem = $item;
                    break;
                }
            }
        }

        if ($transmitterItem) {
            $satuanTerkecil = (float)($transmitterItem->satuan_terkecil ?? 0);
            $qty = $jumlah * 2;
            $transmitterItem->qty = $qty;
            $totalWindowHardwareTransmitterQty += $qty;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE FRICTION STAY ===
    $ukuranFrictionStay = $panjang / 3;

    $frictionStayMapping = [
        25 => 175,
        30 => 174,
        35 => 179,
        40 => 173,
        45 => 176,
        50 => 177,
        60 => 178,
    ];

    $ukuranFrictionStayFinal = $ukuranFrictionStay;
    if (!isset($frictionStayMapping[$ukuranFrictionStay])) {
        $availableSizes = array_keys($frictionStayMapping);
        sort($availableSizes);
        
        $found = false;
        for ($i = 0; $i < count($availableSizes); $i++) {
            if ($availableSizes[$i] >= $ukuranFrictionStay) {
                $ukuranFrictionStayFinal = $availableSizes[$i];
                $found = true;
                break;
            }
        }
        
        if (!$found) {
            $ukuranFrictionStayFinal = max($availableSizes);
        }
    }

    $frictionStayItem = null;
    $frictionStayId = $frictionStayMapping[$ukuranFrictionStayFinal] ?? null;

    if ($frictionStayId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $frictionStayId) {
                $frictionStayItem = $item;
                break;
            }
        }
    }

    $totalWindowHardwareFrictionStayQty = 0;
    if ($frictionStayItem) {
        $satuanTerkecil = (float)($frictionStayItem->satuan_terkecil ?? 0);
        $qty = $jumlah * 4;
        $frictionStayItem->qty = $qty;
        $totalWindowHardwareFrictionStayQty += $qty;
    }

    // === PERHITUNGAN SCREW TRANSMITTER ===
    $screwTransmitterItem = null;
    $screwTransmitterQty = 0;

    // HANYA JIKA MULTILOCK DAN ADA TRANSMITTER
    if ($isMultilock && $transmitterItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-transmitter') {
                $screwTransmitterItem = $item;
                break;
            }
        }

        $satuanTerkecilScrewTransmitter = $screwTransmitterItem ? (float)$screwTransmitterItem->satuan_terkecil : 0;
        $screwTransmitterQty = ($totalWindowHardwareTransmitterQty * $satuanTerkecilScrewTransmitter);
        if ($screwTransmitterItem) {
            $screwTransmitterItem->qty = $screwTransmitterQty;
        }
    }

    // === PERHITUNGAN SCREW FRICTION STAY ===
    $screwFrictionStayItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-friction-stay') {
            $screwFrictionStayItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewFrictionStay = $screwFrictionStayItem ? (float)$screwFrictionStayItem->satuan_terkecil : 0;
    $screwFrictionStayQty = $totalWindowHardwareFrictionStayQty * $satuanTerkecilScrewFrictionStay;
    if ($screwFrictionStayItem) {
        $screwFrictionStayItem->qty = $screwFrictionStayQty;
    }

    // === PERHITUNGAN SCREW HANDLE ===
    $screwHandleItem = null;
    if ($handleItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-handle') {
                $screwHandleItem = $item;
                break;
            }
        }
    }

    $satuanTerkecilScrewHandle = $screwHandleItem ? (float)$screwHandleItem->satuan_terkecil : 0;
    $screwHandleQty = $totalWindowHardwareHandleQty * $satuanTerkecilScrewHandle;
    if ($screwHandleItem) {
        $screwHandleItem->qty = $screwHandleQty;
    }

    // === PERHITUNGAN SETTING BLOCK ===
    $settingBlockItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'setting-block') {
            $settingBlockItem = $item;
            break;
        }
    }
    
    $satuanTerkecilSettingBlock = $settingBlockItem ? (float)$settingBlockItem->satuan_terkecil : 0;
    
    $variableC = 1 * $satuanTerkecilSettingBlock;
    $variableD = $variableC * $jumlah;
    $variableE = $variableD * 25;
    $variableF = $variableE / 1000;
    $settingBlockQty = ceil($variableF);

    // === PERHITUNGAN SCREW REINFORCEMENT ===
    $screwItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-reinforcement') {
            $screwItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrew = $screwItem ? (float)$screwItem->satuan_terkecil : 0;
    $screwQty = ((($totalLebar + $totalPanjang)) + ($variableSashVertikalB + $variableSashHorizontalB)) / $satuanTerkecilScrew;
    $screwQty = ceil($screwQty * 10);

    // === PERHITUNGAN QTY PER AKSESORIS ===
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        $areaSlug = $item->area ? $item->area->slug : '';
        $qty = 0;
        
        if ($areaSlug == 'profile-vertikal') {
            $qty = $batangVertikal;
        } elseif ($areaSlug == 'profile-horizontal') {
            $qty = $batangHorizontal;
        } elseif ($areaSlug == 'glaze-bead-vertical') {
            $qty = ($panjang / 100) * $jumlah;
        } elseif ($areaSlug == 'glaze-bead-horizontal') {
            $qty = ($lebar / 100) * $jumlah;
        } elseif ($areaSlug == 'reinforcement') {
            $qty = $reinforcementQty;
        } elseif ($areaSlug == 'reinforcement-sash') {
            $qty = $reinforcementSashQty;
        } elseif ($areaSlug == 'kaca') {
            $qty = $luasKacaTotal;
        } elseif ($areaSlug == 'screw-reinforcement') {
            $qty = $screwQty;
        } elseif ($areaSlug == 'setting-block') {
            $qty = $settingBlockQty;
        } elseif ($areaSlug == 'profile-sash-vertikal') {
            $qty = $batangSashVertikalQty;
        } elseif ($areaSlug == 'profile-sash-horizontal') {
            $qty = $batangSashHorizontalQty;
        } elseif ($areaSlug == 'profile-coupling-vertikal') {
            $qty = $batangCouplingVertikalQty;
        } elseif ($areaSlug == 'window-hardware-transmitter') {
            $qty = ($transmitterItem && $transmitterItem->id == $item->id) ? $transmitterItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-friction-stay') {
            $qty = ($frictionStayItem && $frictionStayItem->id == $item->id) ? $frictionStayItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-handle-rambuncis' || $areaSlug == 'window-hardware-handle-multilock') {
            $qty = $item->qty;
        } elseif ($areaSlug == 'screw-transmitter') {
            $qty = $screwTransmitterQty;
        } elseif ($areaSlug == 'screw-friction-stay') {
            $qty = $screwFrictionStayQty;
        } elseif ($areaSlug == 'screw-handle') {
            $qty = $screwHandleQty;
        } elseif ($areaSlug == 'profile-decoration-vertikal') {
            $qty = $batangDecorationVertikalQty;
        } elseif ($areaSlug == 'profile-decoration-horizontal') {
            $qty = $batangDecorationHorizontalQty;
        } else {
            $qty = $jumlah * ($item->satuan_terkecil ?? 1);
        }
        
        $item->qty = $qty;
    }

    // Data untuk view
    $data = [
        'produk' => $produkUtama,
        'panjang' => $panjang,
        'lebar' => $lebar,
        'tebal_kaca' => $tebalKaca,
        'jumlah' => $jumlah,
        'warna' => $warna,
        'type_kaca' => $typeKaca,
        'handle_id' => $handleId,
        'is_multilock' => $isMultilock,
        
        'luas_kaca_per_unit' => $luasKacaPerUnit,
        'luas_kaca_total' => $luasKacaTotal,
        'keliling_per_unit' => $kelilingPerUnit,
        'keliling_total' => $kelilingTotal,
        
        'profile_vertikal' => $profileVertikal,
        'variable_a' => $variableA,
        'frame_vertikal' => $frameVertikal,
        'batang_vertikal' => $batangVertikal,
        
        'profile_horizontal' => $profileHorizontal,
        'satuan_terkecil_horizontal' => $satuanTerkecilHorizontal,
        'variable_b' => $variableB,
        'frame_horizontal' => $frameHorizontal,
        'batang_horizontal' => $batangHorizontal,
        
        'total_batang' => $totalBatang,
        'reinforcement_qty' => $reinforcementQty,
        
        'profile_sash_vertikal' => $profileSashVertikal,
        'satuan_terkecil_sash_vertikal' => $satuanTerkecilSashVertikal,
        'variable_sash_vertikal_a' => $variableSashVertikalA,
        'variable_sash_vertikal_b' => $variableSashVertikalB,
        'batang_sash_vertikal' => $batangSashVertikal,
        'batang_sash_vertikal_qty' => $batangSashVertikalQty,
        
        'profile_sash_horizontal' => $profileSashHorizontal,
        'satuan_terkecil_sash_horizontal' => $satuanTerkecilSashHorizontal,
        'variable_sash_horizontal_a' => $variableSashHorizontalA,
        'variable_sash_horizontal_b' => $variableSashHorizontalB,
        'batang_sash_horizontal' => $batangSashHorizontal,
        'batang_sash_horizontal_qty' => $batangSashHorizontalQty,
        
        'profile_coupling_vertikal' => $profileCouplingVertikal,
        'satuan_terkecil_coupling_vertikal' => $satuanTerkecilCouplingVertikal,
        'variable_coupling_vertikal_a' => $variableCouplingVertikalA,
        'variable_coupling_vertikal_b' => $variableCouplingVertikalB,
        'batang_coupling_vertikal' => $batangCouplingVertikal,
        'batang_coupling_vertikal_qty' => $batangCouplingVertikalQty,
        
        'reinforcement_sash_qty' => $reinforcementSashQty,
        
        'decoration_bar_vertikal_input' => $decorationBarVertikalInput,
        'decoration_bar_vertikal_item' => $decorationBarVertikalItem,
        'batang_decoration_vertikal' => $batangDecorationVertikal,
        'batang_decoration_vertikal_qty' => $batangDecorationVertikalQty,
        
        'decoration_bar_horizontal_input' => $decorationBarHorizontalInput,
        'decoration_bar_horizontal_item' => $decorationBarHorizontalItem,
        'batang_decoration_horizontal' => $batangDecorationHorizontal,
        'batang_decoration_horizontal_qty' => $batangDecorationHorizontalQty,
        
        'total_decoration_bar_qty' => $totalDecorationBarQty,
        
        'transmitter_item' => $transmitterItem,
        'ukuran_transmitter' => $ukuranTransmitter,
        'ukuran_transmitter_final' => $ukuranTransmitterFinal,
        'total_window_hardware_transmitter_qty' => $totalWindowHardwareTransmitterQty,
        
        'friction_stay_item' => $frictionStayItem,
        'ukuran_friction_stay' => $ukuranFrictionStay,
        'ukuran_friction_stay_final' => $ukuranFrictionStayFinal,
        'total_window_hardware_friction_stay_qty' => $totalWindowHardwareFrictionStayQty,
        
        'handle_item' => $handleItem,
        'total_window_hardware_handle_qty' => $totalWindowHardwareHandleQty,
        
        'screw_transmitter_item' => $screwTransmitterItem,
        'screw_transmitter_qty' => $screwTransmitterQty,
        
        'screw_friction_stay_item' => $screwFrictionStayItem,
        'screw_friction_stay_qty' => $screwFrictionStayQty,
        
        'screw_handle_item' => $screwHandleItem,
        'screw_handle_qty' => $screwHandleQty,
        
        'satuan_terkecil_screw' => $satuanTerkecilScrew,
        'screw_qty' => $screwQty,
        
        'setting_block_item' => $settingBlockItem,
        'satuan_terkecil_setting_block' => $satuanTerkecilSettingBlock,
        'variable_c' => $variableC,
        'variable_d' => $variableD,
        'variable_e' => $variableE,
        'variable_f' => $variableF,
        'setting_block_qty' => $settingBlockQty,
        
        'aksesoris' => $aksesoris,
    ];

    return view('boq.jendela.jendela-jungkit-2', $data);
}

public function exportPdfJungkit2(Request $request)
{
    $panjang = $request->panjang;
    $lebar = $request->lebar;
    $tebal_kaca = $request->tebal_kaca;
    $jumlah = $request->jumlah;
    $warna = $request->warna;
    $type_kaca = $request->type_kaca;
    $handle_id = $request->handle_id;
    $judul = $request->judul ?? 'BOQ - Jendela Jungkit 2 Daun';

    // Ambil data aksesoris
    $aksesorisIds = ProductAccessories::where('parent_product_id', 184)->pluck('accessory_id');
    $aksesoris = Product::with('area', 'unit')
        ->whereIn('id', $aksesorisIds)
        ->get();

    // === PERHITUNGAN DASAR ===
    $panjangM = $panjang / 100;
    $lebarM = $lebar / 100;
    
    $luasKacaPerUnit = $panjangM * $lebarM;
    $luasKacaTotal = $luasKacaPerUnit * $jumlah;
    $luasKacaTotal = ceil($luasKacaTotal * 10) / 10;

    $kelilingPerUnit = 2 * ($panjangM + $lebarM);
    $kelilingTotal = $kelilingPerUnit * $jumlah;

    // === PERHITUNGAN PROFILE VERTIKAL ===
    $profileVertikal = null;
    $aksesorisCount = count($aksesoris);
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-vertikal') {
            $profileVertikal = $item;
            break;
        }
    }
    $satuanTerkecilVertikal = $profileVertikal ? (float)$profileVertikal->satuan_terkecil : 0;

    $variableA = $jumlah * 4;
    $frameVertikal = $variableA * $panjang;
    $batangVertikal = $frameVertikal / 580;
    $batangVertikal = ceil($batangVertikal * 10) / 10;
    $totalPanjang = $panjang * $variableA;

    // === PERHITUNGAN PROFILE HORIZONTAL ===
    $profileHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-horizontal') {
            $profileHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilHorizontal = $profileHorizontal ? (float)$profileHorizontal->satuan_terkecil : 0;
    
    $variableB = $jumlah * $satuanTerkecilHorizontal;
    $frameHorizontal = $variableB * $lebar;
    $batangHorizontal = $frameHorizontal / 580;
    $batangHorizontal = ceil($batangHorizontal * 10) / 10;
    $totalLebar = $lebar * $variableB;

    // === PERHITUNGAN REINFORCEMENT ===
    $totalBatang = ($frameVertikal + $frameHorizontal) / 600;
    $reinforcementQty = ceil($totalBatang * 10) / 10;

    // === PERHITUNGAN PROFILE SASH VERTIKAL ===
    $profileSashVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-vertikal') {
            $profileSashVertikal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashVertikal = $profileSashVertikal ? (float)$profileSashVertikal->satuan_terkecil : 0;
    
    $variableSashVertikalA = 4 * $jumlah;
    $variableSashVertikalB = $variableSashVertikalA * $panjang;
    $batangSashVertikal = $variableSashVertikalB / 580;
    $batangSashVertikalQty = ceil($batangSashVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE SASH HORIZONTAL ===
    $profileSashHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-horizontal') {
            $profileSashHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashHorizontal = $profileSashHorizontal ? (float)$profileSashHorizontal->satuan_terkecil : 0;
    
    $variableSashHorizontalA = $satuanTerkecilSashHorizontal * $jumlah;
    $variableSashHorizontalB = $variableSashHorizontalA * $lebar;
    $batangSashHorizontal = $variableSashHorizontalB / 580;
    $batangSashHorizontalQty = ceil($batangSashHorizontal * 10) / 10;

    // === PERHITUNGAN PROFILE COUPLING VERTIKAL ===
    $profileCouplingVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-coupling-vertikal') {
            $profileCouplingVertikal = $item;
            break;
        }
    }

    $satuanTerkecilCouplingVertikal = $profileCouplingVertikal ? (float)$profileCouplingVertikal->satuan_terkecil : 0;

    $variableCouplingVertikalA = $satuanTerkecilCouplingVertikal * $jumlah * 2;
    $variableCouplingVertikalB = $variableCouplingVertikalA * $panjang;
    $batangCouplingVertikal = $variableCouplingVertikalB / 580;
    $batangCouplingVertikalQty = ceil($batangCouplingVertikal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT SASH ===
    $totalBatangSash = ($variableSashVertikalB + $variableSashHorizontalB) / 600;
    $reinforcementSashQty = ceil($totalBatangSash * 10) / 10;

    // === PERHITUNGAN DECORATION BAR ===
    $decorationBarVertikalInput = (int)($request->decoration_bar_vertikal ?? 0);
    $decorationBarVertikalItem = null;
    $batangDecorationVertikal = 0;
    $batangDecorationVertikalQty = 0;

    if ($decorationBarVertikalInput > 0) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'profile-decoration-vertikal') {
                $decorationBarVertikalItem = $item;
                break;
            }
        }
        if ($decorationBarVertikalItem) {
            $satuanTerkecil = (float)($decorationBarVertikalItem->satuan_terkecil ?? 0);
            $variableDecorationVertikalA = $decorationBarVertikalInput * $jumlah * 2;
            $variableDecorationVertikalB = $variableDecorationVertikalA * $panjang;
            $batangDecorationVertikal = $variableDecorationVertikalB / 580;
            $batangDecorationVertikalQty = ceil($batangDecorationVertikal * 10) / 10;
            $decorationBarVertikalItem->qty = $batangDecorationVertikalQty;
        }
    }

    $decorationBarHorizontalInput = (int)($request->decoration_bar_horizontal ?? 0);
    $decorationBarHorizontalItem = null;
    $batangDecorationHorizontal = 0;
    $batangDecorationHorizontalQty = 0;

    if ($decorationBarHorizontalInput > 0) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'profile-decoration-horizontal') {
                $decorationBarHorizontalItem = $item;
                break;
            }
        }
        if ($decorationBarHorizontalItem) {
            $satuanTerkecil = (float)($decorationBarHorizontalItem->satuan_terkecil ?? 0);
            $variableDecorationHorizontalA = $decorationBarHorizontalInput * $jumlah * 2;
            $variableDecorationHorizontalB = $variableDecorationHorizontalA * $lebar;
            $batangDecorationHorizontal = $variableDecorationHorizontalB / 580;
            $batangDecorationHorizontalQty = ceil($batangDecorationHorizontal * 10) / 10;
            $decorationBarHorizontalItem->qty = $batangDecorationHorizontalQty;
        }
    }

    $totalDecorationBarQty = ceil(($batangDecorationVertikal + $batangDecorationHorizontal) * 10) / 10;

    // === PERHITUNGAN WINDOW HARDWARE HANDLE ===
    $handleItem = null;
    $totalWindowHardwareHandleQty = 0;

    // RESET QTY UNTUK SEMUA HANDLE = 0
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && ($item->area->slug == 'window-hardware-handle-rambuncis' || $item->area->slug == 'window-hardware-handle-multilock')) {
            $item->qty = 0;
        }
    }

    // SET QTY UNTUK HANDLE YANG DIPILIH
    if ($handle_id) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $handle_id) {
                $handleItem = $item;
                break;
            }
        }
    }

    if ($handleItem) {
        // QTY SELALU 2 UNTUK JENDELA JUNGKIT 2
        $qty = 2;
        $handleItem->qty = $qty;
        $totalWindowHardwareHandleQty += $qty;
    }

    // CEK APAKAH HANDLE YANG DIPILIH ADALAH MULTILOCK
    $isMultilock = false;
    if ($handleItem) {
        $namaLower = strtolower($handleItem->nama_produk);
        if (str_contains($namaLower, 'multilock')) {
            $isMultilock = true;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE TRANSMITTER ===
    $transmitterItem = null;
    $totalWindowHardwareTransmitterQty = 0;
    $ukuranTransmitter = 0;
    $ukuranTransmitterFinal = 0;

    if ($isMultilock) {
        $ukuranTransmitter = $panjang - 20;

        $transmitterMapping = [
            40 => 172,
            60 => 171,
            80 => 170,
            100 => 173,
            120 => 162,
            140 => 166,
            160 => 167,
            180 => 168,
            200 => 169,
        ];

        $ukuranTransmitterFinal = $ukuranTransmitter;
        if (!isset($transmitterMapping[$ukuranTransmitter])) {
            $availableSizes = array_keys($transmitterMapping);
            sort($availableSizes);
            
            $found = false;
            for ($i = 0; $i < count($availableSizes); $i++) {
                if ($availableSizes[$i] >= $ukuranTransmitter) {
                    $ukuranTransmitterFinal = $availableSizes[$i];
                    $found = true;
                    break;
                }
            }
            
            if (!$found) {
                $ukuranTransmitterFinal = max($availableSizes);
            }
        }

        $transmitterId = $transmitterMapping[$ukuranTransmitterFinal] ?? null;

        if ($transmitterId) {
            for ($i = 0; $i < $aksesorisCount; $i++) {
                $item = $aksesoris[$i];
                if ($item->id == $transmitterId) {
                    $transmitterItem = $item;
                    break;
                }
            }
        }

        if ($transmitterItem) {
            $qty = $jumlah * 2;
            $transmitterItem->qty = $qty;
            $totalWindowHardwareTransmitterQty += $qty;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE FRICTION STAY ===
    $ukuranFrictionStay = $panjang / 3;

    $frictionStayMapping = [
        25 => 175,
        30 => 174,
        35 => 179,
        40 => 173,
        45 => 176,
        50 => 177,
        60 => 178,
    ];

    $ukuranFrictionStayFinal = $ukuranFrictionStay;
    if (!isset($frictionStayMapping[$ukuranFrictionStay])) {
        $availableSizes = array_keys($frictionStayMapping);
        sort($availableSizes);
        
        $found = false;
        for ($i = 0; $i < count($availableSizes); $i++) {
            if ($availableSizes[$i] >= $ukuranFrictionStay) {
                $ukuranFrictionStayFinal = $availableSizes[$i];
                $found = true;
                break;
            }
        }
        
        if (!$found) {
            $ukuranFrictionStayFinal = max($availableSizes);
        }
    }

    $frictionStayItem = null;
    $frictionStayId = $frictionStayMapping[$ukuranFrictionStayFinal] ?? null;

    if ($frictionStayId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $frictionStayId) {
                $frictionStayItem = $item;
                break;
            }
        }
    }

    $totalWindowHardwareFrictionStayQty = 0;
    if ($frictionStayItem) {
        $qty = $jumlah * 4;
        $frictionStayItem->qty = $qty;
        $totalWindowHardwareFrictionStayQty += $qty;
    }

    // === PERHITUNGAN SCREW TRANSMITTER ===
    $screwTransmitterItem = null;
    $screwTransmitterQty = 0;

    if ($isMultilock && $transmitterItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-transmitter') {
                $screwTransmitterItem = $item;
                break;
            }
        }

        $satuanTerkecilScrewTransmitter = $screwTransmitterItem ? (float)$screwTransmitterItem->satuan_terkecil : 0;
        $screwTransmitterQty = ($totalWindowHardwareTransmitterQty * $satuanTerkecilScrewTransmitter);
        if ($screwTransmitterItem) {
            $screwTransmitterItem->qty = $screwTransmitterQty;
        }
    }

    // === PERHITUNGAN SCREW FRICTION STAY ===
    $screwFrictionStayItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-friction-stay') {
            $screwFrictionStayItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewFrictionStay = $screwFrictionStayItem ? (float)$screwFrictionStayItem->satuan_terkecil : 0;
    $screwFrictionStayQty = $totalWindowHardwareFrictionStayQty * $satuanTerkecilScrewFrictionStay;
    if ($screwFrictionStayItem) {
        $screwFrictionStayItem->qty = $screwFrictionStayQty;
    }

    // === PERHITUNGAN SCREW HANDLE ===
    $screwHandleItem = null;
    if ($handleItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-handle') {
                $screwHandleItem = $item;
                break;
            }
        }
    }

    $satuanTerkecilScrewHandle = $screwHandleItem ? (float)$screwHandleItem->satuan_terkecil : 0;
    $screwHandleQty = $totalWindowHardwareHandleQty * $satuanTerkecilScrewHandle;
    if ($screwHandleItem) {
        $screwHandleItem->qty = $screwHandleQty;
    }

    // === PERHITUNGAN SETTING BLOCK ===
    $settingBlockItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'setting-block') {
            $settingBlockItem = $item;
            break;
        }
    }
    
    $satuanTerkecilSettingBlock = $settingBlockItem ? (float)$settingBlockItem->satuan_terkecil : 0;
    
    $variableC = 1 * $satuanTerkecilSettingBlock;
    $variableD = $variableC * $jumlah;
    $variableE = $variableD * 25;
    $variableF = $variableE / 1000;
    $settingBlockQty = ceil($variableF);

    // === PERHITUNGAN SCREW REINFORCEMENT ===
    $screwItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-reinforcement') {
            $screwItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrew = $screwItem ? (float)$screwItem->satuan_terkecil : 0;
    $screwQty = ((($totalLebar + $totalPanjang)) + ($variableSashVertikalB + $variableSashHorizontalB)) / $satuanTerkecilScrew;
    $screwQty = ceil($screwQty * 10);

    // === HITUNG QTY PER AKSESORIS ===
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        $areaSlug = $item->area ? $item->area->slug : '';
        $qty = 0;
        
        if ($areaSlug == 'profile-vertikal') {
            $qty = $batangVertikal;
        } elseif ($areaSlug == 'profile-horizontal') {
            $qty = $batangHorizontal;
        } elseif ($areaSlug == 'glaze-bead-vertical') {
            $qty = ($panjang / 100) * $jumlah;
        } elseif ($areaSlug == 'glaze-bead-horizontal') {
            $qty = ($lebar / 100) * $jumlah;
        } elseif ($areaSlug == 'reinforcement') {
            $qty = $reinforcementQty;
        } elseif ($areaSlug == 'reinforcement-sash') {
            $qty = $reinforcementSashQty;
        } elseif ($areaSlug == 'kaca') {
            $qty = $luasKacaTotal;
        } elseif ($areaSlug == 'screw-reinforcement') {
            $qty = $screwQty;
        } elseif ($areaSlug == 'setting-block') {
            $qty = $settingBlockQty;
        } elseif ($areaSlug == 'profile-sash-vertikal') {
            $qty = $batangSashVertikalQty;
        } elseif ($areaSlug == 'profile-sash-horizontal') {
            $qty = $batangSashHorizontalQty;
        } elseif ($areaSlug == 'profile-coupling-vertikal') {
            $qty = $batangCouplingVertikalQty;
        } elseif ($areaSlug == 'window-hardware-transmitter') {
            $qty = ($transmitterItem && $transmitterItem->id == $item->id) ? $transmitterItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-friction-stay') {
            $qty = ($frictionStayItem && $frictionStayItem->id == $item->id) ? $frictionStayItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-handle-rambuncis' || $areaSlug == 'window-hardware-handle-multilock') {
            $qty = $item->qty;
        } elseif ($areaSlug == 'screw-transmitter') {
            $qty = $screwTransmitterQty;
        } elseif ($areaSlug == 'screw-friction-stay') {
            $qty = $screwFrictionStayQty;
        } elseif ($areaSlug == 'screw-handle') {
            $qty = $screwHandleQty;
        } elseif ($areaSlug == 'profile-decoration-vertikal') {
            $qty = $batangDecorationVertikalQty;
        } elseif ($areaSlug == 'profile-decoration-horizontal') {
            $qty = $batangDecorationHorizontalQty;
        } else {
            $qty = $jumlah * ($item->satuan_terkecil ?? 1);
        }
        
        $item->qty = $qty;
    }

    // Kelompokkan berdasarkan area
    $grouped = [];
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->qty <= 0) {
            continue;
        }
        
        // Skip transmitter, friction stay, dan handle yang tidak terpilih (qty 0)
        if ($item->area && ($item->area->slug == 'window-hardware-transmitter' || $item->area->slug == 'window-hardware-friction-stay' || $item->area->slug == 'window-hardware-handle-rambuncis' || $item->area->slug == 'window-hardware-handle-multilock') && $item->qty <= 0) {
            continue;
        }
        
        $areaSlug = $item->area ? $item->area->slug : 'lainnya';
        
        if (str_starts_with($areaSlug, 'profile')) {
            $groupKey = 'profile';
        } elseif ($areaSlug == 'setting-block') {
            $groupKey = 'kaca';
        } elseif ($areaSlug == 'reinforcement' || $areaSlug == 'reinforcement-sash') {
            $groupKey = 'reinforcement';
        } elseif (str_starts_with($areaSlug, 'window-hardware')) {
            $groupKey = 'window-hardware';
        } elseif ($areaSlug == 'screw-reinforcement' || $areaSlug == 'screw-transmitter' || $areaSlug == 'screw-friction-stay' || $areaSlug == 'screw-handle') {
            $groupKey = 'screw';
        } else {
            $groupKey = $areaSlug;
        }
        
        if (!isset($grouped[$groupKey])) {
            $grouped[$groupKey] = [];
        }
        $grouped[$groupKey][] = $item;
    }

    $areaLabels = [
        'profile' => 'PROFILE',
        'reinforcement' => 'REINFORCEMENT',
        'kaca' => 'KACA',
        'screw' => 'SCREW',
        'window-hardware' => 'WINDOW HARDWARE',
    ];

    // ============ GENERATE NOMOR BOQ ============
    $nomorBoq = Boq::generateNomorBoq();

    // ============ STORE BOQ ============
    try {
        $allResults = [];
        
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->qty > 0) {
                $allResults[] = [
                    'produk_id' => $item->id,
                    'qty' => $item->qty,
                    'nama_produk' => $item->nama_produk,
                ];
            }
        }
        
        $uniqueResults = [];
        $seenIds = [];
        $allResultsCount = count($allResults);
        
        for ($i = 0; $i < $allResultsCount; $i++) {
            $item = $allResults[$i];
            $produkId = $item['produk_id'] ?? null;
            
            if (!$produkId) {
                continue;
            }
            
            $isDuplicate = false;
            $seenCount = count($seenIds);
            for ($j = 0; $j < $seenCount; $j++) {
                if ($seenIds[$j] == $produkId) {
                    $isDuplicate = true;
                    break;
                }
            }
            
            if ($isDuplicate) {
                continue;
            }
            
            $seenIds[] = $produkId;
            $uniqueResults[] = $item;
        }
        
        if (count($uniqueResults) > 0) {
            $boq = new Boq();
            $boq->nomor_boq = $nomorBoq;
            $boq->tanggal_boq = now();
            $boq->save();
            
            $uniqueCount = count($uniqueResults);
            for ($i = 0; $i < $uniqueCount; $i++) {
                $item = $uniqueResults[$i];
                $produkId = $item['produk_id'] ?? null;
                $qty = (int)($item['qty'] ?? 0);
                
                if ($produkId && $qty > 0) {
                    $produk = Product::find($produkId);
                    
                    \DB::table('detail_boq')->insert([
                        'boq_id' => $boq->id,
                        'produk_id' => $produkId,
                        'kode_produk' => $produk ? $produk->kode_produk : null,
                        'qty' => $qty,
                        'created_at' => now(),
                        'updated_at' => now()
                    ]);
                }
            }
            
            \Log::info('BOQ SAVED JENDELA JUNGKIT 2:', [
                'boq_id' => $boq->id,
                'nomor_boq' => $nomorBoq,
                'total' => count($uniqueResults)
            ]);
        }
        
    } catch (\Exception $e) {
        \Log::error('Error saving BOQ Jendela Jungkit 2: ' . $e->getMessage());
        \Log::error($e->getTraceAsString());
    }

    $data = [
        'judul' => $judul,
        'panjang' => $panjang,
        'lebar' => $lebar,
        'tebal_kaca' => $tebal_kaca,
        'jumlah' => $jumlah,
        'warna' => $warna,
        'type_kaca' => $type_kaca,
        'handle_id' => $handle_id,
        'is_multilock' => $isMultilock,
        'luas_kaca_total' => $luasKacaTotal,
        'keliling_total' => $kelilingTotal,
        'batang_vertikal' => $batangVertikal,
        'batang_horizontal' => $batangHorizontal,
        'reinforcement_qty' => $reinforcementQty,
        'reinforcement_sash_qty' => $reinforcementSashQty,
        'batang_sash_vertikal_qty' => $batangSashVertikalQty,
        'batang_sash_horizontal_qty' => $batangSashHorizontalQty,
        'batang_coupling_vertikal_qty' => $batangCouplingVertikalQty,
        'total_decoration_bar_qty' => $totalDecorationBarQty,
        'handle_item' => $handleItem,
        'total_window_hardware_handle_qty' => $totalWindowHardwareHandleQty,
        'transmitter_item' => $transmitterItem,
        'ukuran_transmitter' => $ukuranTransmitter,
        'ukuran_transmitter_final' => $ukuranTransmitterFinal,
        'total_window_hardware_transmitter_qty' => $totalWindowHardwareTransmitterQty,
        'friction_stay_item' => $frictionStayItem,
        'ukuran_friction_stay' => $ukuranFrictionStay,
        'ukuran_friction_stay_final' => $ukuranFrictionStayFinal,
        'total_window_hardware_friction_stay_qty' => $totalWindowHardwareFrictionStayQty,
        'screw_transmitter_qty' => $screwTransmitterQty,
        'screw_friction_stay_qty' => $screwFrictionStayQty,
        'screw_handle_qty' => $screwHandleQty,
        'screw_qty' => $screwQty,
        'setting_block_qty' => $settingBlockQty,
        'grouped' => $grouped,
        'areaLabels' => $areaLabels,
        'nomor_boq' => $nomorBoq,
    ];

    return view('boq.jendela.pdf-jendela-jungkit-2', compact('data'));
}

public function hitungJungkit1mullion(Request $request)
{
    $request->validate([
        'panjang' => 'required|numeric|min:1',
        'lebar' => 'required|numeric|min:1',
        'tebal_kaca' => 'required|numeric|min:1',
        'jumlah' => 'required|numeric|min:1',
        'warna' => 'required|string',
        'type_kaca' => 'required|string',
    ]);

    // Ambil data dari form
    $panjang = $request->panjang; // cm
    $lebar = $request->lebar; // cm
    $tebalKaca = $request->tebal_kaca; // mm
    $jumlah = $request->jumlah;
    $warna = $request->warna;
    $typeKaca = $request->type_kaca;
    $handleId = $request->handle_id;

    // Ambil produk utama (Jendela Jungkit 1) dari database
    $produkUtama = Product::find(185);
    
    if (!$produkUtama) {
        return back()->with('error', 'Produk Jendela Jungkit 1 tidak ditemukan!');
    }

    // Ambil aksesoris dari tabel product_accessories dengan relasi area
    $aksesorisIds = ProductAccessories::where('parent_product_id', 185)->pluck('accessory_id');
    $aksesoris = Product::with('area', 'unit')
        ->whereIn('id', $aksesorisIds)
        ->get();

    // === PERHITUNGAN DASAR ===
    
    // Konversi ke meter
    $panjangM = $panjang / 100;
    $lebarM = $lebar / 100;
    $tebalKacaM = $tebalKaca / 1000;

    // 1. Luas Kaca (m²)
    $luasKacaPerUnit = $panjangM * $lebarM;
    $luasKacaTotal = $luasKacaPerUnit * $jumlah;
    $luasKacaTotal = ceil($luasKacaTotal * 10) / 10;

    // 2. Keliling Profile (meter)
    $kelilingPerUnit = 2 * ($panjangM + $lebarM);
    $kelilingTotal = $kelilingPerUnit * $jumlah;

    // === PERHITUNGAN PROFILE VERTIKAL ===
    $profileVertikal = null;
    $aksesorisCount = count($aksesoris);
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-vertikal') {
            $profileVertikal = $item;
            break;
        }
    }
    $satuanTerkecilVertikal = $profileVertikal ? (float)$profileVertikal->satuan_terkecil : 0;

    $variableA = $jumlah * $satuanTerkecilVertikal;
    $frameVertikal = $variableA * $panjang;
    $batangVertikal = $frameVertikal / 580;
    $batangVertikal = ceil($batangVertikal * 10) / 10;
    $totalPanjang = $panjang * $variableA;

    // === PERHITUNGAN PROFILE HORIZONTAL ===
    $profileHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-horizontal') {
            $profileHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilHorizontal = $profileHorizontal ? (float)$profileHorizontal->satuan_terkecil : 0;
    
    $variableB = $jumlah * $satuanTerkecilHorizontal;
    $frameHorizontal = $variableB * $lebar;
    $batangHorizontal = $frameHorizontal / 580;
    $batangHorizontal = ceil($batangHorizontal * 10) / 10;
    $totalLebar = $lebar * $variableB;

    // === PERHITUNGAN REINFORCEMENT ===
    $totalBatang = ($frameVertikal + $frameHorizontal) / 600;
    $reinforcementQty = ceil($totalBatang * 10) / 10;

    // === PERHITUNGAN PROFILE SASH VERTIKAL ===
    $profileSashVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-vertikal') {
            $profileSashVertikal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashVertikal = $profileSashVertikal ? (float)$profileSashVertikal->satuan_terkecil : 0;
    
    $variableSashVertikalA = $satuanTerkecilSashVertikal * $jumlah;
    $variableSashVertikalB = $variableSashVertikalA * $panjang;
    $batangSashVertikal = $variableSashVertikalB / 580;
    $batangSashVertikalQty = ceil($batangSashVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE SASH HORIZONTAL ===
    $profileSashHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-horizontal') {
            $profileSashHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashHorizontal = $profileSashHorizontal ? (float)$profileSashHorizontal->satuan_terkecil : 0;
    
    $variableSashHorizontalA = $satuanTerkecilSashHorizontal * $jumlah;
    $variableSashHorizontalB = $variableSashHorizontalA * $lebar;
    $batangSashHorizontal = $variableSashHorizontalB / 580;
    $batangSashHorizontalQty = ceil($batangSashHorizontal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT SASH ===
    $totalBatangSash = ($variableSashVertikalB + $variableSashHorizontalB) / 600;
    $reinforcementSashQty = ceil($totalBatangSash * 10) / 10;

    // === PERHITUNGAN PROFILE MULLION VERTIKAL ===
    $profileMullionVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-mullion-vertikal') {
            $profileMullionVertikal = $item;
            break;
        }
    }

    $satuanTerkecilMullionVertikal = $profileMullionVertikal ? (float)$profileMullionVertikal->satuan_terkecil : 0;
    
    $variableMullionVertikalA = $satuanTerkecilMullionVertikal * $jumlah;
    $variableMullionVertikalB = $variableMullionVertikalA * $panjang;
    $batangMullionVertikal = $variableMullionVertikalB / 580;
    $batangMullionVertikalQty = ceil($batangMullionVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE MULLION HORIZONTAL ===
    $profileMullionHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-mullion-horizontal') {
            $profileMullionHorizontal = $item;
            break;
        }
    }

    $satuanTerkecilMullionHorizontal = $profileMullionHorizontal ? (float)$profileMullionHorizontal->satuan_terkecil : 0;
    
    $variableMullionHorizontalA = 6 * $jumlah;
    $variableMullionHorizontalB = $variableMullionHorizontalA * $lebar;
    $batangMullionHorizontal = $variableMullionHorizontalB / 580;
    $batangMullionHorizontalQty = ceil($batangMullionHorizontal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT MULLION ===
    $totalBatangMullion = ($variableMullionVertikalB + $variableMullionHorizontalB) / 600;
    $reinforcementMullionQty = ceil($totalBatangMullion * 10) / 10;

    // === PERHITUNGAN WINDOW HARDWARE HANDLE (dari dropdown) ===
    $handleItem = null;
    $totalWindowHardwareHandleQty = 0;

    // RESET QTY UNTUK SEMUA HANDLE = 0
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && ($item->area->slug == 'window-hardware-handle-rambuncis' || $item->area->slug == 'window-hardware-handle-multilock')) {
            $item->qty = 0;
        }
    }

    // SET QTY UNTUK HANDLE YANG DIPILIH
    if ($handleId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $handleId) {
                $handleItem = $item;
                break;
            }
        }
    }

    if ($handleItem) {
        $satuanTerkecil = (float)($handleItem->satuan_terkecil ?? 0);
        $qty = $jumlah * $satuanTerkecil;
        $handleItem->qty = $qty;
        $totalWindowHardwareHandleQty += $qty;
    }

    // CEK APAKAH HANDLE YANG DIPILIH ADALAH MULTILOCK
    $isMultilock = false;
    if ($handleItem) {
        $namaLower = strtolower($handleItem->nama_produk);
        if (str_contains($namaLower, 'multilock')) {
            $isMultilock = true;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE TRANSMITTER ===
    $transmitterItem = null;
    $totalWindowHardwareTransmitterQty = 0;
    $ukuranTransmitter = 0;
    $ukuranTransmitterFinal = 0;

    // HANYA HITUNG TRANSMITTER JIKA HANDLE MULTILOCK
    if ($isMultilock) {
        $ukuranTransmitter = $panjang - 20;

        $transmitterMapping = [
            40 => 172,
            60 => 171,
            80 => 170,
            100 => 173,
            120 => 162,
            140 => 166,
            160 => 167,
            180 => 168,
            200 => 169,
        ];

        $ukuranTransmitterFinal = $ukuranTransmitter;
        if (!isset($transmitterMapping[$ukuranTransmitter])) {
            $availableSizes = array_keys($transmitterMapping);
            sort($availableSizes);
            
            $found = false;
            for ($i = 0; $i < count($availableSizes); $i++) {
                if ($availableSizes[$i] >= $ukuranTransmitter) {
                    $ukuranTransmitterFinal = $availableSizes[$i];
                    $found = true;
                    break;
                }
            }
            
            if (!$found) {
                $ukuranTransmitterFinal = max($availableSizes);
            }
        }

        $transmitterId = $transmitterMapping[$ukuranTransmitterFinal] ?? null;

        if ($transmitterId) {
            for ($i = 0; $i < $aksesorisCount; $i++) {
                $item = $aksesoris[$i];
                if ($item->id == $transmitterId) {
                    $transmitterItem = $item;
                    break;
                }
            }
        }

        if ($transmitterItem) {
            $satuanTerkecil = (float)($transmitterItem->satuan_terkecil ?? 0);
            $qty = $jumlah * $satuanTerkecil;
            $transmitterItem->qty = $qty;
            $totalWindowHardwareTransmitterQty += $qty;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE FRICTION STAY ===
    $ukuranFrictionStay = $panjang / 3;

    $frictionStayMapping = [
        25 => 175,
        30 => 174,
        35 => 179,
        40 => 173,
        45 => 176,
        50 => 177,
        60 => 178,
    ];

    $ukuranFrictionStayFinal = $ukuranFrictionStay;
    if (!isset($frictionStayMapping[$ukuranFrictionStay])) {
        $availableSizes = array_keys($frictionStayMapping);
        sort($availableSizes);
        
        $found = false;
        for ($i = 0; $i < count($availableSizes); $i++) {
            if ($availableSizes[$i] >= $ukuranFrictionStay) {
                $ukuranFrictionStayFinal = $availableSizes[$i];
                $found = true;
                break;
            }
        }
        
        if (!$found) {
            $ukuranFrictionStayFinal = max($availableSizes);
        }
    }

    $frictionStayItem = null;
    $frictionStayId = $frictionStayMapping[$ukuranFrictionStayFinal] ?? null;

    if ($frictionStayId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $frictionStayId) {
                $frictionStayItem = $item;
                break;
            }
        }
    }

    $totalWindowHardwareFrictionStayQty = 0;
    if ($frictionStayItem) {
        $satuanTerkecil = (float)($frictionStayItem->satuan_terkecil ?? 0);
        $qty = $jumlah * $satuanTerkecil;
        $frictionStayItem->qty = $qty;
        $totalWindowHardwareFrictionStayQty += $qty;
    }

    // === PERHITUNGAN SCREW TRANSMITTER ===
    $screwTransmitterItem = null;
    $screwTransmitterQty = 0;

    // HANYA JIKA MULTILOCK DAN ADA TRANSMITTER
    if ($isMultilock && $transmitterItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-transmitter') {
                $screwTransmitterItem = $item;
                break;
            }
        }

        $satuanTerkecilScrewTransmitter = $screwTransmitterItem ? (float)$screwTransmitterItem->satuan_terkecil : 0;
        $screwTransmitterQty = ($totalWindowHardwareTransmitterQty * $satuanTerkecilScrewTransmitter);
        if ($screwTransmitterItem) {
            $screwTransmitterItem->qty = $screwTransmitterQty;
        }
    }

    // === PERHITUNGAN SCREW FRICTION STAY ===
    $screwFrictionStayItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-friction-stay') {
            $screwFrictionStayItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewFrictionStay = $screwFrictionStayItem ? (float)$screwFrictionStayItem->satuan_terkecil : 0;
    $screwFrictionStayQty = $totalWindowHardwareFrictionStayQty * $satuanTerkecilScrewFrictionStay;
    if ($screwFrictionStayItem) {
        $screwFrictionStayItem->qty = $screwFrictionStayQty;
    }

    // === PERHITUNGAN SCREW HANDLE ===
    $screwHandleItem = null;
    if ($handleItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-handle') {
                $screwHandleItem = $item;
                break;
            }
        }
    }

    $satuanTerkecilScrewHandle = $screwHandleItem ? (float)$screwHandleItem->satuan_terkecil : 0;
    $screwHandleQty = $totalWindowHardwareHandleQty * $satuanTerkecilScrewHandle;
    if ($screwHandleItem) {
        $screwHandleItem->qty = $screwHandleQty;
    }

    // === PERHITUNGAN SETTING BLOCK ===
    $settingBlockItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'setting-block') {
            $settingBlockItem = $item;
            break;
        }
    }
    
    $satuanTerkecilSettingBlock = $settingBlockItem ? (float)$settingBlockItem->satuan_terkecil : 0;
    
    $variableC = 1 * $satuanTerkecilSettingBlock;
    $variableD = $variableC * $jumlah;
    $variableE = $variableD * 25;
    $variableF = $variableE / 1000;
    $settingBlockQty = ceil($variableF);

    // === PERHITUNGAN SCREW REINFORCEMENT ===
    $screwItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-reinforcement') {
            $screwItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrew = $screwItem ? (float)$screwItem->satuan_terkecil : 0;
    $screwQty = ((($totalLebar + $totalPanjang)) + ($variableSashVertikalB + $variableSashHorizontalB) + ($variableMullionVertikalB + $variableMullionHorizontalB)) / $satuanTerkecilScrew;
    $screwQty = ceil($screwQty * 10);

    // === PERHITUNGAN QTY PER AKSESORIS ===
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        $areaSlug = $item->area ? $item->area->slug : '';
        $qty = 0;
        
        if ($areaSlug == 'profile-vertikal') {
            $qty = $batangVertikal;
        } elseif ($areaSlug == 'profile-horizontal') {
            $qty = $batangHorizontal;
        } elseif ($areaSlug == 'glaze-bead-vertical') {
            $qty = ($panjang / 100) * $jumlah;
        } elseif ($areaSlug == 'glaze-bead-horizontal') {
            $qty = ($lebar / 100) * $jumlah;
        } elseif ($areaSlug == 'reinforcement') {
            $qty = $reinforcementQty;
        } elseif ($areaSlug == 'reinforcement-sash') {
            $qty = $reinforcementSashQty;
        } elseif ($areaSlug == 'reinforcement-mullion') {
            $qty = $reinforcementMullionQty;
        } elseif ($areaSlug == 'kaca') {
            $qty = $luasKacaTotal;
        } elseif ($areaSlug == 'screw-reinforcement') {
            $qty = $screwQty;
        } elseif ($areaSlug == 'setting-block') {
            $qty = $settingBlockQty;
        } elseif ($areaSlug == 'profile-sash-vertikal') {
            $qty = $batangSashVertikalQty;
        } elseif ($areaSlug == 'profile-sash-horizontal') {
            $qty = $batangSashHorizontalQty;
        } elseif ($areaSlug == 'profile-mullion-vertikal') {
            $qty = $batangMullionVertikalQty;
        } elseif ($areaSlug == 'profile-mullion-horizontal') {
            $qty = $batangMullionHorizontalQty;
        } elseif ($areaSlug == 'window-hardware-transmitter') {
            $qty = ($transmitterItem && $transmitterItem->id == $item->id) ? $transmitterItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-friction-stay') {
            $qty = ($frictionStayItem && $frictionStayItem->id == $item->id) ? $frictionStayItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-handle-rambuncis' || $areaSlug == 'window-hardware-handle-multilock') {
            $qty = $item->qty;
        } elseif ($areaSlug == 'screw-transmitter') {
            $qty = $screwTransmitterQty;
        } elseif ($areaSlug == 'screw-friction-stay') {
            $qty = $screwFrictionStayQty;
        } elseif ($areaSlug == 'screw-handle') {
            $qty = $screwHandleQty;
        } else {
            $qty = $jumlah * ($item->satuan_terkecil ?? 1);
        }
        
        $item->qty = $qty;
    }

    // Data untuk view
    $data = [
        'produk' => $produkUtama,
        'panjang' => $panjang,
        'lebar' => $lebar,
        'tebal_kaca' => $tebalKaca,
        'jumlah' => $jumlah,
        'warna' => $warna,
        'type_kaca' => $typeKaca,
        'handle_id' => $handleId,
        'is_multilock' => $isMultilock,
        
        'luas_kaca_per_unit' => $luasKacaPerUnit,
        'luas_kaca_total' => $luasKacaTotal,
        'keliling_per_unit' => $kelilingPerUnit,
        'keliling_total' => $kelilingTotal,
        
        'profile_vertikal' => $profileVertikal,
        'variable_a' => $variableA,
        'frame_vertikal' => $frameVertikal,
        'batang_vertikal' => $batangVertikal,
        
        'profile_horizontal' => $profileHorizontal,
        'satuan_terkecil_horizontal' => $satuanTerkecilHorizontal,
        'variable_b' => $variableB,
        'frame_horizontal' => $frameHorizontal,
        'batang_horizontal' => $batangHorizontal,
        
        'total_batang' => $totalBatang,
        'reinforcement_qty' => $reinforcementQty,
        
        'profile_sash_vertikal' => $profileSashVertikal,
        'satuan_terkecil_sash_vertikal' => $satuanTerkecilSashVertikal,
        'variable_sash_vertikal_a' => $variableSashVertikalA,
        'variable_sash_vertikal_b' => $variableSashVertikalB,
        'batang_sash_vertikal' => $batangSashVertikal,
        'batang_sash_vertikal_qty' => $batangSashVertikalQty,
        
        'profile_sash_horizontal' => $profileSashHorizontal,
        'satuan_terkecil_sash_horizontal' => $satuanTerkecilSashHorizontal,
        'variable_sash_horizontal_a' => $variableSashHorizontalA,
        'variable_sash_horizontal_b' => $variableSashHorizontalB,
        'batang_sash_horizontal' => $batangSashHorizontal,
        'batang_sash_horizontal_qty' => $batangSashHorizontalQty,
        
        'reinforcement_sash_qty' => $reinforcementSashQty,
        
        'profile_mullion_vertikal' => $profileMullionVertikal,
        'satuan_terkecil_mullion_vertikal' => $satuanTerkecilMullionVertikal,
        'variable_mullion_vertikal_a' => $variableMullionVertikalA,
        'variable_mullion_vertikal_b' => $variableMullionVertikalB,
        'batang_mullion_vertikal' => $batangMullionVertikal,
        'batang_mullion_vertikal_qty' => $batangMullionVertikalQty,
        
        'profile_mullion_horizontal' => $profileMullionHorizontal,
        'satuan_terkecil_mullion_horizontal' => $satuanTerkecilMullionHorizontal,
        'variable_mullion_horizontal_a' => $variableMullionHorizontalA,
        'variable_mullion_horizontal_b' => $variableMullionHorizontalB,
        'batang_mullion_horizontal' => $batangMullionHorizontal,
        'batang_mullion_horizontal_qty' => $batangMullionHorizontalQty,
        
        'total_batang_mullion' => $totalBatangMullion,
        'reinforcement_mullion_qty' => $reinforcementMullionQty,
        
        'transmitter_item' => $transmitterItem,
        'ukuran_transmitter' => $ukuranTransmitter,
        'ukuran_transmitter_final' => $ukuranTransmitterFinal,
        'total_window_hardware_transmitter_qty' => $totalWindowHardwareTransmitterQty,
        
        'friction_stay_item' => $frictionStayItem,
        'ukuran_friction_stay' => $ukuranFrictionStay,
        'ukuran_friction_stay_final' => $ukuranFrictionStayFinal,
        'total_window_hardware_friction_stay_qty' => $totalWindowHardwareFrictionStayQty,
        
        'handle_item' => $handleItem,
        'total_window_hardware_handle_qty' => $totalWindowHardwareHandleQty,
        
        'screw_transmitter_item' => $screwTransmitterItem,
        'screw_transmitter_qty' => $screwTransmitterQty,
        
        'screw_friction_stay_item' => $screwFrictionStayItem,
        'screw_friction_stay_qty' => $screwFrictionStayQty,
        
        'screw_handle_item' => $screwHandleItem,
        'screw_handle_qty' => $screwHandleQty,
        
        'satuan_terkecil_screw' => $satuanTerkecilScrew,
        'screw_qty' => $screwQty,
        
        'setting_block_item' => $settingBlockItem,
        'satuan_terkecil_setting_block' => $satuanTerkecilSettingBlock,
        'variable_c' => $variableC,
        'variable_d' => $variableD,
        'variable_e' => $variableE,
        'variable_f' => $variableF,
        'setting_block_qty' => $settingBlockQty,
        
        'aksesoris' => $aksesoris,
    ];

    return view('boq.jendela.jendela-jungkit-1-mullion', $data);
}

public function exportPdfJungkit1mullion(Request $request)
{
    $panjang = $request->panjang;
    $lebar = $request->lebar;
    $tebal_kaca = $request->tebal_kaca;
    $jumlah = $request->jumlah;
    $warna = $request->warna;
    $type_kaca = $request->type_kaca;
    $handle_id = $request->handle_id;
    $judul = $request->judul ?? 'BOQ - Jendela Jungkit 1 Daun (Mullion)';

    // Ambil data aksesoris
    $aksesorisIds = ProductAccessories::where('parent_product_id', 185)->pluck('accessory_id');
    $aksesoris = Product::with('area', 'unit')
        ->whereIn('id', $aksesorisIds)
        ->get();

    // === PERHITUNGAN DASAR ===
    $panjangM = $panjang / 100;
    $lebarM = $lebar / 100;
    
    $luasKacaPerUnit = $panjangM * $lebarM;
    $luasKacaTotal = $luasKacaPerUnit * $jumlah;
    $luasKacaTotal = ceil($luasKacaTotal * 10) / 10;

    $kelilingPerUnit = 2 * ($panjangM + $lebarM);
    $kelilingTotal = $kelilingPerUnit * $jumlah;

    // === PERHITUNGAN PROFILE VERTIKAL ===
    $profileVertikal = null;
    $aksesorisCount = count($aksesoris);
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-vertikal') {
            $profileVertikal = $item;
            break;
        }
    }
    $satuanTerkecilVertikal = $profileVertikal ? (float)$profileVertikal->satuan_terkecil : 0;

    $variableA = $jumlah * $satuanTerkecilVertikal;
    $frameVertikal = $variableA * $panjang;
    $batangVertikal = $frameVertikal / 580;
    $batangVertikal = ceil($batangVertikal * 10) / 10;
    $totalPanjang = $panjang * $variableA;

    // === PERHITUNGAN PROFILE HORIZONTAL ===
    $profileHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-horizontal') {
            $profileHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilHorizontal = $profileHorizontal ? (float)$profileHorizontal->satuan_terkecil : 0;
    
    $variableB = $jumlah * $satuanTerkecilHorizontal;
    $frameHorizontal = $variableB * $lebar;
    $batangHorizontal = $frameHorizontal / 580;
    $batangHorizontal = ceil($batangHorizontal * 10) / 10;
    $totalLebar = $lebar * $variableB;

    // === PERHITUNGAN REINFORCEMENT ===
    $totalBatang = ($frameVertikal + $frameHorizontal) / 600;
    $reinforcementQty = ceil($totalBatang * 10) / 10;

    // === PERHITUNGAN PROFILE SASH VERTIKAL ===
    $profileSashVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-vertikal') {
            $profileSashVertikal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashVertikal = $profileSashVertikal ? (float)$profileSashVertikal->satuan_terkecil : 0;
    
    $variableSashVertikalA = $satuanTerkecilSashVertikal * $jumlah;
    $variableSashVertikalB = $variableSashVertikalA * $panjang;
    $batangSashVertikal = $variableSashVertikalB / 580;
    $batangSashVertikalQty = ceil($batangSashVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE SASH HORIZONTAL ===
    $profileSashHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-horizontal') {
            $profileSashHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashHorizontal = $profileSashHorizontal ? (float)$profileSashHorizontal->satuan_terkecil : 0;
    
    $variableSashHorizontalA = $satuanTerkecilSashHorizontal * $jumlah;
    $variableSashHorizontalB = $variableSashHorizontalA * $lebar;
    $batangSashHorizontal = $variableSashHorizontalB / 580;
    $batangSashHorizontalQty = ceil($batangSashHorizontal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT SASH ===
    $totalBatangSash = ($variableSashVertikalB + $variableSashHorizontalB) / 600;
    $reinforcementSashQty = ceil($totalBatangSash * 10) / 10;

    // === PERHITUNGAN PROFILE MULLION VERTIKAL ===
    $profileMullionVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-mullion-vertikal') {
            $profileMullionVertikal = $item;
            break;
        }
    }

    $satuanTerkecilMullionVertikal = $profileMullionVertikal ? (float)$profileMullionVertikal->satuan_terkecil : 0;
    
    $variableMullionVertikalA = $satuanTerkecilMullionVertikal * $jumlah;
    $variableMullionVertikalB = $variableMullionVertikalA * $panjang;
    $batangMullionVertikal = $variableMullionVertikalB / 580;
    $batangMullionVertikalQty = ceil($batangMullionVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE MULLION HORIZONTAL ===
    $profileMullionHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-mullion-horizontal') {
            $profileMullionHorizontal = $item;
            break;
        }
    }

    $satuanTerkecilMullionHorizontal = $profileMullionHorizontal ? (float)$profileMullionHorizontal->satuan_terkecil : 0;
    
    $variableMullionHorizontalA = 6 * $jumlah;
    $variableMullionHorizontalB = $variableMullionHorizontalA * $lebar;
    $batangMullionHorizontal = $variableMullionHorizontalB / 580;
    $batangMullionHorizontalQty = ceil($batangMullionHorizontal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT MULLION ===
    $totalBatangMullion = ($variableMullionVertikalB + $variableMullionHorizontalB) / 600;
    $reinforcementMullionQty = ceil($totalBatangMullion * 10) / 10;

    // === PERHITUNGAN WINDOW HARDWARE HANDLE ===
    $handleItem = null;
    $totalWindowHardwareHandleQty = 0;

    // RESET QTY UNTUK SEMUA HANDLE = 0
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && ($item->area->slug == 'window-hardware-handle-rambuncis' || $item->area->slug == 'window-hardware-handle-multilock')) {
            $item->qty = 0;
        }
    }

    // SET QTY UNTUK HANDLE YANG DIPILIH
    if ($handle_id) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $handle_id) {
                $handleItem = $item;
                break;
            }
        }
    }

    if ($handleItem) {
        $satuanTerkecil = (float)($handleItem->satuan_terkecil ?? 0);
        $qty = $jumlah * $satuanTerkecil;
        $handleItem->qty = $qty;
        $totalWindowHardwareHandleQty += $qty;
    }

    // CEK APAKAH HANDLE YANG DIPILIH ADALAH MULTILOCK
    $isMultilock = false;
    if ($handleItem) {
        $namaLower = strtolower($handleItem->nama_produk);
        if (str_contains($namaLower, 'multilock')) {
            $isMultilock = true;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE TRANSMITTER ===
    $transmitterItem = null;
    $totalWindowHardwareTransmitterQty = 0;
    $ukuranTransmitter = 0;
    $ukuranTransmitterFinal = 0;

    if ($isMultilock) {
        $ukuranTransmitter = $panjang - 20;

        $transmitterMapping = [
            40 => 172,
            60 => 171,
            80 => 170,
            100 => 173,
            120 => 162,
            140 => 166,
            160 => 167,
            180 => 168,
            200 => 169,
        ];

        $ukuranTransmitterFinal = $ukuranTransmitter;
        if (!isset($transmitterMapping[$ukuranTransmitter])) {
            $availableSizes = array_keys($transmitterMapping);
            sort($availableSizes);
            
            $found = false;
            for ($i = 0; $i < count($availableSizes); $i++) {
                if ($availableSizes[$i] >= $ukuranTransmitter) {
                    $ukuranTransmitterFinal = $availableSizes[$i];
                    $found = true;
                    break;
                }
            }
            
            if (!$found) {
                $ukuranTransmitterFinal = max($availableSizes);
            }
        }

        $transmitterId = $transmitterMapping[$ukuranTransmitterFinal] ?? null;

        if ($transmitterId) {
            for ($i = 0; $i < $aksesorisCount; $i++) {
                $item = $aksesoris[$i];
                if ($item->id == $transmitterId) {
                    $transmitterItem = $item;
                    break;
                }
            }
        }

        if ($transmitterItem) {
            $satuanTerkecil = (float)($transmitterItem->satuan_terkecil ?? 0);
            $qty = $jumlah * $satuanTerkecil;
            $transmitterItem->qty = $qty;
            $totalWindowHardwareTransmitterQty += $qty;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE FRICTION STAY ===
    $ukuranFrictionStay = $panjang / 3;

    $frictionStayMapping = [
        25 => 175,
        30 => 174,
        35 => 179,
        40 => 173,
        45 => 176,
        50 => 177,
        60 => 178,
    ];

    $ukuranFrictionStayFinal = $ukuranFrictionStay;
    if (!isset($frictionStayMapping[$ukuranFrictionStay])) {
        $availableSizes = array_keys($frictionStayMapping);
        sort($availableSizes);
        
        $found = false;
        for ($i = 0; $i < count($availableSizes); $i++) {
            if ($availableSizes[$i] >= $ukuranFrictionStay) {
                $ukuranFrictionStayFinal = $availableSizes[$i];
                $found = true;
                break;
            }
        }
        
        if (!$found) {
            $ukuranFrictionStayFinal = max($availableSizes);
        }
    }

    $frictionStayItem = null;
    $frictionStayId = $frictionStayMapping[$ukuranFrictionStayFinal] ?? null;

    if ($frictionStayId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $frictionStayId) {
                $frictionStayItem = $item;
                break;
            }
        }
    }

    $totalWindowHardwareFrictionStayQty = 0;
    if ($frictionStayItem) {
        $satuanTerkecil = (float)($frictionStayItem->satuan_terkecil ?? 0);
        $qty = $jumlah * $satuanTerkecil;
        $frictionStayItem->qty = $qty;
        $totalWindowHardwareFrictionStayQty += $qty;
    }

    // === PERHITUNGAN SCREW TRANSMITTER ===
    $screwTransmitterItem = null;
    $screwTransmitterQty = 0;

    if ($isMultilock && $transmitterItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-transmitter') {
                $screwTransmitterItem = $item;
                break;
            }
        }

        $satuanTerkecilScrewTransmitter = $screwTransmitterItem ? (float)$screwTransmitterItem->satuan_terkecil : 0;
        $screwTransmitterQty = ($totalWindowHardwareTransmitterQty * $satuanTerkecilScrewTransmitter);
        if ($screwTransmitterItem) {
            $screwTransmitterItem->qty = $screwTransmitterQty;
        }
    }

    // === PERHITUNGAN SCREW FRICTION STAY ===
    $screwFrictionStayItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-friction-stay') {
            $screwFrictionStayItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewFrictionStay = $screwFrictionStayItem ? (float)$screwFrictionStayItem->satuan_terkecil : 0;
    $screwFrictionStayQty = $totalWindowHardwareFrictionStayQty * $satuanTerkecilScrewFrictionStay;
    if ($screwFrictionStayItem) {
        $screwFrictionStayItem->qty = $screwFrictionStayQty;
    }

    // === PERHITUNGAN SCREW HANDLE ===
    $screwHandleItem = null;
    if ($handleItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-handle') {
                $screwHandleItem = $item;
                break;
            }
        }
    }

    $satuanTerkecilScrewHandle = $screwHandleItem ? (float)$screwHandleItem->satuan_terkecil : 0;
    $screwHandleQty = $totalWindowHardwareHandleQty * $satuanTerkecilScrewHandle;
    if ($screwHandleItem) {
        $screwHandleItem->qty = $screwHandleQty;
    }

    // === PERHITUNGAN SETTING BLOCK ===
    $settingBlockItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'setting-block') {
            $settingBlockItem = $item;
            break;
        }
    }
    
    $satuanTerkecilSettingBlock = $settingBlockItem ? (float)$settingBlockItem->satuan_terkecil : 0;
    
    $variableC = 1 * $satuanTerkecilSettingBlock;
    $variableD = $variableC * $jumlah;
    $variableE = $variableD * 25;
    $variableF = $variableE / 1000;
    $settingBlockQty = ceil($variableF);

    // === PERHITUNGAN SCREW REINFORCEMENT ===
    $screwItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-reinforcement') {
            $screwItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrew = $screwItem ? (float)$screwItem->satuan_terkecil : 0;
    $screwQty = ((($totalLebar + $totalPanjang)) + ($variableSashVertikalB + $variableSashHorizontalB) + ($variableMullionVertikalB + $variableMullionHorizontalB)) / $satuanTerkecilScrew;
    $screwQty = ceil($screwQty * 10);

    // === HITUNG QTY PER AKSESORIS ===
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        $areaSlug = $item->area ? $item->area->slug : '';
        $qty = 0;
        
        if ($areaSlug == 'profile-vertikal') {
            $qty = $batangVertikal;
        } elseif ($areaSlug == 'profile-horizontal') {
            $qty = $batangHorizontal;
        } elseif ($areaSlug == 'glaze-bead-vertical') {
            $qty = ($panjang / 100) * $jumlah;
        } elseif ($areaSlug == 'glaze-bead-horizontal') {
            $qty = ($lebar / 100) * $jumlah;
        } elseif ($areaSlug == 'reinforcement') {
            $qty = $reinforcementQty;
        } elseif ($areaSlug == 'reinforcement-sash') {
            $qty = $reinforcementSashQty;
        } elseif ($areaSlug == 'reinforcement-mullion') {
            $qty = $reinforcementMullionQty;
        } elseif ($areaSlug == 'kaca') {
            $qty = $luasKacaTotal;
        } elseif ($areaSlug == 'screw-reinforcement') {
            $qty = $screwQty;
        } elseif ($areaSlug == 'setting-block') {
            $qty = $settingBlockQty;
        } elseif ($areaSlug == 'profile-sash-vertikal') {
            $qty = $batangSashVertikalQty;
        } elseif ($areaSlug == 'profile-sash-horizontal') {
            $qty = $batangSashHorizontalQty;
        } elseif ($areaSlug == 'profile-mullion-vertikal') {
            $qty = $batangMullionVertikalQty;
        } elseif ($areaSlug == 'profile-mullion-horizontal') {
            $qty = $batangMullionHorizontalQty;
        } elseif ($areaSlug == 'window-hardware-transmitter') {
            $qty = ($transmitterItem && $transmitterItem->id == $item->id) ? $transmitterItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-friction-stay') {
            $qty = ($frictionStayItem && $frictionStayItem->id == $item->id) ? $frictionStayItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-handle-rambuncis' || $areaSlug == 'window-hardware-handle-multilock') {
            $qty = $item->qty;
        } elseif ($areaSlug == 'screw-transmitter') {
            $qty = $screwTransmitterQty;
        } elseif ($areaSlug == 'screw-friction-stay') {
            $qty = $screwFrictionStayQty;
        } elseif ($areaSlug == 'screw-handle') {
            $qty = $screwHandleQty;
        } else {
            $qty = $jumlah * ($item->satuan_terkecil ?? 1);
        }
        
        $item->qty = $qty;
    }

    // Kelompokkan berdasarkan area
    $grouped = [];
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->qty <= 0) {
            continue;
        }
        
        // Skip transmitter, friction stay, dan handle yang tidak terpilih (qty 0)
        if ($item->area && ($item->area->slug == 'window-hardware-transmitter' || $item->area->slug == 'window-hardware-friction-stay') && $item->qty <= 0) {
            continue;
        }
        if ($item->area && ($item->area->slug == 'window-hardware-handle-rambuncis' || $item->area->slug == 'window-hardware-handle-multilock') && $item->qty <= 0) {
            continue;
        }
        
        $areaSlug = $item->area ? $item->area->slug : 'lainnya';
        
        if (str_starts_with($areaSlug, 'profile')) {
            $groupKey = 'profile';
        } elseif ($areaSlug == 'setting-block') {
            $groupKey = 'kaca';
        } elseif ($areaSlug == 'reinforcement' || $areaSlug == 'reinforcement-sash' || $areaSlug == 'reinforcement-mullion') {
            $groupKey = 'reinforcement';
        } elseif (str_starts_with($areaSlug, 'window-hardware')) {
            $groupKey = 'window-hardware';
        } elseif ($areaSlug == 'screw-reinforcement' || $areaSlug == 'screw-transmitter' || $areaSlug == 'screw-friction-stay' || $areaSlug == 'screw-handle') {
            $groupKey = 'screw';
        } else {
            $groupKey = $areaSlug;
        }
        
        if (!isset($grouped[$groupKey])) {
            $grouped[$groupKey] = [];
        }
        $grouped[$groupKey][] = $item;
    }

    $areaLabels = [
        'profile' => 'PROFILE (Termasuk Mullion)',
        'reinforcement' => 'REINFORCEMENT',
        'kaca' => 'KACA',
        'screw' => 'SCREW',
        'window-hardware' => 'WINDOW HARDWARE',
    ];

    // ============ GENERATE NOMOR BOQ ============
    $nomorBoq = Boq::generateNomorBoq();

    // ============ STORE BOQ ============
    try {
        $allResults = [];
        
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->qty > 0) {
                $allResults[] = [
                    'produk_id' => $item->id,
                    'qty' => $item->qty,
                    'nama_produk' => $item->nama_produk,
                ];
            }
        }
        
        $uniqueResults = [];
        $seenIds = [];
        $allResultsCount = count($allResults);
        
        for ($i = 0; $i < $allResultsCount; $i++) {
            $item = $allResults[$i];
            $produkId = $item['produk_id'] ?? null;
            
            if (!$produkId) {
                continue;
            }
            
            $isDuplicate = false;
            $seenCount = count($seenIds);
            for ($j = 0; $j < $seenCount; $j++) {
                if ($seenIds[$j] == $produkId) {
                    $isDuplicate = true;
                    break;
                }
            }
            
            if ($isDuplicate) {
                continue;
            }
            
            $seenIds[] = $produkId;
            $uniqueResults[] = $item;
        }
        
        if (count($uniqueResults) > 0) {
            $boq = new Boq();
            $boq->nomor_boq = $nomorBoq;
            $boq->tanggal_boq = now();
            $boq->save();
            
            $uniqueCount = count($uniqueResults);
            for ($i = 0; $i < $uniqueCount; $i++) {
                $item = $uniqueResults[$i];
                $produkId = $item['produk_id'] ?? null;
                $qty = (int)($item['qty'] ?? 0);
                
                if ($produkId && $qty > 0) {
                    $produk = Product::find($produkId);
                    
                    \DB::table('detail_boq')->insert([
                        'boq_id' => $boq->id,
                        'produk_id' => $produkId,
                        'kode_produk' => $produk ? $produk->kode_produk : null,
                        'qty' => $qty,
                        'created_at' => now(),
                        'updated_at' => now()
                    ]);
                }
            }
            
            \Log::info('BOQ SAVED JENDELA JUNGKIT 1 MULLION:', [
                'boq_id' => $boq->id,
                'nomor_boq' => $nomorBoq,
                'total' => count($uniqueResults)
            ]);
        }
        
    } catch (\Exception $e) {
        \Log::error('Error saving BOQ Jendela Jungkit 1 Mullion: ' . $e->getMessage());
        \Log::error($e->getTraceAsString());
    }

    $data = [
        'judul' => $judul,
        'panjang' => $panjang,
        'lebar' => $lebar,
        'tebal_kaca' => $tebal_kaca,
        'jumlah' => $jumlah,
        'warna' => $warna,
        'type_kaca' => $type_kaca,
        'handle_id' => $handle_id,
        'is_multilock' => $isMultilock,
        'luas_kaca_total' => $luasKacaTotal,
        'keliling_total' => $kelilingTotal,
        'batang_vertikal' => $batangVertikal,
        'batang_horizontal' => $batangHorizontal,
        'reinforcement_qty' => $reinforcementQty,
        'reinforcement_sash_qty' => $reinforcementSashQty,
        'reinforcement_mullion_qty' => $reinforcementMullionQty,
        'batang_sash_vertikal_qty' => $batangSashVertikalQty,
        'batang_sash_horizontal_qty' => $batangSashHorizontalQty,
        'batang_mullion_vertikal_qty' => $batangMullionVertikalQty,
        'batang_mullion_horizontal_qty' => $batangMullionHorizontalQty,
        'handle_item' => $handleItem,
        'total_window_hardware_handle_qty' => $totalWindowHardwareHandleQty,
        'transmitter_item' => $transmitterItem,
        'ukuran_transmitter' => $ukuranTransmitter,
        'ukuran_transmitter_final' => $ukuranTransmitterFinal,
        'total_window_hardware_transmitter_qty' => $totalWindowHardwareTransmitterQty,
        'friction_stay_item' => $frictionStayItem,
        'ukuran_friction_stay' => $ukuranFrictionStay,
        'ukuran_friction_stay_final' => $ukuranFrictionStayFinal,
        'total_window_hardware_friction_stay_qty' => $totalWindowHardwareFrictionStayQty,
        'screw_transmitter_qty' => $screwTransmitterQty,
        'screw_friction_stay_qty' => $screwFrictionStayQty,
        'screw_handle_qty' => $screwHandleQty,
        'screw_qty' => $screwQty,
        'setting_block_qty' => $settingBlockQty,
        'grouped' => $grouped,
        'areaLabels' => $areaLabels,
        'nomor_boq' => $nomorBoq,
    ];

    return view('boq.jendela.pdf-jendela-jungkit-1-mullion', compact('data'));
}

public function hitungJungkit2mullion(Request $request)
{
    $request->validate([
        'panjang' => 'required|numeric|min:1',
        'lebar' => 'required|numeric|min:1',
        'tebal_kaca' => 'required|numeric|min:1',
        'jumlah' => 'required|numeric|min:1',
        'warna' => 'required|string',
        'type_kaca' => 'required|string',
    ]);

    // Ambil data dari form
    $panjang = $request->panjang; // cm
    $lebar = $request->lebar; // cm
    $tebalKaca = $request->tebal_kaca; // mm
    $jumlah = $request->jumlah;
    $warna = $request->warna;
    $typeKaca = $request->type_kaca;
    $handleId = $request->handle_id;

    // Ambil produk utama (Jendela Jungkit 2) dari database
    $produkUtama = Product::find(186);
    
    if (!$produkUtama) {
        return back()->with('error', 'Produk Jendela Jungkit 2 tidak ditemukan!');
    }

    // Ambil aksesoris dari tabel product_accessories dengan relasi area
    $aksesorisIds = ProductAccessories::where('parent_product_id', 186)->pluck('accessory_id');
    $aksesoris = Product::with('area', 'unit')
        ->whereIn('id', $aksesorisIds)
        ->get();

    // === PERHITUNGAN DASAR ===
    
    // Konversi ke meter
    $panjangM = $panjang / 100;
    $lebarM = $lebar / 100;
    $tebalKacaM = $tebalKaca / 1000;

    // 1. Luas Kaca (m²)
    $luasKacaPerUnit = $panjangM * $lebarM;
    $luasKacaTotal = $luasKacaPerUnit * $jumlah;
    $luasKacaTotal = ceil($luasKacaTotal * 10) / 10;

    // 2. Keliling Profile (meter)
    $kelilingPerUnit = 2 * ($panjangM + $lebarM);
    $kelilingTotal = $kelilingPerUnit * $jumlah;

    // === PERHITUNGAN PROFILE VERTIKAL ===
    $profileVertikal = null;
    $aksesorisCount = count($aksesoris);
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-vertikal') {
            $profileVertikal = $item;
            break;
        }
    }
    $satuanTerkecilVertikal = $profileVertikal ? (float)$profileVertikal->satuan_terkecil : 0;

    $variableA = $jumlah * 4;
    $frameVertikal = $variableA * $panjang;
    $batangVertikal = $frameVertikal / 580;
    $batangVertikal = ceil($batangVertikal * 10) / 10;
    $totalPanjang = $panjang * $variableA;

    // === PERHITUNGAN PROFILE HORIZONTAL ===
    $profileHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-horizontal') {
            $profileHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilHorizontal = $profileHorizontal ? (float)$profileHorizontal->satuan_terkecil : 0;
    
    $variableB = $jumlah * $satuanTerkecilHorizontal;
    $frameHorizontal = $variableB * $lebar;
    $batangHorizontal = $frameHorizontal / 580;
    $batangHorizontal = ceil($batangHorizontal * 10) / 10;
    $totalLebar = $lebar * $variableB;

    // === PERHITUNGAN REINFORCEMENT ===
    $totalBatang = ($frameVertikal + $frameHorizontal) / 600;
    $reinforcementQty = ceil($totalBatang * 10) / 10;

    // === PERHITUNGAN PROFILE SASH VERTIKAL ===
    $profileSashVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-vertikal') {
            $profileSashVertikal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashVertikal = $profileSashVertikal ? (float)$profileSashVertikal->satuan_terkecil : 0;
    
    $variableSashVertikalA = 4 * $jumlah;
    $variableSashVertikalB = $variableSashVertikalA * $panjang;
    $batangSashVertikal = $variableSashVertikalB / 580;
    $batangSashVertikalQty = ceil($batangSashVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE SASH HORIZONTAL ===
    $profileSashHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-horizontal') {
            $profileSashHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashHorizontal = $profileSashHorizontal ? (float)$profileSashHorizontal->satuan_terkecil : 0;
    
    $variableSashHorizontalA = $satuanTerkecilSashHorizontal * $jumlah;
    $variableSashHorizontalB = $variableSashHorizontalA * $lebar;
    $batangSashHorizontal = $variableSashHorizontalB / 580;
    $batangSashHorizontalQty = ceil($batangSashHorizontal * 10) / 10;

    // === PERHITUNGAN PROFILE COUPLING VERTIKAL ===
    $profileCouplingVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-coupling-vertikal') {
            $profileCouplingVertikal = $item;
            break;
        }
    }

    $satuanTerkecilCouplingVertikal = $profileCouplingVertikal ? (float)$profileCouplingVertikal->satuan_terkecil : 0;

    $variableCouplingVertikalA = $satuanTerkecilCouplingVertikal * $jumlah * 2;
    $variableCouplingVertikalB = $variableCouplingVertikalA * $panjang;
    $batangCouplingVertikal = $variableCouplingVertikalB / 580;
    $batangCouplingVertikalQty = ceil($batangCouplingVertikal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT SASH ===
    $totalBatangSash = ($variableSashVertikalB + $variableSashHorizontalB) / 600;
    $reinforcementSashQty = ceil($totalBatangSash * 10) / 10;

    // === PERHITUNGAN PROFILE MULLION VERTIKAL ===
    $profileMullionVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-mullion-vertikal') {
            $profileMullionVertikal = $item;
            break;
        }
    }

    $satuanTerkecilMullionVertikal = $profileMullionVertikal ? (float)$profileMullionVertikal->satuan_terkecil : 0;
    
    $variableMullionVertikalA = 4 * $jumlah;
    $variableMullionVertikalB = $variableMullionVertikalA * $panjang;
    $batangMullionVertikal = $variableMullionVertikalB / 580;
    $batangMullionVertikalQty = ceil($batangMullionVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE MULLION HORIZONTAL ===
    $profileMullionHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-mullion-horizontal') {
            $profileMullionHorizontal = $item;
            break;
        }
    }

    $satuanTerkecilMullionHorizontal = $profileMullionHorizontal ? (float)$profileMullionHorizontal->satuan_terkecil : 0;
    
    $variableMullionHorizontalA = 6 * $jumlah;
    $variableMullionHorizontalB = $variableMullionHorizontalA * $lebar;
    $batangMullionHorizontal = $variableMullionHorizontalB / 580;
    $batangMullionHorizontalQty = ceil($batangMullionHorizontal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT MULLION ===
    $totalBatangMullion = ($variableMullionVertikalB + $variableMullionHorizontalB) / 600;
    $reinforcementMullionQty = ceil($totalBatangMullion * 10) / 10;

    // === PERHITUNGAN WINDOW HARDWARE HANDLE (dari dropdown) ===
    $handleItem = null;
    $totalWindowHardwareHandleQty = 0;

    // RESET QTY UNTUK SEMUA HANDLE = 0
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && ($item->area->slug == 'window-hardware-handle-rambuncis' || $item->area->slug == 'window-hardware-handle-multilock')) {
            $item->qty = 0;
        }
    }

    // SET QTY UNTUK HANDLE YANG DIPILIH
    if ($handleId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $handleId) {
                $handleItem = $item;
                break;
            }
        }
    }

    if ($handleItem) {
        $satuanTerkecil = (float)($handleItem->satuan_terkecil ?? 0);
        $qty = $jumlah * 2;
        $handleItem->qty = $qty;
        $totalWindowHardwareHandleQty += $qty;
    }

    // CEK APAKAH HANDLE YANG DIPILIH ADALAH MULTILOCK
    $isMultilock = false;
    if ($handleItem) {
        $namaLower = strtolower($handleItem->nama_produk);
        if (str_contains($namaLower, 'multilock')) {
            $isMultilock = true;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE TRANSMITTER ===
    $transmitterItem = null;
    $totalWindowHardwareTransmitterQty = 0;
    $ukuranTransmitter = 0;
    $ukuranTransmitterFinal = 0;

    // HANYA HITUNG TRANSMITTER JIKA HANDLE MULTILOCK
    if ($isMultilock) {
        $ukuranTransmitter = $panjang - 20;

        $transmitterMapping = [
            40 => 172,
            60 => 171,
            80 => 170,
            100 => 173,
            120 => 162,
            140 => 166,
            160 => 167,
            180 => 168,
            200 => 169,
        ];

        $ukuranTransmitterFinal = $ukuranTransmitter;
        if (!isset($transmitterMapping[$ukuranTransmitter])) {
            $availableSizes = array_keys($transmitterMapping);
            sort($availableSizes);
            
            $found = false;
            for ($i = 0; $i < count($availableSizes); $i++) {
                if ($availableSizes[$i] >= $ukuranTransmitter) {
                    $ukuranTransmitterFinal = $availableSizes[$i];
                    $found = true;
                    break;
                }
            }
            
            if (!$found) {
                $ukuranTransmitterFinal = max($availableSizes);
            }
        }

        $transmitterId = $transmitterMapping[$ukuranTransmitterFinal] ?? null;

        if ($transmitterId) {
            for ($i = 0; $i < $aksesorisCount; $i++) {
                $item = $aksesoris[$i];
                if ($item->id == $transmitterId) {
                    $transmitterItem = $item;
                    break;
                }
            }
        }

        if ($transmitterItem) {
            $satuanTerkecil = (float)($transmitterItem->satuan_terkecil ?? 0);
            $qty = $jumlah * 2;
            $transmitterItem->qty = $qty;
            $totalWindowHardwareTransmitterQty += $qty;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE FRICTION STAY ===
    $ukuranFrictionStay = $panjang / 3;

    $frictionStayMapping = [
        25 => 175,
        30 => 174,
        35 => 179,
        40 => 173,
        45 => 176,
        50 => 177,
        60 => 178,
    ];

    $ukuranFrictionStayFinal = $ukuranFrictionStay;
    if (!isset($frictionStayMapping[$ukuranFrictionStay])) {
        $availableSizes = array_keys($frictionStayMapping);
        sort($availableSizes);
        
        $found = false;
        for ($i = 0; $i < count($availableSizes); $i++) {
            if ($availableSizes[$i] >= $ukuranFrictionStay) {
                $ukuranFrictionStayFinal = $availableSizes[$i];
                $found = true;
                break;
            }
        }
        
        if (!$found) {
            $ukuranFrictionStayFinal = max($availableSizes);
        }
    }

    $frictionStayItem = null;
    $frictionStayId = $frictionStayMapping[$ukuranFrictionStayFinal] ?? null;

    if ($frictionStayId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $frictionStayId) {
                $frictionStayItem = $item;
                break;
            }
        }
    }

    $totalWindowHardwareFrictionStayQty = 0;
    if ($frictionStayItem) {
        $satuanTerkecil = (float)($frictionStayItem->satuan_terkecil ?? 0);
        $qty = $jumlah * 4;
        $frictionStayItem->qty = $qty;
        $totalWindowHardwareFrictionStayQty += $qty;
    }

    // === PERHITUNGAN SCREW TRANSMITTER ===
    $screwTransmitterItem = null;
    $screwTransmitterQty = 0;

    // HANYA JIKA MULTILOCK DAN ADA TRANSMITTER
    if ($isMultilock && $transmitterItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-transmitter') {
                $screwTransmitterItem = $item;
                break;
            }
        }

        $satuanTerkecilScrewTransmitter = $screwTransmitterItem ? (float)$screwTransmitterItem->satuan_terkecil : 0;
        $screwTransmitterQty = ($totalWindowHardwareTransmitterQty * $satuanTerkecilScrewTransmitter);
        if ($screwTransmitterItem) {
            $screwTransmitterItem->qty = $screwTransmitterQty;
        }
    }

    // === PERHITUNGAN SCREW FRICTION STAY ===
    $screwFrictionStayItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-friction-stay') {
            $screwFrictionStayItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewFrictionStay = $screwFrictionStayItem ? (float)$screwFrictionStayItem->satuan_terkecil : 0;
    $screwFrictionStayQty = $totalWindowHardwareFrictionStayQty * $satuanTerkecilScrewFrictionStay;
    if ($screwFrictionStayItem) {
        $screwFrictionStayItem->qty = $screwFrictionStayQty;
    }

    // === PERHITUNGAN SCREW HANDLE ===
    $screwHandleItem = null;
    if ($handleItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-handle') {
                $screwHandleItem = $item;
                break;
            }
        }
    }

    $satuanTerkecilScrewHandle = $screwHandleItem ? (float)$screwHandleItem->satuan_terkecil : 0;
    $screwHandleQty = $totalWindowHardwareHandleQty * $satuanTerkecilScrewHandle;
    if ($screwHandleItem) {
        $screwHandleItem->qty = $screwHandleQty;
    }

    // === PERHITUNGAN SETTING BLOCK ===
    $settingBlockItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'setting-block') {
            $settingBlockItem = $item;
            break;
        }
    }
    
    $satuanTerkecilSettingBlock = $settingBlockItem ? (float)$settingBlockItem->satuan_terkecil : 0;
    
    $variableC = 2 * $satuanTerkecilSettingBlock;
    $variableD = $variableC * $jumlah;
    $variableE = $variableD * 25;
    $variableF = $variableE / 1000;
    $settingBlockQty = ceil($variableF);

    // === PERHITUNGAN SCREW REINFORCEMENT ===
    $screwItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-reinforcement') {
            $screwItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrew = $screwItem ? (float)$screwItem->satuan_terkecil : 0;
    $screwQty = ((($totalLebar + $totalPanjang)) + ($variableSashVertikalB + $variableSashHorizontalB) + ($variableMullionVertikalB + $variableMullionHorizontalB)) / $satuanTerkecilScrew;
    $screwQty = ceil($screwQty * 10);

    // === PERHITUNGAN QTY PER AKSESORIS ===
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        $areaSlug = $item->area ? $item->area->slug : '';
        $qty = 0;
        
        if ($areaSlug == 'profile-vertikal') {
            $qty = $batangVertikal;
        } elseif ($areaSlug == 'profile-horizontal') {
            $qty = $batangHorizontal;
        } elseif ($areaSlug == 'glaze-bead-vertical') {
            $qty = ($panjang / 100) * $jumlah;
        } elseif ($areaSlug == 'glaze-bead-horizontal') {
            $qty = ($lebar / 100) * $jumlah;
        } elseif ($areaSlug == 'reinforcement') {
            $qty = $reinforcementQty;
        } elseif ($areaSlug == 'reinforcement-sash') {
            $qty = $reinforcementSashQty;
        } elseif ($areaSlug == 'reinforcement-mullion') {
            $qty = $reinforcementMullionQty;
        } elseif ($areaSlug == 'kaca') {
            $qty = $luasKacaTotal;
        } elseif ($areaSlug == 'screw-reinforcement') {
            $qty = $screwQty;
        } elseif ($areaSlug == 'setting-block') {
            $qty = $settingBlockQty;
        } elseif ($areaSlug == 'profile-sash-vertikal') {
            $qty = $batangSashVertikalQty;
        } elseif ($areaSlug == 'profile-sash-horizontal') {
            $qty = $batangSashHorizontalQty;
        } elseif ($areaSlug == 'profile-coupling-vertikal') {
            $qty = $batangCouplingVertikalQty;
        } elseif ($areaSlug == 'profile-mullion-vertikal') {
            $qty = $batangMullionVertikalQty;
        } elseif ($areaSlug == 'profile-mullion-horizontal') {
            $qty = $batangMullionHorizontalQty;
        } elseif ($areaSlug == 'window-hardware-transmitter') {
            $qty = ($transmitterItem && $transmitterItem->id == $item->id) ? $transmitterItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-friction-stay') {
            $qty = ($frictionStayItem && $frictionStayItem->id == $item->id) ? $frictionStayItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-handle-rambuncis' || $areaSlug == 'window-hardware-handle-multilock') {
            $qty = $item->qty;
        } elseif ($areaSlug == 'screw-transmitter') {
            $qty = $screwTransmitterQty;
        } elseif ($areaSlug == 'screw-friction-stay') {
            $qty = $screwFrictionStayQty;
        } elseif ($areaSlug == 'screw-handle') {
            $qty = $screwHandleQty;
        } else {
            $qty = $jumlah * ($item->satuan_terkecil ?? 1);
        }
        
        $item->qty = $qty;
    }

    // Data untuk view
    $data = [
        'produk' => $produkUtama,
        'panjang' => $panjang,
        'lebar' => $lebar,
        'tebal_kaca' => $tebalKaca,
        'jumlah' => $jumlah,
        'warna' => $warna,
        'type_kaca' => $typeKaca,
        'handle_id' => $handleId,
        'is_multilock' => $isMultilock,
        
        'luas_kaca_per_unit' => $luasKacaPerUnit,
        'luas_kaca_total' => $luasKacaTotal,
        'keliling_per_unit' => $kelilingPerUnit,
        'keliling_total' => $kelilingTotal,
        
        'profile_vertikal' => $profileVertikal,
        'variable_a' => $variableA,
        'frame_vertikal' => $frameVertikal,
        'batang_vertikal' => $batangVertikal,
        
        'profile_horizontal' => $profileHorizontal,
        'satuan_terkecil_horizontal' => $satuanTerkecilHorizontal,
        'variable_b' => $variableB,
        'frame_horizontal' => $frameHorizontal,
        'batang_horizontal' => $batangHorizontal,
        
        'total_batang' => $totalBatang,
        'reinforcement_qty' => $reinforcementQty,
        
        'profile_sash_vertikal' => $profileSashVertikal,
        'satuan_terkecil_sash_vertikal' => $satuanTerkecilSashVertikal,
        'variable_sash_vertikal_a' => $variableSashVertikalA,
        'variable_sash_vertikal_b' => $variableSashVertikalB,
        'batang_sash_vertikal' => $batangSashVertikal,
        'batang_sash_vertikal_qty' => $batangSashVertikalQty,
        
        'profile_sash_horizontal' => $profileSashHorizontal,
        'satuan_terkecil_sash_horizontal' => $satuanTerkecilSashHorizontal,
        'variable_sash_horizontal_a' => $variableSashHorizontalA,
        'variable_sash_horizontal_b' => $variableSashHorizontalB,
        'batang_sash_horizontal' => $batangSashHorizontal,
        'batang_sash_horizontal_qty' => $batangSashHorizontalQty,
        
        'profile_coupling_vertikal' => $profileCouplingVertikal,
        'satuan_terkecil_coupling_vertikal' => $satuanTerkecilCouplingVertikal,
        'variable_coupling_vertikal_a' => $variableCouplingVertikalA,
        'variable_coupling_vertikal_b' => $variableCouplingVertikalB,
        'batang_coupling_vertikal' => $batangCouplingVertikal,
        'batang_coupling_vertikal_qty' => $batangCouplingVertikalQty,
        
        'reinforcement_sash_qty' => $reinforcementSashQty,
        
        'profile_mullion_vertikal' => $profileMullionVertikal,
        'satuan_terkecil_mullion_vertikal' => $satuanTerkecilMullionVertikal,
        'variable_mullion_vertikal_a' => $variableMullionVertikalA,
        'variable_mullion_vertikal_b' => $variableMullionVertikalB,
        'batang_mullion_vertikal' => $batangMullionVertikal,
        'batang_mullion_vertikal_qty' => $batangMullionVertikalQty,
        
        'profile_mullion_horizontal' => $profileMullionHorizontal,
        'satuan_terkecil_mullion_horizontal' => $satuanTerkecilMullionHorizontal,
        'variable_mullion_horizontal_a' => $variableMullionHorizontalA,
        'variable_mullion_horizontal_b' => $variableMullionHorizontalB,
        'batang_mullion_horizontal' => $batangMullionHorizontal,
        'batang_mullion_horizontal_qty' => $batangMullionHorizontalQty,
        
        'total_batang_mullion' => $totalBatangMullion,
        'reinforcement_mullion_qty' => $reinforcementMullionQty,
        
        'transmitter_item' => $transmitterItem,
        'ukuran_transmitter' => $ukuranTransmitter,
        'ukuran_transmitter_final' => $ukuranTransmitterFinal,
        'total_window_hardware_transmitter_qty' => $totalWindowHardwareTransmitterQty,
        
        'friction_stay_item' => $frictionStayItem,
        'ukuran_friction_stay' => $ukuranFrictionStay,
        'ukuran_friction_stay_final' => $ukuranFrictionStayFinal,
        'total_window_hardware_friction_stay_qty' => $totalWindowHardwareFrictionStayQty,
        
        'handle_item' => $handleItem,
        'total_window_hardware_handle_qty' => $totalWindowHardwareHandleQty,
        
        'screw_transmitter_item' => $screwTransmitterItem,
        'screw_transmitter_qty' => $screwTransmitterQty,
        
        'screw_friction_stay_item' => $screwFrictionStayItem,
        'screw_friction_stay_qty' => $screwFrictionStayQty,
        
        'screw_handle_item' => $screwHandleItem,
        'screw_handle_qty' => $screwHandleQty,
        
        'satuan_terkecil_screw' => $satuanTerkecilScrew,
        'screw_qty' => $screwQty,
        
        'setting_block_item' => $settingBlockItem,
        'satuan_terkecil_setting_block' => $satuanTerkecilSettingBlock,
        'variable_c' => $variableC,
        'variable_d' => $variableD,
        'variable_e' => $variableE,
        'variable_f' => $variableF,
        'setting_block_qty' => $settingBlockQty,
        
        'aksesoris' => $aksesoris,
    ];

    return view('boq.jendela.jendela-jungkit-2-mullion', $data);
}

public function exportPdfJungkit2mullion(Request $request)
{
    $panjang = $request->panjang;
    $lebar = $request->lebar;
    $tebal_kaca = $request->tebal_kaca;
    $jumlah = $request->jumlah;
    $warna = $request->warna;
    $type_kaca = $request->type_kaca;
    $handle_id = $request->handle_id;
    $judul = $request->judul ?? 'BOQ - Jendela Jungkit 2 Daun (Mullion)';

    // Ambil data aksesoris
    $aksesorisIds = ProductAccessories::where('parent_product_id', 186)->pluck('accessory_id');
    $aksesoris = Product::with('area', 'unit')
        ->whereIn('id', $aksesorisIds)
        ->get();

    // === PERHITUNGAN DASAR ===
    $panjangM = $panjang / 100;
    $lebarM = $lebar / 100;
    
    $luasKacaPerUnit = $panjangM * $lebarM;
    $luasKacaTotal = $luasKacaPerUnit * $jumlah;
    $luasKacaTotal = ceil($luasKacaTotal * 10) / 10;

    $kelilingPerUnit = 2 * ($panjangM + $lebarM);
    $kelilingTotal = $kelilingPerUnit * $jumlah;

    // === PERHITUNGAN PROFILE VERTIKAL ===
    $profileVertikal = null;
    $aksesorisCount = count($aksesoris);
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-vertikal') {
            $profileVertikal = $item;
            break;
        }
    }
    $satuanTerkecilVertikal = $profileVertikal ? (float)$profileVertikal->satuan_terkecil : 0;

    $variableA = $jumlah * 4;
    $frameVertikal = $variableA * $panjang;
    $batangVertikal = $frameVertikal / 580;
    $batangVertikal = ceil($batangVertikal * 10) / 10;
    $totalPanjang = $panjang * $variableA;

    // === PERHITUNGAN PROFILE HORIZONTAL ===
    $profileHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-horizontal') {
            $profileHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilHorizontal = $profileHorizontal ? (float)$profileHorizontal->satuan_terkecil : 0;
    
    $variableB = $jumlah * $satuanTerkecilHorizontal;
    $frameHorizontal = $variableB * $lebar;
    $batangHorizontal = $frameHorizontal / 580;
    $batangHorizontal = ceil($batangHorizontal * 10) / 10;
    $totalLebar = $lebar * $variableB;

    // === PERHITUNGAN REINFORCEMENT ===
    $totalBatang = ($frameVertikal + $frameHorizontal) / 600;
    $reinforcementQty = ceil($totalBatang * 10) / 10;

    // === PERHITUNGAN PROFILE SASH VERTIKAL ===
    $profileSashVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-vertikal') {
            $profileSashVertikal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashVertikal = $profileSashVertikal ? (float)$profileSashVertikal->satuan_terkecil : 0;
    
    $variableSashVertikalA = 4 * $jumlah;
    $variableSashVertikalB = $variableSashVertikalA * $panjang;
    $batangSashVertikal = $variableSashVertikalB / 580;
    $batangSashVertikalQty = ceil($batangSashVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE SASH HORIZONTAL ===
    $profileSashHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-horizontal') {
            $profileSashHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashHorizontal = $profileSashHorizontal ? (float)$profileSashHorizontal->satuan_terkecil : 0;
    
    $variableSashHorizontalA = $satuanTerkecilSashHorizontal * $jumlah;
    $variableSashHorizontalB = $variableSashHorizontalA * $lebar;
    $batangSashHorizontal = $variableSashHorizontalB / 580;
    $batangSashHorizontalQty = ceil($batangSashHorizontal * 10) / 10;

    // === PERHITUNGAN PROFILE COUPLING VERTIKAL ===
    $profileCouplingVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-coupling-vertikal') {
            $profileCouplingVertikal = $item;
            break;
        }
    }

    $satuanTerkecilCouplingVertikal = $profileCouplingVertikal ? (float)$profileCouplingVertikal->satuan_terkecil : 0;

    $variableCouplingVertikalA = $satuanTerkecilCouplingVertikal * $jumlah * 2;
    $variableCouplingVertikalB = $variableCouplingVertikalA * $panjang;
    $batangCouplingVertikal = $variableCouplingVertikalB / 580;
    $batangCouplingVertikalQty = ceil($batangCouplingVertikal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT SASH ===
    $totalBatangSash = ($variableSashVertikalB + $variableSashHorizontalB) / 600;
    $reinforcementSashQty = ceil($totalBatangSash * 10) / 10;

    // === PERHITUNGAN PROFILE MULLION VERTIKAL ===
    $profileMullionVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-mullion-vertikal') {
            $profileMullionVertikal = $item;
            break;
        }
    }

    $satuanTerkecilMullionVertikal = $profileMullionVertikal ? (float)$profileMullionVertikal->satuan_terkecil : 0;
    
    $variableMullionVertikalA = 4 * $jumlah;
    $variableMullionVertikalB = $variableMullionVertikalA * $panjang;
    $batangMullionVertikal = $variableMullionVertikalB / 580;
    $batangMullionVertikalQty = ceil($batangMullionVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE MULLION HORIZONTAL ===
    $profileMullionHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-mullion-horizontal') {
            $profileMullionHorizontal = $item;
            break;
        }
    }

    $satuanTerkecilMullionHorizontal = $profileMullionHorizontal ? (float)$profileMullionHorizontal->satuan_terkecil : 0;
    
    $variableMullionHorizontalA = 6 * $jumlah;
    $variableMullionHorizontalB = $variableMullionHorizontalA * $lebar;
    $batangMullionHorizontal = $variableMullionHorizontalB / 580;
    $batangMullionHorizontalQty = ceil($batangMullionHorizontal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT MULLION ===
    $totalBatangMullion = ($variableMullionVertikalB + $variableMullionHorizontalB) / 600;
    $reinforcementMullionQty = ceil($totalBatangMullion * 10) / 10;

    // === PERHITUNGAN WINDOW HARDWARE HANDLE ===
    $handleItem = null;
    $totalWindowHardwareHandleQty = 0;

    // RESET QTY UNTUK SEMUA HANDLE = 0
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && ($item->area->slug == 'window-hardware-handle-rambuncis' || $item->area->slug == 'window-hardware-handle-multilock')) {
            $item->qty = 0;
        }
    }

    // SET QTY UNTUK HANDLE YANG DIPILIH
    if ($handle_id) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $handle_id) {
                $handleItem = $item;
                break;
            }
        }
    }

    if ($handleItem) {
        $satuanTerkecil = (float)($handleItem->satuan_terkecil ?? 0);
        $qty = $jumlah * 2;
        $handleItem->qty = $qty;
        $totalWindowHardwareHandleQty += $qty;
    }

    // CEK APAKAH HANDLE YANG DIPILIH ADALAH MULTILOCK
    $isMultilock = false;
    if ($handleItem) {
        $namaLower = strtolower($handleItem->nama_produk);
        if (str_contains($namaLower, 'multilock')) {
            $isMultilock = true;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE TRANSMITTER ===
    $transmitterItem = null;
    $totalWindowHardwareTransmitterQty = 0;
    $ukuranTransmitter = 0;
    $ukuranTransmitterFinal = 0;

    if ($isMultilock) {
        $ukuranTransmitter = $panjang - 20;

        $transmitterMapping = [
            40 => 172,
            60 => 171,
            80 => 170,
            100 => 173,
            120 => 162,
            140 => 166,
            160 => 167,
            180 => 168,
            200 => 169,
        ];

        $ukuranTransmitterFinal = $ukuranTransmitter;
        if (!isset($transmitterMapping[$ukuranTransmitter])) {
            $availableSizes = array_keys($transmitterMapping);
            sort($availableSizes);
            
            $found = false;
            for ($i = 0; $i < count($availableSizes); $i++) {
                if ($availableSizes[$i] >= $ukuranTransmitter) {
                    $ukuranTransmitterFinal = $availableSizes[$i];
                    $found = true;
                    break;
                }
            }
            
            if (!$found) {
                $ukuranTransmitterFinal = max($availableSizes);
            }
        }

        $transmitterId = $transmitterMapping[$ukuranTransmitterFinal] ?? null;

        if ($transmitterId) {
            for ($i = 0; $i < $aksesorisCount; $i++) {
                $item = $aksesoris[$i];
                if ($item->id == $transmitterId) {
                    $transmitterItem = $item;
                    break;
                }
            }
        }

        if ($transmitterItem) {
            $satuanTerkecil = (float)($transmitterItem->satuan_terkecil ?? 0);
            $qty = $jumlah * 2;
            $transmitterItem->qty = $qty;
            $totalWindowHardwareTransmitterQty += $qty;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE FRICTION STAY ===
    $ukuranFrictionStay = $panjang / 3;

    $frictionStayMapping = [
        25 => 175,
        30 => 174,
        35 => 179,
        40 => 173,
        45 => 176,
        50 => 177,
        60 => 178,
    ];

    $ukuranFrictionStayFinal = $ukuranFrictionStay;
    if (!isset($frictionStayMapping[$ukuranFrictionStay])) {
        $availableSizes = array_keys($frictionStayMapping);
        sort($availableSizes);
        
        $found = false;
        for ($i = 0; $i < count($availableSizes); $i++) {
            if ($availableSizes[$i] >= $ukuranFrictionStay) {
                $ukuranFrictionStayFinal = $availableSizes[$i];
                $found = true;
                break;
            }
        }
        
        if (!$found) {
            $ukuranFrictionStayFinal = max($availableSizes);
        }
    }

    $frictionStayItem = null;
    $frictionStayId = $frictionStayMapping[$ukuranFrictionStayFinal] ?? null;

    if ($frictionStayId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $frictionStayId) {
                $frictionStayItem = $item;
                break;
            }
        }
    }

    $totalWindowHardwareFrictionStayQty = 0;
    if ($frictionStayItem) {
        $satuanTerkecil = (float)($frictionStayItem->satuan_terkecil ?? 0);
        $qty = $jumlah * 4;
        $frictionStayItem->qty = $qty;
        $totalWindowHardwareFrictionStayQty += $qty;
    }

    // === PERHITUNGAN SCREW TRANSMITTER ===
    $screwTransmitterItem = null;
    $screwTransmitterQty = 0;

    if ($isMultilock && $transmitterItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-transmitter') {
                $screwTransmitterItem = $item;
                break;
            }
        }

        $satuanTerkecilScrewTransmitter = $screwTransmitterItem ? (float)$screwTransmitterItem->satuan_terkecil : 0;
        $screwTransmitterQty = ($totalWindowHardwareTransmitterQty * $satuanTerkecilScrewTransmitter);
        if ($screwTransmitterItem) {
            $screwTransmitterItem->qty = $screwTransmitterQty;
        }
    }

    // === PERHITUNGAN SCREW FRICTION STAY ===
    $screwFrictionStayItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-friction-stay') {
            $screwFrictionStayItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewFrictionStay = $screwFrictionStayItem ? (float)$screwFrictionStayItem->satuan_terkecil : 0;
    $screwFrictionStayQty = $totalWindowHardwareFrictionStayQty * $satuanTerkecilScrewFrictionStay;
    if ($screwFrictionStayItem) {
        $screwFrictionStayItem->qty = $screwFrictionStayQty;
    }

    // === PERHITUNGAN SCREW HANDLE ===
    $screwHandleItem = null;
    if ($handleItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-handle') {
                $screwHandleItem = $item;
                break;
            }
        }
    }

    $satuanTerkecilScrewHandle = $screwHandleItem ? (float)$screwHandleItem->satuan_terkecil : 0;
    $screwHandleQty = $totalWindowHardwareHandleQty * $satuanTerkecilScrewHandle;
    if ($screwHandleItem) {
        $screwHandleItem->qty = $screwHandleQty;
    }

    // === PERHITUNGAN SETTING BLOCK ===
    $settingBlockItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'setting-block') {
            $settingBlockItem = $item;
            break;
        }
    }
    
    $satuanTerkecilSettingBlock = $settingBlockItem ? (float)$settingBlockItem->satuan_terkecil : 0;
    
    $variableC = 2 * $satuanTerkecilSettingBlock;
    $variableD = $variableC * $jumlah;
    $variableE = $variableD * 25;
    $variableF = $variableE / 1000;
    $settingBlockQty = ceil($variableF);

    // === PERHITUNGAN SCREW REINFORCEMENT ===
    $screwItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-reinforcement') {
            $screwItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrew = $screwItem ? (float)$screwItem->satuan_terkecil : 0;
    $screwQty = ((($totalLebar + $totalPanjang)) + ($variableSashVertikalB + $variableSashHorizontalB) + ($variableMullionVertikalB + $variableMullionHorizontalB)) / $satuanTerkecilScrew;
    $screwQty = ceil($screwQty * 10);

    // === HITUNG QTY PER AKSESORIS ===
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        $areaSlug = $item->area ? $item->area->slug : '';
        $qty = 0;
        
        if ($areaSlug == 'profile-vertikal') {
            $qty = $batangVertikal;
        } elseif ($areaSlug == 'profile-horizontal') {
            $qty = $batangHorizontal;
        } elseif ($areaSlug == 'glaze-bead-vertical') {
            $qty = ($panjang / 100) * $jumlah;
        } elseif ($areaSlug == 'glaze-bead-horizontal') {
            $qty = ($lebar / 100) * $jumlah;
        } elseif ($areaSlug == 'reinforcement') {
            $qty = $reinforcementQty;
        } elseif ($areaSlug == 'reinforcement-sash') {
            $qty = $reinforcementSashQty;
        } elseif ($areaSlug == 'reinforcement-mullion') {
            $qty = $reinforcementMullionQty;
        } elseif ($areaSlug == 'kaca') {
            $qty = $luasKacaTotal;
        } elseif ($areaSlug == 'screw-reinforcement') {
            $qty = $screwQty;
        } elseif ($areaSlug == 'setting-block') {
            $qty = $settingBlockQty;
        } elseif ($areaSlug == 'profile-sash-vertikal') {
            $qty = $batangSashVertikalQty;
        } elseif ($areaSlug == 'profile-sash-horizontal') {
            $qty = $batangSashHorizontalQty;
        } elseif ($areaSlug == 'profile-coupling-vertikal') {
            $qty = $batangCouplingVertikalQty;
        } elseif ($areaSlug == 'profile-mullion-vertikal') {
            $qty = $batangMullionVertikalQty;
        } elseif ($areaSlug == 'profile-mullion-horizontal') {
            $qty = $batangMullionHorizontalQty;
        } elseif ($areaSlug == 'window-hardware-transmitter') {
            $qty = ($transmitterItem && $transmitterItem->id == $item->id) ? $transmitterItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-friction-stay') {
            $qty = ($frictionStayItem && $frictionStayItem->id == $item->id) ? $frictionStayItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-handle-rambuncis' || $areaSlug == 'window-hardware-handle-multilock') {
            $qty = $item->qty;
        } elseif ($areaSlug == 'screw-transmitter') {
            $qty = $screwTransmitterQty;
        } elseif ($areaSlug == 'screw-friction-stay') {
            $qty = $screwFrictionStayQty;
        } elseif ($areaSlug == 'screw-handle') {
            $qty = $screwHandleQty;
        } else {
            $qty = $jumlah * ($item->satuan_terkecil ?? 1);
        }
        
        $item->qty = $qty;
    }

    // Kelompokkan berdasarkan area
    $grouped = [];
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->qty <= 0) {
            continue;
        }
        
        // Skip transmitter, friction stay, dan handle yang tidak terpilih (qty 0)
        if ($item->area && ($item->area->slug == 'window-hardware-transmitter' || $item->area->slug == 'window-hardware-friction-stay') && $item->qty <= 0) {
            continue;
        }
        if ($item->area && ($item->area->slug == 'window-hardware-handle-rambuncis' || $item->area->slug == 'window-hardware-handle-multilock') && $item->qty <= 0) {
            continue;
        }
        
        $areaSlug = $item->area ? $item->area->slug : 'lainnya';
        
        if (str_starts_with($areaSlug, 'profile')) {
            $groupKey = 'profile';
        } elseif ($areaSlug == 'setting-block') {
            $groupKey = 'kaca';
        } elseif ($areaSlug == 'reinforcement' || $areaSlug == 'reinforcement-sash' || $areaSlug == 'reinforcement-mullion') {
            $groupKey = 'reinforcement';
        } elseif (str_starts_with($areaSlug, 'window-hardware')) {
            $groupKey = 'window-hardware';
        } elseif ($areaSlug == 'screw-reinforcement' || $areaSlug == 'screw-transmitter' || $areaSlug == 'screw-friction-stay' || $areaSlug == 'screw-handle') {
            $groupKey = 'screw';
        } else {
            $groupKey = $areaSlug;
        }
        
        if (!isset($grouped[$groupKey])) {
            $grouped[$groupKey] = [];
        }
        $grouped[$groupKey][] = $item;
    }

    $areaLabels = [
        'profile' => 'PROFILE',
        'reinforcement' => 'REINFORCEMENT',
        'kaca' => 'KACA',
        'screw' => 'SCREW',
        'window-hardware' => 'WINDOW HARDWARE',
    ];

    // ============ GENERATE NOMOR BOQ ============
    $nomorBoq = Boq::generateNomorBoq();

    // ============ STORE BOQ ============
    try {
        $allResults = [];
        
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->qty > 0) {
                $allResults[] = [
                    'produk_id' => $item->id,
                    'qty' => $item->qty,
                    'nama_produk' => $item->nama_produk,
                ];
            }
        }
        
        $uniqueResults = [];
        $seenIds = [];
        $allResultsCount = count($allResults);
        
        for ($i = 0; $i < $allResultsCount; $i++) {
            $item = $allResults[$i];
            $produkId = $item['produk_id'] ?? null;
            
            if (!$produkId) {
                continue;
            }
            
            $isDuplicate = false;
            $seenCount = count($seenIds);
            for ($j = 0; $j < $seenCount; $j++) {
                if ($seenIds[$j] == $produkId) {
                    $isDuplicate = true;
                    break;
                }
            }
            
            if ($isDuplicate) {
                continue;
            }
            
            $seenIds[] = $produkId;
            $uniqueResults[] = $item;
        }
        
        if (count($uniqueResults) > 0) {
            $boq = new Boq();
            $boq->nomor_boq = $nomorBoq;
            $boq->tanggal_boq = now();
            $boq->save();
            
            $uniqueCount = count($uniqueResults);
            for ($i = 0; $i < $uniqueCount; $i++) {
                $item = $uniqueResults[$i];
                $produkId = $item['produk_id'] ?? null;
                $qty = (int)($item['qty'] ?? 0);
                
                if ($produkId && $qty > 0) {
                    $produk = Product::find($produkId);
                    
                    \DB::table('detail_boq')->insert([
                        'boq_id' => $boq->id,
                        'produk_id' => $produkId,
                        'kode_produk' => $produk ? $produk->kode_produk : null,
                        'qty' => $qty,
                        'created_at' => now(),
                        'updated_at' => now()
                    ]);
                }
            }
            
            \Log::info('BOQ SAVED JENDELA JUNGKIT 2 MULLION:', [
                'boq_id' => $boq->id,
                'nomor_boq' => $nomorBoq,
                'total' => count($uniqueResults)
            ]);
        }
        
    } catch (\Exception $e) {
        \Log::error('Error saving BOQ Jendela Jungkit 2 Mullion: ' . $e->getMessage());
        \Log::error($e->getTraceAsString());
    }

    $data = [
        'judul' => $judul,
        'panjang' => $panjang,
        'lebar' => $lebar,
        'tebal_kaca' => $tebal_kaca,
        'jumlah' => $jumlah,
        'warna' => $warna,
        'type_kaca' => $type_kaca,
        'handle_id' => $handle_id,
        'is_multilock' => $isMultilock,
        'luas_kaca_total' => $luasKacaTotal,
        'keliling_total' => $kelilingTotal,
        'batang_vertikal' => $batangVertikal,
        'batang_horizontal' => $batangHorizontal,
        'reinforcement_qty' => $reinforcementQty,
        'reinforcement_sash_qty' => $reinforcementSashQty,
        'reinforcement_mullion_qty' => $reinforcementMullionQty,
        'batang_sash_vertikal_qty' => $batangSashVertikalQty,
        'batang_sash_horizontal_qty' => $batangSashHorizontalQty,
        'batang_coupling_vertikal_qty' => $batangCouplingVertikalQty,
        'batang_mullion_vertikal_qty' => $batangMullionVertikalQty,
        'batang_mullion_horizontal_qty' => $batangMullionHorizontalQty,
        'handle_item' => $handleItem,
        'total_window_hardware_handle_qty' => $totalWindowHardwareHandleQty,
        'transmitter_item' => $transmitterItem,
        'ukuran_transmitter' => $ukuranTransmitter,
        'ukuran_transmitter_final' => $ukuranTransmitterFinal,
        'total_window_hardware_transmitter_qty' => $totalWindowHardwareTransmitterQty,
        'friction_stay_item' => $frictionStayItem,
        'ukuran_friction_stay' => $ukuranFrictionStay,
        'ukuran_friction_stay_final' => $ukuranFrictionStayFinal,
        'total_window_hardware_friction_stay_qty' => $totalWindowHardwareFrictionStayQty,
        'screw_transmitter_qty' => $screwTransmitterQty,
        'screw_friction_stay_qty' => $screwFrictionStayQty,
        'screw_handle_qty' => $screwHandleQty,
        'screw_qty' => $screwQty,
        'setting_block_qty' => $settingBlockQty,
        'grouped' => $grouped,
        'areaLabels' => $areaLabels,
        'nomor_boq' => $nomorBoq,
    ];

    return view('boq.jendela.pdf-jendela-jungkit-2-mullion', compact('data'));
}

public function hitungJungkit4bouven(Request $request)
{
    $request->validate([
        'panjang' => 'required|numeric|min:1',
        'lebar' => 'required|numeric|min:1',
        'tebal_kaca' => 'required|numeric|min:1',
        'jumlah' => 'required|numeric|min:1',
        'warna' => 'required|string',
        'type_kaca' => 'required|string',
    ]);

    // Ambil data dari form
    $panjang = $request->panjang; // cm
    $lebar = $request->lebar; // cm
    $tebalKaca = $request->tebal_kaca; // mm
    $jumlah = $request->jumlah;
    $warna = $request->warna;
    $typeKaca = $request->type_kaca;
    $handleId = $request->handle_id;

    // Ambil produk utama (Jendela Bouven 4 Kaca) dari database
    $produkUtama = Product::find(187);
    
    if (!$produkUtama) {
        return back()->with('error', 'Produk Jendela Bouven 4 Kaca tidak ditemukan!');
    }

    // Ambil aksesoris dari tabel product_accessories dengan relasi area
    $aksesorisIds = ProductAccessories::where('parent_product_id', 187)->pluck('accessory_id');
    $aksesoris = Product::with('area', 'unit')
        ->whereIn('id', $aksesorisIds)
        ->get();

    // === PERHITUNGAN DASAR ===
    
    // Konversi ke meter
    $panjangM = $panjang / 100;
    $lebarM = $lebar / 100;
    $tebalKacaM = $tebalKaca / 1000;

    // 1. Luas Kaca (m²)
    $luasKacaPerUnit = $panjangM * $lebarM;
    $luasKacaTotal = $luasKacaPerUnit * $jumlah;
    $luasKacaTotal = ceil($luasKacaTotal * 10) / 10;

    // 2. Keliling Profile (meter)
    $kelilingPerUnit = 2 * ($panjangM + $lebarM);
    $kelilingTotal = $kelilingPerUnit * $jumlah;

    // === PERHITUNGAN PROFILE VERTIKAL ===
    $profileVertikal = null;
    $aksesorisCount = count($aksesoris);
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-vertikal') {
            $profileVertikal = $item;
            break;
        }
    }
    $satuanTerkecilVertikal = $profileVertikal ? (float)$profileVertikal->satuan_terkecil : 0;

    $variableA = $jumlah * 8;
    $frameVertikal = $variableA * $panjang;
    $batangVertikal = $frameVertikal / 580;
    $batangVertikal = ceil($batangVertikal * 10) / 10;
    $totalPanjang = $panjang * $variableA;

    // === PERHITUNGAN PROFILE HORIZONTAL ===
    $profileHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-horizontal') {
            $profileHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilHorizontal = $profileHorizontal ? (float)$profileHorizontal->satuan_terkecil : 0;
    
    $variableB = $jumlah * $satuanTerkecilHorizontal;
    $frameHorizontal = $variableB * $lebar;
    $batangHorizontal = $frameHorizontal / 580;
    $batangHorizontal = ceil($batangHorizontal * 10) / 10;
    $totalLebar = $lebar * $variableB;

    // === PERHITUNGAN REINFORCEMENT ===
    $totalBatang = ($frameVertikal + $frameHorizontal) / 600;
    $reinforcementQty = ceil($totalBatang * 10) / 10;

    // === PERHITUNGAN PROFILE SASH VERTIKAL ===
    $profileSashVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-vertikal') {
            $profileSashVertikal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashVertikal = $profileSashVertikal ? (float)$profileSashVertikal->satuan_terkecil : 0;
    
    $variableSashVertikalA = 8 * $jumlah;
    $variableSashVertikalB = $variableSashVertikalA * $panjang;
    $batangSashVertikal = $variableSashVertikalB / 580;
    $batangSashVertikalQty = ceil($batangSashVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE SASH HORIZONTAL ===
    $profileSashHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-horizontal') {
            $profileSashHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashHorizontal = $profileSashHorizontal ? (float)$profileSashHorizontal->satuan_terkecil : 0;
    
    $variableSashHorizontalA = $satuanTerkecilSashHorizontal * $jumlah;
    $variableSashHorizontalB = $variableSashHorizontalA * $lebar;
    $batangSashHorizontal = $variableSashHorizontalB / 580;
    $batangSashHorizontalQty = ceil($batangSashHorizontal * 10) / 10;

    // === PERHITUNGAN PROFILE COUPLING VERTIKAL ===
    $profileCouplingVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-coupling-vertikal') {
            $profileCouplingVertikal = $item;
            break;
        }
    }

    $satuanTerkecilCouplingVertikal = $profileCouplingVertikal ? (float)$profileCouplingVertikal->satuan_terkecil : 0;

    $variableCouplingVertikalA = 3 * $jumlah * 2;
    $variableCouplingVertikalB = $variableCouplingVertikalA * $panjang;
    $batangCouplingVertikal = $variableCouplingVertikalB / 580;
    $batangCouplingVertikalQty = ceil($batangCouplingVertikal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT SASH ===
    $totalBatangSash = ($variableSashVertikalB + $variableSashHorizontalB) / 600;
    $reinforcementSashQty = ceil($totalBatangSash * 10) / 10;

    // === PERHITUNGAN WINDOW HARDWARE HANDLE (dari dropdown) ===
    $handleItem = null;
    $totalWindowHardwareHandleQty = 0;

    // RESET QTY UNTUK SEMUA HANDLE = 0
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && ($item->area->slug == 'window-hardware-handle-rambuncis' || $item->area->slug == 'window-hardware-handle-multilock')) {
            $item->qty = 0;
        }
    }

    // SET QTY UNTUK HANDLE YANG DIPILIH
    if ($handleId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $handleId) {
                $handleItem = $item;
                break;
            }
        }
    }

    if ($handleItem) {
        $satuanTerkecil = (float)($handleItem->satuan_terkecil ?? 0);
        $qty = $jumlah * 4;
        $handleItem->qty = $qty;
        $totalWindowHardwareHandleQty += $qty;
    }

    // CEK APAKAH HANDLE YANG DIPILIH ADALAH MULTILOCK
    $isMultilock = false;
    if ($handleItem) {
        $namaLower = strtolower($handleItem->nama_produk);
        if (str_contains($namaLower, 'multilock')) {
            $isMultilock = true;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE TRANSMITTER ===
    $transmitterItem = null;
    $totalWindowHardwareTransmitterQty = 0;
    $ukuranTransmitter = 0;
    $ukuranTransmitterFinal = 0;

    // HANYA HITUNG TRANSMITTER JIKA HANDLE MULTILOCK
    if ($isMultilock) {
        $ukuranTransmitter = $panjang - 20;

        $transmitterMapping = [
            40 => 172,
            60 => 171,
            80 => 170,
            100 => 173,
            120 => 162,
            140 => 166,
            160 => 167,
            180 => 168,
            200 => 169,
        ];

        $ukuranTransmitterFinal = $ukuranTransmitter;
        if (!isset($transmitterMapping[$ukuranTransmitter])) {
            $availableSizes = array_keys($transmitterMapping);
            sort($availableSizes);
            
            $found = false;
            for ($i = 0; $i < count($availableSizes); $i++) {
                if ($availableSizes[$i] >= $ukuranTransmitter) {
                    $ukuranTransmitterFinal = $availableSizes[$i];
                    $found = true;
                    break;
                }
            }
            
            if (!$found) {
                $ukuranTransmitterFinal = max($availableSizes);
            }
        }

        $transmitterId = $transmitterMapping[$ukuranTransmitterFinal] ?? null;

        if ($transmitterId) {
            for ($i = 0; $i < $aksesorisCount; $i++) {
                $item = $aksesoris[$i];
                if ($item->id == $transmitterId) {
                    $transmitterItem = $item;
                    break;
                }
            }
        }

        if ($transmitterItem) {
            $satuanTerkecil = (float)($transmitterItem->satuan_terkecil ?? 0);
            $qty = $jumlah * 4;
            $transmitterItem->qty = $qty;
            $totalWindowHardwareTransmitterQty += $qty;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE FRICTION STAY ===
$ukuranFrictionStay = $panjang / 3;

$frictionStayMapping = [
    25 => 175,
    30 => 174,
    35 => 179,
    40 => 173,
    45 => 176,
    50 => 177,
    60 => 178,
];

$ukuranFrictionStayFinal = $ukuranFrictionStay;
if (!isset($frictionStayMapping[$ukuranFrictionStay])) {
    $availableSizes = array_keys($frictionStayMapping);
    sort($availableSizes);
    
    $found = false;
    for ($i = 0; $i < count($availableSizes); $i++) {
        if ($availableSizes[$i] >= $ukuranFrictionStay) {
            $ukuranFrictionStayFinal = $availableSizes[$i];
            $found = true;
            break;
        }
    }
    
    if (!$found) {
        $ukuranFrictionStayFinal = max($availableSizes);
    }
}

$frictionStayItem = null;
$frictionStayId = $frictionStayMapping[$ukuranFrictionStayFinal] ?? null;

if ($frictionStayId) {
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->id == $frictionStayId) {
            $frictionStayItem = $item;
            break;
        }
    }
}

$totalWindowHardwareFrictionStayQty = 0;
if ($frictionStayItem) {
    $satuanTerkecil = (float)($frictionStayItem->satuan_terkecil ?? 0);
    // QTY = qty handle x 2
    $qty = $totalWindowHardwareHandleQty * 2;
    $frictionStayItem->qty = $qty;
    $totalWindowHardwareFrictionStayQty += $qty;
}

    // === PERHITUNGAN SCREW TRANSMITTER ===
    $screwTransmitterItem = null;
    $screwTransmitterQty = 0;

    // HANYA JIKA MULTILOCK DAN ADA TRANSMITTER
    if ($isMultilock && $transmitterItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-transmitter') {
                $screwTransmitterItem = $item;
                break;
            }
        }

        $satuanTerkecilScrewTransmitter = $screwTransmitterItem ? (float)$screwTransmitterItem->satuan_terkecil : 0;
        $screwTransmitterQty = ($totalWindowHardwareTransmitterQty * $satuanTerkecilScrewTransmitter);
        if ($screwTransmitterItem) {
            $screwTransmitterItem->qty = $screwTransmitterQty;
        }
    }

    // === PERHITUNGAN SCREW FRICTION STAY ===
    $screwFrictionStayItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-friction-stay') {
            $screwFrictionStayItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewFrictionStay = $screwFrictionStayItem ? (float)$screwFrictionStayItem->satuan_terkecil : 0;
    $screwFrictionStayQty = $totalWindowHardwareFrictionStayQty * $satuanTerkecilScrewFrictionStay;
    if ($screwFrictionStayItem) {
        $screwFrictionStayItem->qty = $screwFrictionStayQty;
    }

    // === PERHITUNGAN SCREW HANDLE ===
    $screwHandleItem = null;
    if ($handleItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-handle') {
                $screwHandleItem = $item;
                break;
            }
        }
    }

    $satuanTerkecilScrewHandle = $screwHandleItem ? (float)$screwHandleItem->satuan_terkecil : 0;
    $screwHandleQty = $totalWindowHardwareHandleQty * $satuanTerkecilScrewHandle;
    if ($screwHandleItem) {
        $screwHandleItem->qty = $screwHandleQty;
    }

    // === PERHITUNGAN SETTING BLOCK ===
    $settingBlockItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'setting-block') {
            $settingBlockItem = $item;
            break;
        }
    }
    
    $satuanTerkecilSettingBlock = $settingBlockItem ? (float)$settingBlockItem->satuan_terkecil : 0;
    
    $variableC = 4 * $satuanTerkecilSettingBlock;
    $variableD = $variableC * $jumlah;
    $variableE = $variableD * 25;
    $variableF = $variableE / 1000;
    $settingBlockQty = ceil($variableF);

    // === PERHITUNGAN SCREW REINFORCEMENT ===
    $screwItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-reinforcement') {
            $screwItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrew = $screwItem ? (float)$screwItem->satuan_terkecil : 0;
    $screwQty = ((($totalLebar + $totalPanjang)) + ($variableSashVertikalB + $variableSashHorizontalB)) / $satuanTerkecilScrew;
    $screwQty = ceil($screwQty * 10);

    // === PERHITUNGAN QTY PER AKSESORIS ===
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        $areaSlug = $item->area ? $item->area->slug : '';
        $qty = 0;
        
        if ($areaSlug == 'profile-vertikal') {
            $qty = $batangVertikal;
        } elseif ($areaSlug == 'profile-horizontal') {
            $qty = $batangHorizontal;
        } elseif ($areaSlug == 'glaze-bead-vertical') {
            $qty = ($panjang / 100) * $jumlah;
        } elseif ($areaSlug == 'glaze-bead-horizontal') {
            $qty = ($lebar / 100) * $jumlah;
        } elseif ($areaSlug == 'reinforcement') {
            $qty = $reinforcementQty;
        } elseif ($areaSlug == 'reinforcement-sash') {
            $qty = $reinforcementSashQty;
        } elseif ($areaSlug == 'kaca') {
            $qty = $luasKacaTotal;
        } elseif ($areaSlug == 'screw-reinforcement') {
            $qty = $screwQty;
        } elseif ($areaSlug == 'setting-block') {
            $qty = $settingBlockQty;
        } elseif ($areaSlug == 'profile-sash-vertikal') {
            $qty = $batangSashVertikalQty;
        } elseif ($areaSlug == 'profile-sash-horizontal') {
            $qty = $batangSashHorizontalQty;
        } elseif ($areaSlug == 'profile-coupling-vertikal') {
            $qty = $batangCouplingVertikalQty;
        } elseif ($areaSlug == 'window-hardware-transmitter') {
            $qty = ($transmitterItem && $transmitterItem->id == $item->id) ? $transmitterItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-friction-stay') {
            $qty = ($frictionStayItem && $frictionStayItem->id == $item->id) ? $frictionStayItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-handle-rambuncis' || $areaSlug == 'window-hardware-handle-multilock') {
            $qty = $item->qty;
        } elseif ($areaSlug == 'screw-transmitter') {
            $qty = $screwTransmitterQty;
        } elseif ($areaSlug == 'screw-friction-stay') {
            $qty = $screwFrictionStayQty;
        } elseif ($areaSlug == 'screw-handle') {
            $qty = $screwHandleQty;
        } else {
            $qty = $jumlah * ($item->satuan_terkecil ?? 1);
        }
        
        $item->qty = $qty;
    }

    // Data untuk view
    $data = [
        'produk' => $produkUtama,
        'panjang' => $panjang,
        'lebar' => $lebar,
        'tebal_kaca' => $tebalKaca,
        'jumlah' => $jumlah,
        'warna' => $warna,
        'type_kaca' => $typeKaca,
        'handle_id' => $handleId,
        'is_multilock' => $isMultilock,
        
        'luas_kaca_per_unit' => $luasKacaPerUnit,
        'luas_kaca_total' => $luasKacaTotal,
        'keliling_per_unit' => $kelilingPerUnit,
        'keliling_total' => $kelilingTotal,
        
        'profile_vertikal' => $profileVertikal,
        'variable_a' => $variableA,
        'frame_vertikal' => $frameVertikal,
        'batang_vertikal' => $batangVertikal,
        
        'profile_horizontal' => $profileHorizontal,
        'satuan_terkecil_horizontal' => $satuanTerkecilHorizontal,
        'variable_b' => $variableB,
        'frame_horizontal' => $frameHorizontal,
        'batang_horizontal' => $batangHorizontal,
        
        'total_batang' => $totalBatang,
        'reinforcement_qty' => $reinforcementQty,
        
        'profile_sash_vertikal' => $profileSashVertikal,
        'satuan_terkecil_sash_vertikal' => $satuanTerkecilSashVertikal,
        'variable_sash_vertikal_a' => $variableSashVertikalA,
        'variable_sash_vertikal_b' => $variableSashVertikalB,
        'batang_sash_vertikal' => $batangSashVertikal,
        'batang_sash_vertikal_qty' => $batangSashVertikalQty,
        
        'profile_sash_horizontal' => $profileSashHorizontal,
        'satuan_terkecil_sash_horizontal' => $satuanTerkecilSashHorizontal,
        'variable_sash_horizontal_a' => $variableSashHorizontalA,
        'variable_sash_horizontal_b' => $variableSashHorizontalB,
        'batang_sash_horizontal' => $batangSashHorizontal,
        'batang_sash_horizontal_qty' => $batangSashHorizontalQty,
        
        'profile_coupling_vertikal' => $profileCouplingVertikal,
        'satuan_terkecil_coupling_vertikal' => $satuanTerkecilCouplingVertikal,
        'variable_coupling_vertikal_a' => $variableCouplingVertikalA,
        'variable_coupling_vertikal_b' => $variableCouplingVertikalB,
        'batang_coupling_vertikal' => $batangCouplingVertikal,
        'batang_coupling_vertikal_qty' => $batangCouplingVertikalQty,
        
        'reinforcement_sash_qty' => $reinforcementSashQty,
        
        'transmitter_item' => $transmitterItem,
        'ukuran_transmitter' => $ukuranTransmitter,
        'ukuran_transmitter_final' => $ukuranTransmitterFinal,
        'total_window_hardware_transmitter_qty' => $totalWindowHardwareTransmitterQty,
        
        'friction_stay_item' => $frictionStayItem,
        'ukuran_friction_stay' => $ukuranFrictionStay,
        'ukuran_friction_stay_final' => $ukuranFrictionStayFinal,
        'total_window_hardware_friction_stay_qty' => $totalWindowHardwareFrictionStayQty,
        
        'handle_item' => $handleItem,
        'total_window_hardware_handle_qty' => $totalWindowHardwareHandleQty,
        
        'screw_transmitter_item' => $screwTransmitterItem,
        'screw_transmitter_qty' => $screwTransmitterQty,
        
        'screw_friction_stay_item' => $screwFrictionStayItem,
        'screw_friction_stay_qty' => $screwFrictionStayQty,
        
        'screw_handle_item' => $screwHandleItem,
        'screw_handle_qty' => $screwHandleQty,
        
        'satuan_terkecil_screw' => $satuanTerkecilScrew,
        'screw_qty' => $screwQty,
        
        'setting_block_item' => $settingBlockItem,
        'satuan_terkecil_setting_block' => $satuanTerkecilSettingBlock,
        'variable_c' => $variableC,
        'variable_d' => $variableD,
        'variable_e' => $variableE,
        'variable_f' => $variableF,
        'setting_block_qty' => $settingBlockQty,
        
        'aksesoris' => $aksesoris,
    ];

    return view('boq.jendela.jendela-jungkit-4-bouven', $data);
}

public function exportPdfJungkit4Bouven(Request $request)
{
    $panjang = $request->panjang;
    $lebar = $request->lebar;
    $tebal_kaca = $request->tebal_kaca;
    $jumlah = $request->jumlah;
    $warna = $request->warna;
    $type_kaca = $request->type_kaca;
    $handle_id = $request->handle_id;
    $judul = $request->judul ?? 'BOQ - Jendela Bouven 4 Kaca';

    // Ambil data aksesoris
    $aksesorisIds = ProductAccessories::where('parent_product_id', 187)->pluck('accessory_id');
    $aksesoris = Product::with('area', 'unit')
        ->whereIn('id', $aksesorisIds)
        ->get();

    // === PERHITUNGAN DASAR ===
    $panjangM = $panjang / 100;
    $lebarM = $lebar / 100;
    
    $luasKacaPerUnit = $panjangM * $lebarM;
    $luasKacaTotal = $luasKacaPerUnit * $jumlah;
    $luasKacaTotal = ceil($luasKacaTotal * 10) / 10;

    $kelilingPerUnit = 2 * ($panjangM + $lebarM);
    $kelilingTotal = $kelilingPerUnit * $jumlah;

    // === PERHITUNGAN PROFILE VERTIKAL ===
    $profileVertikal = null;
    $aksesorisCount = count($aksesoris);
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-vertikal') {
            $profileVertikal = $item;
            break;
        }
    }
    $satuanTerkecilVertikal = $profileVertikal ? (float)$profileVertikal->satuan_terkecil : 0;

    $variableA = $jumlah * 8;
    $frameVertikal = $variableA * $panjang;
    $batangVertikal = $frameVertikal / 580;
    $batangVertikal = ceil($batangVertikal * 10) / 10;
    $totalPanjang = $panjang * $variableA;

    // === PERHITUNGAN PROFILE HORIZONTAL ===
    $profileHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-horizontal') {
            $profileHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilHorizontal = $profileHorizontal ? (float)$profileHorizontal->satuan_terkecil : 0;
    
    $variableB = $jumlah * $satuanTerkecilHorizontal;
    $frameHorizontal = $variableB * $lebar;
    $batangHorizontal = $frameHorizontal / 580;
    $batangHorizontal = ceil($batangHorizontal * 10) / 10;
    $totalLebar = $lebar * $variableB;

    // === PERHITUNGAN REINFORCEMENT ===
    $totalBatang = ($frameVertikal + $frameHorizontal) / 600;
    $reinforcementQty = ceil($totalBatang * 10) / 10;

    // === PERHITUNGAN PROFILE SASH VERTIKAL ===
    $profileSashVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-vertikal') {
            $profileSashVertikal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashVertikal = $profileSashVertikal ? (float)$profileSashVertikal->satuan_terkecil : 0;
    
    $variableSashVertikalA = 8 * $jumlah;
    $variableSashVertikalB = $variableSashVertikalA * $panjang;
    $batangSashVertikal = $variableSashVertikalB / 580;
    $batangSashVertikalQty = ceil($batangSashVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE SASH HORIZONTAL ===
    $profileSashHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-horizontal') {
            $profileSashHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashHorizontal = $profileSashHorizontal ? (float)$profileSashHorizontal->satuan_terkecil : 0;
    
    $variableSashHorizontalA = $satuanTerkecilSashHorizontal * $jumlah;
    $variableSashHorizontalB = $variableSashHorizontalA * $lebar;
    $batangSashHorizontal = $variableSashHorizontalB / 580;
    $batangSashHorizontalQty = ceil($batangSashHorizontal * 10) / 10;

    // === PERHITUNGAN PROFILE COUPLING VERTIKAL ===
    $profileCouplingVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-coupling-vertikal') {
            $profileCouplingVertikal = $item;
            break;
        }
    }

    $satuanTerkecilCouplingVertikal = $profileCouplingVertikal ? (float)$profileCouplingVertikal->satuan_terkecil : 0;

    $variableCouplingVertikalA = 3 * $jumlah * 2;
    $variableCouplingVertikalB = $variableCouplingVertikalA * $panjang;
    $batangCouplingVertikal = $variableCouplingVertikalB / 580;
    $batangCouplingVertikalQty = ceil($batangCouplingVertikal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT SASH ===
    $totalBatangSash = ($variableSashVertikalB + $variableSashHorizontalB) / 600;
    $reinforcementSashQty = ceil($totalBatangSash * 10) / 10;

    // === PERHITUNGAN WINDOW HARDWARE HANDLE ===
    $handleItem = null;
    $totalWindowHardwareHandleQty = 0;

    // RESET QTY UNTUK SEMUA HANDLE = 0
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && ($item->area->slug == 'window-hardware-handle-rambuncis' || $item->area->slug == 'window-hardware-handle-multilock')) {
            $item->qty = 0;
        }
    }

    // SET QTY UNTUK HANDLE YANG DIPILIH
    if ($handle_id) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $handle_id) {
                $handleItem = $item;
                break;
            }
        }
    }

    if ($handleItem) {
        $satuanTerkecil = (float)($handleItem->satuan_terkecil ?? 0);
        $qty = $jumlah * 4;
        $handleItem->qty = $qty;
        $totalWindowHardwareHandleQty += $qty;
    }

    // CEK APAKAH HANDLE YANG DIPILIH ADALAH MULTILOCK
    $isMultilock = false;
    if ($handleItem) {
        $namaLower = strtolower($handleItem->nama_produk);
        if (str_contains($namaLower, 'multilock')) {
            $isMultilock = true;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE TRANSMITTER ===
    $transmitterItem = null;
    $totalWindowHardwareTransmitterQty = 0;
    $ukuranTransmitter = 0;
    $ukuranTransmitterFinal = 0;

    if ($isMultilock) {
        $ukuranTransmitter = $panjang - 20;

        $transmitterMapping = [
            40 => 172,
            60 => 171,
            80 => 170,
            100 => 173,
            120 => 162,
            140 => 166,
            160 => 167,
            180 => 168,
            200 => 169,
        ];

        $ukuranTransmitterFinal = $ukuranTransmitter;
        if (!isset($transmitterMapping[$ukuranTransmitter])) {
            $availableSizes = array_keys($transmitterMapping);
            sort($availableSizes);
            
            $found = false;
            for ($i = 0; $i < count($availableSizes); $i++) {
                if ($availableSizes[$i] >= $ukuranTransmitter) {
                    $ukuranTransmitterFinal = $availableSizes[$i];
                    $found = true;
                    break;
                }
            }
            
            if (!$found) {
                $ukuranTransmitterFinal = max($availableSizes);
            }
        }

        $transmitterId = $transmitterMapping[$ukuranTransmitterFinal] ?? null;

        if ($transmitterId) {
            for ($i = 0; $i < $aksesorisCount; $i++) {
                $item = $aksesoris[$i];
                if ($item->id == $transmitterId) {
                    $transmitterItem = $item;
                    break;
                }
            }
        }

        if ($transmitterItem) {
            $satuanTerkecil = (float)($transmitterItem->satuan_terkecil ?? 0);
            $qty = $jumlah * 4;
            $transmitterItem->qty = $qty;
            $totalWindowHardwareTransmitterQty += $qty;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE FRICTION STAY ===
    $ukuranFrictionStay = $panjang / 3;

    $frictionStayMapping = [
        25 => 175,
        30 => 174,
        35 => 179,
        40 => 173,
        45 => 176,
        50 => 177,
        60 => 178,
    ];

    $ukuranFrictionStayFinal = $ukuranFrictionStay;
    if (!isset($frictionStayMapping[$ukuranFrictionStay])) {
        $availableSizes = array_keys($frictionStayMapping);
        sort($availableSizes);
        
        $found = false;
        for ($i = 0; $i < count($availableSizes); $i++) {
            if ($availableSizes[$i] >= $ukuranFrictionStay) {
                $ukuranFrictionStayFinal = $availableSizes[$i];
                $found = true;
                break;
            }
        }
        
        if (!$found) {
            $ukuranFrictionStayFinal = max($availableSizes);
        }
    }

    $frictionStayItem = null;
    $frictionStayId = $frictionStayMapping[$ukuranFrictionStayFinal] ?? null;

    if ($frictionStayId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $frictionStayId) {
                $frictionStayItem = $item;
                break;
            }
        }
    }

    $totalWindowHardwareFrictionStayQty = 0;
    if ($frictionStayItem) {
        $satuanTerkecil = (float)($frictionStayItem->satuan_terkecil ?? 0);
        // QTY = qty handle x 2
        $qty = $totalWindowHardwareHandleQty * 2;
        $frictionStayItem->qty = $qty;
        $totalWindowHardwareFrictionStayQty += $qty;
    }

    // === PERHITUNGAN SCREW TRANSMITTER ===
    $screwTransmitterItem = null;
    $screwTransmitterQty = 0;

    if ($isMultilock && $transmitterItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-transmitter') {
                $screwTransmitterItem = $item;
                break;
            }
        }

        $satuanTerkecilScrewTransmitter = $screwTransmitterItem ? (float)$screwTransmitterItem->satuan_terkecil : 0;
        $screwTransmitterQty = ($totalWindowHardwareTransmitterQty * $satuanTerkecilScrewTransmitter);
        if ($screwTransmitterItem) {
            $screwTransmitterItem->qty = $screwTransmitterQty;
        }
    }

    // === PERHITUNGAN SCREW FRICTION STAY ===
    $screwFrictionStayItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-friction-stay') {
            $screwFrictionStayItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewFrictionStay = $screwFrictionStayItem ? (float)$screwFrictionStayItem->satuan_terkecil : 0;
    $screwFrictionStayQty = $totalWindowHardwareFrictionStayQty * $satuanTerkecilScrewFrictionStay;
    if ($screwFrictionStayItem) {
        $screwFrictionStayItem->qty = $screwFrictionStayQty;
    }

    // === PERHITUNGAN SCREW HANDLE ===
    $screwHandleItem = null;
    if ($handleItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-handle') {
                $screwHandleItem = $item;
                break;
            }
        }
    }

    $satuanTerkecilScrewHandle = $screwHandleItem ? (float)$screwHandleItem->satuan_terkecil : 0;
    $screwHandleQty = $totalWindowHardwareHandleQty * $satuanTerkecilScrewHandle;
    if ($screwHandleItem) {
        $screwHandleItem->qty = $screwHandleQty;
    }

    // === PERHITUNGAN SETTING BLOCK ===
    $settingBlockItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'setting-block') {
            $settingBlockItem = $item;
            break;
        }
    }
    
    $satuanTerkecilSettingBlock = $settingBlockItem ? (float)$settingBlockItem->satuan_terkecil : 0;
    
    $variableC = 4 * $satuanTerkecilSettingBlock;
    $variableD = $variableC * $jumlah;
    $variableE = $variableD * 25;
    $variableF = $variableE / 1000;
    $settingBlockQty = ceil($variableF);

    // === PERHITUNGAN SCREW REINFORCEMENT ===
    $screwItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-reinforcement') {
            $screwItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrew = $screwItem ? (float)$screwItem->satuan_terkecil : 0;
    $screwQty = ((($totalLebar + $totalPanjang)) + ($variableSashVertikalB + $variableSashHorizontalB)) / $satuanTerkecilScrew;
    $screwQty = ceil($screwQty * 10);

    // === HITUNG QTY PER AKSESORIS ===
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        $areaSlug = $item->area ? $item->area->slug : '';
        $qty = 0;
        
        if ($areaSlug == 'profile-vertikal') {
            $qty = $batangVertikal;
        } elseif ($areaSlug == 'profile-horizontal') {
            $qty = $batangHorizontal;
        } elseif ($areaSlug == 'glaze-bead-vertical') {
            $qty = ($panjang / 100) * $jumlah;
        } elseif ($areaSlug == 'glaze-bead-horizontal') {
            $qty = ($lebar / 100) * $jumlah;
        } elseif ($areaSlug == 'reinforcement') {
            $qty = $reinforcementQty;
        } elseif ($areaSlug == 'reinforcement-sash') {
            $qty = $reinforcementSashQty;
        } elseif ($areaSlug == 'kaca') {
            $qty = $luasKacaTotal;
        } elseif ($areaSlug == 'screw-reinforcement') {
            $qty = $screwQty;
        } elseif ($areaSlug == 'setting-block') {
            $qty = $settingBlockQty;
        } elseif ($areaSlug == 'profile-sash-vertikal') {
            $qty = $batangSashVertikalQty;
        } elseif ($areaSlug == 'profile-sash-horizontal') {
            $qty = $batangSashHorizontalQty;
        } elseif ($areaSlug == 'profile-coupling-vertikal') {
            $qty = $batangCouplingVertikalQty;
        } elseif ($areaSlug == 'window-hardware-transmitter') {
            $qty = ($transmitterItem && $transmitterItem->id == $item->id) ? $transmitterItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-friction-stay') {
            $qty = ($frictionStayItem && $frictionStayItem->id == $item->id) ? $frictionStayItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-handle-rambuncis' || $areaSlug == 'window-hardware-handle-multilock') {
            $qty = $item->qty;
        } elseif ($areaSlug == 'screw-transmitter') {
            $qty = $screwTransmitterQty;
        } elseif ($areaSlug == 'screw-friction-stay') {
            $qty = $screwFrictionStayQty;
        } elseif ($areaSlug == 'screw-handle') {
            $qty = $screwHandleQty;
        } else {
            $qty = $jumlah * ($item->satuan_terkecil ?? 1);
        }
        
        $item->qty = $qty;
    }

    // Kelompokkan berdasarkan area
    $grouped = [];
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->qty <= 0) {
            continue;
        }
        
        // Skip transmitter, friction stay, dan handle yang tidak terpilih (qty 0)
        if ($item->area && ($item->area->slug == 'window-hardware-transmitter' || $item->area->slug == 'window-hardware-friction-stay') && $item->qty <= 0) {
            continue;
        }
        if ($item->area && ($item->area->slug == 'window-hardware-handle-rambuncis' || $item->area->slug == 'window-hardware-handle-multilock') && $item->qty <= 0) {
            continue;
        }
        
        $areaSlug = $item->area ? $item->area->slug : 'lainnya';
        
        if (str_starts_with($areaSlug, 'profile')) {
            $groupKey = 'profile';
        } elseif ($areaSlug == 'setting-block') {
            $groupKey = 'kaca';
        } elseif ($areaSlug == 'reinforcement' || $areaSlug == 'reinforcement-sash') {
            $groupKey = 'reinforcement';
        } elseif (str_starts_with($areaSlug, 'window-hardware')) {
            $groupKey = 'window-hardware';
        } elseif ($areaSlug == 'screw-reinforcement' || $areaSlug == 'screw-transmitter' || $areaSlug == 'screw-friction-stay' || $areaSlug == 'screw-handle') {
            $groupKey = 'screw';
        } else {
            $groupKey = $areaSlug;
        }
        
        if (!isset($grouped[$groupKey])) {
            $grouped[$groupKey] = [];
        }
        $grouped[$groupKey][] = $item;
    }

    $areaLabels = [
        'profile' => 'PROFILE',
        'reinforcement' => 'REINFORCEMENT',
        'kaca' => 'KACA',
        'screw' => 'SCREW',
        'window-hardware' => 'WINDOW HARDWARE',
    ];

    // ============ GENERATE NOMOR BOQ ============
    $nomorBoq = Boq::generateNomorBoq();

    // ============ STORE BOQ ============
    try {
        $allResults = [];
        
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->qty > 0) {
                $allResults[] = [
                    'produk_id' => $item->id,
                    'qty' => $item->qty,
                    'nama_produk' => $item->nama_produk,
                ];
            }
        }
        
        $uniqueResults = [];
        $seenIds = [];
        $allResultsCount = count($allResults);
        
        for ($i = 0; $i < $allResultsCount; $i++) {
            $item = $allResults[$i];
            $produkId = $item['produk_id'] ?? null;
            
            if (!$produkId) {
                continue;
            }
            
            $isDuplicate = false;
            $seenCount = count($seenIds);
            for ($j = 0; $j < $seenCount; $j++) {
                if ($seenIds[$j] == $produkId) {
                    $isDuplicate = true;
                    break;
                }
            }
            
            if ($isDuplicate) {
                continue;
            }
            
            $seenIds[] = $produkId;
            $uniqueResults[] = $item;
        }
        
        if (count($uniqueResults) > 0) {
            $boq = new Boq();
            $boq->nomor_boq = $nomorBoq;
            $boq->tanggal_boq = now();
            $boq->save();
            
            $uniqueCount = count($uniqueResults);
            for ($i = 0; $i < $uniqueCount; $i++) {
                $item = $uniqueResults[$i];
                $produkId = $item['produk_id'] ?? null;
                $qty = (int)($item['qty'] ?? 0);
                
                if ($produkId && $qty > 0) {
                    $produk = Product::find($produkId);
                    
                    \DB::table('detail_boq')->insert([
                        'boq_id' => $boq->id,
                        'produk_id' => $produkId,
                        'kode_produk' => $produk ? $produk->kode_produk : null,
                        'qty' => $qty,
                        'created_at' => now(),
                        'updated_at' => now()
                    ]);
                }
            }
            
            \Log::info('BOQ SAVED JENDELA BOUVEN 4 KACA:', [
                'boq_id' => $boq->id,
                'nomor_boq' => $nomorBoq,
                'total' => count($uniqueResults)
            ]);
        }
        
    } catch (\Exception $e) {
        \Log::error('Error saving BOQ Jendela Bouven 4 Kaca: ' . $e->getMessage());
        \Log::error($e->getTraceAsString());
    }

    $data = [
        'judul' => $judul,
        'panjang' => $panjang,
        'lebar' => $lebar,
        'tebal_kaca' => $tebal_kaca,
        'jumlah' => $jumlah,
        'warna' => $warna,
        'type_kaca' => $type_kaca,
        'handle_id' => $handle_id,
        'is_multilock' => $isMultilock,
        'luas_kaca_total' => $luasKacaTotal,
        'keliling_total' => $kelilingTotal,
        'batang_vertikal' => $batangVertikal,
        'batang_horizontal' => $batangHorizontal,
        'reinforcement_qty' => $reinforcementQty,
        'reinforcement_sash_qty' => $reinforcementSashQty,
        'batang_sash_vertikal_qty' => $batangSashVertikalQty,
        'batang_sash_horizontal_qty' => $batangSashHorizontalQty,
        'batang_coupling_vertikal_qty' => $batangCouplingVertikalQty,
        'handle_item' => $handleItem,
        'total_window_hardware_handle_qty' => $totalWindowHardwareHandleQty,
        'transmitter_item' => $transmitterItem,
        'ukuran_transmitter' => $ukuranTransmitter,
        'ukuran_transmitter_final' => $ukuranTransmitterFinal,
        'total_window_hardware_transmitter_qty' => $totalWindowHardwareTransmitterQty,
        'friction_stay_item' => $frictionStayItem,
        'ukuran_friction_stay' => $ukuranFrictionStay,
        'ukuran_friction_stay_final' => $ukuranFrictionStayFinal,
        'total_window_hardware_friction_stay_qty' => $totalWindowHardwareFrictionStayQty,
        'screw_transmitter_qty' => $screwTransmitterQty,
        'screw_friction_stay_qty' => $screwFrictionStayQty,
        'screw_handle_qty' => $screwHandleQty,
        'screw_qty' => $screwQty,
        'setting_block_qty' => $settingBlockQty,
        'grouped' => $grouped,
        'areaLabels' => $areaLabels,
        'nomor_boq' => $nomorBoq,
    ];

    return view('boq.jendela.pdf-jendela-jungkit-4-bouven', compact('data'));
}

public function hitungJungkit2bouven(Request $request)
{
    $request->validate([
        'panjang' => 'required|numeric|min:1',
        'lebar' => 'required|numeric|min:1',
        'tebal_kaca' => 'required|numeric|min:1',
        'jumlah' => 'required|numeric|min:1',
        'warna' => 'required|string',
        'type_kaca' => 'required|string',
    ]);

    // Ambil data dari form
    $panjang = $request->panjang; // cm
    $lebar = $request->lebar; // cm
    $tebalKaca = $request->tebal_kaca; // mm
    $jumlah = $request->jumlah;
    $warna = $request->warna;
    $typeKaca = $request->type_kaca;
    $handleId = $request->handle_id;

    // Ambil produk utama (Jendela Bouven 4 Kaca) dari database
    $produkUtama = Product::find(187);
    
    if (!$produkUtama) {
        return back()->with('error', 'Produk Jendela Bouven 4 Kaca tidak ditemukan!');
    }

    // Ambil aksesoris dari tabel product_accessories dengan relasi area
    $aksesorisIds = ProductAccessories::where('parent_product_id', 187)->pluck('accessory_id');
    $aksesoris = Product::with('area', 'unit')
        ->whereIn('id', $aksesorisIds)
        ->get();

    // === PERHITUNGAN DASAR ===
    
    // Konversi ke meter
    $panjangM = $panjang / 100;
    $lebarM = $lebar / 100;
    $tebalKacaM = $tebalKaca / 1000;

    // 1. Luas Kaca (m²)
    $luasKacaPerUnit = $panjangM * $lebarM;
    $luasKacaTotal = $luasKacaPerUnit * $jumlah;
    $luasKacaTotal = ceil($luasKacaTotal * 10) / 10;

    // 2. Keliling Profile (meter)
    $kelilingPerUnit = 2 * ($panjangM + $lebarM);
    $kelilingTotal = $kelilingPerUnit * $jumlah;

    // === PERHITUNGAN PROFILE VERTIKAL ===
    $profileVertikal = null;
    $aksesorisCount = count($aksesoris);
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-vertikal') {
            $profileVertikal = $item;
            break;
        }
    }
    $satuanTerkecilVertikal = $profileVertikal ? (float)$profileVertikal->satuan_terkecil : 0;

    $variableA = $jumlah * 4;
    $frameVertikal = $variableA * $panjang;
    $batangVertikal = $frameVertikal / 580;
    $batangVertikal = ceil($batangVertikal * 10) / 10;
    $totalPanjang = $panjang * $variableA;

    // === PERHITUNGAN PROFILE HORIZONTAL ===
    $profileHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-horizontal') {
            $profileHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilHorizontal = $profileHorizontal ? (float)$profileHorizontal->satuan_terkecil : 0;
    
    $variableB = $jumlah * $satuanTerkecilHorizontal;
    $frameHorizontal = $variableB * $lebar;
    $batangHorizontal = $frameHorizontal / 580;
    $batangHorizontal = ceil($batangHorizontal * 10) / 10;
    $totalLebar = $lebar * $variableB;

    // === PERHITUNGAN REINFORCEMENT ===
    $totalBatang = ($frameVertikal + $frameHorizontal) / 600;
    $reinforcementQty = ceil($totalBatang * 10) / 10;

    // === PERHITUNGAN PROFILE SASH VERTIKAL ===
    $profileSashVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-vertikal') {
            $profileSashVertikal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashVertikal = $profileSashVertikal ? (float)$profileSashVertikal->satuan_terkecil : 0;
    
    $variableSashVertikalA = 4 * $jumlah;
    $variableSashVertikalB = $variableSashVertikalA * $panjang;
    $batangSashVertikal = $variableSashVertikalB / 580;
    $batangSashVertikalQty = ceil($batangSashVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE SASH HORIZONTAL ===
    $profileSashHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-horizontal') {
            $profileSashHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashHorizontal = $profileSashHorizontal ? (float)$profileSashHorizontal->satuan_terkecil : 0;
    
    $variableSashHorizontalA = $satuanTerkecilSashHorizontal * $jumlah;
    $variableSashHorizontalB = $variableSashHorizontalA * $lebar;
    $batangSashHorizontal = $variableSashHorizontalB / 580;
    $batangSashHorizontalQty = ceil($batangSashHorizontal * 10) / 10;

    // === PERHITUNGAN PROFILE COUPLING VERTIKAL ===
    $profileCouplingVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-coupling-vertikal') {
            $profileCouplingVertikal = $item;
            break;
        }
    }

    $satuanTerkecilCouplingVertikal = $profileCouplingVertikal ? (float)$profileCouplingVertikal->satuan_terkecil : 0;

    $variableCouplingVertikalA = $satuanTerkecilCouplingVertikal * $jumlah * 2;
    $variableCouplingVertikalB = $variableCouplingVertikalA * $panjang;
    $batangCouplingVertikal = $variableCouplingVertikalB / 580;
    $batangCouplingVertikalQty = ceil($batangCouplingVertikal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT SASH ===
    $totalBatangSash = ($variableSashVertikalB + $variableSashHorizontalB) / 600;
    $reinforcementSashQty = ceil($totalBatangSash * 10) / 10;

    // === PERHITUNGAN WINDOW HARDWARE HANDLE (dari dropdown) ===
    $handleItem = null;
    $totalWindowHardwareHandleQty = 0;

    // RESET QTY UNTUK SEMUA HANDLE = 0
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && ($item->area->slug == 'window-hardware-handle-rambuncis' || $item->area->slug == 'window-hardware-handle-multilock')) {
            $item->qty = 0;
        }
    }

    // SET QTY UNTUK HANDLE YANG DIPILIH
    if ($handleId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $handleId) {
                $handleItem = $item;
                break;
            }
        }
    }

    if ($handleItem) {
        $satuanTerkecil = (float)($handleItem->satuan_terkecil ?? 0);
        $qty = $jumlah * 2;
        $handleItem->qty = $qty;
        $totalWindowHardwareHandleQty += $qty;
    }

    // CEK APAKAH HANDLE YANG DIPILIH ADALAH MULTILOCK
    $isMultilock = false;
    if ($handleItem) {
        $namaLower = strtolower($handleItem->nama_produk);
        if (str_contains($namaLower, 'multilock')) {
            $isMultilock = true;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE TRANSMITTER ===
    $transmitterItem = null;
    $totalWindowHardwareTransmitterQty = 0;
    $ukuranTransmitter = 0;
    $ukuranTransmitterFinal = 0;

    // HANYA HITUNG TRANSMITTER JIKA HANDLE MULTILOCK
    if ($isMultilock) {
        $ukuranTransmitter = $panjang - 20;

        $transmitterMapping = [
            40 => 172,
            60 => 171,
            80 => 170,
            100 => 173,
            120 => 162,
            140 => 166,
            160 => 167,
            180 => 168,
            200 => 169,
        ];

        $ukuranTransmitterFinal = $ukuranTransmitter;
        if (!isset($transmitterMapping[$ukuranTransmitter])) {
            $availableSizes = array_keys($transmitterMapping);
            sort($availableSizes);
            
            $found = false;
            for ($i = 0; $i < count($availableSizes); $i++) {
                if ($availableSizes[$i] >= $ukuranTransmitter) {
                    $ukuranTransmitterFinal = $availableSizes[$i];
                    $found = true;
                    break;
                }
            }
            
            if (!$found) {
                $ukuranTransmitterFinal = max($availableSizes);
            }
        }

        $transmitterId = $transmitterMapping[$ukuranTransmitterFinal] ?? null;

        if ($transmitterId) {
            for ($i = 0; $i < $aksesorisCount; $i++) {
                $item = $aksesoris[$i];
                if ($item->id == $transmitterId) {
                    $transmitterItem = $item;
                    break;
                }
            }
        }

        if ($transmitterItem) {
            $satuanTerkecil = (float)($transmitterItem->satuan_terkecil ?? 0);
            $qty = $jumlah * 2;
            $transmitterItem->qty = $qty;
            $totalWindowHardwareTransmitterQty += $qty;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE FRICTION STAY ===
$ukuranFrictionStay = $panjang / 3;

$frictionStayMapping = [
    25 => 175,
    30 => 174,
    35 => 179,
    40 => 173,
    45 => 176,
    50 => 177,
    60 => 178,
];

$ukuranFrictionStayFinal = $ukuranFrictionStay;
if (!isset($frictionStayMapping[$ukuranFrictionStay])) {
    $availableSizes = array_keys($frictionStayMapping);
    sort($availableSizes);
    
    $found = false;
    for ($i = 0; $i < count($availableSizes); $i++) {
        if ($availableSizes[$i] >= $ukuranFrictionStay) {
            $ukuranFrictionStayFinal = $availableSizes[$i];
            $found = true;
            break;
        }
    }
    
    if (!$found) {
        $ukuranFrictionStayFinal = max($availableSizes);
    }
}

$frictionStayItem = null;
$frictionStayId = $frictionStayMapping[$ukuranFrictionStayFinal] ?? null;

if ($frictionStayId) {
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->id == $frictionStayId) {
            $frictionStayItem = $item;
            break;
        }
    }
}

$totalWindowHardwareFrictionStayQty = 0;
if ($frictionStayItem) {
    $satuanTerkecil = (float)($frictionStayItem->satuan_terkecil ?? 0);
    // QTY = qty handle x 2
    $qty = $totalWindowHardwareHandleQty * 2;
    $frictionStayItem->qty = $qty;
    $totalWindowHardwareFrictionStayQty += $qty;
}

    // === PERHITUNGAN SCREW TRANSMITTER ===
    $screwTransmitterItem = null;
    $screwTransmitterQty = 0;

    // HANYA JIKA MULTILOCK DAN ADA TRANSMITTER
    if ($isMultilock && $transmitterItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-transmitter') {
                $screwTransmitterItem = $item;
                break;
            }
        }

        $satuanTerkecilScrewTransmitter = $screwTransmitterItem ? (float)$screwTransmitterItem->satuan_terkecil : 0;
        $screwTransmitterQty = ($totalWindowHardwareTransmitterQty * $satuanTerkecilScrewTransmitter);
        if ($screwTransmitterItem) {
            $screwTransmitterItem->qty = $screwTransmitterQty;
        }
    }

    // === PERHITUNGAN SCREW FRICTION STAY ===
    $screwFrictionStayItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-friction-stay') {
            $screwFrictionStayItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewFrictionStay = $screwFrictionStayItem ? (float)$screwFrictionStayItem->satuan_terkecil : 0;
    $screwFrictionStayQty = $totalWindowHardwareFrictionStayQty * $satuanTerkecilScrewFrictionStay;
    if ($screwFrictionStayItem) {
        $screwFrictionStayItem->qty = $screwFrictionStayQty;
    }

    // === PERHITUNGAN SCREW HANDLE ===
    $screwHandleItem = null;
    if ($handleItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-handle') {
                $screwHandleItem = $item;
                break;
            }
        }
    }

    $satuanTerkecilScrewHandle = $screwHandleItem ? (float)$screwHandleItem->satuan_terkecil : 0;
    $screwHandleQty = $totalWindowHardwareHandleQty * $satuanTerkecilScrewHandle;
    if ($screwHandleItem) {
        $screwHandleItem->qty = $screwHandleQty;
    }

    // === PERHITUNGAN SETTING BLOCK ===
    $settingBlockItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'setting-block') {
            $settingBlockItem = $item;
            break;
        }
    }
    
    $satuanTerkecilSettingBlock = $settingBlockItem ? (float)$settingBlockItem->satuan_terkecil : 0;
    
    $variableC = 2 * $satuanTerkecilSettingBlock;
    $variableD = $variableC * $jumlah;
    $variableE = $variableD * 25;
    $variableF = $variableE / 1000;
    $settingBlockQty = ceil($variableF);

    // === PERHITUNGAN SCREW REINFORCEMENT ===
    $screwItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-reinforcement') {
            $screwItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrew = $screwItem ? (float)$screwItem->satuan_terkecil : 0;
    $screwQty = ((($totalLebar + $totalPanjang)) + ($variableSashVertikalB + $variableSashHorizontalB)) / $satuanTerkecilScrew;
    $screwQty = ceil($screwQty * 10);

    // === PERHITUNGAN QTY PER AKSESORIS ===
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        $areaSlug = $item->area ? $item->area->slug : '';
        $qty = 0;
        
        if ($areaSlug == 'profile-vertikal') {
            $qty = $batangVertikal;
        } elseif ($areaSlug == 'profile-horizontal') {
            $qty = $batangHorizontal;
        } elseif ($areaSlug == 'glaze-bead-vertical') {
            $qty = ($panjang / 100) * $jumlah;
        } elseif ($areaSlug == 'glaze-bead-horizontal') {
            $qty = ($lebar / 100) * $jumlah;
        } elseif ($areaSlug == 'reinforcement') {
            $qty = $reinforcementQty;
        } elseif ($areaSlug == 'reinforcement-sash') {
            $qty = $reinforcementSashQty;
        } elseif ($areaSlug == 'kaca') {
            $qty = $luasKacaTotal;
        } elseif ($areaSlug == 'screw-reinforcement') {
            $qty = $screwQty;
        } elseif ($areaSlug == 'setting-block') {
            $qty = $settingBlockQty;
        } elseif ($areaSlug == 'profile-sash-vertikal') {
            $qty = $batangSashVertikalQty;
        } elseif ($areaSlug == 'profile-sash-horizontal') {
            $qty = $batangSashHorizontalQty;
        } elseif ($areaSlug == 'profile-coupling-vertikal') {
            $qty = $batangCouplingVertikalQty;
        } elseif ($areaSlug == 'window-hardware-transmitter') {
            $qty = ($transmitterItem && $transmitterItem->id == $item->id) ? $transmitterItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-friction-stay') {
            $qty = ($frictionStayItem && $frictionStayItem->id == $item->id) ? $frictionStayItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-handle-rambuncis' || $areaSlug == 'window-hardware-handle-multilock') {
            $qty = $item->qty;
        } elseif ($areaSlug == 'screw-transmitter') {
            $qty = $screwTransmitterQty;
        } elseif ($areaSlug == 'screw-friction-stay') {
            $qty = $screwFrictionStayQty;
        } elseif ($areaSlug == 'screw-handle') {
            $qty = $screwHandleQty;
        } else {
            $qty = $jumlah * ($item->satuan_terkecil ?? 1);
        }
        
        $item->qty = $qty;
    }

    // Data untuk view
    $data = [
        'produk' => $produkUtama,
        'panjang' => $panjang,
        'lebar' => $lebar,
        'tebal_kaca' => $tebalKaca,
        'jumlah' => $jumlah,
        'warna' => $warna,
        'type_kaca' => $typeKaca,
        'handle_id' => $handleId,
        'is_multilock' => $isMultilock,
        
        'luas_kaca_per_unit' => $luasKacaPerUnit,
        'luas_kaca_total' => $luasKacaTotal,
        'keliling_per_unit' => $kelilingPerUnit,
        'keliling_total' => $kelilingTotal,
        
        'profile_vertikal' => $profileVertikal,
        'variable_a' => $variableA,
        'frame_vertikal' => $frameVertikal,
        'batang_vertikal' => $batangVertikal,
        
        'profile_horizontal' => $profileHorizontal,
        'satuan_terkecil_horizontal' => $satuanTerkecilHorizontal,
        'variable_b' => $variableB,
        'frame_horizontal' => $frameHorizontal,
        'batang_horizontal' => $batangHorizontal,
        
        'total_batang' => $totalBatang,
        'reinforcement_qty' => $reinforcementQty,
        
        'profile_sash_vertikal' => $profileSashVertikal,
        'satuan_terkecil_sash_vertikal' => $satuanTerkecilSashVertikal,
        'variable_sash_vertikal_a' => $variableSashVertikalA,
        'variable_sash_vertikal_b' => $variableSashVertikalB,
        'batang_sash_vertikal' => $batangSashVertikal,
        'batang_sash_vertikal_qty' => $batangSashVertikalQty,
        
        'profile_sash_horizontal' => $profileSashHorizontal,
        'satuan_terkecil_sash_horizontal' => $satuanTerkecilSashHorizontal,
        'variable_sash_horizontal_a' => $variableSashHorizontalA,
        'variable_sash_horizontal_b' => $variableSashHorizontalB,
        'batang_sash_horizontal' => $batangSashHorizontal,
        'batang_sash_horizontal_qty' => $batangSashHorizontalQty,
        
        'profile_coupling_vertikal' => $profileCouplingVertikal,
        'satuan_terkecil_coupling_vertikal' => $satuanTerkecilCouplingVertikal,
        'variable_coupling_vertikal_a' => $variableCouplingVertikalA,
        'variable_coupling_vertikal_b' => $variableCouplingVertikalB,
        'batang_coupling_vertikal' => $batangCouplingVertikal,
        'batang_coupling_vertikal_qty' => $batangCouplingVertikalQty,
        
        'reinforcement_sash_qty' => $reinforcementSashQty,
        
        'transmitter_item' => $transmitterItem,
        'ukuran_transmitter' => $ukuranTransmitter,
        'ukuran_transmitter_final' => $ukuranTransmitterFinal,
        'total_window_hardware_transmitter_qty' => $totalWindowHardwareTransmitterQty,
        
        'friction_stay_item' => $frictionStayItem,
        'ukuran_friction_stay' => $ukuranFrictionStay,
        'ukuran_friction_stay_final' => $ukuranFrictionStayFinal,
        'total_window_hardware_friction_stay_qty' => $totalWindowHardwareFrictionStayQty,
        
        'handle_item' => $handleItem,
        'total_window_hardware_handle_qty' => $totalWindowHardwareHandleQty,
        
        'screw_transmitter_item' => $screwTransmitterItem,
        'screw_transmitter_qty' => $screwTransmitterQty,
        
        'screw_friction_stay_item' => $screwFrictionStayItem,
        'screw_friction_stay_qty' => $screwFrictionStayQty,
        
        'screw_handle_item' => $screwHandleItem,
        'screw_handle_qty' => $screwHandleQty,
        
        'satuan_terkecil_screw' => $satuanTerkecilScrew,
        'screw_qty' => $screwQty,
        
        'setting_block_item' => $settingBlockItem,
        'satuan_terkecil_setting_block' => $satuanTerkecilSettingBlock,
        'variable_c' => $variableC,
        'variable_d' => $variableD,
        'variable_e' => $variableE,
        'variable_f' => $variableF,
        'setting_block_qty' => $settingBlockQty,
        
        'aksesoris' => $aksesoris,
    ];

    return view('boq.jendela.jendela-jungkit-2-bouven', $data);
}

public function exportPdfJungkit2bouven(Request $request)
{
    $panjang = $request->panjang;
    $lebar = $request->lebar;
    $tebal_kaca = $request->tebal_kaca;
    $jumlah = $request->jumlah;
    $warna = $request->warna;
    $type_kaca = $request->type_kaca;
    $handle_id = $request->handle_id;
    $judul = $request->judul ?? 'BOQ - Jendela Jungkit 2 Bouven';

    // Ambil data aksesoris
    $aksesorisIds = ProductAccessories::where('parent_product_id', 187)->pluck('accessory_id');
    $aksesoris = Product::with('area', 'unit')
        ->whereIn('id', $aksesorisIds)
        ->get();

    // === PERHITUNGAN DASAR ===
    $panjangM = $panjang / 100;
    $lebarM = $lebar / 100;
    
    $luasKacaPerUnit = $panjangM * $lebarM;
    $luasKacaTotal = $luasKacaPerUnit * $jumlah;
    $luasKacaTotal = ceil($luasKacaTotal * 10) / 10;

    $kelilingPerUnit = 2 * ($panjangM + $lebarM);
    $kelilingTotal = $kelilingPerUnit * $jumlah;

    // === PERHITUNGAN PROFILE VERTIKAL ===
    $profileVertikal = null;
    $aksesorisCount = count($aksesoris);
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-vertikal') {
            $profileVertikal = $item;
            break;
        }
    }
    $satuanTerkecilVertikal = $profileVertikal ? (float)$profileVertikal->satuan_terkecil : 0;

    $variableA = $jumlah * 4;
    $frameVertikal = $variableA * $panjang;
    $batangVertikal = $frameVertikal / 580;
    $batangVertikal = ceil($batangVertikal * 10) / 10;
    $totalPanjang = $panjang * $variableA;

    // === PERHITUNGAN PROFILE HORIZONTAL ===
    $profileHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-horizontal') {
            $profileHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilHorizontal = $profileHorizontal ? (float)$profileHorizontal->satuan_terkecil : 0;
    
    $variableB = $jumlah * $satuanTerkecilHorizontal;
    $frameHorizontal = $variableB * $lebar;
    $batangHorizontal = $frameHorizontal / 580;
    $batangHorizontal = ceil($batangHorizontal * 10) / 10;
    $totalLebar = $lebar * $variableB;

    // === PERHITUNGAN REINFORCEMENT ===
    $totalBatang = ($frameVertikal + $frameHorizontal) / 600;
    $reinforcementQty = ceil($totalBatang * 10) / 10;

    // === PERHITUNGAN PROFILE SASH VERTIKAL ===
    $profileSashVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-vertikal') {
            $profileSashVertikal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashVertikal = $profileSashVertikal ? (float)$profileSashVertikal->satuan_terkecil : 0;
    
    $variableSashVertikalA = 4 * $jumlah;
    $variableSashVertikalB = $variableSashVertikalA * $panjang;
    $batangSashVertikal = $variableSashVertikalB / 580;
    $batangSashVertikalQty = ceil($batangSashVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE SASH HORIZONTAL ===
    $profileSashHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-horizontal') {
            $profileSashHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashHorizontal = $profileSashHorizontal ? (float)$profileSashHorizontal->satuan_terkecil : 0;
    
    $variableSashHorizontalA = $satuanTerkecilSashHorizontal * $jumlah;
    $variableSashHorizontalB = $variableSashHorizontalA * $lebar;
    $batangSashHorizontal = $variableSashHorizontalB / 580;
    $batangSashHorizontalQty = ceil($batangSashHorizontal * 10) / 10;

    // === PERHITUNGAN PROFILE COUPLING VERTIKAL ===
    $profileCouplingVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-coupling-vertikal') {
            $profileCouplingVertikal = $item;
            break;
        }
    }

    $satuanTerkecilCouplingVertikal = $profileCouplingVertikal ? (float)$profileCouplingVertikal->satuan_terkecil : 0;

    $variableCouplingVertikalA = $satuanTerkecilCouplingVertikal * $jumlah * 2;
    $variableCouplingVertikalB = $variableCouplingVertikalA * $panjang;
    $batangCouplingVertikal = $variableCouplingVertikalB / 580;
    $batangCouplingVertikalQty = ceil($batangCouplingVertikal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT SASH ===
    $totalBatangSash = ($variableSashVertikalB + $variableSashHorizontalB) / 600;
    $reinforcementSashQty = ceil($totalBatangSash * 10) / 10;

    // === PERHITUNGAN WINDOW HARDWARE HANDLE ===
    $handleItem = null;
    $totalWindowHardwareHandleQty = 0;

    // RESET QTY UNTUK SEMUA HANDLE = 0
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && ($item->area->slug == 'window-hardware-handle-rambuncis' || $item->area->slug == 'window-hardware-handle-multilock')) {
            $item->qty = 0;
        }
    }

    // SET QTY UNTUK HANDLE YANG DIPILIH
    if ($handle_id) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $handle_id) {
                $handleItem = $item;
                break;
            }
        }
    }

    if ($handleItem) {
        $satuanTerkecil = (float)($handleItem->satuan_terkecil ?? 0);
        $qty = $jumlah * 2;
        $handleItem->qty = $qty;
        $totalWindowHardwareHandleQty += $qty;
    }

    // CEK APAKAH HANDLE YANG DIPILIH ADALAH MULTILOCK
    $isMultilock = false;
    if ($handleItem) {
        $namaLower = strtolower($handleItem->nama_produk);
        if (str_contains($namaLower, 'multilock')) {
            $isMultilock = true;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE TRANSMITTER ===
    $transmitterItem = null;
    $totalWindowHardwareTransmitterQty = 0;
    $ukuranTransmitter = 0;
    $ukuranTransmitterFinal = 0;

    if ($isMultilock) {
        $ukuranTransmitter = $panjang - 20;

        $transmitterMapping = [
            40 => 172,
            60 => 171,
            80 => 170,
            100 => 173,
            120 => 162,
            140 => 166,
            160 => 167,
            180 => 168,
            200 => 169,
        ];

        $ukuranTransmitterFinal = $ukuranTransmitter;
        if (!isset($transmitterMapping[$ukuranTransmitter])) {
            $availableSizes = array_keys($transmitterMapping);
            sort($availableSizes);
            
            $found = false;
            for ($i = 0; $i < count($availableSizes); $i++) {
                if ($availableSizes[$i] >= $ukuranTransmitter) {
                    $ukuranTransmitterFinal = $availableSizes[$i];
                    $found = true;
                    break;
                }
            }
            
            if (!$found) {
                $ukuranTransmitterFinal = max($availableSizes);
            }
        }

        $transmitterId = $transmitterMapping[$ukuranTransmitterFinal] ?? null;

        if ($transmitterId) {
            for ($i = 0; $i < $aksesorisCount; $i++) {
                $item = $aksesoris[$i];
                if ($item->id == $transmitterId) {
                    $transmitterItem = $item;
                    break;
                }
            }
        }

        if ($transmitterItem) {
            $satuanTerkecil = (float)($transmitterItem->satuan_terkecil ?? 0);
            $qty = $jumlah * 2;
            $transmitterItem->qty = $qty;
            $totalWindowHardwareTransmitterQty += $qty;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE FRICTION STAY ===
    $ukuranFrictionStay = $panjang / 3;

    $frictionStayMapping = [
        25 => 175,
        30 => 174,
        35 => 179,
        40 => 173,
        45 => 176,
        50 => 177,
        60 => 178,
    ];

    $ukuranFrictionStayFinal = $ukuranFrictionStay;
    if (!isset($frictionStayMapping[$ukuranFrictionStay])) {
        $availableSizes = array_keys($frictionStayMapping);
        sort($availableSizes);
        
        $found = false;
        for ($i = 0; $i < count($availableSizes); $i++) {
            if ($availableSizes[$i] >= $ukuranFrictionStay) {
                $ukuranFrictionStayFinal = $availableSizes[$i];
                $found = true;
                break;
            }
        }
        
        if (!$found) {
            $ukuranFrictionStayFinal = max($availableSizes);
        }
    }

    $frictionStayItem = null;
    $frictionStayId = $frictionStayMapping[$ukuranFrictionStayFinal] ?? null;

    if ($frictionStayId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $frictionStayId) {
                $frictionStayItem = $item;
                break;
            }
        }
    }

    $totalWindowHardwareFrictionStayQty = 0;
    if ($frictionStayItem) {
        $satuanTerkecil = (float)($frictionStayItem->satuan_terkecil ?? 0);
        // QTY = qty handle x 2
        $qty = $totalWindowHardwareHandleQty * 2;
        $frictionStayItem->qty = $qty;
        $totalWindowHardwareFrictionStayQty += $qty;
    }

    // === PERHITUNGAN SCREW TRANSMITTER ===
    $screwTransmitterItem = null;
    $screwTransmitterQty = 0;

    if ($isMultilock && $transmitterItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-transmitter') {
                $screwTransmitterItem = $item;
                break;
            }
        }

        $satuanTerkecilScrewTransmitter = $screwTransmitterItem ? (float)$screwTransmitterItem->satuan_terkecil : 0;
        $screwTransmitterQty = ($totalWindowHardwareTransmitterQty * $satuanTerkecilScrewTransmitter);
        if ($screwTransmitterItem) {
            $screwTransmitterItem->qty = $screwTransmitterQty;
        }
    }

    // === PERHITUNGAN SCREW FRICTION STAY ===
    $screwFrictionStayItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-friction-stay') {
            $screwFrictionStayItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewFrictionStay = $screwFrictionStayItem ? (float)$screwFrictionStayItem->satuan_terkecil : 0;
    $screwFrictionStayQty = $totalWindowHardwareFrictionStayQty * $satuanTerkecilScrewFrictionStay;
    if ($screwFrictionStayItem) {
        $screwFrictionStayItem->qty = $screwFrictionStayQty;
    }

    // === PERHITUNGAN SCREW HANDLE ===
    $screwHandleItem = null;
    if ($handleItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-handle') {
                $screwHandleItem = $item;
                break;
            }
        }
    }

    $satuanTerkecilScrewHandle = $screwHandleItem ? (float)$screwHandleItem->satuan_terkecil : 0;
    $screwHandleQty = $totalWindowHardwareHandleQty * $satuanTerkecilScrewHandle;
    if ($screwHandleItem) {
        $screwHandleItem->qty = $screwHandleQty;
    }

    // === PERHITUNGAN SETTING BLOCK ===
    $settingBlockItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'setting-block') {
            $settingBlockItem = $item;
            break;
        }
    }
    
    $satuanTerkecilSettingBlock = $settingBlockItem ? (float)$settingBlockItem->satuan_terkecil : 0;
    
    $variableC = 2 * $satuanTerkecilSettingBlock;
    $variableD = $variableC * $jumlah;
    $variableE = $variableD * 25;
    $variableF = $variableE / 1000;
    $settingBlockQty = ceil($variableF);

    // === PERHITUNGAN SCREW REINFORCEMENT ===
    $screwItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-reinforcement') {
            $screwItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrew = $screwItem ? (float)$screwItem->satuan_terkecil : 0;
    $screwQty = ((($totalLebar + $totalPanjang)) + ($variableSashVertikalB + $variableSashHorizontalB)) / $satuanTerkecilScrew;
    $screwQty = ceil($screwQty * 10);

    // === HITUNG QTY PER AKSESORIS ===
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        $areaSlug = $item->area ? $item->area->slug : '';
        $qty = 0;
        
        if ($areaSlug == 'profile-vertikal') {
            $qty = $batangVertikal;
        } elseif ($areaSlug == 'profile-horizontal') {
            $qty = $batangHorizontal;
        } elseif ($areaSlug == 'glaze-bead-vertical') {
            $qty = ($panjang / 100) * $jumlah;
        } elseif ($areaSlug == 'glaze-bead-horizontal') {
            $qty = ($lebar / 100) * $jumlah;
        } elseif ($areaSlug == 'reinforcement') {
            $qty = $reinforcementQty;
        } elseif ($areaSlug == 'reinforcement-sash') {
            $qty = $reinforcementSashQty;
        } elseif ($areaSlug == 'kaca') {
            $qty = $luasKacaTotal;
        } elseif ($areaSlug == 'screw-reinforcement') {
            $qty = $screwQty;
        } elseif ($areaSlug == 'setting-block') {
            $qty = $settingBlockQty;
        } elseif ($areaSlug == 'profile-sash-vertikal') {
            $qty = $batangSashVertikalQty;
        } elseif ($areaSlug == 'profile-sash-horizontal') {
            $qty = $batangSashHorizontalQty;
        } elseif ($areaSlug == 'profile-coupling-vertikal') {
            $qty = $batangCouplingVertikalQty;
        } elseif ($areaSlug == 'window-hardware-transmitter') {
            $qty = ($transmitterItem && $transmitterItem->id == $item->id) ? $transmitterItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-friction-stay') {
            $qty = ($frictionStayItem && $frictionStayItem->id == $item->id) ? $frictionStayItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-handle-rambuncis' || $areaSlug == 'window-hardware-handle-multilock') {
            $qty = $item->qty;
        } elseif ($areaSlug == 'screw-transmitter') {
            $qty = $screwTransmitterQty;
        } elseif ($areaSlug == 'screw-friction-stay') {
            $qty = $screwFrictionStayQty;
        } elseif ($areaSlug == 'screw-handle') {
            $qty = $screwHandleQty;
        } else {
            $qty = $jumlah * ($item->satuan_terkecil ?? 1);
        }
        
        $item->qty = $qty;
    }

    // Kelompokkan berdasarkan area
    $grouped = [];
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->qty <= 0) {
            continue;
        }
        
        // Skip transmitter, friction stay, dan handle yang tidak terpilih (qty 0)
        if ($item->area && ($item->area->slug == 'window-hardware-transmitter' || $item->area->slug == 'window-hardware-friction-stay') && $item->qty <= 0) {
            continue;
        }
        if ($item->area && ($item->area->slug == 'window-hardware-handle-rambuncis' || $item->area->slug == 'window-hardware-handle-multilock') && $item->qty <= 0) {
            continue;
        }
        
        $areaSlug = $item->area ? $item->area->slug : 'lainnya';
        
        if (str_starts_with($areaSlug, 'profile')) {
            $groupKey = 'profile';
        } elseif ($areaSlug == 'setting-block') {
            $groupKey = 'kaca';
        } elseif ($areaSlug == 'reinforcement' || $areaSlug == 'reinforcement-sash') {
            $groupKey = 'reinforcement';
        } elseif (str_starts_with($areaSlug, 'window-hardware')) {
            $groupKey = 'window-hardware';
        } elseif ($areaSlug == 'screw-reinforcement' || $areaSlug == 'screw-transmitter' || $areaSlug == 'screw-friction-stay' || $areaSlug == 'screw-handle') {
            $groupKey = 'screw';
        } else {
            $groupKey = $areaSlug;
        }
        
        if (!isset($grouped[$groupKey])) {
            $grouped[$groupKey] = [];
        }
        $grouped[$groupKey][] = $item;
    }

    $areaLabels = [
        'profile' => 'PROFILE',
        'reinforcement' => 'REINFORCEMENT',
        'kaca' => 'KACA',
        'screw' => 'SCREW',
        'window-hardware' => 'WINDOW HARDWARE',
    ];

    // ============ GENERATE NOMOR BOQ ============
    $nomorBoq = Boq::generateNomorBoq();

    // ============ STORE BOQ ============
    try {
        $allResults = [];
        
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->qty > 0) {
                $allResults[] = [
                    'produk_id' => $item->id,
                    'qty' => $item->qty,
                    'nama_produk' => $item->nama_produk,
                ];
            }
        }
        
        $uniqueResults = [];
        $seenIds = [];
        $allResultsCount = count($allResults);
        
        for ($i = 0; $i < $allResultsCount; $i++) {
            $item = $allResults[$i];
            $produkId = $item['produk_id'] ?? null;
            
            if (!$produkId) {
                continue;
            }
            
            $isDuplicate = false;
            $seenCount = count($seenIds);
            for ($j = 0; $j < $seenCount; $j++) {
                if ($seenIds[$j] == $produkId) {
                    $isDuplicate = true;
                    break;
                }
            }
            
            if ($isDuplicate) {
                continue;
            }
            
            $seenIds[] = $produkId;
            $uniqueResults[] = $item;
        }
        
        if (count($uniqueResults) > 0) {
            $boq = new Boq();
            $boq->nomor_boq = $nomorBoq;
            $boq->tanggal_boq = now();
            $boq->save();
            
            $uniqueCount = count($uniqueResults);
            for ($i = 0; $i < $uniqueCount; $i++) {
                $item = $uniqueResults[$i];
                $produkId = $item['produk_id'] ?? null;
                $qty = (int)($item['qty'] ?? 0);
                
                if ($produkId && $qty > 0) {
                    $produk = Product::find($produkId);
                    
                    \DB::table('detail_boq')->insert([
                        'boq_id' => $boq->id,
                        'produk_id' => $produkId,
                        'kode_produk' => $produk ? $produk->kode_produk : null,
                        'qty' => $qty,
                        'created_at' => now(),
                        'updated_at' => now()
                    ]);
                }
            }
            
            \Log::info('BOQ SAVED JENDELA JUNGKIT 2 BOUVEN:', [
                'boq_id' => $boq->id,
                'nomor_boq' => $nomorBoq,
                'total' => count($uniqueResults)
            ]);
        }
        
    } catch (\Exception $e) {
        \Log::error('Error saving BOQ Jendela Jungkit 2 Bouven: ' . $e->getMessage());
        \Log::error($e->getTraceAsString());
    }

    $data = [
        'judul' => $judul,
        'panjang' => $panjang,
        'lebar' => $lebar,
        'tebal_kaca' => $tebal_kaca,
        'jumlah' => $jumlah,
        'warna' => $warna,
        'type_kaca' => $type_kaca,
        'handle_id' => $handle_id,
        'is_multilock' => $isMultilock,
        'luas_kaca_total' => $luasKacaTotal,
        'keliling_total' => $kelilingTotal,
        'batang_vertikal' => $batangVertikal,
        'batang_horizontal' => $batangHorizontal,
        'reinforcement_qty' => $reinforcementQty,
        'reinforcement_sash_qty' => $reinforcementSashQty,
        'batang_sash_vertikal_qty' => $batangSashVertikalQty,
        'batang_sash_horizontal_qty' => $batangSashHorizontalQty,
        'batang_coupling_vertikal_qty' => $batangCouplingVertikalQty,
        'handle_item' => $handleItem,
        'total_window_hardware_handle_qty' => $totalWindowHardwareHandleQty,
        'transmitter_item' => $transmitterItem,
        'ukuran_transmitter' => $ukuranTransmitter,
        'ukuran_transmitter_final' => $ukuranTransmitterFinal,
        'total_window_hardware_transmitter_qty' => $totalWindowHardwareTransmitterQty,
        'friction_stay_item' => $frictionStayItem,
        'ukuran_friction_stay' => $ukuranFrictionStay,
        'ukuran_friction_stay_final' => $ukuranFrictionStayFinal,
        'total_window_hardware_friction_stay_qty' => $totalWindowHardwareFrictionStayQty,
        'screw_transmitter_qty' => $screwTransmitterQty,
        'screw_friction_stay_qty' => $screwFrictionStayQty,
        'screw_handle_qty' => $screwHandleQty,
        'screw_qty' => $screwQty,
        'setting_block_qty' => $settingBlockQty,
        'grouped' => $grouped,
        'areaLabels' => $areaLabels,
        'nomor_boq' => $nomorBoq,
    ];

    return view('boq.jendela.pdf-jendela-jungkit-2-bouven', compact('data'));
}

public function hitungJungkit12bouven(Request $request)
{
    $request->validate([
        'panjang' => 'required|numeric|min:1',
        'lebar' => 'required|numeric|min:1',
        'tebal_kaca' => 'required|numeric|min:1',
        'jumlah' => 'required|numeric|min:1',
        'warna' => 'required|string',
        'type_kaca' => 'required|string',
    ]);

    // Ambil data dari form
    $panjang = $request->panjang; // cm
    $lebar = $request->lebar; // cm
    $tebalKaca = $request->tebal_kaca; // mm
    $jumlah = $request->jumlah;
    $warna = $request->warna;
    $typeKaca = $request->type_kaca;
    $handleId = $request->handle_id;

    // Ambil produk utama (Jendela Jungkit 12 Bouven) dari database
    $produkUtama = Product::find(189);
    
    if (!$produkUtama) {
        return back()->with('error', 'Produk Jendela Jungkit 12 Bouven tidak ditemukan!');
    }

    // Ambil aksesoris dari tabel product_accessories dengan relasi area
    $aksesorisIds = ProductAccessories::where('parent_product_id', 189)->pluck('accessory_id');
    $aksesoris = Product::with('area', 'unit')
        ->whereIn('id', $aksesorisIds)
        ->get();

    // === PERHITUNGAN DASAR ===
    
    // Konversi ke meter
    $panjangM = $panjang / 100;
    $lebarM = $lebar / 100;
    $tebalKacaM = $tebalKaca / 1000;

    // 1. Luas Kaca (m²)
    $luasKacaPerUnit = $panjangM * $lebarM;
    $luasKacaTotal = $luasKacaPerUnit * $jumlah;
    $luasKacaTotal = ceil($luasKacaTotal * 10) / 10;

    // 2. Keliling Profile (meter)
    $kelilingPerUnit = 2 * ($panjangM + $lebarM);
    $kelilingTotal = $kelilingPerUnit * $jumlah;

    // === PERHITUNGAN PROFILE VERTIKAL ===
    $profileVertikal = null;
    $aksesorisCount = count($aksesoris);
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-vertikal') {
            $profileVertikal = $item;
            break;
        }
    }
    $satuanTerkecilVertikal = $profileVertikal ? (float)$profileVertikal->satuan_terkecil : 0;

    $variableA = $jumlah * 8;
    $frameVertikal = $variableA * $panjang;
    $batangVertikal = $frameVertikal / 580;
    $batangVertikal = ceil($batangVertikal * 10) / 10;
    $totalPanjang = $panjang * $variableA;

    // === PERHITUNGAN PROFILE HORIZONTAL ===
    $profileHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-horizontal') {
            $profileHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilHorizontal = $profileHorizontal ? (float)$profileHorizontal->satuan_terkecil : 0;
    
    $variableB = $jumlah * 6;
    $frameHorizontal = $variableB * $lebar;
    $batangHorizontal = $frameHorizontal / 580;
    $batangHorizontal = ceil($batangHorizontal * 10) / 10;
    $totalLebar = $lebar * $variableB;

    // === PERHITUNGAN REINFORCEMENT ===
    $totalBatang = ($frameVertikal + $frameHorizontal) / 600;
    $reinforcementQty = ceil($totalBatang * 10) / 10;

    // === PERHITUNGAN PROFILE SASH VERTIKAL ===
    $profileSashVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-vertikal') {
            $profileSashVertikal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashVertikal = $profileSashVertikal ? (float)$profileSashVertikal->satuan_terkecil : 0;
    
    $variableSashVertikalA = 8 * $jumlah;
    $variableSashVertikalB = $variableSashVertikalA * $panjang;
    $batangSashVertikal = $variableSashVertikalB / 580;
    $batangSashVertikalQty = ceil($batangSashVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE SASH HORIZONTAL ===
    $profileSashHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-horizontal') {
            $profileSashHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashHorizontal = $profileSashHorizontal ? (float)$profileSashHorizontal->satuan_terkecil : 0;
    
    $variableSashHorizontalA = 6 * $jumlah;
    $variableSashHorizontalB = $variableSashHorizontalA * $lebar;
    $batangSashHorizontal = $variableSashHorizontalB / 580;
    $batangSashHorizontalQty = ceil($batangSashHorizontal * 10) / 10;

    // === PERHITUNGAN PROFILE COUPLING VERTIKAL ===
    $profileCouplingVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-coupling-vertikal') {
            $profileCouplingVertikal = $item;
            break;
        }
    }

    $satuanTerkecilCouplingVertikal = $profileCouplingVertikal ? (float)$profileCouplingVertikal->satuan_terkecil : 0;

    $variableCouplingVertikalA = 3 * $jumlah * 2;
    $variableCouplingVertikalB = $variableCouplingVertikalA * $panjang;
    $batangCouplingVertikal = $variableCouplingVertikalB / 580;
    $batangCouplingVertikalQty = ceil($batangCouplingVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE COUPLING HORIZONTAL ===
    $profileCouplingHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-coupling-horizontal') {
            $profileCouplingHorizontal = $item;
            break;
        }
    }

    $satuanTerkecilCouplingHorizontal = $profileCouplingHorizontal ? (float)$profileCouplingHorizontal->satuan_terkecil : 0;

    $variableCouplingHorizontalA = 2 * $jumlah * 2;
    $variableCouplingHorizontalB = $variableCouplingHorizontalA * $lebar;
    $batangCouplingHorizontal = $variableCouplingHorizontalB / 580;
    $batangCouplingHorizontalQty = ceil($batangCouplingHorizontal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT SASH ===
    $totalBatangSash = ($variableSashVertikalB + $variableSashHorizontalB) / 600;
    $reinforcementSashQty = ceil($totalBatangSash * 10) / 10;

    // === PERHITUNGAN WINDOW HARDWARE HANDLE (dari dropdown) ===
    $handleItem = null;
    $totalWindowHardwareHandleQty = 0;

    // RESET QTY UNTUK SEMUA HANDLE = 0
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && ($item->area->slug == 'window-hardware-handle-rambuncis' || $item->area->slug == 'window-hardware-handle-multilock')) {
            $item->qty = 0;
        }
    }

    // SET QTY UNTUK HANDLE YANG DIPILIH
    if ($handleId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $handleId) {
                $handleItem = $item;
                break;
            }
        }
    }

    if ($handleItem) {
        $satuanTerkecil = (float)($handleItem->satuan_terkecil ?? 0);
        $qty = $jumlah * 12;
        $handleItem->qty = $qty;
        $totalWindowHardwareHandleQty += $qty;
    }

    // CEK APAKAH HANDLE YANG DIPILIH ADALAH MULTILOCK
    $isMultilock = false;
    if ($handleItem) {
        $namaLower = strtolower($handleItem->nama_produk);
        if (str_contains($namaLower, 'multilock')) {
            $isMultilock = true;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE TRANSMITTER ===
    $transmitterItem = null;
    $totalWindowHardwareTransmitterQty = 0;
    $ukuranTransmitter = 0;
    $ukuranTransmitterFinal = 0;

    // HANYA HITUNG TRANSMITTER JIKA HANDLE MULTILOCK
    if ($isMultilock) {
        $ukuranTransmitter = $panjang - 20;

        $transmitterMapping = [
            40 => 172,
            60 => 171,
            80 => 170,
            100 => 173,
            120 => 162,
            140 => 166,
            160 => 167,
            180 => 168,
            200 => 169,
        ];

        $ukuranTransmitterFinal = $ukuranTransmitter;
        if (!isset($transmitterMapping[$ukuranTransmitter])) {
            $availableSizes = array_keys($transmitterMapping);
            sort($availableSizes);
            
            $found = false;
            for ($i = 0; $i < count($availableSizes); $i++) {
                if ($availableSizes[$i] >= $ukuranTransmitter) {
                    $ukuranTransmitterFinal = $availableSizes[$i];
                    $found = true;
                    break;
                }
            }
            
            if (!$found) {
                $ukuranTransmitterFinal = max($availableSizes);
            }
        }

        $transmitterId = $transmitterMapping[$ukuranTransmitterFinal] ?? null;

        if ($transmitterId) {
            for ($i = 0; $i < $aksesorisCount; $i++) {
                $item = $aksesoris[$i];
                if ($item->id == $transmitterId) {
                    $transmitterItem = $item;
                    break;
                }
            }
        }

        if ($transmitterItem) {
            $satuanTerkecil = (float)($transmitterItem->satuan_terkecil ?? 0);
            $qty = $jumlah * 12;
            $transmitterItem->qty = $qty;
            $totalWindowHardwareTransmitterQty += $qty;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE FRICTION STAY ===
    $ukuranFrictionStay = $panjang / 3;

    $frictionStayMapping = [
        25 => 175,
        30 => 174,
        35 => 179,
        40 => 173,
        45 => 176,
        50 => 177,
        60 => 178,
    ];

    $ukuranFrictionStayFinal = $ukuranFrictionStay;
    if (!isset($frictionStayMapping[$ukuranFrictionStay])) {
        $availableSizes = array_keys($frictionStayMapping);
        sort($availableSizes);
        
        $found = false;
        for ($i = 0; $i < count($availableSizes); $i++) {
            if ($availableSizes[$i] >= $ukuranFrictionStay) {
                $ukuranFrictionStayFinal = $availableSizes[$i];
                $found = true;
                break;
            }
        }
        
        if (!$found) {
            $ukuranFrictionStayFinal = max($availableSizes);
        }
    }

    $frictionStayItem = null;
    $frictionStayId = $frictionStayMapping[$ukuranFrictionStayFinal] ?? null;

    if ($frictionStayId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $frictionStayId) {
                $frictionStayItem = $item;
                break;
            }
        }
    }

    $totalWindowHardwareFrictionStayQty = 0;
    if ($frictionStayItem) {
        $satuanTerkecil = (float)($frictionStayItem->satuan_terkecil ?? 0);
        // QTY = qty handle x 2
        $qty = $totalWindowHardwareHandleQty * 2;
        $frictionStayItem->qty = $qty;
        $totalWindowHardwareFrictionStayQty += $qty;
    }

    // === PERHITUNGAN SCREW TRANSMITTER ===
    $screwTransmitterItem = null;
    $screwTransmitterQty = 0;

    // HANYA JIKA MULTILOCK DAN ADA TRANSMITTER
    if ($isMultilock && $transmitterItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-transmitter') {
                $screwTransmitterItem = $item;
                break;
            }
        }

        $satuanTerkecilScrewTransmitter = $screwTransmitterItem ? (float)$screwTransmitterItem->satuan_terkecil : 0;
        $screwTransmitterQty = ($totalWindowHardwareTransmitterQty * $satuanTerkecilScrewTransmitter);
        if ($screwTransmitterItem) {
            $screwTransmitterItem->qty = $screwTransmitterQty;
        }
    }

    // === PERHITUNGAN SCREW FRICTION STAY ===
    $screwFrictionStayItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-friction-stay') {
            $screwFrictionStayItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewFrictionStay = $screwFrictionStayItem ? (float)$screwFrictionStayItem->satuan_terkecil : 0;
    $screwFrictionStayQty = $totalWindowHardwareFrictionStayQty * $satuanTerkecilScrewFrictionStay;
    if ($screwFrictionStayItem) {
        $screwFrictionStayItem->qty = $screwFrictionStayQty;
    }

    // === PERHITUNGAN SCREW HANDLE ===
    $screwHandleItem = null;
    if ($handleItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-handle') {
                $screwHandleItem = $item;
                break;
            }
        }
    }

    $satuanTerkecilScrewHandle = $screwHandleItem ? (float)$screwHandleItem->satuan_terkecil : 0;
    $screwHandleQty = $totalWindowHardwareHandleQty * $satuanTerkecilScrewHandle;
    if ($screwHandleItem) {
        $screwHandleItem->qty = $screwHandleQty;
    }

    // === PERHITUNGAN SETTING BLOCK ===
    $settingBlockItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'setting-block') {
            $settingBlockItem = $item;
            break;
        }
    }
    
    $satuanTerkecilSettingBlock = $settingBlockItem ? (float)$settingBlockItem->satuan_terkecil : 0;
    
    $variableC = 12 * $satuanTerkecilSettingBlock;
    $variableD = $variableC * $jumlah;
    $variableE = $variableD * 25;
    $variableF = $variableE / 1000;
    $settingBlockQty = ceil($variableF);

    // === PERHITUNGAN SCREW REINFORCEMENT ===
    $screwItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-reinforcement') {
            $screwItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrew = $screwItem ? (float)$screwItem->satuan_terkecil : 0;
    $screwQty = ((($totalLebar + $totalPanjang)) + ($variableSashVertikalB + $variableSashHorizontalB)) / $satuanTerkecilScrew;
    $screwQty = ceil($screwQty * 10);

    // === PERHITUNGAN QTY PER AKSESORIS ===
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        $areaSlug = $item->area ? $item->area->slug : '';
        $qty = 0;
        
        if ($areaSlug == 'profile-vertikal') {
            $qty = $batangVertikal;
        } elseif ($areaSlug == 'profile-horizontal') {
            $qty = $batangHorizontal;
        } elseif ($areaSlug == 'glaze-bead-vertical') {
            $qty = ($panjang / 100) * $jumlah;
        } elseif ($areaSlug == 'glaze-bead-horizontal') {
            $qty = ($lebar / 100) * $jumlah;
        } elseif ($areaSlug == 'reinforcement') {
            $qty = $reinforcementQty;
        } elseif ($areaSlug == 'reinforcement-sash') {
            $qty = $reinforcementSashQty;
        } elseif ($areaSlug == 'kaca') {
            $qty = $luasKacaTotal;
        } elseif ($areaSlug == 'screw-reinforcement') {
            $qty = $screwQty;
        } elseif ($areaSlug == 'setting-block') {
            $qty = $settingBlockQty;
        } elseif ($areaSlug == 'profile-sash-vertikal') {
            $qty = $batangSashVertikalQty;
        } elseif ($areaSlug == 'profile-sash-horizontal') {
            $qty = $batangSashHorizontalQty;
        } elseif ($areaSlug == 'profile-coupling-vertikal') {
            $qty = $batangCouplingVertikalQty;
        } elseif ($areaSlug == 'profile-coupling-horizontal') {
            $qty = $batangCouplingHorizontalQty;
        } elseif ($areaSlug == 'window-hardware-transmitter') {
            $qty = ($transmitterItem && $transmitterItem->id == $item->id) ? $transmitterItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-friction-stay') {
            $qty = ($frictionStayItem && $frictionStayItem->id == $item->id) ? $frictionStayItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-handle-rambuncis' || $areaSlug == 'window-hardware-handle-multilock') {
            $qty = $item->qty;
        } elseif ($areaSlug == 'screw-transmitter') {
            $qty = $screwTransmitterQty;
        } elseif ($areaSlug == 'screw-friction-stay') {
            $qty = $screwFrictionStayQty;
        } elseif ($areaSlug == 'screw-handle') {
            $qty = $screwHandleQty;
        } else {
            $qty = $jumlah * ($item->satuan_terkecil ?? 1);
        }
        
        $item->qty = $qty;
    }

    // Data untuk view
    $data = [
        'produk' => $produkUtama,
        'panjang' => $panjang,
        'lebar' => $lebar,
        'tebal_kaca' => $tebalKaca,
        'jumlah' => $jumlah,
        'warna' => $warna,
        'type_kaca' => $typeKaca,
        'handle_id' => $handleId,
        'is_multilock' => $isMultilock,
        
        'luas_kaca_per_unit' => $luasKacaPerUnit,
        'luas_kaca_total' => $luasKacaTotal,
        'keliling_per_unit' => $kelilingPerUnit,
        'keliling_total' => $kelilingTotal,
        
        'profile_vertikal' => $profileVertikal,
        'variable_a' => $variableA,
        'frame_vertikal' => $frameVertikal,
        'batang_vertikal' => $batangVertikal,
        
        'profile_horizontal' => $profileHorizontal,
        'satuan_terkecil_horizontal' => $satuanTerkecilHorizontal,
        'variable_b' => $variableB,
        'frame_horizontal' => $frameHorizontal,
        'batang_horizontal' => $batangHorizontal,
        
        'total_batang' => $totalBatang,
        'reinforcement_qty' => $reinforcementQty,
        
        'profile_sash_vertikal' => $profileSashVertikal,
        'satuan_terkecil_sash_vertikal' => $satuanTerkecilSashVertikal,
        'variable_sash_vertikal_a' => $variableSashVertikalA,
        'variable_sash_vertikal_b' => $variableSashVertikalB,
        'batang_sash_vertikal' => $batangSashVertikal,
        'batang_sash_vertikal_qty' => $batangSashVertikalQty,
        
        'profile_sash_horizontal' => $profileSashHorizontal,
        'satuan_terkecil_sash_horizontal' => $satuanTerkecilSashHorizontal,
        'variable_sash_horizontal_a' => $variableSashHorizontalA,
        'variable_sash_horizontal_b' => $variableSashHorizontalB,
        'batang_sash_horizontal' => $batangSashHorizontal,
        'batang_sash_horizontal_qty' => $batangSashHorizontalQty,
        
        'profile_coupling_vertikal' => $profileCouplingVertikal,
        'satuan_terkecil_coupling_vertikal' => $satuanTerkecilCouplingVertikal,
        'variable_coupling_vertikal_a' => $variableCouplingVertikalA,
        'variable_coupling_vertikal_b' => $variableCouplingVertikalB,
        'batang_coupling_vertikal' => $batangCouplingVertikal,
        'batang_coupling_vertikal_qty' => $batangCouplingVertikalQty,
        
        'profile_coupling_horizontal' => $profileCouplingHorizontal,
        'satuan_terkecil_coupling_horizontal' => $satuanTerkecilCouplingHorizontal,
        'variable_coupling_horizontal_a' => $variableCouplingHorizontalA,
        'variable_coupling_horizontal_b' => $variableCouplingHorizontalB,
        'batang_coupling_horizontal' => $batangCouplingHorizontal,
        'batang_coupling_horizontal_qty' => $batangCouplingHorizontalQty,
        
        'reinforcement_sash_qty' => $reinforcementSashQty,
        
        'transmitter_item' => $transmitterItem,
        'ukuran_transmitter' => $ukuranTransmitter,
        'ukuran_transmitter_final' => $ukuranTransmitterFinal,
        'total_window_hardware_transmitter_qty' => $totalWindowHardwareTransmitterQty,
        
        'friction_stay_item' => $frictionStayItem,
        'ukuran_friction_stay' => $ukuranFrictionStay,
        'ukuran_friction_stay_final' => $ukuranFrictionStayFinal,
        'total_window_hardware_friction_stay_qty' => $totalWindowHardwareFrictionStayQty,
        
        'handle_item' => $handleItem,
        'total_window_hardware_handle_qty' => $totalWindowHardwareHandleQty,
        
        'screw_transmitter_item' => $screwTransmitterItem,
        'screw_transmitter_qty' => $screwTransmitterQty,
        
        'screw_friction_stay_item' => $screwFrictionStayItem,
        'screw_friction_stay_qty' => $screwFrictionStayQty,
        
        'screw_handle_item' => $screwHandleItem,
        'screw_handle_qty' => $screwHandleQty,
        
        'satuan_terkecil_screw' => $satuanTerkecilScrew,
        'screw_qty' => $screwQty,
        
        'setting_block_item' => $settingBlockItem,
        'satuan_terkecil_setting_block' => $satuanTerkecilSettingBlock,
        'variable_c' => $variableC,
        'variable_d' => $variableD,
        'variable_e' => $variableE,
        'variable_f' => $variableF,
        'setting_block_qty' => $settingBlockQty,
        
        'aksesoris' => $aksesoris,
    ];

    return view('boq.jendela.jendela-jungkit-12-bouven', $data);
}

public function exportPdfJungkit12bouven(Request $request)
{
    $panjang = $request->panjang;
    $lebar = $request->lebar;
    $tebal_kaca = $request->tebal_kaca;
    $jumlah = $request->jumlah;
    $warna = $request->warna;
    $type_kaca = $request->type_kaca;
    $handle_id = $request->handle_id;
    $judul = $request->judul ?? 'BOQ - Jendela Jungkit 12 Bouven';

    // Ambil data aksesoris
    $aksesorisIds = ProductAccessories::where('parent_product_id', 189)->pluck('accessory_id');
    $aksesoris = Product::with('area', 'unit')
        ->whereIn('id', $aksesorisIds)
        ->get();

    // === PERHITUNGAN DASAR ===
    $panjangM = $panjang / 100;
    $lebarM = $lebar / 100;
    
    $luasKacaPerUnit = $panjangM * $lebarM;
    $luasKacaTotal = $luasKacaPerUnit * $jumlah;
    $luasKacaTotal = ceil($luasKacaTotal * 10) / 10;

    $kelilingPerUnit = 2 * ($panjangM + $lebarM);
    $kelilingTotal = $kelilingPerUnit * $jumlah;

    // === PERHITUNGAN PROFILE VERTIKAL ===
    $profileVertikal = null;
    $aksesorisCount = count($aksesoris);
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-vertikal') {
            $profileVertikal = $item;
            break;
        }
    }
    $satuanTerkecilVertikal = $profileVertikal ? (float)$profileVertikal->satuan_terkecil : 0;

    $variableA = $jumlah * 8;
    $frameVertikal = $variableA * $panjang;
    $batangVertikal = $frameVertikal / 580;
    $batangVertikal = ceil($batangVertikal * 10) / 10;
    $totalPanjang = $panjang * $variableA;

    // === PERHITUNGAN PROFILE HORIZONTAL ===
    $profileHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-horizontal') {
            $profileHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilHorizontal = $profileHorizontal ? (float)$profileHorizontal->satuan_terkecil : 0;
    
    $variableB = $jumlah * 6;
    $frameHorizontal = $variableB * $lebar;
    $batangHorizontal = $frameHorizontal / 580;
    $batangHorizontal = ceil($batangHorizontal * 10) / 10;
    $totalLebar = $lebar * $variableB;

    // === PERHITUNGAN REINFORCEMENT ===
    $totalBatang = ($frameVertikal + $frameHorizontal) / 600;
    $reinforcementQty = ceil($totalBatang * 10) / 10;

    // === PERHITUNGAN PROFILE SASH VERTIKAL ===
    $profileSashVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-vertikal') {
            $profileSashVertikal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashVertikal = $profileSashVertikal ? (float)$profileSashVertikal->satuan_terkecil : 0;
    
    $variableSashVertikalA = 8 * $jumlah;
    $variableSashVertikalB = $variableSashVertikalA * $panjang;
    $batangSashVertikal = $variableSashVertikalB / 580;
    $batangSashVertikalQty = ceil($batangSashVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE SASH HORIZONTAL ===
    $profileSashHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-horizontal') {
            $profileSashHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashHorizontal = $profileSashHorizontal ? (float)$profileSashHorizontal->satuan_terkecil : 0;
    
    $variableSashHorizontalA = 6 * $jumlah;
    $variableSashHorizontalB = $variableSashHorizontalA * $lebar;
    $batangSashHorizontal = $variableSashHorizontalB / 580;
    $batangSashHorizontalQty = ceil($batangSashHorizontal * 10) / 10;

    // === PERHITUNGAN PROFILE COUPLING VERTIKAL ===
    $profileCouplingVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-coupling-vertikal') {
            $profileCouplingVertikal = $item;
            break;
        }
    }

    $satuanTerkecilCouplingVertikal = $profileCouplingVertikal ? (float)$profileCouplingVertikal->satuan_terkecil : 0;

    $variableCouplingVertikalA = 3 * $jumlah * 2;
    $variableCouplingVertikalB = $variableCouplingVertikalA * $panjang;
    $batangCouplingVertikal = $variableCouplingVertikalB / 580;
    $batangCouplingVertikalQty = ceil($batangCouplingVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE COUPLING HORIZONTAL ===
    $profileCouplingHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-coupling-horizontal') {
            $profileCouplingHorizontal = $item;
            break;
        }
    }

    $satuanTerkecilCouplingHorizontal = $profileCouplingHorizontal ? (float)$profileCouplingHorizontal->satuan_terkecil : 0;

    $variableCouplingHorizontalA = 2 * $jumlah * 2;
    $variableCouplingHorizontalB = $variableCouplingHorizontalA * $lebar;
    $batangCouplingHorizontal = $variableCouplingHorizontalB / 580;
    $batangCouplingHorizontalQty = ceil($batangCouplingHorizontal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT SASH ===
    $totalBatangSash = ($variableSashVertikalB + $variableSashHorizontalB) / 600;
    $reinforcementSashQty = ceil($totalBatangSash * 10) / 10;

    // === PERHITUNGAN WINDOW HARDWARE HANDLE ===
    $handleItem = null;
    $totalWindowHardwareHandleQty = 0;

    // RESET QTY UNTUK SEMUA HANDLE = 0
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && ($item->area->slug == 'window-hardware-handle-rambuncis' || $item->area->slug == 'window-hardware-handle-multilock')) {
            $item->qty = 0;
        }
    }

    // SET QTY UNTUK HANDLE YANG DIPILIH
    if ($handle_id) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $handle_id) {
                $handleItem = $item;
                break;
            }
        }
    }

    if ($handleItem) {
        $satuanTerkecil = (float)($handleItem->satuan_terkecil ?? 0);
        $qty = $jumlah * 12;
        $handleItem->qty = $qty;
        $totalWindowHardwareHandleQty += $qty;
    }

    // CEK APAKAH HANDLE YANG DIPILIH ADALAH MULTILOCK
    $isMultilock = false;
    if ($handleItem) {
        $namaLower = strtolower($handleItem->nama_produk);
        if (str_contains($namaLower, 'multilock')) {
            $isMultilock = true;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE TRANSMITTER ===
    $transmitterItem = null;
    $totalWindowHardwareTransmitterQty = 0;
    $ukuranTransmitter = 0;
    $ukuranTransmitterFinal = 0;

    if ($isMultilock) {
        $ukuranTransmitter = $panjang - 20;

        $transmitterMapping = [
            40 => 172,
            60 => 171,
            80 => 170,
            100 => 173,
            120 => 162,
            140 => 166,
            160 => 167,
            180 => 168,
            200 => 169,
        ];

        $ukuranTransmitterFinal = $ukuranTransmitter;
        if (!isset($transmitterMapping[$ukuranTransmitter])) {
            $availableSizes = array_keys($transmitterMapping);
            sort($availableSizes);
            
            $found = false;
            for ($i = 0; $i < count($availableSizes); $i++) {
                if ($availableSizes[$i] >= $ukuranTransmitter) {
                    $ukuranTransmitterFinal = $availableSizes[$i];
                    $found = true;
                    break;
                }
            }
            
            if (!$found) {
                $ukuranTransmitterFinal = max($availableSizes);
            }
        }

        $transmitterId = $transmitterMapping[$ukuranTransmitterFinal] ?? null;

        if ($transmitterId) {
            for ($i = 0; $i < $aksesorisCount; $i++) {
                $item = $aksesoris[$i];
                if ($item->id == $transmitterId) {
                    $transmitterItem = $item;
                    break;
                }
            }
        }

        if ($transmitterItem) {
            $satuanTerkecil = (float)($transmitterItem->satuan_terkecil ?? 0);
            $qty = $jumlah * 12;
            $transmitterItem->qty = $qty;
            $totalWindowHardwareTransmitterQty += $qty;
        }
    }

    // === PERHITUNGAN WINDOW HARDWARE FRICTION STAY ===
    $ukuranFrictionStay = $panjang / 3;

    $frictionStayMapping = [
        25 => 175,
        30 => 174,
        35 => 179,
        40 => 173,
        45 => 176,
        50 => 177,
        60 => 178,
    ];

    $ukuranFrictionStayFinal = $ukuranFrictionStay;
    if (!isset($frictionStayMapping[$ukuranFrictionStay])) {
        $availableSizes = array_keys($frictionStayMapping);
        sort($availableSizes);
        
        $found = false;
        for ($i = 0; $i < count($availableSizes); $i++) {
            if ($availableSizes[$i] >= $ukuranFrictionStay) {
                $ukuranFrictionStayFinal = $availableSizes[$i];
                $found = true;
                break;
            }
        }
        
        if (!$found) {
            $ukuranFrictionStayFinal = max($availableSizes);
        }
    }

    $frictionStayItem = null;
    $frictionStayId = $frictionStayMapping[$ukuranFrictionStayFinal] ?? null;

    if ($frictionStayId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $frictionStayId) {
                $frictionStayItem = $item;
                break;
            }
        }
    }

    $totalWindowHardwareFrictionStayQty = 0;
    if ($frictionStayItem) {
        $satuanTerkecil = (float)($frictionStayItem->satuan_terkecil ?? 0);
        $qty = $totalWindowHardwareHandleQty * 2;
        $frictionStayItem->qty = $qty;
        $totalWindowHardwareFrictionStayQty += $qty;
    }

    // === PERHITUNGAN SCREW TRANSMITTER ===
    $screwTransmitterItem = null;
    $screwTransmitterQty = 0;

    if ($isMultilock && $transmitterItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-transmitter') {
                $screwTransmitterItem = $item;
                break;
            }
        }

        $satuanTerkecilScrewTransmitter = $screwTransmitterItem ? (float)$screwTransmitterItem->satuan_terkecil : 0;
        $screwTransmitterQty = ($totalWindowHardwareTransmitterQty * $satuanTerkecilScrewTransmitter);
        if ($screwTransmitterItem) {
            $screwTransmitterItem->qty = $screwTransmitterQty;
        }
    }

    // === PERHITUNGAN SCREW FRICTION STAY ===
    $screwFrictionStayItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-friction-stay') {
            $screwFrictionStayItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewFrictionStay = $screwFrictionStayItem ? (float)$screwFrictionStayItem->satuan_terkecil : 0;
    $screwFrictionStayQty = $totalWindowHardwareFrictionStayQty * $satuanTerkecilScrewFrictionStay;
    if ($screwFrictionStayItem) {
        $screwFrictionStayItem->qty = $screwFrictionStayQty;
    }

    // === PERHITUNGAN SCREW HANDLE ===
    $screwHandleItem = null;
    if ($handleItem) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->area && $item->area->slug == 'screw-handle') {
                $screwHandleItem = $item;
                break;
            }
        }
    }

    $satuanTerkecilScrewHandle = $screwHandleItem ? (float)$screwHandleItem->satuan_terkecil : 0;
    $screwHandleQty = $totalWindowHardwareHandleQty * $satuanTerkecilScrewHandle;
    if ($screwHandleItem) {
        $screwHandleItem->qty = $screwHandleQty;
    }

    // === PERHITUNGAN SETTING BLOCK ===
    $settingBlockItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'setting-block') {
            $settingBlockItem = $item;
            break;
        }
    }
    
    $satuanTerkecilSettingBlock = $settingBlockItem ? (float)$settingBlockItem->satuan_terkecil : 0;
    
    $variableC = 4 * $satuanTerkecilSettingBlock;
    $variableD = $variableC * $jumlah;
    $variableE = $variableD * 25;
    $variableF = $variableE / 1000;
    $settingBlockQty = ceil($variableF);

    // === PERHITUNGAN SCREW REINFORCEMENT ===
    $screwItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-reinforcement') {
            $screwItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrew = $screwItem ? (float)$screwItem->satuan_terkecil : 0;
    $screwQty = ((($totalLebar + $totalPanjang)) + ($variableSashVertikalB + $variableSashHorizontalB)) / $satuanTerkecilScrew;
    $screwQty = ceil($screwQty * 10);

    // === HITUNG QTY PER AKSESORIS ===
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        $areaSlug = $item->area ? $item->area->slug : '';
        $qty = 0;
        
        if ($areaSlug == 'profile-vertikal') {
            $qty = $batangVertikal;
        } elseif ($areaSlug == 'profile-horizontal') {
            $qty = $batangHorizontal;
        } elseif ($areaSlug == 'glaze-bead-vertical') {
            $qty = ($panjang / 100) * $jumlah;
        } elseif ($areaSlug == 'glaze-bead-horizontal') {
            $qty = ($lebar / 100) * $jumlah;
        } elseif ($areaSlug == 'reinforcement') {
            $qty = $reinforcementQty;
        } elseif ($areaSlug == 'reinforcement-sash') {
            $qty = $reinforcementSashQty;
        } elseif ($areaSlug == 'kaca') {
            $qty = $luasKacaTotal;
        } elseif ($areaSlug == 'screw-reinforcement') {
            $qty = $screwQty;
        } elseif ($areaSlug == 'setting-block') {
            $qty = $settingBlockQty;
        } elseif ($areaSlug == 'profile-sash-vertikal') {
            $qty = $batangSashVertikalQty;
        } elseif ($areaSlug == 'profile-sash-horizontal') {
            $qty = $batangSashHorizontalQty;
        } elseif ($areaSlug == 'profile-coupling-vertikal') {
            $qty = $batangCouplingVertikalQty;
        } elseif ($areaSlug == 'profile-coupling-horizontal') {
            $qty = $batangCouplingHorizontalQty;
        } elseif ($areaSlug == 'window-hardware-transmitter') {
            $qty = ($transmitterItem && $transmitterItem->id == $item->id) ? $transmitterItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-friction-stay') {
            $qty = ($frictionStayItem && $frictionStayItem->id == $item->id) ? $frictionStayItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-handle-rambuncis' || $areaSlug == 'window-hardware-handle-multilock') {
            $qty = $item->qty;
        } elseif ($areaSlug == 'screw-transmitter') {
            $qty = $screwTransmitterQty;
        } elseif ($areaSlug == 'screw-friction-stay') {
            $qty = $screwFrictionStayQty;
        } elseif ($areaSlug == 'screw-handle') {
            $qty = $screwHandleQty;
        } else {
            $qty = $jumlah * ($item->satuan_terkecil ?? 1);
        }
        
        $item->qty = $qty;
    }

    // Kelompokkan berdasarkan area
    $grouped = [];
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->qty <= 0) {
            continue;
        }
        
        // Skip transmitter, friction stay, dan handle yang tidak terpilih (qty 0)
        if ($item->area && ($item->area->slug == 'window-hardware-transmitter' || $item->area->slug == 'window-hardware-friction-stay') && $item->qty <= 0) {
            continue;
        }
        if ($item->area && ($item->area->slug == 'window-hardware-handle-rambuncis' || $item->area->slug == 'window-hardware-handle-multilock') && $item->qty <= 0) {
            continue;
        }
        
        $areaSlug = $item->area ? $item->area->slug : 'lainnya';
        
        if (str_starts_with($areaSlug, 'profile')) {
            $groupKey = 'profile';
        } elseif ($areaSlug == 'setting-block') {
            $groupKey = 'kaca';
        } elseif ($areaSlug == 'reinforcement' || $areaSlug == 'reinforcement-sash') {
            $groupKey = 'reinforcement';
        } elseif (str_starts_with($areaSlug, 'window-hardware')) {
            $groupKey = 'window-hardware';
        } elseif ($areaSlug == 'screw-reinforcement' || $areaSlug == 'screw-transmitter' || $areaSlug == 'screw-friction-stay' || $areaSlug == 'screw-handle') {
            $groupKey = 'screw';
        } else {
            $groupKey = $areaSlug;
        }
        
        if (!isset($grouped[$groupKey])) {
            $grouped[$groupKey] = [];
        }
        $grouped[$groupKey][] = $item;
    }

    $areaLabels = [
        'profile' => 'PROFILE (Termasuk Coupling)',
        'reinforcement' => 'REINFORCEMENT',
        'kaca' => 'KACA',
        'screw' => 'SCREW',
        'window-hardware' => 'WINDOW HARDWARE',
    ];

    // ============ GENERATE NOMOR BOQ ============
    $nomorBoq = Boq::generateNomorBoq();

    // ============ STORE BOQ ============
    try {
        $allResults = [];
        
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->qty > 0) {
                $allResults[] = [
                    'produk_id' => $item->id,
                    'qty' => $item->qty,
                    'nama_produk' => $item->nama_produk,
                ];
            }
        }
        
        $uniqueResults = [];
        $seenIds = [];
        $allResultsCount = count($allResults);
        
        for ($i = 0; $i < $allResultsCount; $i++) {
            $item = $allResults[$i];
            $produkId = $item['produk_id'] ?? null;
            
            if (!$produkId) {
                continue;
            }
            
            $isDuplicate = false;
            $seenCount = count($seenIds);
            for ($j = 0; $j < $seenCount; $j++) {
                if ($seenIds[$j] == $produkId) {
                    $isDuplicate = true;
                    break;
                }
            }
            
            if ($isDuplicate) {
                continue;
            }
            
            $seenIds[] = $produkId;
            $uniqueResults[] = $item;
        }
        
        if (count($uniqueResults) > 0) {
            $boq = new Boq();
            $boq->nomor_boq = $nomorBoq;
            $boq->tanggal_boq = now();
            $boq->save();
            
            $uniqueCount = count($uniqueResults);
            for ($i = 0; $i < $uniqueCount; $i++) {
                $item = $uniqueResults[$i];
                $produkId = $item['produk_id'] ?? null;
                $qty = (int)($item['qty'] ?? 0);
                
                if ($produkId && $qty > 0) {
                    $produk = Product::find($produkId);
                    
                    \DB::table('detail_boq')->insert([
                        'boq_id' => $boq->id,
                        'produk_id' => $produkId,
                        'kode_produk' => $produk ? $produk->kode_produk : null,
                        'qty' => $qty,
                        'created_at' => now(),
                        'updated_at' => now()
                    ]);
                }
            }
            
            \Log::info('BOQ SAVED JENDELA JUNGKIT 12 BOUVEN:', [
                'boq_id' => $boq->id,
                'nomor_boq' => $nomorBoq,
                'total' => count($uniqueResults)
            ]);
        }
        
    } catch (\Exception $e) {
        \Log::error('Error saving BOQ Jendela Jungkit 12 Bouven: ' . $e->getMessage());
        \Log::error($e->getTraceAsString());
    }

    $data = [
        'judul' => $judul,
        'panjang' => $panjang,
        'lebar' => $lebar,
        'tebal_kaca' => $tebal_kaca,
        'jumlah' => $jumlah,
        'warna' => $warna,
        'type_kaca' => $type_kaca,
        'handle_id' => $handle_id,
        'is_multilock' => $isMultilock,
        'luas_kaca_total' => $luasKacaTotal,
        'keliling_total' => $kelilingTotal,
        'batang_vertikal' => $batangVertikal,
        'batang_horizontal' => $batangHorizontal,
        'reinforcement_qty' => $reinforcementQty,
        'reinforcement_sash_qty' => $reinforcementSashQty,
        'batang_sash_vertikal_qty' => $batangSashVertikalQty,
        'batang_sash_horizontal_qty' => $batangSashHorizontalQty,
        'batang_coupling_vertikal_qty' => $batangCouplingVertikalQty,
        'batang_coupling_horizontal_qty' => $batangCouplingHorizontalQty,
        'handle_item' => $handleItem,
        'total_window_hardware_handle_qty' => $totalWindowHardwareHandleQty,
        'transmitter_item' => $transmitterItem,
        'ukuran_transmitter' => $ukuranTransmitter,
        'ukuran_transmitter_final' => $ukuranTransmitterFinal,
        'total_window_hardware_transmitter_qty' => $totalWindowHardwareTransmitterQty,
        'friction_stay_item' => $frictionStayItem,
        'ukuran_friction_stay' => $ukuranFrictionStay,
        'ukuran_friction_stay_final' => $ukuranFrictionStayFinal,
        'total_window_hardware_friction_stay_qty' => $totalWindowHardwareFrictionStayQty,
        'screw_transmitter_qty' => $screwTransmitterQty,
        'screw_friction_stay_qty' => $screwFrictionStayQty,
        'screw_handle_qty' => $screwHandleQty,
        'screw_qty' => $screwQty,
        'setting_block_qty' => $settingBlockQty,
        'grouped' => $grouped,
        'areaLabels' => $areaLabels,
        'nomor_boq' => $nomorBoq,
        'profile_coupling_vertikal' => $profileCouplingVertikal,
        'profile_coupling_horizontal' => $profileCouplingHorizontal,
    ];

    return view('boq.jendela.pdf-jendela-jungkit-12-bouven', compact('data'));
}

public function hitungSliding(Request $request)
{
    $request->validate([
        'panjang' => 'required|numeric|min:1',
        'lebar' => 'required|numeric|min:1',
        'tebal_kaca' => 'required|numeric|min:1',
        'jumlah' => 'required|numeric|min:1',
        'warna' => 'required|string',
        'type_kaca' => 'required|string',
    ]);

    // Ambil data dari form
    $panjang = $request->panjang; // cm
    $lebar = $request->lebar; // cm
    $tebalKaca = $request->tebal_kaca; // mm
    $jumlah = $request->jumlah;
    $warna = $request->warna;
    $typeKaca = $request->type_kaca;

    // Ambil produk utama (Jendela Sliding) dari database
    $produkUtama = Product::find(190);
    
    if (!$produkUtama) {
        return back()->with('error', 'Produk Jendela Sliding tidak ditemukan!');
    }

    // Ambil aksesoris dari tabel product_accessories dengan relasi area
    $aksesorisIds = ProductAccessories::where('parent_product_id', 190)->pluck('accessory_id');
    $aksesoris = Product::with('area', 'unit')
        ->whereIn('id', $aksesorisIds)
        ->get();

    // === PERHITUNGAN DASAR ===
    
    // Konversi ke meter
    $panjangM = $panjang / 100;
    $lebarM = $lebar / 100;
    $tebalKacaM = $tebalKaca / 1000;

    // 1. Luas Kaca (m²)
    $luasKacaPerUnit = $panjangM * $lebarM;
    $luasKacaTotal = $luasKacaPerUnit * $jumlah;
    $luasKacaTotal = ceil($luasKacaTotal * 10) / 10;

    // 2. Keliling Profile (meter)
    $kelilingPerUnit = 2 * ($panjangM + $lebarM);
    $kelilingTotal = $kelilingPerUnit * $jumlah;

    // === PERHITUNGAN PROFILE VERTIKAL ===
    $profileVertikal = null;
    $aksesorisCount = count($aksesoris);
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-vertikal') {
            $profileVertikal = $item;
            break;
        }
    }
    $satuanTerkecilVertikal = $profileVertikal ? (float)$profileVertikal->satuan_terkecil : 0;

    $variableA = $jumlah * 2;
    $frameVertikal = $variableA * $panjang;
    $batangVertikal = $frameVertikal / 580;
    $batangVertikal = ceil($batangVertikal * 10) / 10;
    $totalPanjang = $panjang * $variableA;

    // === PERHITUNGAN PROFILE HORIZONTAL ===
    $profileHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-horizontal') {
            $profileHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilHorizontal = $profileHorizontal ? (float)$profileHorizontal->satuan_terkecil : 0;
    
    $variableB = $jumlah * $satuanTerkecilHorizontal;
    $frameHorizontal = $variableB * $lebar;
    $batangHorizontal = $frameHorizontal / 580;
    $batangHorizontal = ceil($batangHorizontal * 10) / 10;
    $totalLebar = $lebar * $variableB;

    // === PERHITUNGAN REINFORCEMENT ===
    $totalBatang = ($frameVertikal + $frameHorizontal) / 600;
    $reinforcementQty = ceil($totalBatang * 10) / 10;

    // === PERHITUNGAN PROFILE SASH VERTIKAL ===
    $profileSashVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-vertikal') {
            $profileSashVertikal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashVertikal = $profileSashVertikal ? (float)$profileSashVertikal->satuan_terkecil : 0;
    
    $variableSashVertikalA = 4 * $jumlah;
    $variableSashVertikalB = $variableSashVertikalA * $panjang;
    $batangSashVertikal = $variableSashVertikalB / 580;
    $batangSashVertikalQty = ceil($batangSashVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE SASH HORIZONTAL ===
    $profileSashHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-horizontal') {
            $profileSashHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashHorizontal = $profileSashHorizontal ? (float)$profileSashHorizontal->satuan_terkecil : 0;
    
    $variableSashHorizontalA = $satuanTerkecilSashHorizontal * $jumlah;
    $variableSashHorizontalB = $variableSashHorizontalA * $lebar;
    $batangSashHorizontal = $variableSashHorizontalB / 580;
    $batangSashHorizontalQty = ceil($batangSashHorizontal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT SASH ===
    $totalBatangSash = ($variableSashVertikalB + $variableSashHorizontalB) / 600;
    $reinforcementSashQty = ceil($totalBatangSash * 10) / 10;

    // === PERHITUNGAN ALUMUNIUM TRACK ===
    $alumuniumTrackItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-alumunium-track') {
            $alumuniumTrackItem = $item;
            break;
        }
    }

    $satuanTerkecilTrack = $alumuniumTrackItem ? (float)$alumuniumTrackItem->satuan_terkecil : 0;

    $variableTrackA = $satuanTerkecilTrack * $jumlah;
    $variableTrackB = $variableTrackA * $lebar;
    $batangTrack = $variableTrackB / 580;
    $trackQty = ceil($batangTrack * 10) / 10;

    // === PERHITUNGAN PROFILE GLAZE VERTIKAL ===
    $profileGlazeVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-glaze-vertikal') {
            $profileGlazeVertikal = $item;
            break;
        }
    }

    $satuanTerkecilGlazeVertikal = $profileGlazeVertikal ? (float)$profileGlazeVertikal->satuan_terkecil : 0;

    $variableGlazeVertikalA = 4 * $jumlah;
    $variableGlazeVertikalB = $variableGlazeVertikalA * $panjang;
    $batangGlazeVertikal = $variableGlazeVertikalB / 580;
    $batangGlazeVertikalQty = ceil($batangGlazeVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE GLAZE HORIZONTAL ===
    $profileGlazeHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-glaze-horizontal') {
            $profileGlazeHorizontal = $item;
            break;
        }
    }

    $satuanTerkecilGlazeHorizontal = $profileGlazeHorizontal ? (float)$profileGlazeHorizontal->satuan_terkecil : 0;

    $variableGlazeHorizontalA = $satuanTerkecilGlazeHorizontal * $jumlah;
    $variableGlazeHorizontalB = $variableGlazeHorizontalA * $lebar;
    $batangGlazeHorizontal = $variableGlazeHorizontalB / 580;
    $batangGlazeHorizontalQty = ceil($batangGlazeHorizontal * 10) / 10;

    // === PERHITUNGAN PROFILE INTERLOCK VERTIKAL ===
    $profileInterlockVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-interlock-vertikal') {
            $profileInterlockVertikal = $item;
            break;
        }
    }

    $satuanTerkecilInterlock = $profileInterlockVertikal ? (float)$profileInterlockVertikal->satuan_terkecil : 0;

    $variableInterlockA = $satuanTerkecilInterlock * $jumlah;
    $variableInterlockB = $variableInterlockA * $panjang;
    $batangInterlock = $variableInterlockB / 580;
    $batangInterlockQty = ceil($batangInterlock * 10) / 10;

    // === PERHITUNGAN MOHAIR ===
    $mohairItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'mohair') {
            $mohairItem = $item;
            break;
        }
    }
    
    $satuanTerkecilMohair = $mohairItem ? (float)$mohairItem->satuan_terkecil : 0;
    $mohairQty = ceil(( (($variableSashVertikalB + $variableSashHorizontalB)*2) / 100 ) * $jumlah);

    // === PERHITUNGAN WINDOW HARDWARE STRIKE ===
    $strikeItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'window-hardware-strike') {
            $strikeItem = $item;
            break;
        }
    }
    
    $satuanTerkecilStrike = $strikeItem ? (float)$strikeItem->satuan_terkecil : 0;
    $strikeQty = $jumlah * $satuanTerkecilStrike;

    // === PERHITUNGAN WINDOW HARDWARE LIFTING ===
    $liftingItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'window-hardware-lifting') {
            $liftingItem = $item;
            break;
        }
    }
    
    $satuanTerkecilLifting = $liftingItem ? (float)$liftingItem->satuan_terkecil : 0;
    $liftingQty = $jumlah * $satuanTerkecilLifting;

    // === PERHITUNGAN WINDOW HARDWARE ROLLER ===
    $rollerItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'window-hardware-roller') {
            $rollerItem = $item;
            break;
        }
    }
    
    $satuanTerkecilRoller = $rollerItem ? (float)$rollerItem->satuan_terkecil : 0;
    $rollerQty = $jumlah * $satuanTerkecilRoller;

    // === PERHITUNGAN WINDOW HARDWARE HANDLE TOUCH ===
    $handleTouchItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'window-hardware-handle-touch') {
            $handleTouchItem = $item;
            break;
        }
    }
    
    $satuanTerkecilHandleTouch = $handleTouchItem ? (float)$handleTouchItem->satuan_terkecil : 0;
    $handleTouchQty = $jumlah * $satuanTerkecilHandleTouch;

    // === PERHITUNGAN SCREW LIFTING ===
    $screwLiftingItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-lifting') {
            $screwLiftingItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrewLifting = $screwLiftingItem ? (float)$screwLiftingItem->satuan_terkecil : 0;
    $screwLiftingQty = $liftingQty * $satuanTerkecilScrewLifting;

    // === PERHITUNGAN SCREW ANTI STIKE ===
    $screwAntiStikeItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-anti-strike') {
            $screwAntiStikeItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrewAntiStike = $screwAntiStikeItem ? (float)$screwAntiStikeItem->satuan_terkecil : 0;
    $screwAntiStikeQty = $strikeQty * $satuanTerkecilScrewAntiStike;

    // === PERHITUNGAN SCREW DOOR ROLLER ===
    $screwDoorRollerItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-door-roller') {
            $screwDoorRollerItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrewDoorRoller = $screwDoorRollerItem ? (float)$screwDoorRollerItem->satuan_terkecil : 0;
    $screwDoorRollerQty = $rollerQty * $satuanTerkecilScrewDoorRoller;

    // === PERHITUNGAN SETTING BLOCK ===
    $settingBlockItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'setting-block') {
            $settingBlockItem = $item;
            break;
        }
    }
    
    $satuanTerkecilSettingBlock = $settingBlockItem ? (float)$settingBlockItem->satuan_terkecil : 0;
    
    $variableC = 2 * $satuanTerkecilSettingBlock;
    $variableD = $variableC * $jumlah;
    $variableE = $variableD * 25;
    $variableF = $variableE / 1000;
    $settingBlockQty = ceil($variableF);

    // === PERHITUNGAN SCREW REINFORCEMENT ===
    $screwItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-reinforcement') {
            $screwItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrew = $screwItem ? (float)$screwItem->satuan_terkecil : 1;
    $screwQty = ((($totalLebar + $totalPanjang)) + ($variableSashVertikalB + $variableSashHorizontalB)) / $satuanTerkecilScrew;
    $screwQty = ceil($screwQty * 10);

    // === PERHITUNGAN QTY PER AKSESORIS ===
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        $areaSlug = $item->area ? $item->area->slug : '';
        $qty = 0;
        
        if ($areaSlug == 'profile-vertikal') {
            $qty = $batangVertikal;
        } elseif ($areaSlug == 'profile-horizontal') {
            $qty = $batangHorizontal;
        } elseif ($areaSlug == 'glaze-bead-vertical') {
            $qty = ($panjang / 100) * $jumlah;
        } elseif ($areaSlug == 'glaze-bead-horizontal') {
            $qty = ($lebar / 100) * $jumlah;
        } elseif ($areaSlug == 'reinforcement') {
            $qty = $reinforcementQty;
        } elseif ($areaSlug == 'reinforcement-sash') {
            $qty = $reinforcementSashQty;
        } elseif ($areaSlug == 'kaca') {
            $qty = $luasKacaTotal;
        } elseif ($areaSlug == 'screw-reinforcement') {
            $qty = $screwQty;
        } elseif ($areaSlug == 'setting-block') {
            $qty = $settingBlockQty;
        } elseif ($areaSlug == 'profile-sash-vertikal') {
            $qty = $batangSashVertikalQty;
        } elseif ($areaSlug == 'profile-sash-horizontal') {
            $qty = $batangSashHorizontalQty;
        } elseif ($areaSlug == 'profile-alumunium-track') {
            $qty = $trackQty;
        } elseif ($areaSlug == 'profile-glaze-vertikal') {
            $qty = $batangGlazeVertikalQty;
        } elseif ($areaSlug == 'profile-glaze-horizontal') {
            $qty = $batangGlazeHorizontalQty;
        } elseif ($areaSlug == 'profile-interlock-vertikal') {
            $qty = $batangInterlockQty;
        } elseif ($areaSlug == 'mohair') {
            $qty = $mohairQty;
        } elseif ($areaSlug == 'window-hardware-strike') {
            $qty = ($strikeItem && $strikeItem->id == $item->id) ? $strikeQty : 0;
        } elseif ($areaSlug == 'window-hardware-lifting') {
            $qty = ($liftingItem && $liftingItem->id == $item->id) ? $liftingQty : 0;
        } elseif ($areaSlug == 'window-hardware-roller') {
            $qty = ($rollerItem && $rollerItem->id == $item->id) ? $rollerQty : 0;
        } elseif ($areaSlug == 'window-hardware-handle-touch') {
            $qty = ($handleTouchItem && $handleTouchItem->id == $item->id) ? $handleTouchQty : 0;
        } elseif ($areaSlug == 'screw-lifting') {
            $qty = $screwLiftingQty;
        } elseif ($areaSlug == 'screw-anti-strike') {
            $qty = $screwAntiStikeQty;
        } elseif ($areaSlug == 'screw-door-roller') {
            $qty = $screwDoorRollerQty;
        } else {
            $qty = $jumlah * ($item->satuan_terkecil ?? 1);
        }
        
        $item->qty = $qty;
    }

    // Data untuk view
    $data = [
        'produk' => $produkUtama,
        'panjang' => $panjang,
        'lebar' => $lebar,
        'tebal_kaca' => $tebalKaca,
        'jumlah' => $jumlah,
        'warna' => $warna,
        'type_kaca' => $typeKaca,
        
        'luas_kaca_per_unit' => $luasKacaPerUnit,
        'luas_kaca_total' => $luasKacaTotal,
        'keliling_per_unit' => $kelilingPerUnit,
        'keliling_total' => $kelilingTotal,
        
        'profile_vertikal' => $profileVertikal,
        'variable_a' => $variableA,
        'frame_vertikal' => $frameVertikal,
        'batang_vertikal' => $batangVertikal,
        
        'profile_horizontal' => $profileHorizontal,
        'satuan_terkecil_horizontal' => $satuanTerkecilHorizontal,
        'variable_b' => $variableB,
        'frame_horizontal' => $frameHorizontal,
        'batang_horizontal' => $batangHorizontal,
        
        'total_batang' => $totalBatang,
        'reinforcement_qty' => $reinforcementQty,
        
        'profile_sash_vertikal' => $profileSashVertikal,
        'satuan_terkecil_sash_vertikal' => $satuanTerkecilSashVertikal,
        'variable_sash_vertikal_a' => $variableSashVertikalA,
        'variable_sash_vertikal_b' => $variableSashVertikalB,
        'batang_sash_vertikal' => $batangSashVertikal,
        'batang_sash_vertikal_qty' => $batangSashVertikalQty,
        
        'profile_sash_horizontal' => $profileSashHorizontal,
        'satuan_terkecil_sash_horizontal' => $satuanTerkecilSashHorizontal,
        'variable_sash_horizontal_a' => $variableSashHorizontalA,
        'variable_sash_horizontal_b' => $variableSashHorizontalB,
        'batang_sash_horizontal' => $batangSashHorizontal,
        'batang_sash_horizontal_qty' => $batangSashHorizontalQty,
        
        'reinforcement_sash_qty' => $reinforcementSashQty,
        
        'alumunium_track_item' => $alumuniumTrackItem,
        'satuan_terkecil_track' => $satuanTerkecilTrack,
        'variable_track_a' => $variableTrackA,
        'variable_track_b' => $variableTrackB,
        'batang_track' => $batangTrack,
        'track_qty' => $trackQty,
        
        'profile_glaze_vertikal' => $profileGlazeVertikal,
        'satuan_terkecil_glaze_vertikal' => $satuanTerkecilGlazeVertikal,
        'variable_glaze_vertikal_a' => $variableGlazeVertikalA,
        'variable_glaze_vertikal_b' => $variableGlazeVertikalB,
        'batang_glaze_vertikal' => $batangGlazeVertikal,
        'batang_glaze_vertikal_qty' => $batangGlazeVertikalQty,
        
        'profile_glaze_horizontal' => $profileGlazeHorizontal,
        'satuan_terkecil_glaze_horizontal' => $satuanTerkecilGlazeHorizontal,
        'variable_glaze_horizontal_a' => $variableGlazeHorizontalA,
        'variable_glaze_horizontal_b' => $variableGlazeHorizontalB,
        'batang_glaze_horizontal' => $batangGlazeHorizontal,
        'batang_glaze_horizontal_qty' => $batangGlazeHorizontalQty,
        
        'profile_interlock_vertikal' => $profileInterlockVertikal,
        'satuan_terkecil_interlock' => $satuanTerkecilInterlock,
        'variable_interlock_a' => $variableInterlockA,
        'variable_interlock_b' => $variableInterlockB,
        'batang_interlock' => $batangInterlock,
        'batang_interlock_qty' => $batangInterlockQty,
        
        'mohair_item' => $mohairItem,
        'mohair_qty' => $mohairQty,
        
        'strike_item' => $strikeItem,
        'strike_qty' => $strikeQty,
        
        'lifting_item' => $liftingItem,
        'lifting_qty' => $liftingQty,
        
        'roller_item' => $rollerItem,
        'roller_qty' => $rollerQty,
        
        'handle_touch_item' => $handleTouchItem,
        'handle_touch_qty' => $handleTouchQty,
        
        'screw_lifting_item' => $screwLiftingItem,
        'screw_lifting_qty' => $screwLiftingQty,
        
        'screw_anti_stike_item' => $screwAntiStikeItem,
        'screw_anti_stike_qty' => $screwAntiStikeQty,
        
        'screw_door_roller_item' => $screwDoorRollerItem,
        'screw_door_roller_qty' => $screwDoorRollerQty,
        
        'satuan_terkecil_screw' => $satuanTerkecilScrew,
        'screw_qty' => $screwQty,
        
        'setting_block_item' => $settingBlockItem,
        'satuan_terkecil_setting_block' => $satuanTerkecilSettingBlock,
        'variable_c' => $variableC,
        'variable_d' => $variableD,
        'variable_e' => $variableE,
        'variable_f' => $variableF,
        'setting_block_qty' => $settingBlockQty,
        
        'aksesoris' => $aksesoris,
    ];

    return view('boq.jendela.jendela-sliding', $data);
}
public function exportPdfSliding(Request $request)
{
    $panjang = $request->panjang;
    $lebar = $request->lebar;
    $tebal_kaca = $request->tebal_kaca;
    $jumlah = $request->jumlah;
    $warna = $request->warna;
    $type_kaca = $request->type_kaca;
    $judul = $request->judul ?? 'BOQ - Jendela Sliding';

    // Ambil data aksesoris
    $aksesorisIds = ProductAccessories::where('parent_product_id', 190)->pluck('accessory_id');
    $aksesoris = Product::with('area', 'unit')
        ->whereIn('id', $aksesorisIds)
        ->get();

    // === PERHITUNGAN DASAR ===
    $panjangM = $panjang / 100;
    $lebarM = $lebar / 100;
    
    $luasKacaPerUnit = $panjangM * $lebarM;
    $luasKacaTotal = $luasKacaPerUnit * $jumlah;
    $luasKacaTotal = ceil($luasKacaTotal * 10) / 10;

    $kelilingPerUnit = 2 * ($panjangM + $lebarM);
    $kelilingTotal = $kelilingPerUnit * $jumlah;

    // === PERHITUNGAN PROFILE VERTIKAL ===
    $profileVertikal = null;
    $aksesorisCount = count($aksesoris);
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-vertikal') {
            $profileVertikal = $item;
            break;
        }
    }
    $satuanTerkecilVertikal = $profileVertikal ? (float)$profileVertikal->satuan_terkecil : 0;

    $variableA = $jumlah * 2;
    $frameVertikal = $variableA * $panjang;
    $batangVertikal = $frameVertikal / 580;
    $batangVertikal = ceil($batangVertikal * 10) / 10;
    $totalPanjang = $panjang * $variableA;

    // === PERHITUNGAN PROFILE HORIZONTAL ===
    $profileHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-horizontal') {
            $profileHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilHorizontal = $profileHorizontal ? (float)$profileHorizontal->satuan_terkecil : 0;
    
    $variableB = $jumlah * $satuanTerkecilHorizontal;
    $frameHorizontal = $variableB * $lebar;
    $batangHorizontal = $frameHorizontal / 580;
    $batangHorizontal = ceil($batangHorizontal * 10) / 10;
    $totalLebar = $lebar * $variableB;

    // === PERHITUNGAN REINFORCEMENT ===
    $totalBatang = ($frameVertikal + $frameHorizontal) / 600;
    $reinforcementQty = ceil($totalBatang * 10) / 10;

    // === PERHITUNGAN PROFILE SASH VERTIKAL ===
    $profileSashVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-vertikal') {
            $profileSashVertikal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashVertikal = $profileSashVertikal ? (float)$profileSashVertikal->satuan_terkecil : 0;
    
    $variableSashVertikalA = 4 * $jumlah;
    $variableSashVertikalB = $variableSashVertikalA * $panjang;
    $batangSashVertikal = $variableSashVertikalB / 580;
    $batangSashVertikalQty = ceil($batangSashVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE SASH HORIZONTAL ===
    $profileSashHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-horizontal') {
            $profileSashHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashHorizontal = $profileSashHorizontal ? (float)$profileSashHorizontal->satuan_terkecil : 0;
    
    $variableSashHorizontalA = $satuanTerkecilSashHorizontal * $jumlah;
    $variableSashHorizontalB = $variableSashHorizontalA * $lebar;
    $batangSashHorizontal = $variableSashHorizontalB / 580;
    $batangSashHorizontalQty = ceil($batangSashHorizontal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT SASH ===
    $totalBatangSash = ($variableSashVertikalB + $variableSashHorizontalB) / 600;
    $reinforcementSashQty = ceil($totalBatangSash * 10) / 10;

    // === PERHITUNGAN ALUMUNIUM TRACK ===
    $alumuniumTrackItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-alumunium-track') {
            $alumuniumTrackItem = $item;
            break;
        }
    }

    $satuanTerkecilTrack = $alumuniumTrackItem ? (float)$alumuniumTrackItem->satuan_terkecil : 0;

    $variableTrackA = $satuanTerkecilTrack * $jumlah;
    $variableTrackB = $variableTrackA * $lebar;
    $batangTrack = $variableTrackB / 580;
    $trackQty = ceil($batangTrack * 10) / 10;

    // === PERHITUNGAN PROFILE GLAZE VERTIKAL ===
    $profileGlazeVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-glaze-vertikal') {
            $profileGlazeVertikal = $item;
            break;
        }
    }

    $satuanTerkecilGlazeVertikal = $profileGlazeVertikal ? (float)$profileGlazeVertikal->satuan_terkecil : 0;

    $variableGlazeVertikalA = 4 * $jumlah;
    $variableGlazeVertikalB = $variableGlazeVertikalA * $panjang;
    $batangGlazeVertikal = $variableGlazeVertikalB / 580;
    $batangGlazeVertikalQty = ceil($batangGlazeVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE GLAZE HORIZONTAL ===
    $profileGlazeHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-glaze-horizontal') {
            $profileGlazeHorizontal = $item;
            break;
        }
    }

    $satuanTerkecilGlazeHorizontal = $profileGlazeHorizontal ? (float)$profileGlazeHorizontal->satuan_terkecil : 0;

    $variableGlazeHorizontalA = $satuanTerkecilGlazeHorizontal * $jumlah;
    $variableGlazeHorizontalB = $variableGlazeHorizontalA * $lebar;
    $batangGlazeHorizontal = $variableGlazeHorizontalB / 580;
    $batangGlazeHorizontalQty = ceil($batangGlazeHorizontal * 10) / 10;

    // === PERHITUNGAN PROFILE INTERLOCK VERTIKAL ===
    $profileInterlockVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-interlock-vertikal') {
            $profileInterlockVertikal = $item;
            break;
        }
    }

    $satuanTerkecilInterlock = $profileInterlockVertikal ? (float)$profileInterlockVertikal->satuan_terkecil : 0;

    $variableInterlockA = $satuanTerkecilInterlock * $jumlah;
    $variableInterlockB = $variableInterlockA * $panjang;
    $batangInterlock = $variableInterlockB / 580;
    $batangInterlockQty = ceil($batangInterlock * 10) / 10;

    // === PERHITUNGAN MOHAIR ===
    $mohairItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'mohair') {
            $mohairItem = $item;
            break;
        }
    }
    
    $satuanTerkecilMohair = $mohairItem ? (float)$mohairItem->satuan_terkecil : 0;
    $mohairQty = ceil(( (($variableSashVertikalB + $variableSashHorizontalB)*2) / 100 ) * $jumlah);

    // === PERHITUNGAN WINDOW HARDWARE STRIKE ===
    $strikeItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'window-hardware-strike') {
            $strikeItem = $item;
            break;
        }
    }
    
    $satuanTerkecilStrike = $strikeItem ? (float)$strikeItem->satuan_terkecil : 0;
    $strikeQty = $jumlah * $satuanTerkecilStrike;

    // === PERHITUNGAN WINDOW HARDWARE LIFTING ===
    $liftingItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'window-hardware-lifting') {
            $liftingItem = $item;
            break;
        }
    }
    
    $satuanTerkecilLifting = $liftingItem ? (float)$liftingItem->satuan_terkecil : 0;
    $liftingQty = $jumlah * $satuanTerkecilLifting;

    // === PERHITUNGAN WINDOW HARDWARE ROLLER ===
    $rollerItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'window-hardware-roller') {
            $rollerItem = $item;
            break;
        }
    }
    
    $satuanTerkecilRoller = $rollerItem ? (float)$rollerItem->satuan_terkecil : 0;
    $rollerQty = $jumlah * $satuanTerkecilRoller;

    // === PERHITUNGAN WINDOW HARDWARE HANDLE TOUCH ===
    $handleTouchItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'window-hardware-handle-touch') {
            $handleTouchItem = $item;
            break;
        }
    }
    
    $satuanTerkecilHandleTouch = $handleTouchItem ? (float)$handleTouchItem->satuan_terkecil : 0;
    $handleTouchQty = $jumlah * $satuanTerkecilHandleTouch;

    // === PERHITUNGAN SCREW LIFTING ===
    $screwLiftingItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-lifting') {
            $screwLiftingItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrewLifting = $screwLiftingItem ? (float)$screwLiftingItem->satuan_terkecil : 0;
    $screwLiftingQty = $liftingQty * $satuanTerkecilScrewLifting;

    // === PERHITUNGAN SCREW ANTI STIKE ===
    $screwAntiStikeItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-anti-strike') {
            $screwAntiStikeItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrewAntiStike = $screwAntiStikeItem ? (float)$screwAntiStikeItem->satuan_terkecil : 0;
    $screwAntiStikeQty = $strikeQty * $satuanTerkecilScrewAntiStike;

    // === PERHITUNGAN SCREW DOOR ROLLER ===
    $screwDoorRollerItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-door-roller') {
            $screwDoorRollerItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrewDoorRoller = $screwDoorRollerItem ? (float)$screwDoorRollerItem->satuan_terkecil : 0;
    $screwDoorRollerQty = $rollerQty * $satuanTerkecilScrewDoorRoller;

    // === PERHITUNGAN SETTING BLOCK ===
    $settingBlockItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'setting-block') {
            $settingBlockItem = $item;
            break;
        }
    }
    
    $satuanTerkecilSettingBlock = $settingBlockItem ? (float)$settingBlockItem->satuan_terkecil : 0;
    
    $variableC = 2 * $satuanTerkecilSettingBlock;
    $variableD = $variableC * $jumlah;
    $variableE = $variableD * 25;
    $variableF = $variableE / 1000;
    $settingBlockQty = ceil($variableF);

    // === PERHITUNGAN SCREW REINFORCEMENT ===
    $screwItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-reinforcement') {
            $screwItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrew = $screwItem ? (float)$screwItem->satuan_terkecil : 1;
    $screwQty = ((($totalLebar + $totalPanjang)) + ($variableSashVertikalB + $variableSashHorizontalB)) / $satuanTerkecilScrew;
    $screwQty = ceil($screwQty * 10);

    // === HITUNG QTY PER AKSESORIS ===
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        $areaSlug = $item->area ? $item->area->slug : '';
        $qty = 0;
        
        if ($areaSlug == 'profile-vertikal') {
            $qty = $batangVertikal;
        } elseif ($areaSlug == 'profile-horizontal') {
            $qty = $batangHorizontal;
        } elseif ($areaSlug == 'glaze-bead-vertical') {
            $qty = ($panjang / 100) * $jumlah;
        } elseif ($areaSlug == 'glaze-bead-horizontal') {
            $qty = ($lebar / 100) * $jumlah;
        } elseif ($areaSlug == 'reinforcement') {
            $qty = $reinforcementQty;
        } elseif ($areaSlug == 'reinforcement-sash') {
            $qty = $reinforcementSashQty;
        } elseif ($areaSlug == 'kaca') {
            $qty = $luasKacaTotal;
        } elseif ($areaSlug == 'screw-reinforcement') {
            $qty = $screwQty;
        } elseif ($areaSlug == 'setting-block') {
            $qty = $settingBlockQty;
        } elseif ($areaSlug == 'profile-sash-vertikal') {
            $qty = $batangSashVertikalQty;
        } elseif ($areaSlug == 'profile-sash-horizontal') {
            $qty = $batangSashHorizontalQty;
        } elseif ($areaSlug == 'profile-alumunium-track') {
            $qty = $trackQty;
        } elseif ($areaSlug == 'profile-glaze-vertikal') {
            $qty = $batangGlazeVertikalQty;
        } elseif ($areaSlug == 'profile-glaze-horizontal') {
            $qty = $batangGlazeHorizontalQty;
        } elseif ($areaSlug == 'profile-interlock-vertikal') {
            $qty = $batangInterlockQty;
        } elseif ($areaSlug == 'mohair') {
            $qty = $mohairQty;
        } elseif ($areaSlug == 'window-hardware-strike') {
            $qty = ($strikeItem && $strikeItem->id == $item->id) ? $strikeQty : 0;
        } elseif ($areaSlug == 'window-hardware-lifting') {
            $qty = ($liftingItem && $liftingItem->id == $item->id) ? $liftingQty : 0;
        } elseif ($areaSlug == 'window-hardware-roller') {
            $qty = ($rollerItem && $rollerItem->id == $item->id) ? $rollerQty : 0;
        } elseif ($areaSlug == 'window-hardware-handle-touch') {
            $qty = ($handleTouchItem && $handleTouchItem->id == $item->id) ? $handleTouchQty : 0;
        } elseif ($areaSlug == 'screw-lifting') {
            $qty = $screwLiftingQty;
        } elseif ($areaSlug == 'screw-anti-strike') {
            $qty = $screwAntiStikeQty;
        } elseif ($areaSlug == 'screw-door-roller') {
            $qty = $screwDoorRollerQty;
        } else {
            $qty = $jumlah * ($item->satuan_terkecil ?? 1);
        }
        
        $item->qty = $qty;
    }

    // Kelompokkan berdasarkan area
    $grouped = [];
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->qty <= 0) {
            continue;
        }
        
        $areaSlug = $item->area ? $item->area->slug : 'lainnya';
        
        if (str_starts_with($areaSlug, 'profile')) {
            $groupKey = 'profile';
        } elseif ($areaSlug == 'setting-block' || $areaSlug == 'mohair') {
            $groupKey = 'kaca';
        } elseif ($areaSlug == 'reinforcement' || $areaSlug == 'reinforcement-sash') {
            $groupKey = 'reinforcement';
        } elseif (str_starts_with($areaSlug, 'window-hardware')) {
            $groupKey = 'window-hardware';
        } elseif ($areaSlug == 'screw-reinforcement' || $areaSlug == 'screw-lifting' || $areaSlug == 'screw-anti-strike' || $areaSlug == 'screw-door-roller') {
            $groupKey = 'screw';
        } elseif ($areaSlug == 'profile-alumunium-track') {
            $groupKey = 'track';
        } else {
            $groupKey = $areaSlug;
        }
        
        if (!isset($grouped[$groupKey])) {
            $grouped[$groupKey] = [];
        }
        $grouped[$groupKey][] = $item;
    }

    $areaLabels = [
        'profile' => 'PROFILE',
        'track' => 'TRACK',
        'reinforcement' => 'REINFORCEMENT',
        'kaca' => 'KACA',
        'screw' => 'SCREW',
        'window-hardware' => 'WINDOW HARDWARE',
    ];

    // ============ GENERATE NOMOR BOQ ============
    $nomorBoq = Boq::generateNomorBoq();

    // ============ STORE BOQ ============
    try {
        $allResults = [];
        
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->qty > 0) {
                $allResults[] = [
                    'produk_id' => $item->id,
                    'qty' => $item->qty,
                    'nama_produk' => $item->nama_produk,
                ];
            }
        }
        
        $uniqueResults = [];
        $seenIds = [];
        $allResultsCount = count($allResults);
        
        for ($i = 0; $i < $allResultsCount; $i++) {
            $item = $allResults[$i];
            $produkId = $item['produk_id'] ?? null;
            
            if (!$produkId) {
                continue;
            }
            
            $isDuplicate = false;
            $seenCount = count($seenIds);
            for ($j = 0; $j < $seenCount; $j++) {
                if ($seenIds[$j] == $produkId) {
                    $isDuplicate = true;
                    break;
                }
            }
            
            if ($isDuplicate) {
                continue;
            }
            
            $seenIds[] = $produkId;
            $uniqueResults[] = $item;
        }
        
        if (count($uniqueResults) > 0) {
            $boq = new Boq();
            $boq->nomor_boq = $nomorBoq;
            $boq->tanggal_boq = now();
            $boq->save();
            
            $uniqueCount = count($uniqueResults);
            for ($i = 0; $i < $uniqueCount; $i++) {
                $item = $uniqueResults[$i];
                $produkId = $item['produk_id'] ?? null;
                $qty = (int)($item['qty'] ?? 0);
                
                if ($produkId && $qty > 0) {
                    $produk = Product::find($produkId);
                    
                    \DB::table('detail_boq')->insert([
                        'boq_id' => $boq->id,
                        'produk_id' => $produkId,
                        'kode_produk' => $produk ? $produk->kode_produk : null,
                        'qty' => $qty,
                        'created_at' => now(),
                        'updated_at' => now()
                    ]);
                }
            }
            
            \Log::info('BOQ SAVED JENDELA SLIDING:', [
                'boq_id' => $boq->id,
                'nomor_boq' => $nomorBoq,
                'total' => count($uniqueResults)
            ]);
        }
        
    } catch (\Exception $e) {
        \Log::error('Error saving BOQ Jendela Sliding: ' . $e->getMessage());
        \Log::error($e->getTraceAsString());
    }

    $data = [
        'judul' => $judul,
        'panjang' => $panjang,
        'lebar' => $lebar,
        'tebal_kaca' => $tebal_kaca,
        'jumlah' => $jumlah,
        'warna' => $warna,
        'type_kaca' => $type_kaca,
        'luas_kaca_total' => $luasKacaTotal,
        'keliling_total' => $kelilingTotal,
        'batang_vertikal' => $batangVertikal,
        'batang_horizontal' => $batangHorizontal,
        'reinforcement_qty' => $reinforcementQty,
        'reinforcement_sash_qty' => $reinforcementSashQty,
        'batang_sash_vertikal_qty' => $batangSashVertikalQty,
        'batang_sash_horizontal_qty' => $batangSashHorizontalQty,
        'batang_glaze_vertikal_qty' => $batangGlazeVertikalQty,
        'batang_glaze_horizontal_qty' => $batangGlazeHorizontalQty,
        'batang_interlock_qty' => $batangInterlockQty,
        'track_qty' => $trackQty,
        'mohair_qty' => $mohairQty,
        'strike_qty' => $strikeQty,
        'lifting_qty' => $liftingQty,
