    } catch (\Exception $e) {
        \Log::error('Error saving BOQ Jendela Mati 3 Kaca 2 Mullion Vertikal 1 Mullion Horizontal: ' . $e->getMessage());
        \Log::error($e->getTraceAsString());
    }

    $data = [
