        $item->qty = $qty;
    }

    // Kelompokkan berdasarkan area untuk PDF
    $grouped = [];
    for ($i = 0; $i < count($aksesoris); $i++) {
        $item = $aksesoris[$i];
        if ($item->qty <= 0) {
            continue;
        }
        
        $areaSlug = $item->area ? $item->area->slug : 'lainnya';
        
        if (str_starts_with($areaSlug, 'profile')) {
            $groupKey = 'profile';
        } elseif ($areaSlug == 'reinforcement' || $areaSlug == 'reinforcement-mullion') {
            $groupKey = 'reinforcement';
        } elseif ($areaSlug == 'kaca' || $areaSlug == 'setting-block') {
