        'profile_coupling_vertikal' => $profileCouplingVertikal,
        'satuan_terkecil_coupling' => $satuanTerkecilCoupling,
        'variable_coupling_a' => $variableCouplingA,
        'variable_coupling_b' => $variableCouplingB,
