        'batang_vertikal' => $batangVertikal,
        
        'profile_horizontal' => $profileHorizontal,
        'satuan_terkecil_horizontal' => $satuanTerkecilHorizontal,
        'variable_b' => $variableB,
        'frame_horizontal' => $frameHorizontal,
        'batang_horizontal' => $batangHorizontal,
        
        'profile_mullion_vertikal' => $profileMullionVertikal,
        'satuan_terkecil_mullion_vertikal' => $satuanTerkecilMullionVertikal,
        'variable_mullion_vertikal_a' => $variableMullionVertikalA,
        'variable_mullion_vertikal_b' => $variableMullionVertikalB,
        'batang_mullion_vertikal' => $batangMullionVertikal,
