    ];

    return view('boq.jendela.jendela-swing-2-daun-2-mullion-vertikal-3-mullion-horizontal', $data);
}

public function exportPdfSwing2MullionVertikal3MullionHorizontal(Request $request)
{
    // Ambil data dari request
    $panjang = $request->panjang;
    $lebar = $request->lebar;
    $tebal_kaca = $request->tebal_kaca;
    $jumlah = $request->jumlah;
    $warna = $request->warna;
    $type_kaca = $request->type_kaca;
    $judul = $request->judul ?? 'BOQ - Jendela Swing 2 Daun (Mullion Vertikal 1 Horizontal)';

    // Ambil data aksesoris
    $aksesorisIds = ProductAccessories::where('parent_product_id', 263)->pluck('accessory_id');
    $aksesoris = Product::with('area', 'unit')
        ->whereIn('id', $aksesorisIds)
        ->get();

    // === PERHITUNGAN DASAR ===
    $panjangM = $panjang / 100;
    $lebarM = $lebar / 100;
    
    $luasKacaPerUnit = $panjangM * $lebarM;
    $luasKacaTotal = $luasKacaPerUnit * $jumlah;
    $luasKacaTotal = ceil($luasKacaTotal * 10) / 10;

    $kelilingPerUnit = 2 * ($panjangM + $lebarM);
    $kelilingTotal = $kelilingPerUnit * $jumlah;

    // === PERHITUNGAN PROFILE VERTIKAL ===
    $profileVertikal = null;
    $aksesorisCount = count($aksesoris);
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-vertikal') {
            $profileVertikal = $item;
            break;
        }
    }
    $satuanTerkecilVertikal = $profileVertikal ? (float)$profileVertikal->satuan_terkecil : 0;

    $variableA = $jumlah * 4;
    $frameVertikal = $variableA * $panjang;
    $batangVertikal = $frameVertikal / 580;
    $batangVertikal = ceil($batangVertikal * 10) / 10;
    $totalPanjang = $panjang * $variableA;

    // === PERHITUNGAN PROFILE HORIZONTAL ===
    $profileHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-horizontal') {
            $profileHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilHorizontal = $profileHorizontal ? (float)$profileHorizontal->satuan_terkecil : 0;
    
    $variableB = $jumlah * $satuanTerkecilHorizontal;
    $frameHorizontal = $variableB * $lebar;
    $batangHorizontal = $frameHorizontal / 580;
    $batangHorizontal = ceil($batangHorizontal * 10) / 10;
    $totalLebar = $lebar * $variableB;

    // === PERHITUNGAN PROFILE MULLION VERTIKAL ===
    $profileMullionVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-mullion-vertikal') {
            $profileMullionVertikal = $item;
            break;
        }
    }

    $satuanTerkecilMullionVertikal = $profileMullionVertikal ? (float)$profileMullionVertikal->satuan_terkecil : 0;
    
    $variableMullionVertikalA = 4 * $jumlah;
    $variableMullionVertikalB = $variableMullionVertikalA * $panjang;
    $batangMullionVertikal = $variableMullionVertikalB / 580;
    $batangMullionVertikalQty = ceil($batangMullionVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE MULLION HORIZONTAL ===
    $profileMullionHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-mullion-horizontal') {
            $profileMullionHorizontal = $item;
            break;
        }
    }

    $satuanTerkecilMullionHorizontal = $profileMullionHorizontal ? (float)$profileMullionHorizontal->satuan_terkecil : 0;
    
    $variableMullionHorizontalA = 6 * $jumlah;
    $variableMullionHorizontalB = $variableMullionHorizontalA * $lebar;
    $batangMullionHorizontal = $variableMullionHorizontalB / 580;
    $batangMullionHorizontalQty = ceil($batangMullionHorizontal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT ===
    $totalBatang = ($frameVertikal + $frameHorizontal) / 600;
    $reinforcementQty = ceil($totalBatang * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT MULLION ===
    $totalBatangMullion = ($variableMullionVertikalB + $variableMullionHorizontalB) / 600;
    $reinforcementMullionQty = ceil($totalBatangMullion * 10) / 10;

    // === PERHITUNGAN PROFILE SASH VERTIKAL ===
    $profileSashVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-vertikal') {
            $profileSashVertikal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashVertikal = $profileSashVertikal ? (float)$profileSashVertikal->satuan_terkecil : 0;
    
    $variableSashVertikalA = 4 * $jumlah;
    $variableSashVertikalB = $variableSashVertikalA * $panjang;
    $batangSashVertikal = $variableSashVertikalB / 580;
    $batangSashVertikalQty = ceil($batangSashVertikal * 10) / 10;

    // === PERHITUNGAN PROFILE SASH HORIZONTAL ===
    $profileSashHorizontal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-sash-horizontal') {
            $profileSashHorizontal = $item;
            break;
        }
    }
    
    $satuanTerkecilSashHorizontal = $profileSashHorizontal ? (float)$profileSashHorizontal->satuan_terkecil : 0;
    
    $variableSashHorizontalA = $satuanTerkecilSashHorizontal * $jumlah;
    $variableSashHorizontalB = $variableSashHorizontalA * $lebar;
    $batangSashHorizontal = $variableSashHorizontalB / 580;
    $batangSashHorizontalQty = ceil($batangSashHorizontal * 10) / 10;

    // === PERHITUNGAN REINFORCEMENT SASH ===
    $totalBatangSash = ($variableSashVertikalB + $variableSashHorizontalB) / 600;
    $reinforcementSashQty = ceil($totalBatangSash * 10) / 10;

    // === PERHITUNGAN PROFILE COUPLING VERTIKAL ===
    $profileCouplingVertikal = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'profile-coupling-vertikal') {
            $profileCouplingVertikal = $item;
            break;
        }
    }
    
    $satuanTerkecilCoupling = $profileCouplingVertikal ? (float)$profileCouplingVertikal->satuan_terkecil : 0;
    
    $variableCouplingA = $satuanTerkecilCoupling * $jumlah * 2;
    $variableCouplingB = $variableCouplingA * $panjang;
    $batangCoupling = $variableCouplingB / 580;
    $batangCouplingQty = ceil($batangCoupling * 10) / 10;

    // === PERHITUNGAN WINDOW HARDWARE TRANSMITTER ===
    $ukuranTransmitter = $panjang - 20;

    $transmitterMapping = [
        40 => 172,
        60 => 171,
        80 => 170,
        100 => 173,
        120 => 162,
        140 => 166,
        160 => 167,
        180 => 168,
        200 => 169,
    ];

    $ukuranTransmitterFinal = $ukuranTransmitter;
    if (!isset($transmitterMapping[$ukuranTransmitter])) {
        $availableSizes = array_keys($transmitterMapping);
        sort($availableSizes);
        
        $found = false;
        for ($i = 0; $i < count($availableSizes); $i++) {
            if ($availableSizes[$i] >= $ukuranTransmitter) {
                $ukuranTransmitterFinal = $availableSizes[$i];
                $found = true;
                break;
            }
        }
        
        if (!$found) {
            $ukuranTransmitterFinal = max($availableSizes);
        }
    }

    $transmitterItem = null;
    $transmitterId = $transmitterMapping[$ukuranTransmitterFinal] ?? null;

    if ($transmitterId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $transmitterId) {
                $transmitterItem = $item;
                break;
            }
        }
    }

    $totalWindowHardwareTransmitterQty = 0;
    if ($transmitterItem) {
        $satuanTerkecil = (float)($transmitterItem->satuan_terkecil ?? 0);
        $qty = $jumlah * 2;
        $transmitterItem->qty = $qty;
        $totalWindowHardwareTransmitterQty += $qty;
    }

    // === PERHITUNGAN WINDOW HARDWARE FRICTION STAY ===
    $ukuranFrictionStay = $panjang / 3;

    $frictionStayMapping = [
        25 => 175,
        30 => 174,
        35 => 179,
        40 => 173,
        45 => 176,
        50 => 177,
        60 => 178,
    ];

    $ukuranFrictionStayFinal = $ukuranFrictionStay;
    if (!isset($frictionStayMapping[$ukuranFrictionStay])) {
        $availableSizes = array_keys($frictionStayMapping);
        sort($availableSizes);
        
        $found = false;
        for ($i = 0; $i < count($availableSizes); $i++) {
            if ($availableSizes[$i] >= $ukuranFrictionStay) {
                $ukuranFrictionStayFinal = $availableSizes[$i];
                $found = true;
                break;
            }
        }
        
        if (!$found) {
            $ukuranFrictionStayFinal = max($availableSizes);
        }
    }

    $frictionStayItem = null;
    $frictionStayId = $frictionStayMapping[$ukuranFrictionStayFinal] ?? null;

    if ($frictionStayId) {
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->id == $frictionStayId) {
                $frictionStayItem = $item;
                break;
            }
        }
    }

    $totalWindowHardwareFrictionStayQty = 0;
    if ($frictionStayItem) {
        $satuanTerkecil = (float)($frictionStayItem->satuan_terkecil ?? 0);
        $qty = $jumlah * 4;
        $frictionStayItem->qty = $qty;
        $totalWindowHardwareFrictionStayQty += $qty;
    }

    // === PERHITUNGAN WINDOW HARDWARE HANDLE ===
    $handleItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'window-hardware-handle') {
            $handleItem = $item;
            break;
        }
    }

    $totalWindowHardwareHandleQty = 0;
    if ($handleItem) {
        $satuanTerkecil = (float)($handleItem->satuan_terkecil ?? 0);
        $qty = $jumlah * 2;
        $handleItem->qty = $qty;
        $totalWindowHardwareHandleQty += $qty;
    }

    // === PERHITUNGAN SCREW TRANSMITTER ===
    $screwTransmitterItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-transmitter') {
            $screwTransmitterItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewTransmitter = $screwTransmitterItem ? (float)$screwTransmitterItem->satuan_terkecil : 0;
    $screwTransmitterQty = ($totalWindowHardwareTransmitterQty * $satuanTerkecilScrewTransmitter);
    if ($screwTransmitterItem) {
        $screwTransmitterItem->qty = $screwTransmitterQty;
    }

    // === PERHITUNGAN SCREW FRICTION STAY ===
    $screwFrictionStayItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-friction-stay') {
            $screwFrictionStayItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewFrictionStay = $screwFrictionStayItem ? (float)$screwFrictionStayItem->satuan_terkecil : 0;
    $screwFrictionStayQty = $totalWindowHardwareFrictionStayQty * $satuanTerkecilScrewFrictionStay;
    if ($screwFrictionStayItem) {
        $screwFrictionStayItem->qty = $screwFrictionStayQty;
    }

    // === PERHITUNGAN SCREW HANDLE ===
    $screwHandleItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-handle') {
            $screwHandleItem = $item;
            break;
        }
    }

    $satuanTerkecilScrewHandle = $screwHandleItem ? (float)$screwHandleItem->satuan_terkecil : 0;
    $screwHandleQty = $totalWindowHardwareHandleQty * $satuanTerkecilScrewHandle;
    if ($screwHandleItem) {
        $screwHandleItem->qty = $screwHandleQty;
    }

    // === PERHITUNGAN SETTING BLOCK ===
    $settingBlockItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'setting-block') {
            $settingBlockItem = $item;
            break;
        }
    }
    
    $satuanTerkecilSettingBlock = $settingBlockItem ? (float)$settingBlockItem->satuan_terkecil : 0;
    
    $variableC = 2 * $satuanTerkecilSettingBlock;
    $variableD = $variableC * $jumlah;
    $variableE = $variableD * 25;
    $variableF = $variableE / 1000;
    $settingBlockQty = ceil($variableF);

    // === PERHITUNGAN SCREW REINFORCEMENT ===
    $screwItem = null;
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->area && $item->area->slug == 'screw-reinforcement') {
            $screwItem = $item;
            break;
        }
    }
    
    $satuanTerkecilScrew = $screwItem ? (float)$screwItem->satuan_terkecil : 0;
    $screwQty = ((($totalLebar + $totalPanjang)) + ($variableSashVertikalB + $variableSashHorizontalB) + ($variableMullionVertikalB + $variableMullionHorizontalB)) / $satuanTerkecilScrew;
    $screwQty = ceil($screwQty * 10);

    // === HITUNG QTY PER AKSESORIS ===
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        $areaSlug = $item->area ? $item->area->slug : '';
        $qty = 0;
        
        if ($areaSlug == 'profile-vertikal') {
            $qty = $batangVertikal;
        } elseif ($areaSlug == 'profile-horizontal') {
            $qty = $batangHorizontal;
        } elseif ($areaSlug == 'profile-mullion-vertikal') {
            $qty = $batangMullionVertikalQty;
        } elseif ($areaSlug == 'profile-mullion-horizontal') {
            $qty = $batangMullionHorizontalQty;
        } elseif ($areaSlug == 'glaze-bead-vertical') {
            $qty = ($panjang / 100) * $jumlah;
        } elseif ($areaSlug == 'glaze-bead-horizontal') {
            $qty = ($lebar / 100) * $jumlah;
        } elseif ($areaSlug == 'reinforcement') {
            $qty = $reinforcementQty;
        } elseif ($areaSlug == 'reinforcement-sash') {
            $qty = $reinforcementSashQty;
        } elseif ($areaSlug == 'reinforcement-mullion') {
            $qty = $reinforcementMullionQty;
        } elseif ($areaSlug == 'kaca') {
            $qty = $luasKacaTotal;
        } elseif ($areaSlug == 'screw-reinforcement') {
            $qty = $screwQty;
        } elseif ($areaSlug == 'setting-block') {
            $qty = $settingBlockQty;
        } elseif ($areaSlug == 'profile-sash-vertikal') {
            $qty = $batangSashVertikalQty;
        } elseif ($areaSlug == 'profile-sash-horizontal') {
            $qty = $batangSashHorizontalQty;
        } elseif ($areaSlug == 'window-hardware-transmitter') {
            $qty = ($transmitterItem && $transmitterItem->id == $item->id) ? $transmitterItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-friction-stay') {
            $qty = ($frictionStayItem && $frictionStayItem->id == $item->id) ? $frictionStayItem->qty : 0;
        } elseif ($areaSlug == 'window-hardware-handle') {
            $qty = $handleItem ? $handleItem->qty : 0;
        } elseif ($areaSlug == 'profile-coupling-vertikal') {
            $qty = $batangCouplingQty;
        } elseif ($areaSlug == 'screw-transmitter') {
            $qty = $screwTransmitterQty;
        } elseif ($areaSlug == 'screw-friction-stay') {
            $qty = $screwFrictionStayQty;
        } elseif ($areaSlug == 'screw-handle') {
            $qty = $screwHandleQty;
        } else {
            $qty = $jumlah * ($item->satuan_terkecil ?? 1);
        }
        
        $item->qty = $qty;
    }

    // Kelompokkan berdasarkan area
    $grouped = [];
    for ($i = 0; $i < $aksesorisCount; $i++) {
        $item = $aksesoris[$i];
        if ($item->qty <= 0) {
            continue;
        }
        
        // Skip transmitter, friction stay, handle yang tidak terpilih (qty 0)
        if ($item->area && ($item->area->slug == 'window-hardware-transmitter' || $item->area->slug == 'window-hardware-friction-stay' || $item->area->slug == 'window-hardware-handle') && $item->qty <= 0) {
            continue;
        }
        
        $areaSlug = $item->area ? $item->area->slug : 'lainnya';
        
        if (str_starts_with($areaSlug, 'profile')) {
            $groupKey = 'profile';
        } elseif ($areaSlug == 'setting-block') {
            $groupKey = 'kaca';
        } elseif ($areaSlug == 'reinforcement' || $areaSlug == 'reinforcement-sash' || $areaSlug == 'reinforcement-mullion') {
            $groupKey = 'reinforcement';
        } elseif (str_starts_with($areaSlug, 'window-hardware')) {
            $groupKey = 'window-hardware';
        } elseif ($areaSlug == 'screw-reinforcement' || $areaSlug == 'screw-transmitter' || $areaSlug == 'screw-friction-stay' || $areaSlug == 'screw-handle') {
            $groupKey = 'screw';
        } else {
            $groupKey = $areaSlug;
        }
        
        if (!isset($grouped[$groupKey])) {
            $grouped[$groupKey] = [];
        }
        $grouped[$groupKey][] = $item;
    }

    $areaLabels = [
        'profile' => 'PROFILE',
        'reinforcement' => 'REINFORCEMENT',
        'kaca' => 'KACA',
        'screw' => 'SCREW',
        'window-hardware' => 'WINDOW HARDWARE',
    ];

    // ============ GENERATE NOMOR BOQ ============
    $nomorBoq = Boq::generateNomorBoq();

    // ============ STORE BOQ ============
    try {
        $allResults = [];
        
        for ($i = 0; $i < $aksesorisCount; $i++) {
            $item = $aksesoris[$i];
            if ($item->qty > 0) {
                $allResults[] = [
                    'produk_id' => $item->id,
                    'qty' => $item->qty,
                    'nama_produk' => $item->nama_produk,
                ];
            }
        }
        
        $uniqueResults = [];
        $seenIds = [];
        $allResultsCount = count($allResults);
        
        for ($i = 0; $i < $allResultsCount; $i++) {
            $item = $allResults[$i];
            $produkId = $item['produk_id'] ?? null;
            
            if (!$produkId) {
                continue;
            }
            
            $isDuplicate = false;
            $seenCount = count($seenIds);
            for ($j = 0; $j < $seenCount; $j++) {
                if ($seenIds[$j] == $produkId) {
                    $isDuplicate = true;
                    break;
                }
            }
            
            if ($isDuplicate) {
                continue;
            }
            
            $seenIds[] = $produkId;
            $uniqueResults[] = $item;
        }
        
        if (count($uniqueResults) > 0) {
            $boq = new Boq();
            $boq->nomor_boq = $nomorBoq;
            $boq->tanggal_boq = now();
            $boq->save();
            
            $uniqueCount = count($uniqueResults);
            for ($i = 0; $i < $uniqueCount; $i++) {
                $item = $uniqueResults[$i];
                $produkId = $item['produk_id'] ?? null;
                $qty = (int)($item['qty'] ?? 0);
                
                if ($produkId && $qty > 0) {
                    $produk = Product::find($produkId);
                    
                    \DB::table('detail_boq')->insert([
                        'boq_id' => $boq->id,
                        'produk_id' => $produkId,
                        'kode_produk' => $produk ? $produk->kode_produk : null,
                        'qty' => $qty,
                        'created_at' => now(),
                        'updated_at' => now()
                    ]);
                }
            }
            
            \Log::info('BOQ SAVED JENDELA SWING 2 MULLION VERTIKAL 1 HORIZONTAL:', [
                'boq_id' => $boq->id,
                'nomor_boq' => $nomorBoq,
                'total' => count($uniqueResults)
            ]);
        }
        
    } catch (\Exception $e) {
        \Log::error('Error saving BOQ Jendela Swing 2 Mullion Vertikal 1 Horizontal: ' . $e->getMessage());
        \Log::error($e->getTraceAsString());
    }

    $data = [
        'judul' => $judul,
        'panjang' => $panjang,
        'lebar' => $lebar,
        'tebal_kaca' => $tebal_kaca,
        'jumlah' => $jumlah,
        'warna' => $warna,
        'type_kaca' => $type_kaca,
        'luas_kaca_total' => $luasKacaTotal,
        'keliling_total' => $kelilingTotal,
        'batang_vertikal' => $batangVertikal,
        'batang_horizontal' => $batangHorizontal,
        'batang_mullion_vertikal_qty' => $batangMullionVertikalQty,
        'batang_mullion_horizontal_qty' => $batangMullionHorizontalQty,
        'reinforcement_qty' => $reinforcementQty,
        'reinforcement_mullion_qty' => $reinforcementMullionQty,
        'batang_sash_vertikal_qty' => $batangSashVertikalQty,
        'batang_sash_horizontal_qty' => $batangSashHorizontalQty,
        'reinforcement_sash_qty' => $reinforcementSashQty,
        'batang_coupling_qty' => $batangCouplingQty,
        'transmitter_item' => $transmitterItem,
        'ukuran_transmitter' => $ukuranTransmitter,
        'ukuran_transmitter_final' => $ukuranTransmitterFinal,
        'total_window_hardware_transmitter_qty' => $totalWindowHardwareTransmitterQty,
        'friction_stay_item' => $frictionStayItem,
        'ukuran_friction_stay' => $ukuranFrictionStay,
        'ukuran_friction_stay_final' => $ukuranFrictionStayFinal,
        'total_window_hardware_friction_stay_qty' => $totalWindowHardwareFrictionStayQty,
        'handle_item' => $handleItem,
        'total_window_hardware_handle_qty' => $totalWindowHardwareHandleQty,
        'screw_transmitter_qty' => $screwTransmitterQty,
        'screw_friction_stay_qty' => $screwFrictionStayQty,
        'screw_handle_qty' => $screwHandleQty,
        'screw_qty' => $screwQty,
        'setting_block_qty' => $settingBlockQty,
        'grouped' => $grouped,
        'areaLabels' => $areaLabels,
        'nomor_boq' => $nomorBoq,
    ];

    return view('boq.jendela.pdf-jendela-swing-2-mullion-vertikal-3-mullion-horizontal', compact('data'));
}

 public function hitungBouvenSilang(Request $request)
{
    $request->validate([
        'panjang' => 'required|numeric|min:1',
        'lebar' => 'required|numeric|min:1',
        'tebal_kaca' => 'required|numeric|min:1',
        'jumlah' => 'required|numeric|min:1',
        'warna' => 'required|string',
        'type_kaca' => 'required|string',
    ]);

    // Ambil data dari form
    $panjang = $request->panjang; // cm
    $lebar = $request->lebar; // cm
    $tebalKaca = $request->tebal_kaca; // mm
    $jumlah = $request->jumlah;
    $warna = $request->warna;
    $typeKaca = $request->type_kaca;

    // Ambil produk utama (Jendela Mati 1 Kaca) dari database
    $produkUtama = Product::find(265);
    
    if (!$produkUtama) {
        return back()->with('error', 'Produk Jendela Mati 1 Kaca tidak ditemukan!');
    }

    // Ambil aksesoris dari tabel product_accessories dengan relasi area
    $aksesorisIds = ProductAccessories::where('parent_product_id', 265)->pluck('accessory_id');
    $aksesoris = Product::with('area', 'unit')
        ->whereIn('id', $aksesorisIds)
        ->get();

    // === PERHITUNGAN DASAR ===
    
    // Konversi ke meter
    $panjangM = $panjang / 100;
    $lebarM = $lebar / 100;
    $tebalKacaM = $tebalKaca / 1000;

    // 1. Luas Kaca (m²)
    $luasKacaPerUnit = $panjangM * $lebarM;
    $luasKacaTotal = $luasKacaPerUnit * $jumlah;
    $luasKacaTotal = ceil($luasKacaTotal * 10) / 10; // Round up ke 1 desimal

    // 2. Keliling Profile (meter)
    $kelilingPerUnit = 2 * ($panjangM + $lebarM);
    $kelilingTotal = $kelilingPerUnit * $jumlah;

    // 3. Keliling Kaca (meter) - untuk perhitungan lem
    $kelilingKacaPerUnit = 2 * ($panjangM + $lebarM);
    $kelilingKacaTotal = $kelilingKacaPerUnit * $jumlah;

    // === PERHITUNGAN PROFILE VERTIKAL ===
    $profileVertikal = $aksesoris->filter(function($item) {
        return $item->area && $item->area->slug == 'profile-vertikal';
    })->first();
    
    $satuanTerkecilVertikal = $profileVertikal ? (float)$profileVertikal->satuan_terkecil : 0;
    
    $variableA = $jumlah * $satuanTerkecilVertikal;
    $frameVertikal = $variableA * $panjang;
    $batangVertikal = $frameVertikal / 580;
    $batangVertikal = ceil($batangVertikal * 10) / 10;
    $totalPanjang = $panjang * $variableA;

    // === PERHITUNGAN PROFILE HORIZONTAL ===
    $profileHorizontal = $aksesoris->filter(function($item) {
        return $item->area && $item->area->slug == 'profile-horizontal';
    })->first();
    
    $satuanTerkecilHorizontal = $profileHorizontal ? (float)$profileHorizontal->satuan_terkecil : 0;
    
    $variableB = $jumlah * $satuanTerkecilHorizontal;
    $frameHorizontal = $variableB * $lebar;
    $batangHorizontal = $frameHorizontal / 580;
    $batangHorizontal = ceil($batangHorizontal * 10) / 10;
    $totalLebar = $lebar * $variableB;

    // === PERHITUNGAN REINFORCEMENT ===
    // Reinforcement = total batang (vertikal + horizontal)
    $totalBatang = $batangVertikal + $batangHorizontal;
    $reinforcementQty = ceil($totalBatang * 10) / 10;

    // === PERHITUNGAN LEM / SEALANT ===
    // Lem dihitung berdasarkan keliling kaca total (dalam meter)
    // Dikalikan dengan koefisien lem (misal 0.5 kg per meter)
    $koefisienLem = 0.5; // kg per meter (sesuaikan dengan kebutuhan)
    $lemQty = $kelilingKacaTotal * $koefisienLem;
    $lemQty = ceil($lemQty * 10) / 10; // Round up ke 1 desimal

    // === PERHITUNGAN SCREW ===
    // Screw = qty reinforcement / satuan_terkecil screw
    $screwItem = $aksesoris->filter(function($item) {
        return $item->area && $item->area->slug == 'screw-reinforcement';
    })->first();
    
    $satuanTerkecilScrew = $screwItem ? (float)$screwItem->satuan_terkecil : 0;
    $screwQty = ($totalLebar + $totalPanjang) / $satuanTerkecilScrew;
    $screwQty = ceil($screwQty * 10);

    // === PERHITUNGAN QTY PER AKSESORIS ===
    foreach ($aksesoris as $item) {
        $areaSlug = $item->area ? $item->area->slug : '';
        $qty = 0;
        
        // Tentukan qty berdasarkan area slug
        if ($areaSlug == 'profile-vertikal' ) {
            $qty = $batangVertikal;
        } elseif ($areaSlug == 'profile-horizontal' ) {
            $qty = $batangHorizontal;
        } elseif ($areaSlug == 'reinforcement') {
            $qty = $reinforcementQty;
        } elseif ($areaSlug == 'kaca') {
            $qty = $luasKacaTotal;
        } elseif ($areaSlug == 'screw-reinforcement') {
            $qty = $screwQty;
        } elseif ($areaSlug == 'lem') {
            $qty = $lemQty;
        } else {
            $qty = $jumlah * ($item->satuan_terkecil ?? 1);
        }
        
        $item->qty = $qty;
    }

    // Data untuk view
    $data = [
        'produk' => $produkUtama,
        'panjang' => $panjang,
        'lebar' => $lebar,
        'tebal_kaca' => $tebalKaca,
        'jumlah' => $jumlah,
        'warna' => $warna,
        'type_kaca' => $typeKaca,
        
        // Perhitungan dasar
        'luas_kaca_per_unit' => $luasKacaPerUnit,
        'luas_kaca_total' => $luasKacaTotal,
        'keliling_per_unit' => $kelilingPerUnit,
        'keliling_total' => $kelilingTotal,
        'keliling_kaca_per_unit' => $kelilingKacaPerUnit,
        'keliling_kaca_total' => $kelilingKacaTotal,
        
        // Perhitungan Profile Vertikal
        'profile_vertikal' => $profileVertikal,
        'satuan_terkecil_vertikal' => $satuanTerkecilVertikal,
        'variable_a' => $variableA,
        'frame_vertikal' => $frameVertikal,
        'batang_vertikal' => $batangVertikal,
        
        // Perhitungan Profile Horizontal
        'profile_horizontal' => $profileHorizontal,
        'satuan_terkecil_horizontal' => $satuanTerkecilHorizontal,
        'variable_b' => $variableB,
        'frame_horizontal' => $frameHorizontal,
        'batang_horizontal' => $batangHorizontal,
        
        // Perhitungan Reinforcement
        'total_batang' => $totalBatang,
        'reinforcement_qty' => $reinforcementQty,
        
        // Perhitungan Lem
        'koefisien_lem' => $koefisienLem,
        'lem_qty' => $lemQty,
        
        // Perhitungan Screw
        'satuan_terkecil_screw' => $satuanTerkecilScrew,
        'screw_qty' => $screwQty,
        
        // Data aksesoris dengan qty
        'aksesoris' => $aksesoris,
    ];

    return view('boq.jendela.jendela-bouven-silang', $data);
}
public function exportPdfBouvenSilang(Request $request)
{
    $panjang = $request->panjang;
    $lebar = $request->lebar;
    $tebal_kaca = $request->tebal_kaca;
    $jumlah = $request->jumlah;
    $warna = $request->warna;
    $type_kaca = $request->type_kaca;
    $judul = $request->judul ?? 'BOQ - Jendela Mati 1 Kaca';

    // Ambil data aksesoris
    $aksesorisIds = ProductAccessories::where('parent_product_id', 265)->pluck('accessory_id');
    $aksesoris = Product::with('area', 'unit')
        ->whereIn('id', $aksesorisIds)
        ->get();

    // === PERHITUNGAN DASAR ===
    $panjangM = $panjang / 100;
    $lebarM = $lebar / 100;
    
    $luasKacaPerUnit = $panjangM * $lebarM;
    $luasKacaTotal = $luasKacaPerUnit * $jumlah;
    $luasKacaTotal = ceil($luasKacaTotal * 10) / 10;

    $kelilingPerUnit = 2 * ($panjangM + $lebarM);
    $kelilingTotal = $kelilingPerUnit * $jumlah;

    // === PERHITUNGAN PROFILE VERTIKAL ===
    $profileVertikal = $aksesoris->filter(function($item) {
        return $item->area && $item->area->slug == 'profile-vertikal';
    })->first();
    
    $satuanTerkecilVertikal = $profileVertikal ? (float)$profileVertikal->satuan_terkecil : 0;
    $variableA = $jumlah * $satuanTerkecilVertikal;
    $frameVertikal = $variableA * $panjang;
    $batangVertikal = $frameVertikal / 580;
    $batangVertikal = ceil($batangVertikal * 10) / 10;
    $totalPanjang = $panjang * $variableA;

    // === PERHITUNGAN PROFILE HORIZONTAL ===
    $profileHorizontal = $aksesoris->filter(function($item) {
        return $item->area && $item->area->slug == 'profile-horizontal';
    })->first();
    
    $satuanTerkecilHorizontal = $profileHorizontal ? (float)$profileHorizontal->satuan_terkecil : 0;
    $variableB = $jumlah * $satuanTerkecilHorizontal;
    $frameHorizontal = $variableB * $lebar;
    $batangHorizontal = $frameHorizontal / 580;
    $batangHorizontal = ceil($batangHorizontal * 10) / 10;
    $totalLebar = $lebar * $variableB;

    // === PERHITUNGAN REINFORCEMENT ===
    $totalBatang = $batangVertikal + $batangHorizontal;
    $reinforcementQty = ceil($totalBatang * 10) / 10;

    // === PERHITUNGAN SCREW ===
    $screwItem = $aksesoris->filter(function($item) {
        return $item->area && $item->area->slug == 'screw-reinforcement';
    })->first();
    $satuanTerkecilScrew = $screwItem ? (float)$screwItem->satuan_terkecil : 1;
    $screwQty = ($totalLebar + $totalPanjang) / $satuanTerkecilScrew;
    $screwQty = ceil($screwQty * 10);

    // === PERHITUNGAN SETTING BLOCK ===
    $settingBlockItem = $aksesoris->filter(function($item) {
        return $item->area && $item->area->slug == 'setting-block';
    })->first();
    
    $satuanTerkecilSettingBlock = $settingBlockItem ? (float)$settingBlockItem->satuan_terkecil : 0;
    
    // variable c = 1 x satuan terkecil
    $variableC = 1 * $satuanTerkecilSettingBlock;
    
    // variable d = variable c x jumlah
    $variableD = $variableC * $jumlah;
    
    // variable e = variable d x 25
    $variableE = $variableD * 25;
    
    // variable f = variable e / 1000
    $variableF = $variableE / 1000;
    
    // variable g -> qty = ROUNDUP(variable e, 0)
    $settingBlockQty = ceil($variableF);

    // === HITUNG QTY PER AKSESORIS ===
    foreach ($aksesoris as $item) {
        $areaSlug = $item->area ? $item->area->slug : '';
        $qty = 0;
        
        if ($areaSlug == 'profile-vertikal') {
            $qty = $batangVertikal;
        } elseif ($areaSlug == 'profile-horizontal') {
            $qty = $batangHorizontal;
        }  elseif ($areaSlug == 'reinforcement') {
            $qty = $reinforcementQty;
        } elseif ($areaSlug == 'kaca') {
            $qty = $luasKacaTotal;
        } elseif ($areaSlug == 'screw-reinforcement') {
            $qty = $screwQty;
        } elseif ($areaSlug == 'setting-block') {
            $qty = $settingBlockQty;
        } else {
            $qty = $jumlah * ($item->satuan_terkecil ?? 1);
        }
        
        $item->qty = $qty;
    }

    // Kelompokkan berdasarkan area
    $grouped = [];
    foreach ($aksesoris as $item) {
        $areaSlug = $item->area ? $item->area->slug : 'lainnya';
        if (str_starts_with($areaSlug, 'profile')) {
            $groupKey = 'profile';
        } else {
            $groupKey = $areaSlug;
        }
        if (!isset($grouped[$groupKey])) {
            $grouped[$groupKey] = [];
        }
        $grouped[$groupKey][] = $item;
    }

    $areaLabels = [
        'profile' => 'PROFILE',
        'reinforcement' => 'REINFORCEMENT',
        'kaca' => 'KACA',
        'screw' => 'SCREW',
        'setting-block' => 'SETTING BLOCK',
    ];

    // ============ GENERATE NOMOR BOQ ============
    $nomorBoq = Boq::generateNomorBoq();

    // ============ STORE BOQ ============
    try {
        $allResults = [];
        
        // Kumpulkan semua hasil dari aksesoris
        foreach ($aksesoris as $item) {
            if ($item->qty > 0) {
                $allResults[] = [
                    'produk_id' => $item->id,
                    'qty' => $item->qty,
                    'nama_produk' => $item->nama_produk,
                ];
            }
        }
        
        // Filter duplikat berdasarkan produk_id
        $uniqueResults = [];
        $seenIds = [];
        
        foreach ($allResults as $item) {
            $produkId = $item['produk_id'] ?? null;
            
            if (!$produkId) {
                continue;
            }
            
            if (in_array($produkId, $seenIds)) {
                continue;
            }
            
            $seenIds[] = $produkId;
            $uniqueResults[] = $item;
        }
        
        // Simpan ke database
        if (count($uniqueResults) > 0) {
            $boq = new Boq();
            $boq->nomor_boq = $nomorBoq;
            $boq->tanggal_boq = now();
            $boq->save();
            
            foreach ($uniqueResults as $item) {
                $produkId = $item['produk_id'] ?? null;
                $qty = (int)($item['qty'] ?? 0);
                
                if ($produkId && $qty > 0) {
                    $produk = Product::find($produkId);
                    
                    \DB::table('detail_boq')->insert([
                        'boq_id' => $boq->id,
                        'produk_id' => $produkId,
                        'kode_produk' => $produk ? $produk->kode_produk : null,
                        'qty' => $qty,
                        'created_at' => now(),
                        'updated_at' => now()
                    ]);
                }
            }
            
            \Log::info('BOQ SAVED JENDELA MATI 1:', [
                'boq_id' => $boq->id,
                'nomor_boq' => $nomorBoq,
                'total' => count($uniqueResults)
            ]);
        }
        
    } catch (\Exception $e) {
        \Log::error('Error saving BOQ Jendela Mati 1: ' . $e->getMessage());
        \Log::error($e->getTraceAsString());
    }

    $data = [
        'judul' => $judul,
        'panjang' => $panjang,
        'lebar' => $lebar,
        'tebal_kaca' => $tebal_kaca,
        'jumlah' => $jumlah,
        'warna' => $warna,
        'type_kaca' => $type_kaca,
        'luas_kaca_total' => $luasKacaTotal,
        'keliling_total' => $kelilingTotal,
        'batang_vertikal' => $batangVertikal,
        'batang_horizontal' => $batangHorizontal,
        'reinforcement_qty' => $reinforcementQty,
        'screw_qty' => $screwQty,
        'setting_block_qty' => $settingBlockQty,
        'grouped' => $grouped,
        'areaLabels' => $areaLabels,
        'nomor_boq' => $nomorBoq,
    ];

    // Return view PDF (bukan stream/download)
    return view('boq.jendela.pdf-jendela-bouven-silang', compact('data'));
}

 public function hitungBouven1(Request $request)
{
    $request->validate([
        'panjang' => 'required|numeric|min:1',
        'lebar' => 'required|numeric|min:1',
        'tebal_kaca' => 'required|numeric|min:1',
        'jumlah' => 'required|numeric|min:1',
        'warna' => 'required|string',
        'type_kaca' => 'required|string',
    ]);

    // Ambil data dari form
    $panjang = $request->panjang; // cm
    $lebar = $request->lebar; // cm
    $tebalKaca = $request->tebal_kaca; // mm
    $jumlah = $request->jumlah;
    $warna = $request->warna;
    $typeKaca = $request->type_kaca;

    // Ambil produk utama (Jendela Mati 1 Kaca) dari database
    $produkUtama = Product::find(266);
    
    if (!$produkUtama) {
        return back()->with('error', 'Produk Jendela Mati 1 Kaca tidak ditemukan!');
    }

    // Ambil aksesoris dari tabel product_accessories dengan relasi area
    $aksesorisIds = ProductAccessories::where('parent_product_id', 266)->pluck('accessory_id');
    $aksesoris = Product::with('area', 'unit')
        ->whereIn('id', $aksesorisIds)
        ->get();

    // === PERHITUNGAN DASAR ===
    
    // Konversi ke meter
    $panjangM = $panjang / 100;
    $lebarM = $lebar / 100;
    $tebalKacaM = $tebalKaca / 1000;

    // 1. Luas Kaca (m²)
    $luasKacaPerUnit = $panjangM * $lebarM;
    $luasKacaTotal = $luasKacaPerUnit * $jumlah;
    $luasKacaTotal = ceil($luasKacaTotal * 10) / 10; // Round up ke 1 desimal

    // 2. Keliling Profile (meter)
    $kelilingPerUnit = 2 * ($panjangM + $lebarM);
    $kelilingTotal = $kelilingPerUnit * $jumlah;

    // === PERHITUNGAN PROFILE VERTIKAL ===
    $profileVertikal = $aksesoris->filter(function($item) {
        return $item->area && $item->area->slug == 'profile-vertikal';
    })->first();
    
    $satuanTerkecilVertikal = $profileVertikal ? (float)$profileVertikal->satuan_terkecil : 0;
    
    $variableA = $jumlah * 2;
    $frameVertikal = $variableA * $panjang;
    $batangVertikal = $frameVertikal / 580;
    $batangVertikal = ceil($batangVertikal * 10) / 10;
    $totalPanjang = $panjang * $variableA;

    // === PERHITUNGAN PROFILE HORIZONTAL ===
    $profileHorizontal = $aksesoris->filter(function($item) {
        return $item->area && $item->area->slug == 'profile-horizontal';
    })->first();
    
    $satuanTerkecilHorizontal = $profileHorizontal ? (float)$profileHorizontal->satuan_terkecil : 0;
    
    $variableB = $jumlah * 2;
    $frameHorizontal = $variableB * $lebar;
    $batangHorizontal = $frameHorizontal / 580;
    $batangHorizontal = ceil($batangHorizontal * 10) / 10;
    $totalLebar = $lebar * $variableB;

    // === PERHITUNGAN REINFORCEMENT ===
    // Reinforcement = total batang (vertikal + horizontal)
    $totalBatang = $batangVertikal + $batangHorizontal;
    $reinforcementQty = ceil($totalBatang * 10) / 10;

    // === PERHITUNGAN SETTING BLOCK ===
    $settingBlockItem = $aksesoris->filter(function($item) {
        return $item->area && $item->area->slug == 'setting-block';
    })->first();
    
    $satuanTerkecilSettingBlock = $settingBlockItem ? (float)$settingBlockItem->satuan_terkecil : 0;
    
    // variable c = 1 x satuan terkecil
    $variableC = 1 * $satuanTerkecilSettingBlock;
    
    // variable d = variable c x jumlah
    $variableD = $variableC * $jumlah;
    
    // variable e = variable d x 25
    $variableE = $variableD * 25;
    
    // variable f = variable e / 1000
    $variableF = $variableE / 1000;
    
    // variable g -> qty = ROUNDUP(variable e, 0)
    $settingBlockQty = ceil($variableF);

    // === PERHITUNGAN SCREW ===
    // Screw = qty reinforcement / satuan_terkecil screw
    $screwItem = $aksesoris->filter(function($item) {
        return $item->area && $item->area->slug == 'screw-reinforcement';
    })->first();
    
    $satuanTerkecilScrew = $screwItem ? (float)$screwItem->satuan_terkecil : 0;
    $screwQty = ($totalLebar + $totalPanjang) / $satuanTerkecilScrew;
    $screwQty = ceil($screwQty * 10);

    // === PERHITUNGAN QTY PER AKSESORIS ===
    foreach ($aksesoris as $item) {
        $areaSlug = $item->area ? $item->area->slug : '';
        $qty = 0;
        
        // Tentukan qty berdasarkan area slug
        if ($areaSlug == 'profile-vertikal') {
            $qty = $batangVertikal;
        } elseif ($areaSlug == 'profile-horizontal') {
            $qty = $batangHorizontal;
        } elseif ($areaSlug == 'reinforcement') {
            $qty = $reinforcementQty;
        } elseif ($areaSlug == 'kaca') {
            $qty = $luasKacaTotal;
        } elseif ($areaSlug == 'screw-reinforcement') {
            $qty = $screwQty;
        } elseif ($areaSlug == 'setting-block') {
            $qty = $settingBlockQty;
        } else {
            $qty = $jumlah * ($item->satuan_terkecil ?? 1);
        }
        
        $item->qty = $qty;
    }

    // Data untuk view
    $data = [
        'produk' => $produkUtama,
        'panjang' => $panjang,
        'lebar' => $lebar,
        'tebal_kaca' => $tebalKaca,
        'jumlah' => $jumlah,
        'warna' => $warna,
        'type_kaca' => $typeKaca,
        
        // Perhitungan dasar
        'luas_kaca_per_unit' => $luasKacaPerUnit,
        'luas_kaca_total' => $luasKacaTotal,
        'keliling_per_unit' => $kelilingPerUnit,
        'keliling_total' => $kelilingTotal,
        
        // Perhitungan Profile Vertikal
        'profile_vertikal' => $profileVertikal,
        'satuan_terkecil_vertikal' => $satuanTerkecilVertikal,
        'variable_a' => $variableA,
        'frame_vertikal' => $frameVertikal,
        'batang_vertikal' => $batangVertikal,
        
        // Perhitungan Profile Horizontal
        'profile_horizontal' => $profileHorizontal,
        'satuan_terkecil_horizontal' => $satuanTerkecilHorizontal,
        'variable_b' => $variableB,
        'frame_horizontal' => $frameHorizontal,
        'batang_horizontal' => $batangHorizontal,
        
        // Perhitungan Reinforcement
        'total_batang' => $totalBatang,
        'reinforcement_qty' => $reinforcementQty,
        
        // Perhitungan Setting Block
        'setting_block_item' => $settingBlockItem,
        'satuan_terkecil_setting_block' => $satuanTerkecilSettingBlock,
        'variable_c' => $variableC,
        'variable_d' => $variableD,
        'variable_e' => $variableE,
        'variable_f' => $variableF,
        'setting_block_qty' => $settingBlockQty,
        
        // Perhitungan Screw
        'satuan_terkecil_screw' => $satuanTerkecilScrew,
        'screw_qty' => $screwQty,
        
        // Data aksesoris dengan qty
        'aksesoris' => $aksesoris,
    ];

    return view('boq.jendela.jendela-bouven-1-kaca', $data);
}

